use std::cell::Cell;
use std::collections::HashMap;

use goro_parser::ast::*;

use crate::object::{ClassEntry, MethodDef, PropertyDef, Visibility as ObjVisibility};
use crate::opcode::{Op, OpArray, OpCode, OperandType, ParamType, ParamTypeInfo};
use crate::string::PhpString;
use crate::value::Value;

thread_local! {
    /// Global counter for generating unique closure names across all compilation units
    static CLOSURE_COUNTER: Cell<u64> = const { Cell::new(0) };
    /// Compile-time diagnostics (Warning/Deprecated) collected even when compilation
    /// aborts with a fatal. Drained by the SAPI/runner before printing the fatal
    /// message so they appear in source order ahead of the fatal.
    /// Each entry is (severity_label, message, line) where severity_label is
    /// e.g. "Warning" or "Deprecated".
    static PENDING_COMPILE_DIAGNOSTICS: std::cell::RefCell<Vec<(&'static str, String, u32)>>
        = const { std::cell::RefCell::new(Vec::new()) };
    /// Compile-time warnings raised by this compile and the nested compilers
    /// it spawns (function, method, closure and hook bodies); drained by the
    /// top-level `compile()` so none are lost.
    static COMPILE_WARNINGS: std::cell::RefCell<Vec<(String, u32)>>
        = const { std::cell::RefCell::new(Vec::new()) };
    /// FC(declarables).ticks of the file being compiled (shared with the
    /// nested compilers of its functions, methods and closures).
    static TICKS: Cell<u32> = const { Cell::new(0) };
    /// Attributes extensions mark internal (zend_mark_internal_attribute()),
    /// by lowercase name: validated at compile time.
    static EXT_INTERNAL_ATTRIBUTES: std::cell::RefCell<HashMap<Vec<u8>, InternalAttribute>>
        = std::cell::RefCell::new(HashMap::new());
}

/// zend_internal_attribute: the targets (Attribute::TARGET_* flags, with
/// IS_REPEATABLE) and the validator of an internal attribute.
#[derive(Clone, Copy)]
pub struct InternalAttribute {
    pub flags: u32,
    /// Called with the target (one TARGET_* flag): an error message fails
    /// the compilation.
    pub validator: Option<fn(u32) -> Option<String>>,
}

/// Attribute::TARGET_ALL
pub const ATTRIBUTE_TARGET_ALL: u32 = 0x7f;
/// Attribute::IS_REPEATABLE
pub const ATTRIBUTE_IS_REPEATABLE: u32 = 0x80;

/// zend_mark_internal_attribute() for an extension's attribute class.
pub fn register_internal_attribute(name: &[u8], config: InternalAttribute) {
    EXT_INTERNAL_ATTRIBUTES.with(|m| {
        m.borrow_mut().insert(name.to_ascii_lowercase(), config);
    });
}

/// Run `f` (compiling an extension's own declarations, which internal code
/// would not validate) without the extensions' internal attributes.
pub fn without_internal_attributes<R>(f: impl FnOnce() -> R) -> R {
    let saved = EXT_INTERNAL_ATTRIBUTES.with(|m| std::mem::take(&mut *m.borrow_mut()));
    let r = f();
    EXT_INTERNAL_ATTRIBUTES.with(|m| m.borrow_mut().extend(saved));
    r
}

/// The config of internal attribute `name` (resolved, any case).
pub(crate) fn internal_attribute(name: &[u8]) -> Option<InternalAttribute> {
    let n = name
        .strip_prefix(b"\\")
        .unwrap_or(name)
        .to_ascii_lowercase();
    let builtin = match n.as_slice() {
        b"attribute" | b"allowdynamicproperties" => Some(1),
        b"returntypewillchange" => Some(4),
        b"sensitiveparameter" => Some(32),
        b"override" => Some(4 | 8),
        b"deprecated" => Some(4 | 2 | 16 | 64 | 1),
        b"nodiscard" => Some(4 | 2),
        b"delayedtargetvalidation" => Some(ATTRIBUTE_TARGET_ALL),
        _ => None,
    };
    if let Some(flags) = builtin {
        return Some(InternalAttribute {
            flags,
            validator: None,
        });
    }
    EXT_INTERNAL_ATTRIBUTES.with(|m| m.borrow().get(&n).copied())
}

/// The Attribute::TARGET_* flag of a compile target name.
fn attribute_target_flag(target: &str) -> u32 {
    match target {
        "class" => 1,
        "function" => 2,
        "method" => 4,
        "property" => 8,
        "class constant" => 16,
        "parameter" => 32,
        "constant" => 64,
        _ => 0,
    }
}

/// zend_get_attribute_target_names()
fn attribute_target_names(flags: u32) -> String {
    let names = [
        "class",
        "function",
        "method",
        "property",
        "class constant",
        "parameter",
        "constant",
    ];
    names
        .iter()
        .enumerate()
        .filter(|(i, _)| flags & (1 << i) != 0)
        .map(|(_, n)| *n)
        .collect::<Vec<_>>()
        .join(", ")
}

fn push_compile_warning_tuple(w: (String, u32)) {
    push_compile_warning(w.0, w.1);
}

fn push_compile_warning(msg: String, line: u32) {
    COMPILE_WARNINGS.with(|w| w.borrow_mut().push((msg, line)));
}

/// Drain compile-time diagnostics collected during the most recent compile pass.
/// Callers should invoke this after `Compiler::compile` (success or failure) to
/// emit warnings/deprecateds before any fatal message.
pub fn take_pending_compile_warnings() -> Vec<(&'static str, String, u32)> {
    PENDING_COMPILE_DIAGNOSTICS.with(|w| std::mem::take(&mut *w.borrow_mut()))
}

fn push_pending_compile_warning(msg: String, line: u32) {
    PENDING_COMPILE_DIAGNOSTICS.with(|w| w.borrow_mut().push(("Warning", msg, line)));
}

/// Marks a compile-time diagnostic of the returned warning list as
/// E_DEPRECATED (see `Vm::emit_compile_diagnostic`).
pub const COMPILE_DEPRECATED_TAG: &str = "\u{1}Deprecated:";

/// A compile-time deprecation reported with the compile warnings.
fn push_compile_deprecated(msg: String, line: u32) {
    push_compile_warning(format!("{}{}", COMPILE_DEPRECATED_TAG, msg), line);
}

fn push_pending_compile_deprecated(msg: String, line: u32) {
    PENDING_COMPILE_DIAGNOSTICS.with(|w| w.borrow_mut().push(("Deprecated", msg, line)));
}

/// Get the next globally unique closure ID
/// Does a folded constant value still contain a runtime-resolved marker
/// (deferred constant / enum case placeholder)?
fn value_has_marker(v: &Value) -> bool {
    match v {
        Value::String(s) => {
            let b = s.as_bytes();
            b.starts_with(b"__deferred_") || b.starts_with(b"__enum_case__::")
        }
        Value::Array(a) => a.borrow().values().any(value_has_marker),
        _ => false,
    }
}

/// Name prefix of the op arrays compiled for lazily evaluated class
/// constant expressions (see Compiler::compile_const_thunk).
pub const CONST_THUNK_PREFIX: &str = "__const_thunk_";
/// Reserved variable names standing for the operands of a pipe (`|>`).
const PIPE_ALIAS_PREFIX: &[u8] = b"\0pipe";

fn next_closure_id() -> u64 {
    CLOSURE_COUNTER.with(|c| {
        let id = c.get();
        c.set(id + 1);
        id
    })
}

/// Reset the global closure counter (e.g., for test isolation)
pub fn reset_closure_counter() {
    CLOSURE_COUNTER.with(|c| c.set(0));
}

/// Compilation error
#[derive(Debug)]
pub struct CompileError {
    pub message: String,
    pub line: u32,
}

impl std::fmt::Display for CompileError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Compile error on line {}: {}", self.line, self.message)
    }
}

impl std::error::Error for CompileError {}

pub type CompileResult<T> = Result<T, CompileError>;

/// Loop context for break/continue support
struct LoopContext {
    /// Unique id (brk_cont_array index): a goto may only jump to a label in
    /// a loop it is itself inside.
    id: u32,
    /// Jump targets to patch with the loop's end address (for break)
    break_jumps: Vec<u32>,
    /// Jump targets to patch with the loop's continue address
    continue_jumps: Vec<u32>,
    /// The offset to jump to for continue (set when known)
    continue_target: Option<u32>,
    /// Whether this is a switch statement (for "continue targeting switch" warning)
    is_switch: bool,
    /// Number of enclosing finally blocks when the loop started
    finally_depth: usize,
    /// Number of enclosing try-with-finally bodies when the loop started
    try_finally_depth: usize,
    /// Number of enclosing exception-handler regions when the loop started
    handler_depth: usize,
    /// Temporaries live during the loop (foreach iterator/value), released
    /// when `return` / `break N` / `continue N` leaves it (FE_FREE).
    free_tmps: Vec<u32>,
    /// Nop at the loop entry, turned into SaveHandlerDepth (into the tmp)
    /// once a jump out of the loop frees its temporaries.
    depth_nop: Option<u32>,
    depth_tmp: Option<u32>,
}

#[derive(Default)]
struct JumpState {
    /// Forward gotos leaving try-with-finally regions:
    /// (label, SaveJump offset, Jmp offset, regions at the goto)
    pending_finally_gotos: Vec<(Vec<u8>, u32, u32, Vec<u32>)>,
    /// Pending gotos for forward references: maps label name -> list of (jmp instruction offset, source line)
    pending_gotos: HashMap<Vec<u8>, Vec<(u32, u32)>>,
    /// label -> number of loops enclosing it
    label_loop_depth: HashMap<Vec<u8>, usize>,
    /// Loop-variable frees emitted by forward gotos (label, loop index, op
    /// range): those of loops that also enclose the label are removed.
    pending_goto_frees: Vec<(Vec<u8>, usize, u32, u32)>,
    /// Per enclosing try-with-finally: break/continue jumps that leave it
    /// with loop variables to free between its finally block and the next
    /// (SaveJump offset, target loop index, is continue, line). They resume
    /// after the finally block, in stubs emitted after the try statement.
    finally_stubs: Vec<Vec<(u32, usize, bool, u32)>>,
}

/// Compiles an AST into bytecode
pub struct Compiler {
    op_array: OpArray,
    /// `??=` memoization (CG(memoize_mode)): 0 = off, 1 = compile (record
    /// the operands of the target's sub-expressions), 2 = fetch (reuse them).
    memoize_mode: u8,
    memoized_exprs: HashMap<usize, OperandType>,
    /// The synthetic isset / assign node being compiled in memoize mode.
    memoize_root: usize,
    /// CG(zend_lineno): the line of the expression whose compilation started
    /// last. An operator's opline gets it once its operands are compiled, so
    /// a multi-line `$a +\n $b` reports the line of `$b`.
    zend_lineno: u32,
    /// Reserved variable names (not expressible in PHP source) standing for
    /// already-computed operands while synthesized code is compiled (target
    /// keys evaluated before an assigned value).
    tmp_aliases: Vec<(Vec<u8>, OperandType)>,
    /// Hidden `\0vvN` CVs holding the variables of dynamic variable writes
    /// (`$$n[k] = v`, `$$n .= v`, ...) fetched by VarVarFetch; released at
    /// the end of the statement.
    dynvar_count: u32,
    dynvar_pending: Vec<u32>,
    /// Stack of loop contexts for break/continue
    loop_stack: Vec<LoopContext>,
    /// Compiled class entries (stored in the compiler, passed to VM)
    pub compiled_classes: Vec<ClassEntry>,
    /// Current class name (for __CLASS__, __METHOD__)
    current_class: Option<Vec<u8>>,
    /// Current parent class name (for parent::)
    current_parent_class: Option<Vec<u8>>,
    /// Stack of finally block targets (for deferred return)
    finally_targets: Vec<u32>,
    /// Current namespace (e.g. b"Foo\\Bar"), empty for global namespace
    current_namespace: Vec<u8>,
    /// The property whose declaration (default, attributes) is being
    /// compiled: what `__PROPERTY__` means in its constant expressions.
    const_property_name: Vec<u8>,
    /// Use imports: maps lowercase short name (alias) -> fully qualified name (original case)
    use_map: HashMap<Vec<u8>, Vec<u8>>,
    /// Use imports for functions: maps lowercase short name -> fully qualified name
    use_function_map: HashMap<Vec<u8>, Vec<u8>>,
    /// Use imports for constants: maps short name -> fully qualified name (case-sensitive)
    use_const_map: HashMap<Vec<u8>, Vec<u8>>,
    /// Label offsets for goto: maps label name -> instruction offset
    label_offsets: HashMap<Vec<u8>, u32>,
    /// Ids of the try-with-finally regions (try and catch bodies) enclosing
    /// the code being compiled, parallel to `finally_targets`.
    try_finally_ids: Vec<u32>,
    try_finally_counter: u32,
    /// label -> enclosing try-with-finally regions
    label_try_finally: HashMap<Vec<u8>, Vec<u32>>,
    /// Bookkeeping of gotos and loop exits through finally blocks (boxed:
    /// a Compiler lives on the stack of every recursive compile_expr frame).
    jumps: Box<JumpState>,
    /// Source file path (for __FILE__, __DIR__)
    pub source_file: Vec<u8>,
    /// Whether the current function has a "never" return type
    has_never_return: bool,
    /// Map from parser anonymous class names (__anonymous_class_N) to PHP NUL-byte names
    anon_class_name_map: HashMap<Vec<u8>, Vec<u8>>,
    /// Lowercased qualified names of classes that were early-bound (hoisted) in the
    /// hoisting pass. Used so the second pass knows which class decls to skip, and so
    /// the hoisting pass can decide whether a `extends Parent` class can itself be
    /// hoisted (its parent must already be hoisted or be an internal class).
    hoisted_class_names: std::collections::HashSet<Vec<u8>>,
    /// The hoisted (early-bound) class declaration statements, by address: a
    /// same-named declaration elsewhere in the file is not that statement.
    hoisted_class_stmts: std::collections::HashSet<usize>,
    /// The `declare()` statements a file starts with, by address: the only
    /// ones that may declare an encoding (zend_is_first_statement()).
    leading_declare_stmts: std::collections::HashSet<usize>,
    /// Top-level functions declared in this compilation unit: lowercased
    /// qualified name -> (display name, declaration line).
    hoisted_function_names: HashMap<Vec<u8>, (Vec<u8>, u32)>,
    /// Classes declared so far (source order) in the main compile pass,
    /// lowercased qualified names. Used for `use` name conflict checks.
    seen_class_symbols: std::collections::HashSet<Vec<u8>>,
    /// Functions (lowercased qualified names) and constants (qualified
    /// names) declared so far in the main pass (FC(seen_symbols)).
    seen_function_symbols: std::collections::HashSet<Vec<u8>>,
    seen_const_symbols: std::collections::HashSet<Vec<u8>>,
    /// True while running the main (second) top-level compile pass.
    in_main_pass: bool,
    /// True when compiling the body of a free (non-closure, non-method)
    /// function: the class scope is known to be empty, so self/parent/static
    /// references are compile-time errors.
    in_free_function: bool,
    /// Whether we're compiling inside a trait (for self:: tracking)
    is_in_trait: bool,
    /// Compiling the members of a trait: its constant-expression thunks
    /// resolve `self` / `__CLASS__` in the scope of the using class.
    in_trait_body: bool,
    /// Compile-time warnings (message, line)
    pub warnings: Vec<(String, u32)>,
    /// Whether the current expression's result will be discarded (for #[\NoDiscard])
    is_discarding_result: bool,
    /// The assignment being compiled is an expression statement (its value is unused).
    assign_result_discarded: bool,
    /// CG(context).has_assigned_to_http_response_header
    hrh_assigned: bool,
    /// True when compiling inside a function/method/closure body (reserved for future use).
    pub is_in_function_body: bool,
    /// True when compiling inside the body of a *class method* (not a plain function or
    /// closure). Used to enforce "Class declarations may not be nested" for non-anonymous
    /// class declarations.
    pub is_in_class_method: bool,
    /// True in a non-static method body, where `$this` is always bound;
    /// elsewhere uses of `$this` are checked at runtime (ZEND_FETCH_THIS).
    this_always_bound: bool,
    /// Set while compiling the operand of isset($this) / empty($this).
    quiet_this: bool,
    /// Compiling a constant-expression thunk: `self::X` / `parent::X` stay
    /// relative (resolved at run time, reported as written).
    keep_relative_class_names: bool,
    /// Compiling a constant expression (global constant, parameter default,
    /// class constant / property default thunk): property fetches are only
    /// allowed on enums.
    in_const_expr: bool,
    /// Compile-time fatal errors collected during attribute validation that
    /// should be raised before the script executes. The first one wins.
    pub deferred_fatal_errors: Vec<String>,
    /// The attributes being compiled are those of a property hook.
    in_hook_attrs: bool,
    /// The attributes being compiled are those of a closure.
    attrs_scope_unknown: bool,
    /// Ids of the finally blocks enclosing the code being compiled.
    finally_path: Vec<u32>,
    finally_id_counter: u32,
    /// label -> enclosing finally path; gotos -> (label, path, line)
    label_finally_paths: HashMap<Vec<u8>, Vec<u32>>,
    /// label -> ids of the loops/switches enclosing it
    label_loop_paths: HashMap<Vec<u8>, Vec<u32>>,
    /// (label, ids of the loops/switches enclosing the goto, line)
    goto_loop_paths: Vec<(Vec<u8>, Vec<u32>, u32)>,
    goto_finally_paths: Vec<(Vec<u8>, Vec<u32>, u32)>,
    /// The jumps of the `?->` null checks of the chain being compiled,
    /// which short-circuit the whole chain (zend_short_circuiting_commit()).
    nullsafe_chain: Option<Vec<u32>>,
    /// The expression compiled next is the base of a chain element
    /// (`X` of `X->p`, `X[k]`, `X->m()`), not a chain of its own.
    chain_base: bool,
    /// The regions with an active exception handler enclosing the code
    /// being compiled (innermost last): the offset of the TryBegin that
    /// pushes it, and whether it leads to a finally block.
    handler_regions: Vec<(u32, bool)>,
    /// label -> handler regions enclosing it
    label_handler_paths: HashMap<Vec<u8>, Vec<(u32, bool)>>,
    /// Forward gotos: (Jmp offset, label, handler regions at the goto),
    /// given a landing pad by check_pending_gotos() when they leave or
    /// enter handler regions.
    goto_handler_paths: Vec<(u32, Vec<u8>, Vec<(u32, bool)>)>,
    /// Unique id of this compilation's top-level op_array, keying its
    /// static variables (each file / eval'd string has its own).
    main_static_id: u64,
    /// True for the compiler of a whole file/eval (via `compile()`); false for
    /// function/method/closure sub-compilers. Classes declared inside a
    /// sub-compiled body are stored on that body's op_array (`local_classes`).
    is_top_level: bool,
    /// True while compiling a hoisted (early-bound) class declaration.
    in_hoisting_pass: bool,
    /// compiled_classes index of each hoisted class (lowercase qualified name).
    hoisted_class_idx: HashMap<Vec<u8>, i64>,
}

impl Default for Compiler {
    fn default() -> Self {
        Self::new()
    }
}

impl Compiler {
    /// Map a method-call identifier to a synthetic name used by
    /// `is_builtin_byref_param` to drive by-ref argument compilation
    /// for known builtin OO methods. The synthetic name distinguishes
    /// the method-call form (where source args have no leading $this)
    /// from the procedural form (where $stmt is args[0]).
    fn builtin_method_to_bridge_func(method_name: &[u8]) -> Option<Vec<u8>> {
        let lower: Vec<u8> = method_name.iter().map(|b| b.to_ascii_lowercase()).collect();
        match lower.as_slice() {
            b"bind_param" => Some(b"__mysqli_stmt_bind_param_method".to_vec()),
            b"bind_result" => Some(b"__mysqli_stmt_bind_result_method".to_vec()),
            // ZipArchive::getExternalAttributesName/Index($x, &$opsys, &$attr)
            b"getexternalattributesname" | b"getexternalattributesindex" => {
                Some(b"__ziparchive_getexternalattributes_method".to_vec())
            }
            _ => None,
        }
    }

    /// Check if a builtin function's parameter at given position is by-reference
    fn is_builtin_byref_param(func_name: Option<&[u8]>, pos: usize) -> bool {
        match func_name {
            Some(name) => {
                let lower: Vec<u8> = name.iter().map(|b| b.to_ascii_lowercase()).collect();
                match (lower.as_slice(), pos) {
                    // preg_match($pattern, $subject, &$matches, $flags, $offset)
                    (b"preg_match", 2) => true,
                    (b"preg_match_all", 2) => true,
                    // preg_replace($pattern, $replacement, $subject, $limit, &$count)
                    (b"preg_replace", 4) => true,
                    // preg_replace_callback($pattern, $callback, $subject, $limit, &$count)
                    (b"preg_replace_callback", 4) => true,
                    // preg_replace_callback_array($patterns, $subject, $limit, &$count)
                    (b"preg_replace_callback_array", 3) => true,
                    // sscanf with output vars (positions 2+)
                    (b"sscanf", p) if p >= 2 => true,
                    // str_replace($search, $replace, $subject, &$count)
                    (b"str_replace", 3) => true,
                    // str_ireplace($search, $replace, $subject, &$count)
                    (b"str_ireplace", 3) => true,
                    // similar_text($str1, $str2, &$percent)
                    (b"similar_text", 2) => true,
                    // headers_sent(&$filename, &$line)
                    (b"headers_sent", 0) | (b"headers_sent", 1) => true,
                    // settype(&$var, $type)
                    (b"settype", 0) => true,
                    // ext/zend_test: zend_terminate_string(&$str),
                    // zend_test_fill_packed_array(&$array)
                    (b"zend_terminate_string", 0) | (b"zend_test_fill_packed_array", 0) => true,
                    // flock($stream, $operation, &$would_block)
                    (b"flock", 2) => true,
                    // array_walk(&$array, ...): the walk reloads the variable
                    // after each callback, so it needs the variable itself.
                    (b"array_walk", 0) | (b"array_walk_recursive", 0) => true,
                    // getopt($short, $long, &$rest_index)
                    (b"getopt", 2) => true,
                    // parse_str($string, &$result)
                    (b"parse_str", 1) => true,
                    // getimagesize($filename, &$image_info)
                    (b"getimagesize", 1) => true,
                    (b"getimagesizefromstring", 1) => true,
                    // exif_thumbnail($file, &$width, &$height, &$image_type)
                    (b"exif_thumbnail", 1..=3) => true,
                    // is_callable($value, $syntax_only, &$callable_name)
                    (b"is_callable", 2) => true,
                    // xml_parse_into_struct($parser, $data, &$values, &$index)
                    (b"xml_parse_into_struct", 2) => true,
                    (b"xml_parse_into_struct", 3) => true,
                    // proc_open($command, $descriptorspec, &$pipes, $cwd, $env, $options)
                    (b"proc_open", 2) => true,
                    // exec($command, &$output, &$result_code)
                    (b"exec", 1) => true,
                    (b"exec", 2) => true,
                    (b"system", 1) => true,
                    (b"passthru", 1) => true,
                    // fscanf($stream, $format, &$vars...)
                    (b"fscanf", p) if p >= 2 => true,
                    // fsockopen($hostname, $port, &$errno, &$errstr, $timeout)
                    (b"fsockopen", 2) => true,
                    (b"fsockopen", 3) => true,
                    (b"pfsockopen", 2) => true,
                    (b"pfsockopen", 3) => true,
                    // stream_socket_client($address, &$errno, &$errstr, ...)
                    (b"stream_socket_client", 1) => true,
                    (b"stream_socket_client", 2) => true,
                    // stream_socket_server($address, &$errno, &$errstr, ...)
                    (b"stream_socket_server", 1) => true,
                    (b"stream_socket_server", 2) => true,
                    // stream_socket_accept($socket, $timeout, &$peer_name)
                    (b"stream_socket_accept", 2) => true,
                    // stream_socket_recvfrom($socket, $length, $flags, &$address)
                    (b"stream_socket_recvfrom", 3) => true,
                    // stream_select(&$read, &$write, &$except, ...)
                    (b"stream_select", 0..=2) => true,
                    // dns_get_mx($hostname, &$hosts, &$weights)
                    (b"dns_get_mx", 1) | (b"dns_get_mx", 2) => true,
                    (b"getmxrr", 1) | (b"getmxrr", 2) => true,
                    // dns_get_record($hostname, $type, &$authoritative_name_servers, &$additional_records, $raw)
                    (b"dns_get_record", 2) | (b"dns_get_record", 3) => true,
                    // mb_ereg($pattern, $string, &$regs)
                    (b"mb_ereg", 2) => true,
                    (b"mb_eregi", 2) => true,
                    (b"mb_parse_str", 1) => true,
                    (b"mb_convert_variables", p) if p >= 2 => true,
                    // openssl functions with output params
                    (b"openssl_seal", 1) => true,
                    (b"openssl_seal", 2) => true,
                    (b"openssl_seal", 5) => true,
                    (b"openssl_open", 1) => true,
                    (b"openssl_encrypt", 5) => true,
                    (b"openssl_random_pseudo_bytes", 1) => true,
                    (b"openssl_csr_new", 1) => true,
                    (b"openssl_sign", 1) => true,
                    (b"openssl_private_encrypt", 1) => true,
                    (b"openssl_private_decrypt", 1) => true,
                    (b"openssl_public_encrypt", 1) => true,
                    (b"openssl_public_decrypt", 1) => true,
                    (b"openssl_csr_export", 1) => true,
                    (b"openssl_x509_export", 1) => true,
                    (b"openssl_pkey_export", 1) => true,
                    (b"openssl_pkcs12_export", 1) => true,
                    (b"openssl_pkcs12_read", 1) => true,
                    (b"openssl_pkcs7_read", 1) => true,
                    (b"openssl_cms_read", 1) => true,
                    // socket functions with output params
                    (b"socket_create_pair", 3) => true,
                    (b"socket_getpeername", 1) => true,
                    (b"socket_getpeername", 2) => true,
                    (b"socket_getsockname", 1) => true,
                    (b"socket_getsockname", 2) => true,
                    (b"socket_recvfrom", 1) => true,
                    (b"socket_recvfrom", 4) => true,
                    (b"socket_recvfrom", 5) => true,
                    (b"socket_recv", 1) => true,
                    (b"socket_recvmsg", 1) => true,
                    (b"socket_select", 0..=2) => true,
                    (b"curl_multi_exec", 1) => true,
                    (b"curl_multi_info_read", 1) => true,
                    // mysqli_poll(&$read, &$error, &$reject, $sec, $usec)
                    (b"mysqli_poll", 0..=2) => true,
                    // ext/pcntl: the status, rusage and siginfo outputs
                    (b"pcntl_waitpid", 1) | (b"pcntl_waitpid", 3) => true,
                    (b"pcntl_waitid", 2) | (b"pcntl_waitid", 4) => true,
                    (b"pcntl_wait", 0) | (b"pcntl_wait", 2) => true,
                    (b"pcntl_sigprocmask", 2) => true,
                    (b"pcntl_sigwaitinfo", 1) | (b"pcntl_sigtimedwait", 1) => true,
                    // ext/ftp: ftp_alloc($ftp, $size, &$response)
                    (b"ftp_alloc", 2) => true,
                    // ext/sodium: the strings and states updated in place
                    (b"sodium_memzero", 0)
                    | (b"sodium_increment", 0)
                    | (b"sodium_add", 0)
                    | (b"sodium_crypto_generichash_update", 0)
                    | (b"sodium_crypto_generichash_final", 0)
                    | (b"sodium_crypto_secretstream_xchacha20poly1305_push", 0)
                    | (b"sodium_crypto_secretstream_xchacha20poly1305_pull", 0)
                    | (b"sodium_crypto_secretstream_xchacha20poly1305_rekey", 0) => true,
                    // ext/sysvmsg: msg_send(..., &$error_code),
                    // msg_receive($queue, $desired_message_type,
                    // &$received_message_type, $max_message_size, &$message,
                    // $unserialize, $flags, &$error_code)
                    (b"msg_send", 5) => true,
                    (b"msg_receive", 2) | (b"msg_receive", 4) | (b"msg_receive", 7) => true,
                    // mysqli_stmt_bind_param($stmt, $types, &$var1, &$var2, ...)
                    (b"mysqli_stmt_bind_param", p) if p >= 2 => true,
                    // mysqli_stmt_bind_result($stmt, &$var1, &$var2, ...)
                    (b"mysqli_stmt_bind_result", p) if p >= 1 => true,
                    // mysqli_stmt::bind_param method form: ($types, &$var1, ...)
                    (b"__mysqli_stmt_bind_param_method", p) if p >= 1 => true,
                    // mysqli_stmt::bind_result method form: (&$var1, &$var2, ...)
                    (b"__mysqli_stmt_bind_result_method", _) => true,
                    (b"__ziparchive_getexternalattributes_method", 1..=2) => true,
                    // ext/intl: as its stubs declare (collator_sort(),
                    // numfmt_parse(), grapheme_extract(), idn_to_ascii()...)
                    (name, p) => crate::stubs::find_function(name).is_some_and(|f| {
                        (f.ext == "intl" || f.ext == "ldap")
                            && f.args
                                .get(p)
                                .is_some_and(|a| a.flags & crate::stubs::A_BY_REF != 0)
                    }),
                }
            }
            None => false,
        }
    }

    /// Code that shares its caller's scope (eval()) sees the caller's
    /// `$this` in a `$this` CV.
    pub fn with_this_cv(mut self) -> Self {
        self.op_array.get_or_create_cv(b"this");
        self
    }

    pub fn new() -> Self {
        Self {
            op_array: OpArray::new(),
            memoize_mode: 0,
            memoized_exprs: HashMap::new(),
            memoize_root: 0,
            zend_lineno: 0,
            tmp_aliases: Vec::new(),
            dynvar_count: 0,
            dynvar_pending: Vec::new(),
            loop_stack: Vec::new(),
            compiled_classes: Vec::new(),
            current_class: None,
            current_parent_class: None,
            finally_targets: Vec::new(),
            current_namespace: Vec::new(),
            const_property_name: Vec::new(),
            use_map: HashMap::new(),
            use_function_map: HashMap::new(),
            use_const_map: HashMap::new(),
            label_offsets: HashMap::new(),
            try_finally_ids: Vec::new(),
            try_finally_counter: 0,
            label_try_finally: HashMap::new(),
            jumps: Box::default(),
            source_file: Vec::new(),
            has_never_return: false,
            anon_class_name_map: HashMap::new(),
            hoisted_class_names: std::collections::HashSet::new(),
            hoisted_class_stmts: std::collections::HashSet::new(),
            leading_declare_stmts: std::collections::HashSet::new(),
            hoisted_function_names: HashMap::new(),
            seen_class_symbols: std::collections::HashSet::new(),
            seen_function_symbols: std::collections::HashSet::new(),
            seen_const_symbols: std::collections::HashSet::new(),
            in_main_pass: false,
            in_free_function: false,
            is_in_trait: false,
            in_trait_body: false,
            warnings: Vec::new(),
            is_discarding_result: false,
            in_const_expr: false,
            assign_result_discarded: false,
            hrh_assigned: false,
            is_in_function_body: false,
            is_in_class_method: false,
            this_always_bound: false,
            quiet_this: false,
            keep_relative_class_names: false,
            is_top_level: false,
            in_hoisting_pass: false,
            hoisted_class_idx: HashMap::new(),
            deferred_fatal_errors: Vec::new(),
            in_hook_attrs: false,
            attrs_scope_unknown: false,
            finally_path: Vec::new(),
            finally_id_counter: 0,
            label_finally_paths: HashMap::new(),
            label_loop_paths: HashMap::new(),
            goto_loop_paths: Vec::new(),
            goto_finally_paths: Vec::new(),
            nullsafe_chain: None,
            chain_base: false,
            handler_regions: Vec::new(),
            label_handler_paths: HashMap::new(),
            goto_handler_paths: Vec::new(),
            main_static_id: 0,
        }
    }

    /// How many of the try/finally regions `from` (innermost last) a jump
    /// to a place inside `to` leaves.
    fn regions_left(from: &[u32], to: &[u32]) -> usize {
        let common = from
            .iter()
            .zip(to.iter())
            .take_while(|(a, b)| a == b)
            .count();
        from.len() - common
    }

    /// Reject any unresolved gotos in this compiler scope. Called at the end of
    /// each function/method/closure/script body so that an unmatched goto becomes
    /// a clean compile-time fatal error instead of a placeholder Jmp to ip=0 that
    /// would otherwise spin forever at runtime.
    fn check_pending_gotos(&mut self) -> CompileResult<()> {
        // (Also run at the end of every function body:) zend_mark_function_as_generator:
        // a generator's declared return type must be a supertype of Generator.
        if self.op_array.is_generator {
            if let Some(rt) = &self.op_array.return_type {
                let tv = crate::vm::variance::TypeView::from_param_type(rt);
                let valid = tv.mask & crate::vm::variance::T_OBJECT != 0
                    || tv.elems.iter().any(|e| match e {
                        crate::vm::variance::TElem::Name(n) => {
                            n.eq_ignore_ascii_case(b"Traversable")
                                || n.eq_ignore_ascii_case(b"Iterator")
                                || n.eq_ignore_ascii_case(b"Generator")
                        }
                        _ => false,
                    });
                if !valid {
                    return Err(CompileError {
                        message: format!(
                            "Generator return type must be a supertype of Generator, {} given",
                            crate::vm::variance::type_to_string(&tv, None)
                        ),
                        line: self.op_array.decl_line,
                    });
                }
            }
        }
        if let Some((name, locs)) = self.jumps.pending_gotos.iter().next() {
            let label = String::from_utf8_lossy(name).into_owned();
            let line = locs.first().map(|(_, l)| *l).unwrap_or(0);
            return Err(CompileError {
                message: format!("'goto' to undefined label '{}'", label),
                line,
            });
        }
        // zend_resolve_goto_label(): the label's loops must all enclose the goto.
        for (label, goto_path, line) in &self.goto_loop_paths {
            if let Some(label_path) = self.label_loop_paths.get(label) {
                if !goto_path.starts_with(label_path) {
                    return Err(CompileError {
                        message: "'goto' into loop or switch statement is disallowed".into(),
                        line: *line,
                    });
                }
            }
        }
        // zend_check_finally_breakout(): goto may not cross finally boundaries.
        for (label, goto_path, line) in &self.goto_finally_paths {
            if let Some(label_path) = self.label_finally_paths.get(label) {
                let is_prefix = label_path.len() <= goto_path.len()
                    && goto_path[..label_path.len()] == label_path[..];
                if !is_prefix {
                    return Err(CompileError {
                        message: "jump into a finally block is disallowed".into(),
                        line: *line,
                    });
                }
                if goto_path.len() > label_path.len() {
                    return Err(CompileError {
                        message: "jump out of a finally block is disallowed".into(),
                        line: *line,
                    });
                }
            }
        }
        self.emit_goto_pads();
        Ok(())
    }

    /// The handler stack changes of a goto from handler regions `from` to
    /// a label in `to`: how many handlers to pop, and the TryBegin offsets
    /// of the regions entered (outermost first). None when it leaves a
    /// region leading to a finally block (the finally path pops those).
    fn goto_handler_change(from: &[(u32, bool)], to: &[(u32, bool)]) -> Option<(usize, Vec<u32>)> {
        let common = from
            .iter()
            .zip(to.iter())
            .take_while(|(a, b)| a == b)
            .count();
        if from[common..].iter().any(|r| r.1) {
            return None;
        }
        Some((
            from.len() - common,
            to[common..].iter().map(|r| r.0).collect(),
        ))
    }

    /// Emit the handler stack changes of a goto (see goto_handler_change).
    fn emit_handler_change(&mut self, pops: usize, enter: &[u32], line: u32) {
        for _ in 0..pops {
            self.op_array.emit(Op {
                opcode: OpCode::TryEnd,
                op1: OperandType::Unused,
                op2: OperandType::Unused,
                result: OperandType::Unused,
                line,
            });
        }
        for &tb in enter {
            let mut op = self.op_array.ops[tb as usize].clone();
            op.line = line;
            self.op_array.emit(op);
        }
    }

    /// Forward gotos that leave or enter try blocks jump through a landing
    /// pad that pops or pushes their exception handlers (php-src looks the
    /// try blocks up by opline: a goto into a try is covered by its catch).
    fn emit_goto_pads(&mut self) {
        let gotos = std::mem::take(&mut self.goto_handler_paths);
        let mut over = None;
        for (jmp, label, from) in gotos {
            let (Some(to), Some(&target)) = (
                self.label_handler_paths.get(&label).cloned(),
                self.label_offsets.get(&label),
            ) else {
                continue;
            };
            let Some((pops, enter)) = Self::goto_handler_change(&from, &to) else {
                continue;
            };
            if pops == 0 && enter.is_empty() {
                continue;
            }
            let line = self.op_array.ops[jmp as usize].line;
            if over.is_none() {
                over = Some(self.op_array.emit(Op {
                    opcode: OpCode::Jmp,
                    op1: OperandType::JmpTarget(0),
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line,
                }));
            }
            let pad = self.op_array.current_offset();
            self.emit_handler_change(pops, &enter, line);
            self.op_array.emit(Op {
                opcode: OpCode::Jmp,
                op1: OperandType::JmpTarget(target),
                op2: OperandType::Unused,
                result: OperandType::Unused,
                line,
            });
            self.op_array.patch_jump(jmp, pad);
        }
        if let Some(over) = over {
            let end = self.op_array.current_offset();
            self.op_array.patch_jump(over, end);
        }
    }

    /// Compute the canonical PHP closure display name `{closure:<context>:<line>}`
    /// from the current compiler scope (the *parent* of the closure being created).
    ///
    /// `<context>` is one of:
    /// - The parent's already-set `op_array.display_name` (for nested closures inside another
    ///   closure/arrow), with the outer `{closure:...}` braces kept intact, e.g.
    ///   `{closure:{closure:Foo::bar():12}:13}`.
    /// - `Class::method()` when compiling inside a class method.
    /// - `function_name()` when compiling inside a global/namespaced function.
    /// - The source file path otherwise (top-level script).
    fn closure_display_name(&self, line: u32) -> Vec<u8> {
        let mut name = b"{closure:".to_vec();
        // Nested closure: parent already has a display_name like `{closure:...}`.
        if !self.op_array.display_name.is_empty() {
            name.extend_from_slice(&self.op_array.display_name);
        } else if let Some(class) = self
            .current_class
            .as_ref()
            .filter(|_| !self.op_array.name.is_empty())
        {
            // Inside a method: `Class::method()`. Class-level initializers
            // (constants, attributes, defaults) have no active function and
            // use the file name, like the top-level script.
            name.extend_from_slice(class);
            name.extend_from_slice(b"::");
            name.extend_from_slice(&self.op_array.name);
            name.extend_from_slice(b"()");
        } else if !self.op_array.name.is_empty() {
            // Inside a global/namespaced function.
            name.extend_from_slice(&self.op_array.name);
            name.extend_from_slice(b"()");
        } else {
            // Top-level script: use the source file path.
            name.extend_from_slice(&self.source_file);
        }
        name.extend_from_slice(format!(":{}}}", line).as_bytes());
        name
    }

    /// Compile a property name expression, treating bare identifiers as string literals
    /// (not as constant lookups). This is important for $obj->property syntax.
    fn compile_property_name(&mut self, expr: &Expr) -> CompileResult<OperandType> {
        if let ExprKind::Identifier(name) = &expr.kind {
            // Bare identifier in property context is always a string literal
            let idx = self
                .op_array
                .add_literal(Value::String(PhpString::from_vec(name.clone())));
            Ok(OperandType::Const(idx))
        } else if !matches!(expr.kind, ExprKind::String(_)) && self.in_engine_silence() {
            // isset($o->{expr}) / $o->{expr} ?? ...: the name is evaluated
            // normally, only the property fetch is quiet.
            self.compile_key_unsilenced(expr, true)
        } else {
            self.compile_expr(expr)
        }
    }

    /// Whether code emitted now runs inside an engine-silenced region
    /// (isset() / empty() / `??`), as opposed to normal code or `@`.
    fn in_engine_silence(&self) -> bool {
        let mut stack: Vec<bool> = Vec::new();
        for op in &self.op_array.ops {
            match op.opcode {
                OpCode::ErrorSuppress => stack.push(matches!(op.op1, OperandType::Unused)),
                OpCode::ErrorRestore => {
                    stack.pop();
                }
                _ => {}
            }
        }
        stack.last().copied().unwrap_or(false)
    }

    /// Prefix a name with the current namespace. E.g. if namespace is "Foo\Bar" and name is "Baz",
    /// returns "Foo\Bar\Baz". If namespace is empty, returns name unchanged.
    fn prefix_with_namespace(&self, name: &[u8]) -> Vec<u8> {
        if self.current_namespace.is_empty() {
            name.to_vec()
        } else {
            let mut result = self.current_namespace.clone();
            result.push(b'\\');
            result.extend_from_slice(name);
            result
        }
    }

    /// zend_reset_import_tables(): the seen symbols are per namespace.
    fn reset_seen_symbols(&mut self) {
        self.seen_class_symbols.clear();
        self.seen_function_symbols.clear();
        self.seen_const_symbols.clear();
    }

    /// A function / class / constant declaration of (unqualified) `name` in
    /// the main pass, in source order: the collision with a `use` import of
    /// that name in the current namespace (zend_begin_func_decl,
    /// zend_compile_class_decl, zend_compile_const_decl), then
    /// zend_register_seen_symbol() for the `use` checks of later imports.
    fn note_symbol_decl(&mut self, kind: &UseKind, name: &[u8], line: u32) -> CompileResult<()> {
        let qn = self.prefix_with_namespace(name);
        let lc = qn.to_ascii_lowercase();
        let msg = match kind {
            UseKind::Function => self
                .use_function_map
                .get(&name.to_ascii_lowercase())
                .filter(|imp| !imp.eq_ignore_ascii_case(&lc))
                .map(|_| {
                    format!(
                        "Cannot redeclare function {}() (previously declared as local import)",
                        String::from_utf8_lossy(&qn)
                    )
                }),
            UseKind::Normal => self
                .use_map
                .get(&name.to_ascii_lowercase())
                .filter(|imp| !imp.eq_ignore_ascii_case(&lc))
                .map(|_| {
                    format!(
                        "Cannot redeclare class {} (previously declared as local import)",
                        String::from_utf8_lossy(&qn)
                    )
                }),
            UseKind::Constant => self
                .use_const_map
                .get(name)
                .filter(|imp| imp.as_slice() != qn.as_slice())
                .map(|_| {
                    format!(
                        "Cannot declare const {} because the name is already in use",
                        String::from_utf8_lossy(&qn)
                    )
                }),
        };
        if let Some(message) = msg {
            return Err(CompileError { message, line });
        }
        match kind {
            UseKind::Function => self.seen_function_symbols.insert(lc),
            UseKind::Normal => self.seen_class_symbols.insert(lc),
            UseKind::Constant => self.seen_const_symbols.insert(qn),
        };
        Ok(())
    }

    /// Resolve a class/interface/trait name. Rules:
    /// 1. If the name starts with \, it's fully qualified -- strip the leading \
    /// 2. If the name contains a backslash (qualified), check first part against use aliases
    /// 3. If unqualified (no backslash):
    ///    - Check use imports first
    ///    - Otherwise prefix with current namespace
    ///
    /// Special names like "self", "parent", "static" are not resolved.
    /// Compile-time validation of `parent::$prop::get()` / `parent::$prop::set()`
    /// (lowered by the parser to `parent::__property_{get,set}_<prop>()`),
    /// matching zend_compile_parent_property_hook_call(). Returns Ok(false)
    /// when the call is valid (or not a parent hook call).
    fn check_parent_hook_call(
        &self,
        class: &Expr,
        method: &[u8],
        is_fcc: bool,
        line: u32,
    ) -> Result<bool, CompileError> {
        let (kind, prop) = if let Some(p) = method.strip_prefix(b"__property_get_".as_slice()) {
            ("get", p)
        } else if let Some(p) = method.strip_prefix(b"__property_set_".as_slice()) {
            ("set", p)
        } else {
            return Ok(false);
        };
        if !matches!(&class.kind, ExprKind::Identifier(n) if n.eq_ignore_ascii_case(b"parent")) {
            return Ok(false);
        }
        let err = |m: String| Err(CompileError { message: m, line });
        if self.current_class.is_none() {
            return err("Cannot use \"parent\" when no class scope is active".into());
        }
        if is_fcc {
            return err("Cannot create Closure for parent property hook call".into());
        }
        let prop_s = String::from_utf8_lossy(prop);
        let n = &self.op_array.name;
        let active =
            if n.len() > 6 && n[0] == b'$' && (n.ends_with(b"::get") || n.ends_with(b"::set")) {
                Some((&n[1..n.len() - 5], &n[n.len() - 3..]))
            } else {
                None
            };
        let Some((active_prop, active_kind)) = active else {
            return err(format!(
                "Must not use parent::${}::{}() outside a property hook",
                prop_s, kind
            ));
        };
        if active_prop != prop {
            return err(format!(
                "Must not use parent::${}::{}() in a different property (${})",
                prop_s,
                kind,
                String::from_utf8_lossy(active_prop)
            ));
        }
        if active_kind != kind.as_bytes() {
            return err(format!(
                "Must not use parent::${}::{}() in a different property hook ({})",
                prop_s,
                kind,
                String::from_utf8_lossy(active_kind)
            ));
        }
        Ok(false)
    }

    /// Resolve a magic constant or known constant name in class constant context.
    fn resolve_class_const_magic(&self, name_lower: &[u8], class_name: &[u8], line: u32) -> Value {
        match name_lower {
            b"__property__" => Value::String(PhpString::from_vec(self.const_property_name.clone())),
            b"__method__" | b"__function__" => {
                // In class constant context (not a method), __METHOD__ and __FUNCTION__ are ""
                Value::String(PhpString::empty())
            }
            b"__class__" => Value::String(PhpString::from_vec(class_name.to_vec())),
            b"__line__" => Value::Long(line as i64),
            b"__file__" => Value::String(PhpString::from_vec(self.source_file.clone())),
            b"__dir__" => {
                let path = String::from_utf8_lossy(&self.source_file);
                let dir = if let Some(pos) = path.rfind('/') {
                    &path[..pos]
                } else {
                    "."
                };
                Value::String(PhpString::from_string(dir.to_string()))
            }
            b"__namespace__" => Value::String(PhpString::from_vec(self.current_namespace.clone())),
            b"__trait__" => Value::String(PhpString::empty()),
            b"true" => Value::True,
            b"false" => Value::False,
            b"null" => Value::Null,
            b"php_eol" => Value::String(PhpString::from_bytes(b"\n")),
            b"php_int_max" => Value::Long(i64::MAX),
            b"php_int_min" => Value::Long(i64::MIN),
            b"php_int_size" => Value::Long(8),
            b"php_major_version" => Value::Long(8),
            b"php_minor_version" => Value::Long(5),
            b"php_version" => Value::String(PhpString::from_bytes(b"8.5.4")),
            b"php_version_id" => Value::Long(80504),
            b"php_maxpathlen" => Value::Long(4096),
            b"php_os" => Value::String(PhpString::from_bytes(b"Linux")),
            b"php_os_family" => Value::String(PhpString::from_bytes(b"Linux")),
            b"php_sapi" => Value::String(PhpString::from_bytes(b"cli")),
            b"php_float_dig" => Value::Long(15),
            b"php_float_epsilon" => Value::Double(f64::EPSILON),
            b"php_float_max" => Value::Double(f64::MAX),
            b"php_float_min" => Value::Double(f64::MIN_POSITIVE),
            b"php_float_inf" => Value::Double(f64::INFINITY),
            b"php_float_nan" => Value::Double(f64::NAN),
            b"php_prefix" => Value::String(PhpString::from_bytes(b"/usr")),
            b"directory_separator" | b"php_separator" => Value::String(PhpString::from_bytes(b"/")),
            b"path_separator" => Value::String(PhpString::from_bytes(b":")),
            // Error reporting constants
            b"e_error" => Value::Long(1),
            b"e_warning" => Value::Long(2),
            b"e_parse" => Value::Long(4),
            b"e_notice" => Value::Long(8),
            b"e_core_error" => Value::Long(16),
            b"e_core_warning" => Value::Long(32),
            b"e_compile_error" => Value::Long(64),
            b"e_compile_warning" => Value::Long(128),
            b"e_user_error" => Value::Long(256),
            b"e_user_warning" => Value::Long(512),
            b"e_user_notice" => Value::Long(1024),
            b"e_strict" => Value::Long(2048),
            b"e_recoverable_error" => Value::Long(4096),
            b"e_deprecated" => Value::Long(8192),
            b"e_user_deprecated" => Value::Long(16384),
            b"e_all" => Value::Long(30719),
            // SEEK constants
            b"seek_set" => Value::Long(0),
            b"seek_cur" => Value::Long(1),
            b"seek_end" => Value::Long(2),
            // Sort constants
            b"sort_regular" => Value::Long(0),
            b"sort_numeric" => Value::Long(1),
            b"sort_string" => Value::Long(2),
            b"sort_locale_string" => Value::Long(5),
            b"sort_natural" => Value::Long(6),
            b"sort_flag_case" => Value::Long(8),
            // Array filter constants
            b"array_filter_use_both" => Value::Long(1),
            b"array_filter_use_key" => Value::Long(2),
            // JSON constants
            b"json_pretty_print" => Value::Long(128),
            b"json_unescaped_unicode" => Value::Long(256),
            b"json_unescaped_slashes" => Value::Long(64),
            b"json_throw_on_error" => Value::Long(4194304),
            // String constants
            b"str_pad_right" => Value::Long(1),
            b"str_pad_left" => Value::Long(0),
            b"str_pad_both" => Value::Long(2),
            // PREG constants
            b"preg_split_no_empty" => Value::Long(1),
            b"preg_split_delim_capture" => Value::Long(2),
            b"preg_split_offset_capture" => Value::Long(4),
            _ => Value::Null,
        }
    }

    /// Validate built-in attributes against the placement target. Returns
    /// an error message if the attribute cannot be placed in this context.
    /// `target` is one of: "class", "function", "method", "parameter",
    /// "property", "class constant", "constant".
    pub(crate) fn validate_internal_attr(name: &[u8], target: &str) -> Option<String> {
        // Strip leading backslash for fully-qualified names
        let bare: &[u8] = if name.first() == Some(&b'\\') {
            &name[1..]
        } else {
            name
        };
        // "Attribute" is only allowed on classes.
        if bare.eq_ignore_ascii_case(b"Attribute") && target != "class" {
            return Some(format!(
                "Attribute \"Attribute\" cannot target {} (allowed targets: class)",
                target
            ));
        }
        // "AllowDynamicProperties" is only allowed on classes.
        if bare.eq_ignore_ascii_case(b"AllowDynamicProperties") && target != "class" {
            return Some(format!(
                "Attribute \"AllowDynamicProperties\" cannot target {} (allowed targets: class)",
                target
            ));
        }
        // "SensitiveParameter" is only allowed on parameters.
        if bare.eq_ignore_ascii_case(b"SensitiveParameter") && target != "parameter" {
            return Some(format!(
                "Attribute \"SensitiveParameter\" cannot target {} (allowed targets: parameter)",
                target
            ));
        }
        // "NoDiscard" is allowed on function and method
        if bare.eq_ignore_ascii_case(b"NoDiscard") && target != "function" && target != "method" {
            return Some(format!(
                "Attribute \"NoDiscard\" cannot target {} (allowed targets: function, method)",
                target
            ));
        }
        // "Deprecated" cannot target parameters or properties.
        if bare.eq_ignore_ascii_case(b"Deprecated") && matches!(target, "parameter" | "property")
        {
            return Some(format!(
                "Attribute \"Deprecated\" cannot target {} (allowed targets: class, function, method, class constant, constant)",
                target
            ));
        }
        // "ReturnTypeWillChange" is only allowed on methods.
        if bare.eq_ignore_ascii_case(b"ReturnTypeWillChange")
            && !target.is_empty()
            && target != "method"
        {
            return Some(format!(
                "Attribute \"ReturnTypeWillChange\" cannot target {} (allowed targets: method)",
                target
            ));
        }
        // Attributes extensions marked internal.
        if let Some(cfg) =
            EXT_INTERNAL_ATTRIBUTES.with(|m| m.borrow().get(&bare.to_ascii_lowercase()).copied())
        {
            let flag = attribute_target_flag(target);
            if flag != 0 && cfg.flags & flag == 0 {
                return Some(format!(
                    "Attribute \"{}\" cannot target {} (allowed targets: {})",
                    String::from_utf8_lossy(bare),
                    target,
                    attribute_target_names(cfg.flags)
                ));
            }
        }
        // Override and Deprecated (their own placement checks, such as a
        // Deprecated class that is not a trait, come later).
        if bare.eq_ignore_ascii_case(b"Override") || bare.eq_ignore_ascii_case(b"Deprecated") {
            let cfg = internal_attribute(bare)?;
            let flag = attribute_target_flag(target);
            if flag != 0 && cfg.flags & flag == 0 {
                return Some(format!(
                    "Attribute \"{}\" cannot target {} (allowed targets: {})",
                    if bare.eq_ignore_ascii_case(b"Override") {
                        "Override"
                    } else {
                        "Deprecated"
                    },
                    target,
                    attribute_target_names(cfg.flags)
                ));
            }
        }
        None
    }

    /// The attributes of a promoted parameter compiled for `target` (the
    /// parameter or the property): internal attributes that cannot target
    /// it but can target the other one are left out (zend_compile_attributes()
    /// with `promoted`).
    fn promoted_attrs(
        &self,
        attrs: &[goro_parser::ast::Attribute],
        target: u32,
        promoted: u32,
    ) -> Vec<goro_parser::ast::Attribute> {
        attrs
            .iter()
            .filter(|a| {
                let name = self.resolve_class_name(&a.name.join(&b'\\'));
                match internal_attribute(&name) {
                    Some(cfg) => {
                        let t = cfg.flags & ATTRIBUTE_TARGET_ALL;
                        t & target != 0 || t & promoted == 0
                    }
                    None => true,
                }
            })
            .cloned()
            .collect()
    }

    /// The attributes of a closure (or of its parameters): its scope is not
    /// known at compile time (zend_is_scope_known()), so self is resolved
    /// when the arguments are evaluated.
    fn compile_closure_attributes(
        &mut self,
        attrs: &[goro_parser::ast::Attribute],
    ) -> Vec<crate::object::RuntimeAttribute> {
        let saved = std::mem::replace(&mut self.attrs_scope_unknown, true);
        let r = self.compile_attributes(attrs);
        self.attrs_scope_unknown = saved;
        r
    }

    /// The attributes of a property hook (a method target).
    fn compile_hook_attributes(
        &mut self,
        attrs: &[goro_parser::ast::Attribute],
    ) -> Vec<crate::object::RuntimeAttribute> {
        self.in_hook_attrs = true;
        let r = self.compile_attributes_target(attrs, "method");
        self.in_hook_attrs = false;
        r
    }

    fn compile_attributes(
        &mut self,
        attrs: &[goro_parser::ast::Attribute],
    ) -> Vec<crate::object::RuntimeAttribute> {
        self.compile_attributes_target(attrs, "")
    }

    /// Same as `compile_attributes`, but additionally validates built-in
    /// attributes against the placement target. If validation fails the
    /// error is queued on the compiler so the executor can raise a fatal
    /// before running the surrounding code.
    fn compile_attributes_target(
        &mut self,
        attrs: &[goro_parser::ast::Attribute],
        target: &str,
    ) -> Vec<crate::object::RuntimeAttribute> {
        // If #[DelayedTargetValidation] is present, skip compile-time target
        // validation for built-in attributes (PHP 8.5).
        let has_delayed = attrs.iter().any(|a| {
            let last = a.name.last().map(|s| s.as_slice()).unwrap_or(&[]);
            last.strip_prefix(b"\\")
                .unwrap_or(last)
                .eq_ignore_ascii_case(b"DelayedTargetValidation")
        });
        let effective_target = if has_delayed { "" } else { target };
        // Check for repeated internal/non-repeatable attributes at compile time.
        // Internal attributes (Attribute, AllowDynamicProperties, SensitiveParameter,
        // NoDiscard, Override, Deprecated, ReturnTypeWillChange, DelayedTargetValidation)
        // are NOT repeatable. The `#[\DelayedTargetValidation]` bypass does NOT apply
        // to repetition errors (per repetition_errors.phpt).
        let internal_non_repeatable: &[&[u8]] = &[
            b"Attribute",
            b"AllowDynamicProperties",
            b"SensitiveParameter",
            b"NoDiscard",
            b"Override",
            b"Deprecated",
            b"ReturnTypeWillChange",
            b"DelayedTargetValidation",
        ];
        for builtin in internal_non_repeatable {
            let occurrences: Vec<_> = attrs
                .iter()
                .filter(|a| {
                    let last = a.name.last().map(|s| s.as_slice()).unwrap_or(&[]);
                    // Strip leading backslash
                    let bare: &[u8] = if last.first() == Some(&b'\\') {
                        &last[1..]
                    } else {
                        last
                    };
                    bare.eq_ignore_ascii_case(builtin)
                })
                .collect();
            if occurrences.len() > 1 {
                let display = std::str::from_utf8(builtin).unwrap_or("");
                self.deferred_fatal_errors
                    .push(format!("Attribute \"{}\" must not be repeated", display));
            }
        }
        // zend_compile_attributes(): argument list errors.
        fn has_empty_array_elem(e: &Expr) -> bool {
            match &e.kind {
                ExprKind::Array(elems) => elems.iter().any(|el| {
                    (el.key.is_none()
                        && matches!(el.value.kind, ExprKind::Null)
                        && el.value.span.start == el.value.span.end)
                        || el.key.as_ref().is_some_and(has_empty_array_elem)
                        || has_empty_array_elem(&el.value)
                }),
                ExprKind::PropertyAccess { object, .. } => has_empty_array_elem(object),
                ExprKind::ArrayAccess { array, index } => {
                    has_empty_array_elem(array)
                        || index.as_deref().is_some_and(has_empty_array_elem)
                }
                ExprKind::UnaryOp { operand, .. } => has_empty_array_elem(operand),
                ExprKind::BinaryOp { left, right, .. } => {
                    has_empty_array_elem(left) || has_empty_array_elem(right)
                }
                _ => false,
            }
        }
        for a in attrs {
            if a.args.iter().any(|arg| has_empty_array_elem(&arg.value)) {
                self.deferred_fatal_errors
                    .push("Cannot use empty array elements in arrays".into());
            }
            let mut seen_named: Vec<&[u8]> = Vec::new();
            for arg in &a.args {
                match &arg.name {
                    Some(n) => {
                        if seen_named.contains(&n.as_slice()) {
                            self.deferred_fatal_errors.push(format!(
                                "Duplicate named parameter ${}",
                                String::from_utf8_lossy(n)
                            ));
                        }
                        seen_named.push(n);
                    }
                    None if !seen_named.is_empty() && !arg.unpack => {
                        self.deferred_fatal_errors
                            .push("Cannot use positional argument after named argument".into());
                    }
                    None => {}
                }
            }
        }
        attrs
            .iter()
            .map(|attr| {
                let name = if attr.name.len() == 1 {
                    self.resolve_class_name(&attr.name[0])
                } else {
                    let mut f = Vec::new();
                    for (i, p) in attr.name.iter().enumerate() {
                        if i > 0 {
                            f.push(b'\\');
                        }
                        f.extend_from_slice(p);
                    }
                    self.resolve_class_name(&f)
                };
                if !effective_target.is_empty() {
                    if let Some(msg) = Self::validate_internal_attr(&name, effective_target)
                        .or_else(|| {
                            // The validator of an extension's internal attribute
                            // (compile time only).
                            let flag = attribute_target_flag(effective_target);
                            let v = internal_attribute(&name)?.validator?;
                            if flag != 0 { v(flag) } else { None }
                        })
                    {
                        self.deferred_fatal_errors.push(msg);
                    }
                }
                // Attribute argument lists cannot use unpacking (...) per PHP.
                for arg in &attr.args {
                    if arg.unpack {
                        self.deferred_fatal_errors
                            .push("Cannot use unpacking in attribute argument list".to_string());
                        break;
                    }
                }
                // Attribute argument expressions must be constant expressions.
                for arg in &attr.args {
                    if let Some(msg) = Self::const_expr_error(&arg.value, true) {
                        self.deferred_fatal_errors.push(msg);
                        break;
                    }
                }
                let mut ac = Compiler::new();
                ac.const_property_name = self.const_property_name.clone();
                ac.current_namespace = self.current_namespace.clone();
                ac.use_map = self.use_map.clone();
                ac.use_function_map = self.use_function_map.clone();
                ac.use_const_map = self.use_const_map.clone();
                ac.source_file = self.source_file.clone();
                ac.op_array.strict_types = self.op_array.strict_types;
                // Where the attribute is used: newInstance() calls the
                // constructor from there.
                ac.op_array.decl_line = attr.line;
                ac.op_array.filename = self.source_file.clone();
                if let Some(cls) = &self.current_class {
                    ac.current_class = Some(cls.clone());
                    ac.op_array.scope_class =
                        Some(cls.iter().map(|b| b.to_ascii_lowercase()).collect());
                }
                // In a trait or a closure, self is the scope the arguments
                // are evaluated in.
                if self.attrs_scope_unknown || self.is_in_trait || self.in_trait_body {
                    ac.in_const_expr = true;
                    ac.is_in_trait = true;
                    ac.keep_relative_class_names = true;
                }
                if let Some(p) = &self.current_parent_class {
                    ac.current_parent_class = Some(p.clone());
                }
                let arr_tmp = ac.op_array.alloc_temp();
                ac.op_array.emit(Op {
                    opcode: OpCode::ArrayNew,
                    op1: OperandType::Unused,
                    op2: OperandType::Unused,
                    result: OperandType::Tmp(arr_tmp),
                    line: 0,
                });
                for arg in &attr.args {
                    if let Ok(val) = ac.compile_expr(&arg.value) {
                        if let Some(an) = &arg.name {
                            let kl = ac
                                .op_array
                                .add_literal(Value::String(PhpString::from_vec(an.clone())));
                            ac.op_array.emit(Op {
                                opcode: OpCode::ArraySet,
                                op1: OperandType::Tmp(arr_tmp),
                                op2: val,
                                result: OperandType::Const(kl),
                                line: 0,
                            });
                        } else {
                            ac.op_array.emit(Op {
                                opcode: OpCode::ArrayAppend,
                                op1: OperandType::Tmp(arr_tmp),
                                op2: val,
                                result: OperandType::Unused,
                                line: 0,
                            });
                        }
                    }
                }
                ac.op_array.emit(Op {
                    opcode: OpCode::Return,
                    op1: OperandType::Tmp(arr_tmp),
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line: 0,
                });
                // Reflection's rendering of each argument (ReflectionAttribute::__toString).
                ac.op_array.param_default_repr = attr
                    .args
                    .iter()
                    .map(|a| {
                        self.default_value_repr(&a.value).map(|r| match &a.name {
                            Some(n) => format!("{} = {}", String::from_utf8_lossy(n), r),
                            None => r,
                        })
                    })
                    .collect();
                // validate_nodiscard(): not on a property hook.
                let validation_error = (self.in_hook_attrs
                    && name
                        .strip_prefix(b"\\")
                        .unwrap_or(&name)
                        .eq_ignore_ascii_case(b"NoDiscard"))
                .then(|| "#[\\NoDiscard] is not supported for property hooks".to_string());
                if let (Some(e), false) = (&validation_error, has_delayed) {
                    self.deferred_fatal_errors.push(e.clone());
                }
                crate::object::RuntimeAttribute {
                    name,
                    args_op_array: ac.op_array,
                    validation_error: validation_error.filter(|_| has_delayed),
                }
            })
            .collect()
    }

    /// Compile a class-level constant expression (class constant or
    /// property default) that cannot be folded at compile time into a thunk
    /// evaluated with the class scope on first use, like
    /// zend_update_class_constants(). The thunk is stored with the class's
    /// constant closures; the returned marker takes the value's place.
    /// The backing value of an enum case naming a constant: magic
    /// constants fold, others are evaluated (in a "[constant expression]"
    /// frame, like ZEND_AST_CONST_ENUM_INIT) when the case is first used.
    fn enum_case_const_value(
        &mut self,
        expr: &Expr,
        name_lower: &[u8],
        closures: &mut Vec<OpArray>,
        qualified_name: &[u8],
        extends: Option<&[u8]>,
    ) -> CompileResult<Value> {
        let v = self.resolve_class_const_magic(name_lower, qualified_name, expr.span.line);
        if !matches!(v, Value::Null) || name_lower == b"null" || name_lower == b"\\null" {
            return Ok(v);
        }
        let marker = self.compile_const_thunk(expr, closures, qualified_name, extends)?;
        if let Some(op) = closures.last_mut() {
            op.decl_line = expr.span.line;
        }
        Ok(marker)
    }

    fn compile_const_thunk(
        &mut self,
        expr: &Expr,
        closures: &mut Vec<OpArray>,
        qualified_name: &[u8],
        extends: Option<&[u8]>,
    ) -> CompileResult<Value> {
        let mut tc = Compiler::new();
        tc.const_property_name = self.const_property_name.clone();
        tc.current_namespace = self.current_namespace.clone();
        tc.use_map = self.use_map.clone();
        tc.use_function_map = self.use_function_map.clone();
        tc.use_const_map = self.use_const_map.clone();
        tc.source_file = self.source_file.clone();
        tc.op_array.filename = self.source_file.clone();
        tc.op_array.strict_types = self.op_array.strict_types;
        tc.current_class = Some(qualified_name.to_vec());
        tc.current_parent_class = extends.map(|p| self.resolve_class_name(p));
        tc.op_array.scope_class = Some(qualified_name.to_ascii_lowercase());
        let name = format!("{}{}", CONST_THUNK_PREFIX, next_closure_id()).into_bytes();
        tc.op_array.name = name.clone();
        // The expression's source: thunks of trait / class constants are
        // compared by it.
        tc.op_array.display_name = expr_to_source_string(expr).into_bytes();
        // Its AST export, shown by reflection while it is unevaluated.
        let repr = self.default_value_repr_scoped(expr, None);
        tc.op_array.set_param_default_repr(0, repr);
        tc.keep_relative_class_names = true;
        tc.in_const_expr = true;
        tc.is_in_trait = self.in_trait_body;
        // A bare global constant is looked up directly (no AST evaluation,
        // so no "[constant expression]" frame and errors at the access
        // line): decl_line 0 marks it.
        tc.op_array.decl_line = if matches!(
            expr.kind,
            ExprKind::ConstantAccess(_) | ExprKind::Identifier(_)
        ) {
            0
        } else {
            expr.span.line
        };
        let v = tc.compile_expr(expr)?;
        tc.op_array.emit(Op {
            opcode: OpCode::Return,
            op1: v,
            op2: OperandType::Unused,
            result: OperandType::Unused,
            line: expr.span.line,
        });
        closures.push(tc.op_array);
        let mut marker = b"__deferred_thunk__::".to_vec();
        marker.extend_from_slice(&name);
        Ok(Value::String(PhpString::from_vec(marker)))
    }

    /// `'\foo'()`: a string literal callee is a function name, resolved at
    /// compile time (zend_compile_function_name(): the leading `\` goes).
    #[inline(never)]
    fn compile_fq_string_call(&mut self, expr: &Expr) -> CompileResult<OperandType> {
        let mut e = expr.clone();
        if let ExprKind::FunctionCall { name, .. } = &mut e.kind {
            if let ExprKind::String(s) = &mut name.kind {
                s.remove(0);
            }
        }
        self.compile_expr(&e)
    }

    fn resolve_class_name(&self, name: &[u8]) -> Vec<u8> {
        // Special names are never resolved
        if name.eq_ignore_ascii_case(b"self")
            || name.eq_ignore_ascii_case(b"parent")
            || name.eq_ignore_ascii_case(b"static")
        {
            return name.to_vec();
        }

        // Fully qualified name (starts with \) -- strip leading \ and use as-is
        if name.starts_with(b"\\") {
            return name[1..].to_vec();
        }
        // Namespace-relative name: namespace\Foo -> <current ns>\Foo
        if name.len() > 10 && name[..10].eq_ignore_ascii_case(b"namespace\\") {
            let rest = &name[10..];
            if self.current_namespace.is_empty() {
                return rest.to_vec();
            }
            let mut r = self.current_namespace.clone();
            r.push(b'\\');
            r.extend_from_slice(rest);
            return r;
        }

        if let Some(pos) = name.iter().position(|&b| b == b'\\') {
            // Qualified name (contains backslash but doesn't start with one)
            // Check if the first part matches a use alias
            let first_part = &name[..pos];
            let first_part_lower: Vec<u8> =
                first_part.iter().map(|b| b.to_ascii_lowercase()).collect();
            if let Some(resolved) = self.use_map.get(&first_part_lower) {
                let mut result = resolved.clone();
                result.extend_from_slice(&name[pos..]);
                return result;
            }
            // Otherwise, prefix with namespace
            if self.current_namespace.is_empty() {
                name.to_vec()
            } else {
                self.prefix_with_namespace(name)
            }
        } else {
            // Unqualified name
            let name_lower: Vec<u8> = name.iter().map(|b| b.to_ascii_lowercase()).collect();
            if let Some(resolved) = self.use_map.get(&name_lower) {
                return resolved.clone();
            }
            // Prefix with namespace
            self.prefix_with_namespace(name)
        }
    }

    /// Resolve a function name. Rules similar to class names, but:
    /// - Uses use_function_map instead of use_map
    /// - Unqualified function calls fall back to global at RUNTIME (not compile time),
    ///   so we still prefix with namespace, and VM handles fallback
    fn resolve_function_name(&self, name: &[u8]) -> Vec<u8> {
        // Fully qualified name (starts with \) -- strip leading \ and use as-is
        if name.starts_with(b"\\") {
            return name[1..].to_vec();
        }
        // `namespace\foo` is relative to the current namespace.
        if name.len() > 10 && name[..10].eq_ignore_ascii_case(b"namespace\\") {
            return self.prefix_with_namespace(&name[10..]);
        }

        if let Some(pos) = name.iter().position(|&b| b == b'\\') {
            // Qualified name
            let first_part = &name[..pos];
            let first_part_lower: Vec<u8> =
                first_part.iter().map(|b| b.to_ascii_lowercase()).collect();
            if let Some(resolved) = self.use_function_map.get(&first_part_lower) {
                let mut result = resolved.clone();
                result.extend_from_slice(&name[pos..]);
                return result;
            }
            // Also check regular use map for namespace aliases
            if let Some(resolved) = self.use_map.get(&first_part_lower) {
                let mut result = resolved.clone();
                result.extend_from_slice(&name[pos..]);
                return result;
            }
            if self.current_namespace.is_empty() {
                name.to_vec()
            } else {
                self.prefix_with_namespace(name)
            }
        } else {
            // Unqualified name - check function use map first
            let name_lower: Vec<u8> = name.iter().map(|b| b.to_ascii_lowercase()).collect();
            if let Some(resolved) = self.use_function_map.get(&name_lower) {
                return resolved.clone();
            }
            // Prefix with namespace (VM will fall back to global)
            self.prefix_with_namespace(name)
        }
    }

    /// INIT_FCALL's result operand for a call of function `name` (as
    /// written) resolved to `resolved`: a constant when the namespaced name
    /// has no global fallback (qualified, fully qualified or imported with
    /// `use function`: ZEND_INIT_FCALL_BY_NAME), Unused otherwise.
    #[inline(never)]
    fn fcall_no_fallback_flag(&mut self, name: &[u8], resolved: &[u8]) -> OperandType {
        if !resolved.contains(&b'\\') {
            return OperandType::Unused;
        }
        let imported = || {
            self.use_function_map
                .contains_key(&name.to_ascii_lowercase())
        };
        if name.contains(&b'\\') || imported() {
            OperandType::Const(self.op_array.add_literal(Value::True))
        } else {
            OperandType::Unused
        }
    }

    /// Compile and emit SendVal/SendNamedVal/SendUnpack opcodes for function call arguments.
    fn compile_send_args(&mut self, args: &[Argument], line: u32) -> CompileResult<()> {
        self.compile_send_args_with_name(args, line, None)
    }

    fn compile_send_args_with_name(
        &mut self,
        args: &[Argument],
        line: u32,
        func_name: Option<&[u8]>,
    ) -> CompileResult<()> {
        let mut has_named = false;
        let mut has_unpack = false;
        for (i, arg) in args.iter().enumerate() {
            // The operand of a pipe: a temporary (ZEND_SEND_VAL_EX).
            if matches!(&arg.value.kind, ExprKind::Variable(n) if n.starts_with(PIPE_ALIAS_PREFIX))
            {
                let v = self.compile_expr(&arg.value)?;
                let pos_idx = self.op_array.add_literal(Value::Long(i as i64));
                let kind = self.op_array.add_literal(Value::Long(1));
                self.op_array.emit(Op {
                    opcode: OpCode::SendValChecked,
                    op1: v,
                    op2: OperandType::Const(pos_idx),
                    result: OperandType::Const(kind),
                    line,
                });
                continue;
            }
            if arg.unpack {
                // Cannot use argument unpacking after named arguments
                if has_named {
                    return Err(CompileError {
                        message: "Cannot use argument unpacking after named arguments".into(),
                        line,
                    });
                }
                has_unpack = true;
                let val = self.compile_expr(&arg.value)?;
                self.op_array.emit(Op {
                    opcode: OpCode::SendUnpack,
                    op1: val,
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line,
                });
            } else if let Some(name) = &arg.name {
                has_named = true;
                let name_idx = self
                    .op_array
                    .add_literal(Value::String(PhpString::from_vec(name.clone())));
                // An array element or property given to a by-reference
                // parameter is fetched for writing (decided at runtime, as
                // ZEND_FETCH_DIM_FUNC_ARG does).
                let dim_or_prop = matches!(
                    &arg.value.kind,
                    ExprKind::ArrayAccess { index: Some(_), .. }
                        | ExprKind::PropertyAccess {
                            nullsafe: false,
                            ..
                        }
                );
                let var_base = {
                    let mut base = &arg.value;
                    while let ExprKind::ArrayAccess { array, .. } = &base.kind {
                        base = array;
                    }
                    matches!(
                        base.kind,
                        ExprKind::Variable(_) | ExprKind::PropertyAccess { .. }
                    )
                };
                if dim_or_prop && var_base {
                    let jmp_ref = self.op_array.emit(Op {
                        opcode: OpCode::JmpIfArgByRef,
                        op1: OperandType::JmpTarget(0),
                        op2: OperandType::Const(name_idx),
                        result: OperandType::Unused,
                        line,
                    });
                    let v = self.compile_expr(&arg.value)?;
                    self.op_array.emit(Op {
                        opcode: OpCode::SendNamedVal,
                        op1: v,
                        op2: OperandType::Const(name_idx),
                        result: OperandType::Unused,
                        line,
                    });
                    let jmp_end = self.op_array.emit(Op {
                        opcode: OpCode::Jmp,
                        op1: OperandType::JmpTarget(0),
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line,
                    });
                    let ref_start = self.op_array.current_offset();
                    self.op_array.patch_jump(jmp_ref, ref_start);
                    let ref_tmp = match &arg.value.kind {
                        ExprKind::ArrayAccess {
                            array,
                            index: Some(idx_expr),
                        } => {
                            let arr_op = self.compile_dim_write_base(array)?;
                            let idx_op = self.compile_expr(idx_expr)?;
                            let t = self.op_array.alloc_temp();
                            self.op_array.emit(Op {
                                opcode: OpCode::ArrayGetRef,
                                op1: arr_op,
                                op2: idx_op,
                                result: OperandType::Tmp(t),
                                line,
                            });
                            t
                        }
                        ExprKind::PropertyAccess {
                            object, property, ..
                        } => self.compile_property_ref(object, property, line)?,
                        _ => unreachable!(),
                    };
                    // (result = Const: the reference is sent as is)
                    let keep_ref = self.op_array.add_literal(Value::True);
                    self.op_array.emit(Op {
                        opcode: OpCode::SendNamedVal,
                        op1: OperandType::Tmp(ref_tmp),
                        op2: OperandType::Const(name_idx),
                        result: OperandType::Const(keep_ref),
                        line,
                    });
                    let end = self.op_array.current_offset();
                    self.op_array.patch_jump(jmp_end, end);
                    continue;
                }
                let val = self.compile_expr(&arg.value)?;
                self.op_array.emit(Op {
                    opcode: OpCode::SendNamedVal,
                    op1: val,
                    op2: OperandType::Const(name_idx),
                    result: OperandType::Unused,
                    line,
                });
            } else {
                // Cannot use positional argument after named argument or after unpacking
                if has_named {
                    return Err(CompileError {
                        message: "Cannot use positional argument after named argument".into(),
                        line,
                    });
                }
                if has_unpack {
                    return Err(CompileError {
                        message: "Cannot use positional argument after argument unpacking".into(),
                        line,
                    });
                }
                // `sort($$n)`: the array-taking builtins get the variable
                // fetched for writing, like a CV.
                let rewritten;
                let arg = if let ExprKind::DynamicVariable(inner) = &arg.value.kind {
                    if i == 0 && Self::is_array_ref_builtin(func_name) {
                        rewritten = Argument {
                            value: self.dynvar_as_cv_expr(&arg.value, inner, 0)?,
                            ..arg.clone()
                        };
                        &rewritten
                    } else {
                        arg
                    }
                } else {
                    arg
                };
                // Check if this argument position is by-ref for known builtins
                let mut is_byref = Self::is_builtin_byref_param(func_name, i);
                // array_multisort() takes its arguments by "prefer-ref": variables
                // are passed by reference, other expressions (sort flags) by value.
                if func_name
                    .map(|n| n.eq_ignore_ascii_case(b"array_multisort"))
                    .unwrap_or(false)
                {
                    is_byref = Self::is_writable_lvalue(&arg.value);
                }
                // Builtins taking `array &$array`: goro passes arrays by shared
                // handle, but the by-reference diagnostics still apply.
                if !is_byref && i == 0 && Self::is_array_ref_builtin(func_name) {
                    if let ExprKind::Variable(vname) = &arg.value.kind {
                        if vname.as_slice() != b"this" && !Self::is_superglobal_name(vname) {
                            // SEND_REF fetches for write: no "Undefined variable".
                            let cv = self.op_array.get_or_create_cv(vname);
                            self.op_array.emit(Op {
                                opcode: OpCode::InitCvNull,
                                op1: OperandType::Cv(cv),
                                op2: OperandType::Unused,
                                result: OperandType::Unused,
                                line,
                            });
                        }
                    }
                }
                if !is_byref && !Self::is_writable_lvalue(&arg.value) {
                    if let Some(fname) = func_name {
                        let array_ref = i == 0 && Self::is_array_ref_builtin(Some(fname));
                        if array_ref {
                            let is_call = matches!(
                                &arg.value.kind,
                                ExprKind::FunctionCall { .. }
                                    | ExprKind::MethodCall { .. }
                                    | ExprKind::StaticMethodCall { .. }
                            );
                            let (opcode, msg) = if is_call {
                                (
                                    OpCode::EmitNotice,
                                    b"Only variables should be passed by reference".to_vec(),
                                )
                            } else {
                                let disp = String::from_utf8_lossy(fname).to_string();
                                (OpCode::ThrowErrorMsg, format!("{}(): Argument #1 ($array) could not be passed by reference", disp).into_bytes())
                            };
                            let msg_idx = self.op_array.add_literal(Value::String(
                                crate::string::PhpString::from_vec(msg),
                            ));
                            self.op_array.emit(Op {
                                opcode,
                                op1: OperandType::Const(msg_idx),
                                op2: OperandType::Unused,
                                result: OperandType::Unused,
                                line,
                            });
                        }
                    }
                }
                // If by-ref, check that the arg is a variable/writable expression
                // (not a function call, method call, constant, etc.)
                if is_byref && !Self::is_writable_lvalue(&arg.value) {
                    // A function result gets the notice (ZEND_SEND_VAR_NO_REF);
                    // any other expression cannot be passed by reference at
                    // all (ZEND_SEND_VAL_EX throws).
                    let is_call = matches!(
                        &arg.value.kind,
                        ExprKind::FunctionCall { .. }
                            | ExprKind::MethodCall { .. }
                            | ExprKind::StaticMethodCall { .. }
                    ) && !self.is_special_builtin_call(&arg.value);
                    let info = func_name.and_then(|f| {
                        crate::arginfo::lookup(&f.to_ascii_lowercase())
                            .and_then(|fi| fi.params.get(i).map(|p| (fi.name, p.name)))
                    });
                    let (opcode, msg) = match (is_call, info) {
                        (false, Some((f, p))) => (
                            OpCode::ThrowErrorMsg,
                            format!(
                                "{}(): Argument #{} (${}) could not be passed by reference",
                                f,
                                i + 1,
                                p
                            )
                            .into_bytes(),
                        ),
                        _ => (
                            OpCode::EmitNotice,
                            b"Only variables should be passed by reference".to_vec(),
                        ),
                    };
                    let msg_idx = self
                        .op_array
                        .add_literal(Value::String(crate::string::PhpString::from_vec(msg)));
                    self.op_array.emit(Op {
                        opcode,
                        op1: OperandType::Const(msg_idx),
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line,
                    });
                }
                // For by-ref builtin args on $arr[$key], compile as
                // ArrayGetRef → SendRef(tmp) so writes through the
                // Reference land back in the array slot (and the slot
                // is auto-vivified instead of producing an
                // "Undefined array key" warning).
                // Unknown callee at compile time: an array element or property
                // argument may need to be passed by reference. Decide at runtime.
                let dim_or_prop = matches!(
                    &arg.value.kind,
                    ExprKind::ArrayAccess { .. }
                        | ExprKind::StaticPropertyAccess { .. }
                        | ExprKind::DynamicStaticPropertyAccess { .. }
                        | ExprKind::DynamicVariable(_)
                ) || matches!(
                    &arg.value.kind,
                    ExprKind::PropertyAccess {
                        nullsafe: false,
                        ..
                    }
                );
                let is_append = {
                    let mut e = &arg.value;
                    let mut found = false;
                    while let ExprKind::ArrayAccess { array, index } = &e.kind {
                        if index.is_none() {
                            found = true;
                        }
                        e = array;
                    }
                    found
                };
                // Callee declared earlier in this file: its by-ref-ness is known.
                let known_byval = func_name
                    .and_then(|n| {
                        let lower: Vec<u8> = n.iter().map(|b| b.to_ascii_lowercase()).collect();
                        let lower = lower
                            .strip_prefix(b"\\")
                            .map(|x| x.to_vec())
                            .unwrap_or(lower);
                        self.op_array
                            .child_functions
                            .iter()
                            // (a function declared further down is not
                            // declared yet when the call is compiled)
                            .find(|f| f.name.eq_ignore_ascii_case(&lower) && f.decl_line <= line)
                            .map(|f| {
                                !f.by_ref_params.get(i).copied().unwrap_or(false)
                                    && f.variadic_param.is_none()
                            })
                    })
                    .unwrap_or(false);
                if is_append && known_byval {
                    return Err(CompileError {
                        message: "Cannot use [] for reading".into(),
                        line,
                    });
                }
                if !is_byref && dim_or_prop && !known_byval {
                    let pos_idx = self.op_array.add_literal(Value::Long(i as i64));
                    let jmp_ref = self.op_array.emit(Op {
                        opcode: OpCode::JmpIfArgByRef,
                        op1: OperandType::JmpTarget(0),
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line,
                    });
                    if is_append {
                        self.compile_throw_error(b"Cannot use [] for reading", line)?;
                    } else {
                        let v = self.compile_expr(&arg.value)?;
                        self.op_array.emit(Op {
                            opcode: OpCode::SendVal,
                            op1: v,
                            op2: OperandType::Const(pos_idx),
                            result: OperandType::Unused,
                            line,
                        });
                    }
                    let jmp_end = self.op_array.emit(Op {
                        opcode: OpCode::Jmp,
                        op1: OperandType::JmpTarget(0),
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line,
                    });
                    let ref_start = self.op_array.current_offset();
                    self.op_array.patch_jump(jmp_ref, ref_start);
                    let mut base = &arg.value;
                    loop {
                        match &base.kind {
                            ExprKind::ArrayAccess { array, .. } => base = array,
                            ExprKind::PropertyAccess {
                                object,
                                nullsafe: false,
                                ..
                            } => base = object,
                            _ => break,
                        }
                    }
                    let temp_base = !matches!(
                        base.kind,
                        ExprKind::Variable(_)
                            | ExprKind::DynamicVariable(_)
                            | ExprKind::PropertyAccess { .. }
                            | ExprKind::StaticPropertyAccess { .. }
                            | ExprKind::DynamicStaticPropertyAccess { .. }
                            | ExprKind::FunctionCall { .. }
                            | ExprKind::MethodCall { .. }
                            | ExprKind::StaticMethodCall { .. }
                            | ExprKind::DynamicStaticMethodCall { .. }
                    ) || self.is_special_builtin_call(base);
                    if temp_base {
                        self.compile_throw_error(
                            b"Cannot use temporary expression in write context",
                            line,
                        )?;
                        let end = self.op_array.current_offset();
                        self.op_array.patch_jump(jmp_end, end);
                        continue;
                    }
                    if let ExprKind::DynamicVariable(inner) = &arg.value.kind {
                        // FETCH_FUNC_ARG of `$$n` for a by-reference parameter.
                        let cv = self.compile_dynvar_fetch(inner, 0, line)?;
                        self.op_array.emit(Op {
                            opcode: OpCode::SendRef,
                            op1: cv,
                            op2: OperandType::Const(pos_idx),
                            result: OperandType::Unused,
                            line,
                        });
                        let end = self.op_array.current_offset();
                        self.op_array.patch_jump(jmp_end, end);
                        continue;
                    }
                    let ref_tmp = match &arg.value.kind {
                        ExprKind::ArrayAccess { array, index } => {
                            let arr_op = self.compile_dim_write_base(array)?;
                            let idx_op = match index {
                                Some(idx_expr) => self.compile_expr(idx_expr)?,
                                None => OperandType::Unused,
                            };
                            let t = self.op_array.alloc_temp();
                            self.op_array.emit(Op {
                                opcode: OpCode::ArrayGetRef,
                                op1: arr_op,
                                op2: idx_op,
                                result: OperandType::Tmp(t),
                                line,
                            });
                            t
                        }
                        ExprKind::PropertyAccess {
                            object, property, ..
                        } => self.compile_property_ref(object, property, line)?,
                        ExprKind::StaticPropertyAccess { .. }
                        | ExprKind::DynamicStaticPropertyAccess { .. } => {
                            self.emit_static_prop_fetch(OpCode::StaticPropGetRef, &arg.value)?
                        }
                        _ => unreachable!(),
                    };
                    self.op_array.emit(Op {
                        opcode: OpCode::SendRef,
                        op1: OperandType::Tmp(ref_tmp),
                        op2: OperandType::Const(pos_idx),
                        result: OperandType::Unused,
                        line,
                    });
                    let end = self.op_array.current_offset();
                    self.op_array.patch_jump(jmp_end, end);
                    continue;
                }
                if !is_byref
                    && !known_byval
                    && func_name.is_some()
                    && Self::is_call_expr(&arg.value)
                {
                    // f(g()) with f's parameter by reference: g()'s returned
                    // reference is passed; a by-value result raises a notice.
                    // g() is compiled once (keeping a returned reference) and
                    // the by-value send drops the reference: compiling it per
                    // path would be exponential in the nesting of such calls.
                    let pos_idx = self.op_array.add_literal(Value::Long(i as i64));
                    let v = self.compile_expr(&arg.value)?;
                    self.mark_ref_call(&v);
                    let jmp_ref = self.op_array.emit(Op {
                        opcode: OpCode::JmpIfArgByRef,
                        op1: OperandType::JmpTarget(0),
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line,
                    });
                    let deref_flag = self.op_array.add_literal(Value::True);
                    self.op_array.emit(Op {
                        opcode: OpCode::SendVal,
                        op1: v,
                        op2: OperandType::Const(pos_idx),
                        // SendVal with a result operand: pass the value, not
                        // a reference the call may have returned.
                        result: OperandType::Const(deref_flag),
                        line,
                    });
                    let jmp_end = self.op_array.emit(Op {
                        opcode: OpCode::Jmp,
                        op1: OperandType::JmpTarget(0),
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line,
                    });
                    let ref_start = self.op_array.current_offset();
                    self.op_array.patch_jump(jmp_ref, ref_start);
                    let msg_idx = self
                        .op_array
                        .add_literal(Value::String(PhpString::from_bytes(
                            b"Only variables should be passed by reference",
                        )));
                    let cond_idx = self.op_array.add_literal(Value::Long(1));
                    self.op_array.emit(Op {
                        opcode: OpCode::EmitNotice,
                        op1: OperandType::Const(msg_idx),
                        op2: OperandType::Const(cond_idx),
                        result: OperandType::Unused,
                        line,
                    });
                    self.op_array.emit(Op {
                        opcode: OpCode::SendRef,
                        op1: v,
                        op2: OperandType::Const(pos_idx),
                        result: OperandType::Unused,
                        line,
                    });
                    let end = self.op_array.current_offset();
                    self.op_array.patch_jump(jmp_end, end);
                    continue;
                }
                let val = if is_byref {
                    if let ExprKind::ArrayAccess { array, index } = &arg.value.kind {
                        if let Some(idx_expr) = index {
                            let arr_op = self.compile_expr(array)?;
                            let idx_op = self.compile_expr(idx_expr)?;
                            let ref_tmp = self.op_array.alloc_temp();
                            self.op_array.emit(Op {
                                opcode: OpCode::ArrayGetRef,
                                op1: arr_op,
                                op2: idx_op,
                                result: OperandType::Tmp(ref_tmp),
                                line,
                            });
                            OperandType::Tmp(ref_tmp)
                        } else {
                            self.compile_expr(&arg.value)?
                        }
                    } else if matches!(
                        &arg.value.kind,
                        ExprKind::StaticPropertyAccess { .. }
                            | ExprKind::DynamicStaticPropertyAccess { .. }
                    ) {
                        OperandType::Tmp(
                            self.emit_static_prop_fetch(OpCode::StaticPropGetRef, &arg.value)?,
                        )
                    } else if let ExprKind::PropertyAccess {
                        object,
                        property,
                        nullsafe: false,
                    } = &arg.value.kind
                    {
                        // f($obj->prop) with a by-ref builtin parameter: pass
                        // the property slot's reference
                        OperandType::Tmp(self.compile_property_ref(object, property, line)?)
                    } else if let ExprKind::DynamicVariable(inner) = &arg.value.kind {
                        self.compile_dynvar_fetch(inner, 0, line)?
                    } else {
                        self.compile_expr(&arg.value)?
                    }
                } else {
                    self.compile_expr(&arg.value)?
                };
                let pos_idx = self.op_array.add_literal(Value::Long(i as i64));
                // A non-variable passed where the callee (known at run time)
                // may take a reference: SEND_VAR_NO_REF_EX for call results
                // (notice), SEND_VAL_EX for other expressions (Error).
                let checked = if is_byref {
                    None
                } else {
                    match &arg.value.kind {
                        // A nullsafe chain is not a variable (SEND_VAL_EX).
                        _ if expr_is_in_nullsafe_chain(&arg.value) => Some(1),
                        // `[&$a] = $v` / `list(&$a) = $v` is the variable $v
                        // (a destructuring without references is a value).
                        ExprKind::Assign { target, .. }
                            if matches!(&target.kind, ExprKind::Array(elems)
                                if Self::list_has_ref(elems)) =>
                        {
                            None
                        }
                        // A call compiled to a VM builtin yields a TMP, and
                        // $GLOBALS is passed like one (SEND_VAL_EX).
                        ExprKind::FunctionCall { .. }
                            if self.is_special_builtin_call(&arg.value) =>
                        {
                            Some(1)
                        }
                        ExprKind::Variable(n) if n.as_slice() == b"GLOBALS" => Some(1),
                        ExprKind::FunctionCall { .. }
                        | ExprKind::MethodCall { .. }
                        | ExprKind::StaticMethodCall { .. }
                        | ExprKind::DynamicStaticMethodCall { .. }
                        | ExprKind::New { .. }
                        | ExprKind::Include { .. } => Some(0),
                        ExprKind::Variable(_)
                        | ExprKind::DynamicVariable(_)
                        | ExprKind::PropertyAccess { .. }
                        | ExprKind::StaticPropertyAccess { .. }
                        | ExprKind::DynamicStaticPropertyAccess { .. }
                        | ExprKind::ArrayAccess { .. }
                        | ExprKind::AssignRef { .. }
                        | ExprKind::Spread(_) => None,
                        _ => Some(1),
                    }
                };
                let checked_kind = checked
                    .map(|kind| OperandType::Const(self.op_array.add_literal(Value::Long(kind))));
                self.op_array.emit(Op {
                    opcode: if is_byref {
                        OpCode::SendRef
                    } else if checked.is_some() {
                        OpCode::SendValChecked
                    } else {
                        OpCode::SendVal
                    },
                    op1: val,
                    op2: OperandType::Const(pos_idx),
                    result: checked_kind.unwrap_or(OperandType::Unused),
                    line,
                });
            }
        }
        Ok(())
    }

    /// Extract the numeric level from a break/continue expression.
    /// `break` and `break 1` both return 1 (innermost loop).
    /// `break 2` returns 2 (two levels out), etc.
    /// Returns (level, is_non_integer). level=0 means invalid (0 literal), is_non_integer=true means variable/expr operand.
    /// Check if an expression is a writable lvalue (variable, property access, array access)
    /// Used to determine if a by-ref argument should emit "Only variables should be passed by reference"
    fn is_writable_lvalue(expr: &Expr) -> bool {
        match &expr.kind {
            // $GLOBALS is a read-only copy of the symbol table (PHP 8.1+).
            ExprKind::Variable(name) => name.as_slice() != b"GLOBALS",
            ExprKind::DynamicVariable(_) => true,
            ExprKind::PropertyAccess { nullsafe, .. } => !nullsafe,
            ExprKind::StaticPropertyAccess { .. } => true,
            ExprKind::ArrayAccess { .. } => true,
            _ => false,
        }
    }

    fn extract_break_continue_level(level_expr: &Option<Expr>) -> (usize, bool) {
        match level_expr {
            Some(expr) => match &expr.kind {
                ExprKind::Int(n) => (*n as usize, false),
                _ => (0, true), // Non-integer operand (variable expression)
            },
            None => (1, false),
        }
    }

    /// Build a map from parser anonymous class names (__anonymous_class_N) to PHP NUL-byte names.
    /// Must be called before hoisting/compilation so child compilers can inherit the map.
    fn build_anon_class_name_map(&mut self, stmts: &[Statement]) {
        for stmt in stmts {
            match &stmt.kind {
                StmtKind::ClassDecl {
                    name,
                    extends,
                    implements,
                    ..
                } if name.starts_with(b"__anonymous_class_") => {
                    let counter_part = &name[b"__anonymous_class_".len()..];
                    let counter: u32 = std::str::from_utf8(counter_part)
                        .ok()
                        .and_then(|s| s.parse().ok())
                        .unwrap_or(0);
                    // Base name is the fully qualified parent/interface name (as PHP uses it)
                    let base: Vec<u8> = if let Some(p) = extends.as_ref() {
                        // resolve_class_name uses current namespace state
                        self.resolve_class_name(p)
                    } else if let Some(iface) = implements.first() {
                        self.resolve_class_name(iface)
                    } else {
                        b"class".to_vec()
                    };
                    let file = self.source_file.clone();
                    let line = stmt.span.line;
                    let mut anon_name = base;
                    anon_name.extend_from_slice(b"@anonymous\x00");
                    anon_name.extend_from_slice(&file);
                    anon_name.push(b':');
                    anon_name.extend_from_slice(line.to_string().as_bytes());
                    anon_name.push(b'$');
                    anon_name.extend_from_slice(format!("{:x}", counter).as_bytes());
                    self.anon_class_name_map.insert(name.to_vec(), anon_name);
                }
                StmtKind::NamespaceDecl { name, body } => {
                    // Track namespace state for correct class name resolution
                    let saved_ns = self.current_namespace.clone();
                    let saved_use_map = self.use_map.clone();
                    if let Some(parts) = name {
                        let mut ns = Vec::new();
                        for (i, part) in parts.iter().enumerate() {
                            if i > 0 {
                                ns.push(b'\\');
                            }
                            ns.extend_from_slice(part);
                        }
                        self.current_namespace = ns;
                    } else {
                        self.current_namespace = Vec::new();
                    }
                    self.use_map = HashMap::new();
                    if let Some(body_stmts) = body {
                        self.build_anon_class_name_map(body_stmts);
                    }
                    // Restore
                    self.current_namespace = saved_ns;
                    self.use_map = saved_use_map;
                }
                StmtKind::UseDecl(use_items) => {
                    // Track use imports for correct name resolution
                    for item in use_items {
                        if item.kind == UseKind::Normal {
                            let empty_vec: Vec<u8> = Vec::new();
                            let alias_lower = item
                                .alias
                                .as_ref()
                                .unwrap_or_else(|| item.name.last().unwrap_or(&empty_vec))
                                .iter()
                                .map(|b| b.to_ascii_lowercase())
                                .collect::<Vec<u8>>();
                            let mut qualified = Vec::new();
                            for (i, part) in item.name.iter().enumerate() {
                                if i > 0 {
                                    qualified.push(b'\\');
                                }
                                qualified.extend_from_slice(part);
                            }
                            self.use_map.insert(alias_lower, qualified);
                        }
                    }
                }
                _ => {}
            }
        }
    }

    /// Compile a complete program
    /// Compile a program, returning the op_array and compiled classes
    pub fn compile(
        self,
        program: &Program,
    ) -> CompileResult<(OpArray, Vec<ClassEntry>, Vec<(String, u32)>)> {
        // Each file (and eval'd string) starts without declare(ticks).
        let saved_ticks = TICKS.with(|t| t.replace(0));
        let r = self.compile_file(program);
        TICKS.with(|t| t.set(saved_ticks));
        r
    }

    fn compile_file(
        mut self,
        program: &Program,
    ) -> CompileResult<(OpArray, Vec<ClassEntry>, Vec<(String, u32)>)> {
        self.is_top_level = true;
        crate::ast_export::register_program(program);
        let warnings_base = COMPILE_WARNINGS.with(|w| w.borrow().len());
        // Pre-pass: build the anonymous class name map (NUL-byte PHP names)
        self.build_anon_class_name_map(&program.statements);
        // zend_handle_encoding_declaration() warned while the file was parsed.
        for (msg, line) in goro_parser::multibyte::take_declare_warnings() {
            push_compile_warning_tuple((msg.clone(), line));
            push_pending_compile_warning(msg, line);
        }
        self.leading_declare_stmts = program
            .statements
            .iter()
            .take_while(|st| matches!(st.kind, StmtKind::Declare { .. }))
            .map(|st| st as *const Statement as usize)
            .collect();
        // Reject yield/yield-from at script top level (must appear inside a function).
        if let Some(line) = find_top_level_yield(&program.statements) {
            return Err(CompileError {
                message: "The \"yield\" expression can only be used inside a function".into(),
                line,
            });
        }
        // Pre-pass: detect a top-level `declare(strict_types=1)` so that hoisted
        // function/class attributes (and parameter typing) see strict mode. PHP
        // requires the strict_types declare to be the very first statement of
        // the file, so we only look at the leading Declare statements.
        for stmt in &program.statements {
            if let StmtKind::Declare { directives, .. } = &stmt.kind {
                for (name, value) in directives {
                    let name_lower: Vec<u8> = name.iter().map(|b| b.to_ascii_lowercase()).collect();
                    if name_lower == b"strict_types" {
                        if let ExprKind::Int(1) = &value.kind {
                            self.op_array.strict_types = true;
                        }
                    }
                }
            } else {
                break;
            }
        }
        // strict_types placement (zend_is_first_statement): only other declare()s
        // may precede it, it must be at the top level, and not use block mode.
        {
            fn is_declare_directive(stmt: &Statement) -> Option<bool> {
                // Some(has_strict_types) for a real declare(); None for anything else
                if let StmtKind::Declare { directives, .. } = &stmt.kind {
                    if !directives.is_empty()
                        && directives.iter().all(|(n, _)| {
                            n.eq_ignore_ascii_case(b"strict_types")
                                || n.eq_ignore_ascii_case(b"ticks")
                                || n.eq_ignore_ascii_case(b"encoding")
                        })
                    {
                        return Some(
                            directives
                                .iter()
                                .any(|(n, _)| n.eq_ignore_ascii_case(b"strict_types")),
                        );
                    }
                }
                None
            }
            fn nested_strict(stmts: &[Statement]) -> Option<u32> {
                for st in stmts {
                    match &st.kind {
                        StmtKind::NamespaceDecl { body: Some(b), .. } => {
                            if let Some(l) = b
                                .iter()
                                .find(|x| is_declare_directive(x) == Some(true))
                                .map(|x| x.span.line)
                            {
                                return Some(l);
                            }
                        }
                        StmtKind::Declare { body: Some(b), .. } => {
                            if let Some(l) = b
                                .iter()
                                .find(|x| is_declare_directive(x) == Some(true))
                                .map(|x| x.span.line)
                            {
                                return Some(l);
                            }
                        }
                        _ => {}
                    }
                }
                None
            }
            let mut seen_other = false;
            for st in &program.statements {
                match is_declare_directive(st) {
                    Some(true) => {
                        if seen_other {
                            return Err(CompileError {
                                message: "strict_types declaration must be the very first statement in the script".into(),
                                line: st.span.line,
                            });
                        }
                        if let StmtKind::Declare { body: Some(_), .. } = &st.kind {
                            return Err(CompileError {
                                message: "strict_types declaration must not use block mode".into(),
                                line: st.span.line,
                            });
                        }
                    }
                    Some(false) => {}
                    None => {
                        if !matches!(st.kind, StmtKind::Nop) {
                            seen_other = true;
                        }
                    }
                }
            }
            if let Some(line) = nested_strict(&program.statements) {
                return Err(CompileError {
                    message:
                        "strict_types declaration must be the very first statement in the script"
                            .into(),
                    line,
                });
            }
            // zend_compile_namespace() / zend_verify_namespace() placement rules.
            let mut has_bracketed = false;
            let mut current_ns = false;
            let mut in_ns = false;
            let mut only_declares = true;
            for st in &program.statements {
                let StmtKind::NamespaceDecl { body, .. } = &st.kind else {
                    // The parser appends anonymous class declarations.
                    if matches!(&st.kind, StmtKind::ClassDecl { name, .. } if name.starts_with(b"__anonymous_class_"))
                    {
                        continue;
                    }
                    if has_bracketed && !in_ns && !matches!(st.kind, StmtKind::Nop) {
                        return Err(CompileError {
                            message: "No code may exist outside of namespace {}".into(),
                            line: st.span.line,
                        });
                    }
                    if is_declare_directive(st).is_none() && !matches!(st.kind, StmtKind::Nop) {
                        only_declares = false;
                    }
                    continue;
                };
                let check = |with_bracket: bool,
                             has_bracketed: bool,
                             current_ns: bool,
                             in_ns: bool,
                             first_ok: bool|
                 -> Option<&'static str> {
                    if !has_bracketed {
                        if current_ns && with_bracket {
                            return Some(
                                "Cannot mix bracketed namespace declarations with unbracketed namespace declarations",
                            );
                        }
                    } else if !with_bracket {
                        return Some(
                            "Cannot mix bracketed namespace declarations with unbracketed namespace declarations",
                        );
                    } else if current_ns || in_ns {
                        return Some("Namespace declarations cannot be nested");
                    }
                    let is_first =
                        (!with_bracket && !current_ns) || (with_bracket && !has_bracketed);
                    if is_first && !first_ok {
                        return Some(
                            "Namespace declaration statement has to be the very first statement or after any declare call in the script",
                        );
                    }
                    None
                };
                let with_bracket = body.is_some();
                if let Some(msg) = check(
                    with_bracket,
                    has_bracketed,
                    current_ns,
                    in_ns,
                    only_declares,
                ) {
                    return Err(CompileError {
                        message: msg.into(),
                        line: st.span.line,
                    });
                }
                only_declares = false;
                in_ns = true;
                current_ns = !with_bracket
                    || matches!(&st.kind, StmtKind::NamespaceDecl { name: Some(_), .. });
                if let Some(b) = body {
                    has_bracketed = true;
                    for inner in b {
                        if let StmtKind::NamespaceDecl { body: ib, .. } = &inner.kind {
                            if let Some(msg) = check(ib.is_some(), true, current_ns, true, false) {
                                return Err(CompileError {
                                    message: msg.into(),
                                    line: inner.span.line,
                                });
                            }
                        }
                    }
                    // zend_end_namespace()
                    in_ns = false;
                    current_ns = false;
                }
            }
        }
        // First pass: process namespace/use declarations and compile function/class declarations
        // Namespace/use must be processed in order so that class/function names are prefixed correctly
        self.compile_hoisting_pass(&program.statements)?;
        // Reset namespace state for second pass (will be re-applied by NamespaceDecl/UseDecl)
        self.current_namespace = Vec::new();
        self.use_map = HashMap::new();
        self.use_function_map = HashMap::new();
        self.use_const_map = HashMap::new();
        // Second pass: compile everything else
        self.in_main_pass = true;
        for stmt in &program.statements {
            match &stmt.kind {
                StmtKind::FunctionDecl { name, .. } => {
                    // Already compiled in first pass
                    self.note_symbol_decl(&UseKind::Function, name, stmt.span.line)?;
                }
                StmtKind::ClassDecl { name, .. } if !name.starts_with(b"__anonymous_class_") => {
                    // Hoisted (early-bound) classes were already compiled in the first
                    // pass; non-early-bindable ones are compiled here, in source order.
                    let qn_lower: Vec<u8> = self
                        .prefix_with_namespace(name)
                        .iter()
                        .map(|b| b.to_ascii_lowercase())
                        .collect();
                    self.note_symbol_decl(&UseKind::Normal, name, stmt.span.line)?;
                    if !self
                        .hoisted_class_stmts
                        .contains(&(stmt as *const Statement as usize))
                    {
                        self.compile_stmt(stmt)?;
                    } else {
                        self.emit_late_hoisted_decl(&qn_lower, stmt.span.line);
                    }
                }
                StmtKind::NamespaceDecl { name, body } => {
                    // Set namespace state for second pass
                    if let Some(parts) = name {
                        let mut ns = Vec::new();
                        for (i, part) in parts.iter().enumerate() {
                            if i > 0 {
                                ns.push(b'\\');
                            }
                            ns.extend_from_slice(part);
                        }
                        self.current_namespace = ns;
                    } else {
                        self.current_namespace = Vec::new();
                    }
                    self.use_map = HashMap::new();
                    self.use_function_map = HashMap::new();
                    self.use_const_map = HashMap::new();
                    self.reset_seen_symbols();

                    if let Some(body_stmts) = body {
                        // Bracketed namespace: compile body statements (except func/class decls)
                        for s in body_stmts {
                            match &s.kind {
                                StmtKind::FunctionDecl { name, .. } => {
                                    // Already compiled in first pass
                                    self.note_symbol_decl(&UseKind::Function, name, s.span.line)?;
                                }
                                StmtKind::ClassDecl { name, .. }
                                    if !name.starts_with(b"__anonymous_class_") =>
                                {
                                    // Hoisted classes already compiled in first pass; compile
                                    // non-early-bindable ones here, in source order.
                                    let qn_lower: Vec<u8> = self
                                        .prefix_with_namespace(name)
                                        .iter()
                                        .map(|b| b.to_ascii_lowercase())
                                        .collect();
                                    self.note_symbol_decl(&UseKind::Normal, name, s.span.line)?;
                                    if !self
                                        .hoisted_class_stmts
                                        .contains(&(s as *const Statement as usize))
                                    {
                                        self.compile_stmt(s)?;
                                    } else {
                                        self.emit_late_hoisted_decl(&qn_lower, s.span.line);
                                    }
                                }
                                _ => {
                                    self.compile_stmt(s)?;
                                }
                            }
                        }
                        // Reset after block
                        self.current_namespace = Vec::new();
                        self.use_map = HashMap::new();
                        self.use_function_map = HashMap::new();
                        self.use_const_map = HashMap::new();
                        self.reset_seen_symbols();
                    }
                }
                _ => {
                    self.compile_stmt(stmt)?;
                }
            }
        }
        self.in_main_pass = false;
        // Reject any unresolved gotos at top level (PHP: "'goto' to undefined label").
        // Without this, the placeholder Jmp jumps to ip=0 and causes an infinite loop.
        self.check_pending_gotos()?;
        // Emit implicit return null at end of script
        let null_idx = self.op_array.add_literal(Value::Null);
        self.op_array.emit(Op {
            opcode: OpCode::Return,
            op1: OperandType::Const(null_idx),
            op2: OperandType::Unused,
            result: OperandType::Unused,
            line: 0,
        });
        // If any deferred fatal errors were collected (e.g. internal attribute
        // target violations), surface the first one as a compile error.
        if let Some(msg) = self.deferred_fatal_errors.into_iter().next() {
            return Err(CompileError {
                message: msg,
                line: 0,
            });
        }
        let mut warnings = std::mem::take(&mut self.warnings);
        COMPILE_WARNINGS.with(|w| {
            let mut w = w.borrow_mut();
            let base = warnings_base.min(w.len());
            warnings.extend(w.drain(base..));
        });
        Ok((self.op_array, self.compiled_classes, warnings))
    }

    /// First pass: process only namespace/use/function/class declarations for hoisting.
    /// For bracketed namespaces, recurse into the body.
    fn compile_hoisting_pass(&mut self, stmts: &[Statement]) -> CompileResult<()> {
        for stmt in stmts {
            match &stmt.kind {
                StmtKind::NamespaceDecl { name, body } => {
                    // Set namespace state
                    if let Some(parts) = name {
                        let mut ns = Vec::new();
                        for (i, part) in parts.iter().enumerate() {
                            if i > 0 {
                                ns.push(b'\\');
                            }
                            ns.extend_from_slice(part);
                        }
                        self.current_namespace = ns;
                    } else {
                        self.current_namespace = Vec::new();
                    }
                    self.use_map = HashMap::new();
                    self.use_function_map = HashMap::new();
                    self.use_const_map = HashMap::new();

                    if let Some(body_stmts) = body {
                        // Recurse into bracketed namespace body
                        self.compile_hoisting_pass(body_stmts)?;
                        // Reset after block
                        self.current_namespace = Vec::new();
                        self.use_map = HashMap::new();
                        self.use_function_map = HashMap::new();
                        self.use_const_map = HashMap::new();
                        self.reset_seen_symbols();
                    }
                }
                StmtKind::UseDecl(_) => {
                    self.compile_stmt(stmt)?;
                }
                StmtKind::FunctionDecl { name, .. } => {
                    let qn = self.prefix_with_namespace(name);
                    let qn_lower: Vec<u8> = qn.iter().map(|b| b.to_ascii_lowercase()).collect();
                    if let Some((prev_name, prev_line)) = self.hoisted_function_names.get(&qn_lower)
                    {
                        return Err(CompileError {
                            message: format!(
                                "Cannot redeclare function {}() (previously declared in {}:{})",
                                String::from_utf8_lossy(prev_name),
                                String::from_utf8_lossy(&self.source_file),
                                prev_line
                            ),
                            line: stmt.span.line,
                        });
                    }
                    self.hoisted_function_names
                        .insert(qn_lower, (qn, stmt.span.line));
                    self.in_hoisting_pass = true;
                    let r = self.compile_stmt(stmt);
                    self.in_hoisting_pass = false;
                    r?;
                }
                StmtKind::ClassDecl {
                    name,
                    modifiers,
                    extends,
                    implements,
                    body,
                    ..
                } if !name.starts_with(b"__anonymous_class_") => {
                    // Only early-bind (hoist) declarations PHP would early-bind. Others are
                    // left for the second pass to emit at their source position.
                    let qn_lower: Vec<u8> = self
                        .prefix_with_namespace(name)
                        .iter()
                        .map(|b| b.to_ascii_lowercase())
                        .collect();
                    // A name taken by an internal class can't be bound at
                    // compile time: the declaration fails at runtime instead.
                    if self.class_is_early_bindable(modifiers, extends, implements, body)
                        && !crate::vm::is_known_builtin_class_name(&qn_lower)
                    {
                        self.in_hoisting_pass = true;
                        let r = self.compile_stmt(stmt);
                        self.in_hoisting_pass = false;
                        r?;
                        self.hoisted_class_idx
                            .insert(qn_lower.clone(), self.compiled_classes.len() as i64 - 1);
                        self.hoisted_class_names.insert(qn_lower);
                        self.hoisted_class_stmts
                            .insert(stmt as *const Statement as usize);
                    }
                }
                _ => {}
            }
        }
        Ok(())
    }

    /// At the source position of a hoisted class, emit a DeclareClass flagged as
    /// "late" (result = Const(2)): it only declares the class if the early-binding
    /// attempt was deferred at runtime (unresolved variance), like PHP's delayed
    /// early binding.
    fn emit_late_hoisted_decl(&mut self, qn_lower: &[u8], line: u32) {
        if let Some(&idx) = self.hoisted_class_idx.get(qn_lower) {
            let name = self
                .compiled_classes
                .get(idx as usize)
                .map(|c| c.name.clone())
                .unwrap_or_default();
            let name_idx = self
                .op_array
                .add_literal(Value::String(PhpString::from_vec(name)));
            let idx_literal = self.op_array.add_literal(Value::Long(idx));
            let flag = self.op_array.add_literal(Value::Long(2));
            self.op_array.emit(Op {
                opcode: OpCode::DeclareClass,
                op1: OperandType::Const(name_idx),
                op2: OperandType::Const(idx_literal),
                result: OperandType::Const(flag),
                line,
            });
        }
    }

    /// Decide whether a top-level declaration is eligible for early binding (hoisting),
    /// mirroring PHP's Zend early-binding rule:
    /// - enums: never early-bound
    /// - interfaces / traits: early-bound
    /// - classes: early-bound iff no `implements`, no trait `use`, and either no parent
    ///   or the parent is already hoisted (declared earlier) or is an internal class.
    fn class_is_early_bindable(
        &self,
        modifiers: &ClassModifiers,
        extends: &Option<Vec<u8>>,
        implements: &[Vec<u8>],
        body: &[ClassMember],
    ) -> bool {
        // Enums, interfaces and traits keep prior (always-hoisted) behavior: goro's VM
        // pre-registers these so forward references resolve, and deferring them caused
        // regressions with no observable benefit (PHP's stricter ordering for enums is
        // not what the deprecation/trait-binding tests exercise).
        if modifiers.is_enum || modifiers.is_interface || modifiers.is_trait {
            return true;
        }
        if !implements.is_empty() {
            return false;
        }
        if body
            .iter()
            .any(|m| matches!(m, ClassMember::TraitUse { .. }))
        {
            return false;
        }
        if let Some(parent) = extends {
            let parent_lower: Vec<u8> = self
                .resolve_class_name(parent)
                .iter()
                .map(|b| b.to_ascii_lowercase())
                .collect();
            return self.hoisted_class_names.contains(&parent_lower)
                || crate::vm::is_known_builtin_class_name(&parent_lower);
        }
        true
    }

    /// Release the foreach temporaries of the loops `loop_stack[from..]`
    /// (innermost first) that a return/break/continue leaves, except `keep`
    /// (the returned operand).
    fn emit_loop_frees(
        &mut self,
        from: usize,
        keep: OperandType,
        line: u32,
    ) -> Vec<(usize, u32, u32)> {
        // Loops outside the innermost try-with-finally are only released
        // after its finally block ran (php-src emits their FE_FREE after
        // the FAST_CALL), so a finally that throws keeps them running.
        let depth = self.finally_targets.len();
        let levels: Vec<usize> = (from..self.loop_stack.len())
            .rev()
            .take_while(|&i| self.loop_stack[i].try_finally_depth >= depth)
            .filter(|&i| !self.loop_stack[i].free_tmps.is_empty())
            .collect();
        let mut ranges = Vec::new();
        if levels.is_empty() {
            return ranges;
        }
        let undef_const = self.op_array.add_literal(Value::Undef);
        for i in levels {
            let start = self.op_array.current_offset();
            // ZEND_FREE_ON_RETURN: an exception thrown by the release is
            // logically thrown at the end of the loop, so try blocks inside
            // the loop don't catch it (the handler stack is cut back to its
            // depth at the loop entry).
            let depth_op = match (self.loop_stack[i].depth_tmp, self.loop_stack[i].depth_nop) {
                (Some(t), _) => OperandType::Tmp(t),
                (None, Some(nop)) => {
                    let t = self.op_array.alloc_temp();
                    let op = &mut self.op_array.ops[nop as usize];
                    op.opcode = OpCode::SaveHandlerDepth;
                    op.result = OperandType::Tmp(t);
                    self.loop_stack[i].depth_tmp = Some(t);
                    OperandType::Tmp(t)
                }
                (None, None) => OperandType::Unused,
            };
            let tmps: Vec<u32> = self.loop_stack[i]
                .free_tmps
                .iter()
                .copied()
                .filter(|t| !matches!(keep, OperandType::Tmp(k) if k == *t))
                .collect();
            for t in tmps {
                if matches!(depth_op, OperandType::Unused) {
                    self.op_array.emit(Op {
                        opcode: OpCode::Assign,
                        op1: OperandType::Tmp(t),
                        op2: OperandType::Const(undef_const),
                        result: OperandType::Unused,
                        line,
                    });
                } else {
                    self.op_array.emit(Op {
                        opcode: OpCode::FreeLoopVar,
                        op1: OperandType::Tmp(t),
                        op2: depth_op,
                        result: OperandType::Unused,
                        line,
                    });
                }
            }
            ranges.push((i, start, self.op_array.current_offset()));
        }
        ranges
    }

    /// The jump of `break` / `continue` to the loop `loop_stack[target_index]`:
    /// frees the loop variables it leaves and runs the finally blocks in
    /// between (zend_handle_loops_and_finally()).
    fn emit_loop_exit(&mut self, target_index: usize, is_continue: bool, line: u32) {
        self.emit_loop_frees(target_index + 1, OperandType::Unused, line);
        // The try blocks it leaves (up to one leading to a finally block,
        // whose finally path pops it) drop their exception handlers.
        let pops = self.handler_regions[self.loop_stack[target_index].handler_depth..]
            .iter()
            .rev()
            .take_while(|r| !r.1)
            .count();
        self.emit_handler_change(pops, &[], line);
        // Check if we're inside a try-with-finally block that the
        // jump leaves (the target loop started outside of it)
        let leaves_try_finally =
            self.finally_targets.len() > self.loop_stack[target_index].try_finally_depth;
        let Some(&finally_target) = self.finally_targets.last().filter(|_| leaves_try_finally)
        else {
            let jmp = self.op_array.emit(Op {
                opcode: OpCode::Jmp,
                op1: OperandType::JmpTarget(0),
                op2: OperandType::Unused,
                result: OperandType::Unused,
                line,
            });
            if is_continue {
                self.loop_stack[target_index].continue_jumps.push(jmp);
            } else {
                self.loop_stack[target_index].break_jumps.push(jmp);
            }
            return;
        };
        // Loops left after the innermost finally block ran (and before the
        // next one): the jump continues from a stub after the try statement.
        let depth = self.finally_targets.len();
        let needs_stub = (target_index + 1..self.loop_stack.len()).any(|i| {
            self.loop_stack[i].try_finally_depth < depth && !self.loop_stack[i].free_tmps.is_empty()
        });
        // Number of finally blocks the jump runs through.
        let fin_levels = self.op_array.add_literal(Value::Long(if needs_stub {
            1
        } else {
            (self.finally_targets.len() - self.loop_stack[target_index].try_finally_depth) as i64
        }));
        let save_jmp = self.op_array.emit(Op {
            opcode: OpCode::SaveJump,
            op1: OperandType::JmpTarget(0), // patched to the target (or stub) later
            op2: OperandType::Const(fin_levels),
            result: OperandType::Unused,
            line,
        });
        if needs_stub {
            if let Some(stubs) = self.jumps.finally_stubs.last_mut() {
                stubs.push((save_jmp, target_index, is_continue, line));
            }
        } else if is_continue {
            self.loop_stack[target_index].continue_jumps.push(save_jmp);
        } else {
            self.loop_stack[target_index].break_jumps.push(save_jmp);
        }
        // A placeholder 0 is patched by the finally compilation.
        self.op_array.emit(Op {
            opcode: OpCode::Jmp,
            op1: OperandType::JmpTarget(finally_target),
            op2: OperandType::Unused,
            result: OperandType::Unused,
            line,
        });
    }

    /// FreeTmps over a range of temporaries, if it is not empty
    fn emit_free_tmps(&mut self, (start, end): (u32, u32), line: u32) {
        if end > start {
            self.op_array.emit(Op {
                opcode: OpCode::FreeTmps,
                op1: OperandType::Tmp(start),
                op2: OperandType::Tmp(end),
                result: OperandType::Unused,
                line,
            });
        }
    }

    /// A temporary object a method was called on (and the arguments passed)
    /// is released once the call returns (Zend's ZEND_CALL_RELEASE_THIS),
    /// not at the end of the statement: free the call's temporaries except
    /// its result.
    #[inline(never)]
    fn emit_free_call_tmps(&mut self, start: u32, result: u32, line: u32) {
        let end = self.op_array.temp_count;
        self.emit_free_tmps((start, result), line);
        self.emit_free_tmps((result + 1, end), line);
    }

    fn compile_stmt(&mut self, stmt: &Statement) -> CompileResult<()> {
        let r = self.compile_stmt_inner(stmt);
        if !self.dynvar_pending.is_empty() {
            // The variables fetched for dynamic writes are not held past
            // the statement.
            for cv in std::mem::take(&mut self.dynvar_pending) {
                self.op_array.emit(Op {
                    opcode: OpCode::UnsetCv,
                    op1: OperandType::Cv(cv),
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line: stmt.span.line,
                });
            }
        }
        r?;
        // zend_compile_stmt(): a TICKS opcode after each ticked statement.
        let ticks = TICKS.with(|t| t.get());
        if ticks > 0
            && !matches!(
                stmt.kind,
                StmtKind::Nop
                    | StmtKind::Label(_)
                    | StmtKind::FunctionDecl { .. }
                    | StmtKind::ClassDecl { .. }
            )
        {
            let lit = self.op_array.add_literal(Value::Long(ticks as i64));
            self.op_array.emit(Op {
                opcode: OpCode::Tick,
                op1: OperandType::Const(lit),
                op2: OperandType::Unused,
                result: OperandType::Unused,
                line: stmt.span.line,
            });
        }
        Ok(())
    }

    /// The name of `${expr}` when it is a compile-time constant (zend_try_compile_cv):
    /// the variable is then a CV like `$name`.
    fn static_dynvar_name(inner: &Expr) -> Option<Vec<u8>> {
        match &inner.kind {
            ExprKind::String(s)
                if !crate::vm::is_auto_global_name(s) && s.as_slice() != b"GLOBALS" =>
            {
                Some(s.clone())
            }
            _ => None,
        }
    }

    /// FETCH_W / FETCH_RW / FETCH_UNSET (mode 0 / 1 / 2) of `$$inner` into a
    /// hidden CV bound to the variable, which the write then targets.
    fn compile_dynvar_fetch(
        &mut self,
        inner: &Expr,
        mode: i64,
        line: u32,
    ) -> CompileResult<OperandType> {
        if let Some(name) = Self::static_dynvar_name(inner) {
            return Ok(OperandType::Cv(self.op_array.get_or_create_cv(&name)));
        }
        let name_op = self.compile_expr(inner)?;
        let cv = self.dynvar_hidden_cv();
        let mode_idx = self.op_array.add_literal(Value::Long(mode));
        self.op_array.emit(Op {
            opcode: OpCode::VarVarFetch,
            op1: name_op,
            op2: OperandType::Const(mode_idx),
            result: OperandType::Cv(cv),
            line,
        });
        Ok(OperandType::Cv(cv))
    }

    /// A fresh hidden CV for a dynamic variable fetch.
    fn dynvar_hidden_cv(&mut self) -> u32 {
        let mut name = b"\0vv".to_vec();
        name.extend_from_slice(self.dynvar_count.to_string().as_bytes());
        self.dynvar_count += 1;
        let cv = self.op_array.get_or_create_cv(&name);
        self.dynvar_pending.push(cv);
        cv
    }

    /// `$$inner` as an expression naming the hidden CV it was fetched into
    /// (mode as for compile_dynvar_fetch).
    fn dynvar_as_cv_expr(&mut self, e: &Expr, inner: &Expr, mode: i64) -> CompileResult<Expr> {
        let op = self.compile_dynvar_fetch(inner, mode, e.span.line)?;
        let OperandType::Cv(cv) = op else {
            unreachable!()
        };
        Ok(Expr {
            kind: ExprKind::Variable(self.op_array.cv_names[cv as usize].clone()),
            span: e.span,
        })
    }

    #[inline(never)]
    fn compile_assign_ref_dynvar_value(
        &mut self,
        expr: &Expr,
        target: &Expr,
        value: &Expr,
    ) -> CompileResult<OperandType> {
        // `... = &$$n`: FETCH_W of the variable, bound like a CV.
        let ExprKind::DynamicVariable(inner) = &value.kind else {
            unreachable!()
        };
        let v = self.dynvar_as_cv_expr(value, inner, 0)?;
        let e = Expr {
            kind: ExprKind::AssignRef {
                target: Box::new(target.clone()),
                value: Box::new(v),
            },
            span: expr.span,
        };
        self.compile_expr(&e)
    }

    #[inline(never)]
    fn compile_assign_ref_dynvar_target(
        &mut self,
        expr: &Expr,
        target: &Expr,
        value: &Expr,
    ) -> CompileResult<OperandType> {
        // `$$n = &source`: the source's reference is taken through a
        // hidden variable, then bound to the name.
        let ExprKind::DynamicVariable(inner) = &target.kind else {
            unreachable!()
        };
        let result_discarded = self.assign_result_discarded;
        let name_op = self.compile_expr(inner)?;
        let cv = self.dynvar_hidden_cv();
        let e = Expr {
            kind: ExprKind::AssignRef {
                target: Box::new(Expr {
                    kind: ExprKind::Variable(self.op_array.cv_names[cv as usize].clone()),
                    span: target.span,
                }),
                value: Box::new(value.clone()),
            },
            span: expr.span,
        };
        self.compile_expr(&e)?;
        let result = if result_discarded {
            OperandType::Unused
        } else {
            OperandType::Tmp(self.op_array.alloc_temp())
        };
        self.op_array.emit(Op {
            opcode: OpCode::VarVarAssignRef,
            op1: name_op,
            op2: OperandType::Cv(cv),
            result,
            line: expr.span.line,
        });
        Ok(if result_discarded {
            OperandType::Cv(cv)
        } else {
            result
        })
    }

    #[inline(never)]
    fn compile_assign_dynvar(
        &mut self,
        expr: &Expr,
        target: &Expr,
        value: &Expr,
    ) -> CompileResult<OperandType> {
        // `$$n = v`: the name is evaluated before the value; the
        // variable is fetched (FETCH_W) and assigned after it.
        self.assign_result_discarded = false;
        let ExprKind::DynamicVariable(inner) = &target.kind else {
            unreachable!()
        };
        let name_op = self.compile_expr(inner)?;
        let val = self.compile_expr(value)?;
        self.op_array.emit(Op {
            opcode: OpCode::VarVarSet,
            op1: name_op,
            op2: val,
            result: OperandType::Unused,
            line: expr.span.line,
        });
        Ok(val)
    }

    /// `$$n op= v`: the value is computed first, then the variable is
    /// fetched (FETCH_RW) and assigned to.
    #[inline(never)]
    fn compile_compound_dynvar(
        &mut self,
        expr: &Expr,
        op: BinaryOp,
        target: &Expr,
        value: &Expr,
    ) -> CompileResult<OperandType> {
        let ExprKind::DynamicVariable(inner) = &target.kind else {
            unreachable!()
        };
        let saved = self.tmp_aliases.len();
        let name = self.memoize_operand(inner)?;
        let v = self.memoize_operand(value)?;
        let t = self.dynvar_as_cv_expr(target, &name, 1)?;
        let e = Expr {
            kind: ExprKind::CompoundAssign {
                op,
                target: Box::new(t),
                value: Box::new(v),
            },
            span: expr.span,
        };
        let r = self.compile_expr(&e);
        self.tmp_aliases.truncate(saved);
        r
    }

    /// `$$n++`: FETCH_RW of the variable, then the increment.
    #[inline(never)]
    fn compile_incdec_dynvar(
        &mut self,
        expr: &Expr,
        op: UnaryOp,
        operand: &Expr,
        prefix: bool,
    ) -> CompileResult<OperandType> {
        let ExprKind::DynamicVariable(inner) = &operand.kind else {
            unreachable!()
        };
        let t = self.dynvar_as_cv_expr(operand, inner, 1)?;
        let e = Expr {
            kind: ExprKind::UnaryOp {
                op,
                operand: Box::new(t),
                prefix,
            },
            span: expr.span,
        };
        self.compile_expr(&e)
    }

    fn compile_stmt_inner(&mut self, stmt: &Statement) -> CompileResult<()> {
        match &stmt.kind {
            StmtKind::Nop => Ok(()),

            StmtKind::InlineHtml(html) => {
                let idx = self
                    .op_array
                    .add_literal(Value::String(PhpString::from_vec(html.clone())));
                self.op_array.emit(Op {
                    opcode: OpCode::Echo,
                    op1: OperandType::Const(idx),
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line: stmt.span.line,
                });
                Ok(())
            }

            StmtKind::Echo(exprs) => {
                for expr in exprs {
                    let operand = self.compile_expr(expr)?;
                    self.op_array.emit(Op {
                        opcode: OpCode::Echo,
                        op1: operand,
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: stmt.span.line,
                    });
                }
                Ok(())
            }

            StmtKind::Expression(expr) => {
                // Set flag when expression result is discarded (for #[\NoDiscard] checking)
                let is_call = matches!(
                    expr.kind,
                    ExprKind::FunctionCall { .. }
                        | ExprKind::MethodCall { .. }
                        | ExprKind::StaticMethodCall { .. }
                );
                if is_call {
                    self.is_discarding_result = true;
                }
                if matches!(
                    expr.kind,
                    ExprKind::Assign { .. } | ExprKind::AssignRef { .. }
                ) {
                    self.assign_result_discarded = true;
                }
                let tmp_start = self.op_array.temp_count;
                self.compile_expr(expr)?;
                self.is_discarding_result = false;
                let tmp_end = self.op_array.temp_count;
                if tmp_end > tmp_start {
                    self.op_array.emit(Op {
                        opcode: OpCode::FreeTmps,
                        op1: OperandType::Tmp(tmp_start),
                        op2: OperandType::Tmp(tmp_end),
                        result: OperandType::Unused,
                        line: stmt.span.line,
                    });
                }
                Ok(())
            }

            StmtKind::Return(value) => {
                // Check for return in never-returning function
                let callable_kind = if self.current_class.is_some() {
                    "method"
                } else {
                    "function"
                };
                if self.has_never_return {
                    return Err(CompileError {
                        message: format!("A never-returning {} must not return", callable_kind),
                        line: stmt.span.line,
                    });
                }
                // zend_compile_return(): a by-reference return of a
                // short-circuiting chain.
                if let Some(ret_expr) = value {
                    if self.op_array.returns_by_ref
                        && !self.op_array.is_generator
                        && expr_is_in_nullsafe_chain(ret_expr)
                    {
                        return Err(CompileError {
                            message: "Cannot take reference of a nullsafe chain".into(),
                            line: ret_expr.span.line,
                        });
                    }
                }
                // Check for `return expr;` (with value) in void function
                if let Some(ret_expr) = value {
                    if let Some(ref ret_type) = self.op_array.return_type {
                        let is_void = matches!(ret_type, ParamType::Simple(n) if n.eq_ignore_ascii_case(b"void"));
                        if is_void {
                            // Check if the return value is `null` to provide a better hint
                            let is_null_return = matches!(ret_expr.kind, ExprKind::Null);
                            let msg = if is_null_return {
                                format!(
                                    "A void {} must not return a value (did you mean \"return;\" instead of \"return null;\"?)",
                                    callable_kind
                                )
                            } else {
                                format!("A void {} must not return a value", callable_kind)
                            };
                            return Err(CompileError {
                                message: msg,
                                line: stmt.span.line,
                            });
                        }
                    }
                }
                // Check for `return;` (without value) in function with non-void return type
                // Generators are allowed to use `return;` regardless of return type
                if value.is_none() && !self.op_array.is_generator {
                    if let Some(ref ret_type) = self.op_array.return_type {
                        // void allows `return;`
                        let is_void = matches!(ret_type, ParamType::Simple(n) if n.eq_ignore_ascii_case(b"void"));
                        if !is_void {
                            // Check if the type includes null (nullable types allow `return;` with a deprecation in PHP 8.4)
                            let includes_null = match ret_type {
                                ParamType::Nullable(_) => true,
                                ParamType::Simple(n) => n.eq_ignore_ascii_case(b"null"),
                                ParamType::Union(types) => types.iter().any(|t| matches!(t, ParamType::Simple(n) if n.eq_ignore_ascii_case(b"null"))),
                                _ => false,
                            };
                            if includes_null {
                                return Err(CompileError {
                                    message: "A function with return type must return a value (did you mean \"return null;\" instead of \"return;\"?)".to_string(),
                                    line: stmt.span.line,
                                });
                            } else {
                                return Err(CompileError {
                                    message: "A function with return type must return a value"
                                        .to_string(),
                                    line: stmt.span.line,
                                });
                            }
                        }
                    }
                }
                if value.is_none() {
                    // `return;` from a by-ref function returns NULL by value.
                    self.emit_by_ref_return_notice(None, stmt.span.line);
                }
                let operand = if let Some(expr) = value {
                    if self.op_array.returns_by_ref && !self.op_array.is_generator {
                        self.compile_ref_fetch(expr)?
                    } else {
                        self.compile_expr(expr)?
                    }
                } else {
                    let idx = self.op_array.add_literal(Value::Null);
                    OperandType::Const(idx)
                };
                self.emit_loop_frees(0, operand, stmt.span.line);
                // ZEND_RETURN_BY_REF of a non-variable (zend_compile_return):
                // "Only variable references should be returned by reference".
                if self.op_array.returns_by_ref && !self.op_array.is_generator {
                    let is_var_or_call = match value {
                        Some(e) => matches!(
                            e.kind,
                            ExprKind::Variable(_)
                                | ExprKind::DynamicVariable(_)
                                | ExprKind::ArrayAccess { .. }
                                | ExprKind::PropertyAccess { .. }
                                | ExprKind::StaticPropertyAccess { .. }
                                | ExprKind::DynamicStaticPropertyAccess { .. }
                                | ExprKind::FunctionCall { .. }
                                | ExprKind::MethodCall { .. }
                                | ExprKind::StaticMethodCall { .. }
                                | ExprKind::DynamicStaticMethodCall { .. }
                                | ExprKind::Pipe { .. }
                        ),
                        None => true,
                    };
                    // The return type is verified first: a literal failing it throws
                    // before the notice would be raised.
                    let fails_return_type = match (value, &self.op_array.return_type) {
                        (Some(e), Some(rt)) => Self::check_literal_default(rt, e).is_err(),
                        _ => false,
                    };
                    if !is_var_or_call && !fails_return_type {
                        let msg_idx =
                            self.op_array
                                .add_literal(Value::String(PhpString::from_bytes(
                                    b"Only variable references should be returned by reference",
                                )));
                        self.op_array.emit(Op {
                            opcode: OpCode::EmitNotice,
                            op1: OperandType::Const(msg_idx),
                            op2: OperandType::Unused,
                            result: OperandType::Unused,
                            line: stmt.span.line,
                        });
                    }
                }
                if let Some(&finally_target) = self.finally_targets.last() {
                    // Inside try-with-finally: save return value and jump to finally
                    self.op_array.emit(Op {
                        opcode: OpCode::SaveReturn,
                        op1: operand,
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: stmt.span.line,
                    });
                    self.op_array.emit(Op {
                        opcode: OpCode::Jmp,
                        op1: OperandType::JmpTarget(finally_target),
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: stmt.span.line,
                    });
                } else {
                    self.op_array.emit(Op {
                        opcode: OpCode::Return,
                        op1: operand,
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: stmt.span.line,
                    });
                }
                Ok(())
            }

            StmtKind::If {
                condition,
                body,
                elseif_clauses,
                else_body,
            } => {
                let cond_tmps = self.op_array.temp_count;
                let cond = self.compile_expr(condition)?;
                let cond_tmps = (cond_tmps, self.op_array.temp_count);

                // Jump past body if condition is false
                let jmp_false = self.op_array.emit(Op {
                    opcode: OpCode::JmpZ,
                    op1: cond,
                    op2: OperandType::JmpTarget(0), // patched later
                    result: OperandType::Unused,
                    line: stmt.span.line,
                });
                // The condition's temporaries die once it is tested (e.g. the
                // object of `if (!$x = f())`), on both paths.
                self.emit_free_tmps(cond_tmps, stmt.span.line);

                // Compile body
                for s in body {
                    self.compile_stmt(s)?;
                }

                // After body: jump past else/elseif
                let mut end_jumps = Vec::new();
                if !elseif_clauses.is_empty() || else_body.is_some() {
                    let jmp_end = self.op_array.emit(Op {
                        opcode: OpCode::Jmp,
                        op1: OperandType::JmpTarget(0),
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: stmt.span.line,
                    });
                    end_jumps.push(jmp_end);
                }

                // Patch false jump to here
                let after_body = self.op_array.current_offset();
                self.op_array.patch_jump(jmp_false, after_body);
                self.emit_free_tmps(cond_tmps, stmt.span.line);

                // Elseif clauses
                for (elseif_cond, elseif_body) in elseif_clauses {
                    let tmps_start = self.op_array.temp_count;
                    let cond = self.compile_expr(elseif_cond)?;
                    let cond_tmps = (tmps_start, self.op_array.temp_count);
                    let jmp_false = self.op_array.emit(Op {
                        opcode: OpCode::JmpZ,
                        op1: cond,
                        op2: OperandType::JmpTarget(0),
                        result: OperandType::Unused,
                        line: stmt.span.line,
                    });
                    self.emit_free_tmps(cond_tmps, stmt.span.line);
                    for s in elseif_body {
                        self.compile_stmt(s)?;
                    }
                    let jmp_end = self.op_array.emit(Op {
                        opcode: OpCode::Jmp,
                        op1: OperandType::JmpTarget(0),
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: stmt.span.line,
                    });
                    end_jumps.push(jmp_end);
                    let after_elseif = self.op_array.current_offset();
                    self.op_array.patch_jump(jmp_false, after_elseif);
                    self.emit_free_tmps(cond_tmps, stmt.span.line);
                }

                // Else body
                if let Some(else_stmts) = else_body {
                    for s in else_stmts {
                        self.compile_stmt(s)?;
                    }
                }

                // Patch all end jumps to here
                let end = self.op_array.current_offset();
                for jmp in end_jumps {
                    self.op_array.patch_jump(jmp, end);
                }

                Ok(())
            }

            StmtKind::While { condition, body } => {
                self.loop_stack.push(LoopContext {
                    id: next_loop_id(),
                    break_jumps: Vec::new(),
                    continue_jumps: Vec::new(),
                    continue_target: None,
                    is_switch: false,
                    finally_depth: self.finally_path.len(),
                    try_finally_depth: self.finally_targets.len(),
                    free_tmps: Vec::new(),
                    depth_nop: None,
                    depth_tmp: None,
                    handler_depth: self.handler_regions.len(),
                });

                let loop_start = self.op_array.current_offset();
                let cond = self.compile_expr(condition)?;
                let jmp_false = self.op_array.emit(Op {
                    opcode: OpCode::JmpZ,
                    op1: cond,
                    op2: OperandType::JmpTarget(0),
                    result: OperandType::Unused,
                    line: stmt.span.line,
                });

                // Set continue target to loop_start (re-evaluate condition)
                if let Some(ctx) = self.loop_stack.last_mut() {
                    ctx.continue_target = Some(loop_start);
                }

                for s in body {
                    self.compile_stmt(s)?;
                }
                self.op_array.emit(Op {
                    opcode: OpCode::Jmp,
                    op1: OperandType::JmpTarget(loop_start),
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line: stmt.span.line,
                });
                let after_loop = self.op_array.current_offset();
                self.op_array.patch_jump(jmp_false, after_loop);

                // Patch break/continue jumps
                let ctx = self.loop_stack.pop().unwrap();
                for jmp in ctx.break_jumps {
                    self.op_array.patch_jump(jmp, after_loop);
                }
                for jmp in ctx.continue_jumps {
                    self.op_array.patch_jump(jmp, loop_start);
                }
                Ok(())
            }

            StmtKind::DoWhile { body, condition } => {
                self.loop_stack.push(LoopContext {
                    id: next_loop_id(),
                    break_jumps: Vec::new(),
                    continue_jumps: Vec::new(),
                    continue_target: None,
                    is_switch: false,
                    finally_depth: self.finally_path.len(),
                    try_finally_depth: self.finally_targets.len(),
                    free_tmps: Vec::new(),
                    depth_nop: None,
                    depth_tmp: None,
                    handler_depth: self.handler_regions.len(),
                });

                let loop_start = self.op_array.current_offset();
                for s in body {
                    self.compile_stmt(s)?;
                }
                let continue_target = self.op_array.current_offset();
                let cond = self.compile_expr(condition)?;
                self.op_array.emit(Op {
                    opcode: OpCode::JmpNz,
                    op1: cond,
                    op2: OperandType::JmpTarget(loop_start),
                    result: OperandType::Unused,
                    line: stmt.span.line,
                });
                let after_loop = self.op_array.current_offset();

                let ctx = self.loop_stack.pop().unwrap();
                for jmp in ctx.break_jumps {
                    self.op_array.patch_jump(jmp, after_loop);
                }
                for jmp in ctx.continue_jumps {
                    self.op_array.patch_jump(jmp, continue_target);
                }
                Ok(())
            }

            StmtKind::For {
                init,
                condition,
                update,
                body,
            } => {
                // Compile init expressions (their results are discarded)
                for expr in init {
                    self.compile_discarded_expr(expr)?;
                }

                self.loop_stack.push(LoopContext {
                    id: next_loop_id(),
                    break_jumps: Vec::new(),
                    continue_jumps: Vec::new(),
                    continue_target: None,
                    is_switch: false,
                    finally_depth: self.finally_path.len(),
                    try_finally_depth: self.finally_targets.len(),
                    free_tmps: Vec::new(),
                    depth_nop: None,
                    depth_tmp: None,
                    handler_depth: self.handler_regions.len(),
                });

                let loop_start = self.op_array.current_offset();

                // Condition
                // `for (;a, b;)`: every condition expression is evaluated, the
                // last one decides.
                let jmp_false = if let Some((last, rest)) = condition.split_last() {
                    for expr in rest {
                        self.compile_discarded_expr(expr)?;
                    }
                    let cond = self.compile_expr(last)?;
                    Some(self.op_array.emit(Op {
                        opcode: OpCode::JmpZ,
                        op1: cond,
                        op2: OperandType::JmpTarget(0),
                        result: OperandType::Unused,
                        line: stmt.span.line,
                    }))
                } else {
                    None
                };

                // Body
                for s in body {
                    self.compile_stmt(s)?;
                }

                // Continue target is right before the update expressions
                let continue_target = self.op_array.current_offset();

                // Update
                for expr in update {
                    self.compile_discarded_expr(expr)?;
                }

                // Jump back to condition check
                self.op_array.emit(Op {
                    opcode: OpCode::Jmp,
                    op1: OperandType::JmpTarget(loop_start),
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line: stmt.span.line,
                });

                let after_loop = self.op_array.current_offset();
                if let Some(jmp) = jmp_false {
                    self.op_array.patch_jump(jmp, after_loop);
                }

                let ctx = self.loop_stack.pop().unwrap();
                for jmp in ctx.break_jumps {
                    self.op_array.patch_jump(jmp, after_loop);
                }
                for jmp in ctx.continue_jumps {
                    self.op_array.patch_jump(jmp, continue_target);
                }

                Ok(())
            }

            StmtKind::Foreach {
                expr,
                key,
                value,
                by_ref,
                body,
                ..
            } => {
                if matches!(&value.kind, ExprKind::Variable(n) if n == b"GLOBALS")
                    || matches!(&value.kind, ExprKind::Array(elems) if Self::list_writes_globals(elems))
                {
                    return Err(CompileError { message: "$GLOBALS can only be modified using the $GLOBALS[$name] = $value syntax".to_string(), line: stmt.span.line });
                }
                if expr_is_in_nullsafe_chain(value)
                    || key.as_ref().is_some_and(expr_is_in_nullsafe_chain)
                {
                    return Err(CompileError {
                        message: "Can't use nullsafe operator in write context".into(),
                        line: stmt.span.line,
                    });
                }
                // Check for $this in foreach target variables
                if self.check_foreach_this_assign(value, stmt.span.line)? {
                    return Err(CompileError {
                        message: "Cannot re-assign $this".into(),
                        line: stmt.span.line,
                    });
                }
                if let Some(k) = key {
                    let is_list = matches!(k.kind, ExprKind::Array(_))
                        || matches!(&k.kind, ExprKind::FunctionCall { name, .. }
                            if matches!(&name.kind, ExprKind::Identifier(n) if n.eq_ignore_ascii_case(b"list")));
                    if is_list {
                        return Err(CompileError {
                            message: "Cannot use list as key element".into(),
                            line: stmt.span.line,
                        });
                    }
                    if self.check_foreach_this_assign(k, stmt.span.line)? {
                        return Err(CompileError {
                            message: "Cannot re-assign $this".into(),
                            line: stmt.span.line,
                        });
                    }
                }
                // foreach ($a as [&$x, $y]): iterates by reference, each
                // element bound to a hidden variable that is destructured.
                let list_ref =
                    matches!(&value.kind, ExprKind::Array(elems) if Self::list_has_ref(elems));
                let by_ref = &(*by_ref || list_ref);
                let list_ref_cv = if list_ref {
                    let mut name = b"\0vv".to_vec();
                    name.extend_from_slice(self.dynvar_count.to_string().as_bytes());
                    self.dynvar_count += 1;
                    Some(self.op_array.get_or_create_cv(&name))
                } else {
                    None
                };
                let arr = self.compile_expr(expr)?;
                // foreach (f() as &$v): iterate f()'s returned reference, or a
                // copy of a by-value result.
                let call_src = *by_ref && Self::is_call_expr(expr);
                if call_src {
                    self.mark_ref_call(&arr);
                }
                // A nullsafe chain is fetched for reading: a copy is iterated.
                let temp_src = call_src || (*by_ref && expr_is_in_nullsafe_chain(expr));
                let src_flag = if temp_src {
                    OperandType::Const(self.op_array.add_literal(Value::Long(1)))
                } else {
                    OperandType::Unused
                };

                // Create iterator temp
                let iter_tmp = self.op_array.alloc_temp();
                self.op_array.emit(Op {
                    opcode: if *by_ref {
                        OpCode::ForeachInitRef
                    } else {
                        OpCode::ForeachInit
                    },
                    op1: arr,
                    op2: src_flag,
                    result: OperandType::Tmp(iter_tmp),
                    line: stmt.span.line,
                });

                let depth_nop = if self.op_array.is_generator {
                    None
                } else {
                    Some(self.op_array.emit(Op {
                        opcode: OpCode::Nop,
                        op1: OperandType::Unused,
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: stmt.span.line,
                    }))
                };
                self.loop_stack.push(LoopContext {
                    id: next_loop_id(),
                    break_jumps: Vec::new(),
                    continue_jumps: Vec::new(),
                    continue_target: None,
                    is_switch: false,
                    finally_depth: self.finally_path.len(),
                    try_finally_depth: self.finally_targets.len(),
                    free_tmps: Vec::new(),
                    depth_nop: None,
                    depth_tmp: None,
                    handler_depth: self.handler_regions.len(),
                });

                let loop_start = self.op_array.current_offset();

                // Fetch next value (or jump to end if done)
                let val_tmp = self.op_array.alloc_temp();
                if let Some(ctx) = self.loop_stack.last_mut() {
                    ctx.free_tmps = vec![val_tmp, iter_tmp];
                    if let OperandType::Tmp(arr_tmp) = arr {
                        ctx.free_tmps.push(arr_tmp);
                    }
                    ctx.depth_nop = depth_nop;
                }
                // By-ref foreach into a plain variable: ForeachNextRef binds the
                // variable to the element's reference itself.
                let by_ref_cv = match &value.kind {
                    ExprKind::Variable(name) if *by_ref => {
                        Some(self.op_array.get_or_create_cv(name))
                    }
                    _ => list_ref_cv,
                };
                let jmp_done = if *by_ref {
                    // For by-ref foreach, ForeachNextRef stores reference directly in val_tmp

                    self.op_array.emit(Op {
                        opcode: OpCode::ForeachNextRef,
                        op1: OperandType::Tmp(iter_tmp),
                        op2: OperandType::JmpTarget(0), // patched later
                        result: match by_ref_cv {
                            Some(cv) => OperandType::Cv(cv),
                            None => OperandType::Tmp(val_tmp),
                        },
                        line: stmt.span.line,
                    })
                } else {
                    self.op_array.emit(Op {
                        opcode: OpCode::ForeachNext,
                        op1: OperandType::Tmp(iter_tmp),
                        op2: OperandType::JmpTarget(0), // patched later
                        result: OperandType::Tmp(val_tmp),
                        line: stmt.span.line,
                    })
                };

                // Assign value to the value variable
                if let (Some(cv), ExprKind::Array(elems)) = (list_ref_cv, &value.kind) {
                    let hidden = Expr {
                        kind: ExprKind::Variable(self.op_array.cv_names[cv as usize].clone()),
                        span: value.span,
                    };
                    self.compile_list_destructure_ref(elems, &hidden, stmt.span.line)?;
                    self.op_array.emit(Op {
                        opcode: OpCode::UnsetCv,
                        op1: OperandType::Cv(cv),
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: stmt.span.line,
                    });
                } else if *by_ref {
                    // Plain variables were bound by ForeachNextRef; other
                    // targets are bound to the element's reference.
                    match &value.kind {
                        ExprKind::ArrayAccess { array, index } => {
                            let arr = self.compile_dim_write_base(array)?;
                            match index {
                                Some(idx_expr) => {
                                    let idx = self.compile_expr(idx_expr)?;
                                    self.op_array.emit(Op {
                                        opcode: OpCode::ArraySetRef,
                                        op1: arr,
                                        op2: OperandType::Tmp(val_tmp),
                                        result: idx,
                                        line: stmt.span.line,
                                    });
                                }
                                None => {
                                    self.op_array.emit(Op {
                                        opcode: OpCode::ArrayAppendRef,
                                        op1: arr,
                                        op2: OperandType::Tmp(val_tmp),
                                        result: OperandType::Unused,
                                        line: stmt.span.line,
                                    });
                                }
                            }
                        }
                        ExprKind::PropertyAccess {
                            object,
                            property,
                            nullsafe: false,
                        } => {
                            let obj = self.compile_expr(object)?;
                            let name = self.compile_property_name(property)?;
                            self.op_array.emit(Op {
                                opcode: OpCode::PropertySetRef,
                                op1: obj,
                                op2: OperandType::Tmp(val_tmp),
                                result: name,
                                line: stmt.span.line,
                            });
                        }
                        ExprKind::DynamicVariable(inner) => {
                            // foreach (... as &$$n): bind the named variable.
                            let name_op = self.compile_expr(inner)?;
                            self.op_array.emit(Op {
                                opcode: OpCode::VarVarAssignRef,
                                op1: name_op,
                                op2: OperandType::Tmp(val_tmp),
                                result: OperandType::Unused,
                                line: stmt.span.line,
                            });
                        }
                        _ => {}
                    }
                } else if let ExprKind::Variable(name) = &value.kind {
                    let cv = self.op_array.get_or_create_cv(name);
                    self.op_array.emit(Op {
                        opcode: OpCode::Assign,
                        op1: OperandType::Cv(cv),
                        op2: OperandType::Tmp(val_tmp),
                        result: OperandType::Unused,
                        line: stmt.span.line,
                    });
                } else {
                    // Handle list/array destructuring in foreach value:
                    // foreach ($arr as list($a, $b)) or foreach ($arr as [$a, $b])
                    let elems: Option<Vec<ArrayElement>> = match &value.kind {
                        ExprKind::Array(elems) => Some(elems.clone()),
                        ExprKind::FunctionCall { name, args } if matches!(&name.kind, ExprKind::Identifier(n) if n.eq_ignore_ascii_case(b"list")) => {
                            Some(
                                args.iter()
                                    .map(|a| ArrayElement {
                                        key: None,
                                        value: a.value.clone(),
                                        unpack: false,
                                        by_ref: false,
                                    })
                                    .collect(),
                            )
                        }
                        _ => None,
                    };
                    if let Some(elems) = elems {
                        self.compile_list_destructure(
                            &elems,
                            OperandType::Tmp(val_tmp),
                            stmt.span.line,
                        )?;
                    } else {
                        // foreach ($a as $o->p) / ($a as C::$p) / ($a as $b[k])
                        self.compile_assign_tmp_to_target(value, val_tmp, stmt.span.line)?;
                    }
                }

                // Assign key if present
                if let Some(key_expr) = key {
                    let key_tmp = self.op_array.alloc_temp();
                    self.op_array.emit(Op {
                        opcode: OpCode::ForeachKey,
                        op1: OperandType::Tmp(iter_tmp),
                        op2: OperandType::Unused,
                        result: OperandType::Tmp(key_tmp),
                        line: stmt.span.line,
                    });
                    if let ExprKind::Variable(name) = &key_expr.kind {
                        let cv = self.op_array.get_or_create_cv(name);
                        self.op_array.emit(Op {
                            opcode: OpCode::Assign,
                            op1: OperandType::Cv(cv),
                            op2: OperandType::Tmp(key_tmp),
                            result: OperandType::Unused,
                            line: stmt.span.line,
                        });
                    } else {
                        self.compile_assign_tmp_to_target(key_expr, key_tmp, stmt.span.line)?;
                    }
                }

                // Compile body
                for s in body {
                    self.compile_stmt(s)?;
                }

                // Jump back to next iteration
                self.op_array.emit(Op {
                    opcode: OpCode::Jmp,
                    op1: OperandType::JmpTarget(loop_start),
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line: stmt.span.line,
                });

                let after_loop = self.op_array.current_offset();
                self.op_array.patch_jump(jmp_done, after_loop);

                let ctx = self.loop_stack.pop().unwrap();
                for jmp in ctx.break_jumps {
                    self.op_array.patch_jump(jmp, after_loop);
                }
                for jmp in ctx.continue_jumps {
                    self.op_array.patch_jump(jmp, loop_start);
                }

                // Clean up foreach temps to release references
                // (important for by-ref foreach so Rc counts drop correctly)
                let undef_const = self.op_array.add_literal(Value::Undef);
                self.op_array.emit(Op {
                    opcode: OpCode::Assign,
                    op1: OperandType::Tmp(val_tmp),
                    op2: OperandType::Const(undef_const),
                    result: OperandType::Unused,
                    line: stmt.span.line,
                });
                self.op_array.emit(Op {
                    opcode: OpCode::Assign,
                    op1: OperandType::Tmp(iter_tmp),
                    op2: OperandType::Const(undef_const),
                    result: OperandType::Unused,
                    line: stmt.span.line,
                });
                // FE_FREE: the iterated temporary (e.g. an array literal or a
                // call result) is released with the loop.
                if let OperandType::Tmp(arr_tmp) = arr {
                    self.op_array.emit(Op {
                        opcode: OpCode::Assign,
                        op1: OperandType::Tmp(arr_tmp),
                        op2: OperandType::Const(undef_const),
                        result: OperandType::Unused,
                        line: stmt.span.line,
                    });
                }

                Ok(())
            }

            StmtKind::Switch { expr, cases } => {
                let subject = self.compile_expr(expr)?;
                // zend_compile_switch(): a CV subject is compared as is by
                // each CASE (so an undefined one warns per case); anything
                // else is evaluated once.
                let subject_op = if matches!(subject, OperandType::Cv(_)) {
                    subject
                } else {
                    let subject_tmp = self.op_array.alloc_temp();
                    self.op_array.emit(Op {
                        opcode: OpCode::Assign,
                        op1: OperandType::Tmp(subject_tmp),
                        op2: subject,
                        result: OperandType::Unused,
                        line: stmt.span.line,
                    });
                    OperandType::Tmp(subject_tmp)
                };

                self.loop_stack.push(LoopContext {
                    id: next_loop_id(),
                    break_jumps: Vec::new(),
                    continue_jumps: Vec::new(),
                    continue_target: None,
                    is_switch: true,
                    finally_depth: self.finally_path.len(),
                    try_finally_depth: self.finally_targets.len(),
                    free_tmps: Vec::new(),
                    depth_nop: None,
                    depth_tmp: None,
                    handler_depth: self.handler_regions.len(),
                });

                // Switch compilation strategy:
                // 1. Emit all comparisons first, jumping to the matching body
                // 2. Then emit all bodies in order (supporting fall-through)

                let mut case_body_jumps = Vec::new(); // (jmp_to_body_idx, case_index)
                let mut default_index: Option<usize> = None;

                // Phase 1: emit comparisons
                for (i, case) in cases.iter().enumerate() {
                    if let Some(case_val) = &case.value {
                        let case_op = self.compile_expr(case_val)?;
                        let cmp_tmp = self.op_array.alloc_temp();
                        self.op_array.emit(Op {
                            opcode: OpCode::Equal,
                            op1: subject_op,
                            op2: case_op,
                            result: OperandType::Tmp(cmp_tmp),
                            line: case_val.span.line,
                        });
                        // If match, jump to this case's body
                        let jmp = self.op_array.emit(Op {
                            opcode: OpCode::JmpNz,
                            op1: OperandType::Tmp(cmp_tmp),
                            op2: OperandType::JmpTarget(0), // patched later
                            result: OperandType::Unused,
                            line: stmt.span.line,
                        });
                        case_body_jumps.push((jmp, i));
                    } else {
                        if default_index.is_some() {
                            // Report error at the duplicate default clause
                            let err_line = case
                                .body
                                .first()
                                .map(|s| s.span.line.saturating_sub(1))
                                .unwrap_or(stmt.span.line);
                            return Err(CompileError {
                                message: "Switch statements may only contain one default clause"
                                    .into(),
                                line: err_line,
                            });
                        }
                        default_index = Some(i);
                    }
                }

                // If no case matched and there's a default, jump to default body
                // Otherwise jump past the switch
                let jmp_to_default_or_end = self.op_array.emit(Op {
                    opcode: OpCode::Jmp,
                    op1: OperandType::JmpTarget(0), // patched later
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line: stmt.span.line,
                });

                // Phase 2: emit bodies
                let mut body_offsets = Vec::new();
                for case in cases {
                    let offset = self.op_array.current_offset();
                    body_offsets.push(offset);
                    for s in &case.body {
                        self.compile_stmt(s)?;
                    }
                    // Fall through to next case's body (no implicit break)
                }

                let after_switch = self.op_array.current_offset();

                // Patch comparison jumps to their corresponding body offsets
                for (jmp, case_idx) in case_body_jumps {
                    self.op_array.patch_jump(jmp, body_offsets[case_idx]);
                }

                // Patch default/end jump
                if let Some(def_idx) = default_index {
                    self.op_array
                        .patch_jump(jmp_to_default_or_end, body_offsets[def_idx]);
                } else {
                    self.op_array
                        .patch_jump(jmp_to_default_or_end, after_switch);
                }

                let ctx = self.loop_stack.pop().unwrap();
                // `continue` targeting the switch itself behaves like `break`.
                for jmp in ctx.break_jumps.into_iter().chain(ctx.continue_jumps) {
                    self.op_array.patch_jump(jmp, after_switch);
                }

                Ok(())
            }

            StmtKind::Break(level_expr) => {
                let (level, is_non_integer) = Self::extract_break_continue_level(level_expr);
                if is_non_integer {
                    return Err(CompileError {
                        message: "'break' operator with non-integer operand is no longer supported"
                            .into(),
                        line: stmt.span.line,
                    });
                }
                if level == 0 {
                    return Err(CompileError {
                        message: "'break' operator accepts only positive integers".into(),
                        line: stmt.span.line,
                    });
                }
                if self.loop_stack.is_empty() {
                    return Err(CompileError {
                        message: "'break' not in the 'loop' or 'switch' context".into(),
                        line: stmt.span.line,
                    });
                }
                let stack_len = self.loop_stack.len();
                if level > stack_len {
                    return Err(CompileError {
                        message: format!("Cannot 'break' {} levels", level),
                        line: stmt.span.line,
                    });
                }
                let target_index = stack_len - level;
                if self.finally_path.len() > self.loop_stack[target_index].finally_depth {
                    return Err(CompileError {
                        message: "jump out of a finally block is disallowed".into(),
                        line: stmt.span.line,
                    });
                }
                self.emit_loop_exit(target_index, false, stmt.span.line);
                Ok(())
            }

            StmtKind::Continue(level_expr) => {
                let (level, is_non_integer) = Self::extract_break_continue_level(level_expr);
                if is_non_integer {
                    return Err(CompileError {
                        message:
                            "'continue' operator with non-integer operand is no longer supported"
                                .into(),
                        line: stmt.span.line,
                    });
                }
                if level == 0 {
                    return Err(CompileError {
                        message: "'continue' operator accepts only positive integers".into(),
                        line: stmt.span.line,
                    });
                }
                if self.loop_stack.is_empty() {
                    return Err(CompileError {
                        message: "'continue' not in the 'loop' or 'switch' context".into(),
                        line: stmt.span.line,
                    });
                }
                let stack_len = self.loop_stack.len();
                if level > stack_len {
                    return Err(CompileError {
                        message: format!("Cannot 'continue' {} levels", level),
                        line: stmt.span.line,
                    });
                }
                let target_index = stack_len - level;
                // `continue` targeting a switch acts like `break` (zend_compile_break_continue).
                if self.loop_stack[target_index].is_switch {
                    let has_parent = target_index > 0;
                    let msg = match (level == 1, has_parent) {
                        (true, false) => {
                            "\"continue\" targeting switch is equivalent to \"break\"".to_string()
                        }
                        (true, true) => format!(
                            "\"continue\" targeting switch is equivalent to \"break\". Did you mean to use \"continue {}\"?",
                            level + 1
                        ),
                        (false, false) => format!(
                            "\"continue {}\" targeting switch is equivalent to \"break {}\"",
                            level, level
                        ),
                        (false, true) => format!(
                            "\"continue {}\" targeting switch is equivalent to \"break {}\". Did you mean to use \"continue {}\"?",
                            level,
                            level,
                            level + 1
                        ),
                    };
                    push_compile_warning_tuple((msg.clone(), stmt.span.line));
                    push_pending_compile_warning(msg, stmt.span.line);
                }
                if self.finally_path.len() > self.loop_stack[target_index].finally_depth {
                    return Err(CompileError {
                        message: "jump out of a finally block is disallowed".into(),
                        line: stmt.span.line,
                    });
                }
                self.emit_loop_exit(target_index, true, stmt.span.line);
                Ok(())
            }

            StmtKind::FunctionDecl {
                name,
                params,
                body,
                return_type,
                attributes: func_attributes,
                end_line: func_end_line,
                doc_comment: func_doc_comment,
                returns_by_ref: func_returns_by_ref,
                ..
            } => {
                if self.in_main_pass {
                    // A conditional / nested declaration (top-level ones are
                    // noted at their position in the main pass).
                    self.note_symbol_decl(&UseKind::Function, name, stmt.span.line)?;
                }
                if name.eq_ignore_ascii_case(b"assert") {
                    return Err(CompileError {
                        message: "Defining a custom assert() function is not allowed, as the function has special semantics".to_string(),
                        line: stmt.span.line,
                    });
                }
                // Check for promoted properties in free functions
                for param in params {
                    if param.visibility.is_some() || param.readonly || param.is_final {
                        return Err(CompileError {
                            message: "Cannot declare promoted property outside a constructor"
                                .to_string(),
                            line: stmt.span.line,
                        });
                    }
                }
                // NoDiscard validation: cannot be used on void/never function.
                {
                    let has_nodiscard = func_attributes.iter().any(|a| {
                        let last = a.name.last().map(|s| s.as_slice()).unwrap_or(&[]);
                        let bare: &[u8] = if last.first() == Some(&b'\\') {
                            &last[1..]
                        } else {
                            last
                        };
                        bare.eq_ignore_ascii_case(b"NoDiscard")
                    });
                    if has_nodiscard {
                        if let Some(hint) = return_type {
                            if let TypeHint::Simple(s) = hint {
                                if s.eq_ignore_ascii_case(b"never") {
                                    return Err(CompileError {
                                        message: "A never returning function does not return a value, but #[\\NoDiscard] requires a return value".to_string(),
                                        line: stmt.span.line,
                                    });
                                }
                                if s.eq_ignore_ascii_case(b"void") {
                                    return Err(CompileError {
                                        message: "A void function does not return a value, but #[\\NoDiscard] requires a return value".to_string(),
                                        line: stmt.span.line,
                                    });
                                }
                            }
                        }
                    }
                }

                // Check if this function contains yield (making it a generator)
                let is_generator = stmts_contain_yield(body);

                // Prefix function name with namespace
                let qualified_name = self.prefix_with_namespace(name);

                // Compile the function body into a sub-OpArray
                let mut func_compiler = Compiler::new();
                func_compiler.current_namespace = self.current_namespace.clone();
                func_compiler.use_map = self.use_map.clone();
                func_compiler.use_function_map = self.use_function_map.clone();
                func_compiler.use_const_map = self.use_const_map.clone();
                func_compiler.op_array.name = qualified_name.clone();
                func_compiler.in_free_function = self.current_class.is_none();
                func_compiler.op_array.is_generator = is_generator;
                func_compiler.op_array.returns_by_ref = *func_returns_by_ref;
                func_compiler.op_array.decl_line = stmt.span.line;
                func_compiler.op_array.end_line = if *func_end_line > 0 {
                    *func_end_line
                } else {
                    stmt.span.line
                };
                func_compiler.op_array.doc_comment = func_doc_comment.clone();
                func_compiler.op_array.strict_types = self.op_array.strict_types;
                func_compiler.op_array.attributes =
                    self.compile_attributes_target(func_attributes, "function");
                // Carry the source filename so ReflectionFunction::getFileName()
                // can report where the function was declared, not where it was
                // first looked up.
                func_compiler.op_array.filename = self.source_file.clone();
                func_compiler.source_file = self.source_file.clone();
                func_compiler.anon_class_name_map = self.anon_class_name_map.clone();

                // Set return type
                if let Some(hint) = return_type {
                    // Check for self/parent/static outside of class scope
                    if self.current_class.is_none() {
                        if let Some(err) = check_relative_type_outside_class(hint) {
                            return Err(CompileError {
                                message: err,
                                line: stmt.span.line,
                            });
                        }
                    }
                    // Validate type hint for redundancy and standalone constraints
                    if let Some(err) = validate_type_hint(hint, self.current_class.as_deref())
                        .or_else(|| self.type_redundancy_error(hint, stmt.span.line))
                    {
                        return Err(CompileError {
                            message: err,
                            line: stmt.span.line,
                        });
                    }
                    func_compiler.op_array.return_type = Some(type_hint_to_param_type_with_ns(
                        hint,
                        &self.current_namespace,
                        &self.use_map,
                    ));
                    // Check for 'never' return type
                    if let TypeHint::Simple(name) = hint {
                        let name_lower: Vec<u8> =
                            name.iter().map(|b| b.to_ascii_lowercase()).collect();
                        if name_lower == b"never" {
                            func_compiler.has_never_return = true;
                        }
                    }
                }

                // Validate parameter types
                for param in params.iter() {
                    if let Some(hint) = &param.type_hint {
                        // Check for self/parent/static outside class scope
                        if self.current_class.is_none() {
                            if let Some(err) = check_relative_type_outside_class(hint) {
                                return Err(CompileError {
                                    message: err,
                                    line: stmt.span.line,
                                });
                            }
                        }
                        // Validate type hint for redundancy and standalone constraints
                        if let Some(err) = validate_type_hint(hint, self.current_class.as_deref())
                            .or_else(|| self.type_redundancy_error(hint, stmt.span.line))
                        {
                            return Err(CompileError {
                                message: err,
                                line: stmt.span.line,
                            });
                        }
                        let simple_hint = match hint {
                            TypeHint::Simple(n) => Some(n),
                            TypeHint::Nullable(inner) => {
                                if let TypeHint::Simple(n) = inner.as_ref() {
                                    Some(n)
                                } else {
                                    None
                                }
                            }
                            _ => None,
                        };
                        if let Some(n) = simple_hint {
                            let lower: Vec<u8> = n.iter().map(|b| b.to_ascii_lowercase()).collect();
                            if lower == b"void" {
                                return Err(CompileError {
                                    message: "void cannot be used as a parameter type".to_string(),
                                    line: stmt.span.line,
                                });
                            }
                            if lower == b"never" {
                                return Err(CompileError {
                                    message: "never cannot be used as a parameter type".to_string(),
                                    line: stmt.span.line,
                                });
                            }
                            if lower == b"static" {
                                return Err(CompileError {
                                    message: "Cannot use the static modifier on a parameter"
                                        .to_string(),
                                    line: stmt.span.line,
                                });
                            }
                        }
                    }
                }

                // Check for duplicate parameter names and reserved names
                check_duplicate_params(params, func_compiler.op_array.decl_line)?;

                // Set up parameter CVs and default values
                func_compiler.op_array.param_count = params.len() as u32;
                // required_param_count: equals the index AFTER the last required
                // parameter (1-based position). Optional params that appear before
                // a required one are implicitly treated as required (PHP 8.0+).
                func_compiler.op_array.required_param_count = {
                    let mut last_req: i64 = -1;
                    for (i, p) in params.iter().enumerate() {
                        if !p.variadic && p.default.is_none() {
                            last_req = i as i64;
                        }
                    }
                    (last_req + 1) as u32
                };
                // Compile parameter attributes
                func_compiler.op_array.param_attributes = params
                    .iter()
                    .map(|p| self.compile_attributes_target(&p.attributes, "parameter"))
                    .collect();
                // Record which parameters are by-reference
                func_compiler.op_array.by_ref_params = params.iter().map(|p| p.by_ref).collect();
                // Record which parameters have default values
                func_compiler.op_array.param_has_default =
                    params.iter().map(|p| p.default.is_some()).collect();
                for param in params {
                    let cv = func_compiler.op_array.get_or_create_cv(&param.name);
                    if param.variadic {
                        func_compiler.op_array.variadic_param = Some(cv);
                    }
                    if let Some(hint) = &param.type_hint {
                        let pt = type_hint_to_param_type_with_ns(
                            hint,
                            &self.current_namespace,
                            &self.use_map,
                        );
                        if let Some(message) = reserved_type_name_error(&pt) {
                            return Err(CompileError {
                                message,
                                line: stmt.span.line,
                            });
                        }
                    }

                    // Store parameter type info
                    let type_info = param.type_hint.as_ref().map(|hint| {
                        let mut pt = type_hint_to_param_type_with_ns(
                            hint,
                            &self.current_namespace,
                            &self.use_map,
                        );
                        let mut is_implicitly_nullable = false;
                        if let Some(default_expr) = &param.default {
                            if matches!(default_expr.kind, ExprKind::Null)
                                && !is_type_nullable_or_mixed(&pt)
                            {
                                pt = ParamType::Nullable(Box::new(pt));
                                is_implicitly_nullable = true;
                            }
                        }
                        ParamTypeInfo {
                            param_type: pt,
                            param_name: param.name.clone(),
                            implicitly_nullable: is_implicitly_nullable,
                        }
                    });
                    // Ensure param_types vec is large enough
                    while func_compiler.op_array.param_types.len() <= cv as usize {
                        func_compiler.op_array.param_types.push(None);
                    }
                    func_compiler.op_array.param_types[cv as usize] = type_info;

                    if let Some(default_expr) = &param.default {
                        func_compiler
                            .op_array
                            .set_param_default_repr(cv, self.default_value_repr(default_expr));
                        // Emit: if param is Undef, set to default
                        let null_idx = func_compiler.op_array.add_literal(Value::Undef);
                        let check_tmp = func_compiler.op_array.alloc_temp();
                        func_compiler.op_array.emit(Op {
                            opcode: OpCode::Identical,
                            op1: OperandType::Cv(cv),
                            op2: OperandType::Const(null_idx),
                            result: OperandType::Tmp(check_tmp),
                            line: 0,
                        });
                        let jmp_skip = func_compiler.op_array.emit(Op {
                            opcode: OpCode::JmpZ,
                            op1: OperandType::Tmp(check_tmp),
                            op2: OperandType::JmpTarget(0),
                            result: OperandType::Unused,
                            line: 0,
                        });
                        let default_val = func_compiler.compile_const_expr_value(default_expr)?;
                        if !matches!(default_expr.kind, ExprKind::Null) {
                            let pcv = func_compiler.op_array.get_or_create_cv(&param.name) as usize;
                            if let Some(Some(pti)) =
                                func_compiler.op_array.param_types.get(pcv).cloned()
                            {
                                match Self::check_literal_default(&pti.param_type, default_expr) {
                                    Err((tn, _)) => {
                                        return Err(CompileError {
                                            message: format!(
                                                "Cannot use {} as default value for parameter ${} of type {}",
                                                tn,
                                                String::from_utf8_lossy(&param.name),
                                                crate::vm::variance::type_to_string(
                                                    &crate::vm::variance::TypeView::from_param_type(
                                                        &pti.param_type
                                                    ),
                                                    None
                                                )
                                            ),
                                            line: default_expr.span.line,
                                        });
                                    }
                                    Ok(Some(widened)) => {
                                        if let OperandType::Const(li) = default_val {
                                            func_compiler.op_array.literals[li as usize] = widened;
                                        }
                                    }
                                    Ok(None) => {}
                                }
                            }
                        }
                        // Check if CV is Undef (null check + type check)
                        func_compiler.op_array.emit(Op {
                            opcode: OpCode::Assign,
                            op1: OperandType::Cv(cv),
                            op2: default_val,
                            result: OperandType::Unused,
                            line: 0,
                        });
                        Self::emit_recv_default_check(
                            &mut func_compiler.op_array,
                            cv,
                            default_expr,
                        );
                        let after = func_compiler.op_array.current_offset();
                        func_compiler.op_array.patch_jump(jmp_skip, after);
                    }
                }

                for s in body {
                    func_compiler.compile_stmt(s)?;
                }

                // Reject any unresolved gotos in this function body
                func_compiler.check_pending_gotos()?;

                // Implicit return null
                let implicit_line = func_compiler.op_array.end_line;
                func_compiler.emit_by_ref_return_notice(None, implicit_line);
                let null_idx = func_compiler.op_array.add_literal(Value::Null);
                func_compiler.op_array.emit(Op {
                    opcode: OpCode::Return,
                    op1: OperandType::Const(null_idx),
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line: 0,
                });

                // Store the compiled function and emit a DeclareFunction opcode
                let func_idx = self.op_array.child_functions.len() as u32;
                self.op_array.child_functions.push(func_compiler.op_array);

                let name_idx = self
                    .op_array
                    .add_literal(Value::String(PhpString::from_vec(qualified_name)));
                let idx_literal = self.op_array.add_literal(Value::Long(func_idx as i64));
                // result = Const(error type): a named function declaration,
                // bound with do_bind_function()'s redeclaration check (closures
                // share the opcode but are re-declared on every evaluation).
                // A top-level declaration is bound at compile time in PHP
                // (E_COMPILE_ERROR), a conditional / nested one at run time.
                let named_marker = self
                    .op_array
                    .add_literal(Value::Long(if self.in_hoisting_pass { 64 } else { 1 }));

                self.op_array.emit(Op {
                    opcode: OpCode::DeclareFunction,
                    op1: OperandType::Const(name_idx),
                    op2: OperandType::Const(idx_literal),
                    result: OperandType::Const(named_marker),
                    line: stmt.span.line,
                });

                Ok(())
            }

            StmtKind::Declare {
                directives,
                body,
                attributes,
                is_const,
            } => {
                // If attributes are present and there's more than one directive,
                // this is `#[Attr] const A=1, B=2;` which is a fatal error.
                if !attributes.is_empty() && directives.len() > 1 {
                    self.deferred_fatal_errors
                        .push("Cannot apply attributes to multiple constants at once".to_string());
                }

                let mut new_ticks: Option<u32> = None;
                // Handle const declarations (parsed as Declare directives)
                for (name, value) in directives {
                    let name_lower: Vec<u8> = name.iter().map(|b| b.to_ascii_lowercase()).collect();
                    // Handle declare(strict_types=1)
                    if name_lower == b"strict_types" {
                        if let ExprKind::Int(n) = &value.kind {
                            if *n == 1 {
                                self.op_array.strict_types = true;
                            }
                        }
                        continue;
                    }
                    // declare(ticks = N): value must be a literal
                    if name_lower == b"ticks" {
                        if !matches!(
                            &value.kind,
                            ExprKind::Int(_)
                                | ExprKind::Float(_)
                                | ExprKind::String(_)
                                | ExprKind::True
                                | ExprKind::False
                                | ExprKind::Null
                        ) {
                            return Err(CompileError {
                                message: "declare(ticks) value must be a literal".into(),
                                line: stmt.span.line,
                            });
                        }
                        // zval_get_long() of the literal
                        let n = Self::eval_const_expr(value)
                            .map(|v| v.to_long())
                            .unwrap_or(0);
                        new_ticks = Some(n.clamp(0, u32::MAX as i64) as u32);
                        continue;
                    }
                    // declare(encoding = ...): value must be a literal; non-string literals get a warning
                    if name_lower == b"encoding" {
                        let line = value.span.line;
                        // (with zend.multibyte off, the parser warned instead)
                        let multibyte = goro_parser::multibyte::multibyte_enabled();
                        match &value.kind {
                            // Checked by the parser
                            ExprKind::String(_) => {}
                            ExprKind::Int(_)
                            | ExprKind::Float(_)
                            | ExprKind::True
                            | ExprKind::False
                            | ExprKind::Null
                                if !multibyte => {}
                            ExprKind::Int(n) => {
                                let msg = format!("Unsupported encoding [{}]", n);
                                push_compile_warning_tuple((msg.clone(), line));
                                push_pending_compile_warning(msg, line);
                            }
                            ExprKind::Float(f) => {
                                let s = crate::value::format_php_float(*f);
                                let msg = format!("Unsupported encoding [{}]", s);
                                push_compile_warning_tuple((msg.clone(), line));
                                push_pending_compile_warning(msg, line);
                            }
                            ExprKind::True => {
                                let msg = "Unsupported encoding [1]".to_string();
                                push_compile_warning_tuple((msg.clone(), line));
                                push_pending_compile_warning(msg, line);
                            }
                            ExprKind::False | ExprKind::Null => {
                                let msg = "Unsupported encoding []".to_string();
                                push_compile_warning_tuple((msg.clone(), line));
                                push_pending_compile_warning(msg, line);
                            }
                            _ => {
                                return Err(CompileError {
                                    message: "Encoding must be a literal".into(),
                                    line: value.span.line,
                                });
                            }
                        }
                        if !self
                            .leading_declare_stmts
                            .contains(&(stmt as *const Statement as usize))
                        {
                            return Err(CompileError {
                                message: "Encoding declaration pragma must be the very first statement in the script".into(),
                                line: stmt.span.line,
                            });
                        }
                        continue;
                    }
                    if !*is_const {
                        // zend_compile_declare(): E_COMPILE_WARNING
                        let msg =
                            format!("Unsupported declare '{}'", String::from_utf8_lossy(name));
                        push_compile_warning_tuple((msg.clone(), stmt.span.line));
                        push_pending_compile_warning(msg, stmt.span.line);
                        continue;
                    }
                    // This is a const declaration: const FOO = value;
                    if let Some(message) = Self::const_expr_error(value, true) {
                        return Err(CompileError {
                            message,
                            line: value.span.line,
                        });
                    }
                    // zend_compile_const_decl(): true/false/null cannot be
                    // redeclared; then the collision with a `use const`.
                    if matches!(name_lower.as_slice(), b"true" | b"false" | b"null") {
                        return Err(CompileError {
                            message: format!(
                                "Cannot redeclare constant '{}'",
                                String::from_utf8_lossy(name)
                            ),
                            line: stmt.span.line,
                        });
                    }
                    self.note_symbol_decl(&UseKind::Constant, name, stmt.span.line)?;
                    // Check for invalid spreads BEFORE emitting the define() call.
                    // PHP only allows arrays (or constant arrays) to be spread in constant expressions.
                    // A non-constant spread (e.g. `[...new ArrayObject()]`) is compiled as a runtime
                    // Error throw (not a compile error), matching PHP's behavior.
                    if let ExprKind::Array(elements) = &value.kind {
                        let mut has_invalid_spread = false;
                        for elem in elements.iter() {
                            if elem.unpack {
                                match Self::eval_const_expr(&elem.value) {
                                    Some(Value::Array(_)) => {} // OK: literal array spread
                                    Some(_) => {} // Non-array constant; will fail at runtime
                                    None => {
                                        // Cannot evaluate at compile time: non-constant expression
                                        has_invalid_spread = true;
                                        break;
                                    }
                                }
                            }
                        }
                        if has_invalid_spread {
                            // Emit: throw new Error("Only arrays can be unpacked in constant expression")
                            let err_msg_bytes =
                                b"Only arrays can be unpacked in constant expression";
                            let err_class_idx = self
                                .op_array
                                .add_literal(Value::String(PhpString::from_bytes(b"Error")));
                            let err_msg_idx = self
                                .op_array
                                .add_literal(Value::String(PhpString::from_bytes(err_msg_bytes)));
                            let err_tmp = self.op_array.alloc_temp();
                            self.op_array.emit(Op {
                                opcode: OpCode::NewObject,
                                op1: OperandType::Const(err_class_idx),
                                op2: OperandType::Unused,
                                result: OperandType::Tmp(err_tmp),
                                line: value.span.line,
                            });
                            let ctor_name_idx = self
                                .op_array
                                .add_literal(Value::String(PhpString::from_bytes(b"__construct")));
                            self.op_array.emit(Op {
                                opcode: OpCode::InitMethodCall,
                                op1: OperandType::Tmp(err_tmp),
                                op2: OperandType::Const(ctor_name_idx),
                                result: OperandType::Unused,
                                line: value.span.line,
                            });
                            let pos0_idx = self.op_array.add_literal(Value::Long(0));
                            self.op_array.emit(Op {
                                opcode: OpCode::SendVal,
                                op1: OperandType::Const(err_msg_idx),
                                op2: OperandType::Const(pos0_idx),
                                result: OperandType::Unused,
                                line: value.span.line,
                            });
                            let call_tmp = self.op_array.alloc_temp();
                            self.op_array.emit(Op {
                                opcode: OpCode::DoFCall,
                                op1: OperandType::Unused,
                                op2: OperandType::Unused,
                                result: OperandType::Tmp(call_tmp),
                                line: value.span.line,
                            });
                            self.op_array.emit(Op {
                                opcode: OpCode::Throw,
                                op1: OperandType::Tmp(err_tmp),
                                op2: OperandType::Unused,
                                result: OperandType::Unused,
                                line: value.span.line,
                            });
                            continue; // Skip the define() call for this const
                        }
                    }
                    // Emit it as a define() call
                    // Build the fully-qualified constant name
                    let fqn = self.prefix_with_namespace(name);
                    // Register any attributes for this constant (PHP 8.5+)
                    if !attributes.is_empty() {
                        let compiled_attrs = self.compile_attributes_target(attributes, "constant");
                        let idx = self.op_array.const_attribute_table.len() as i64;
                        self.op_array
                            .const_attribute_table
                            .push((fqn.clone(), compiled_attrs));
                        let idx_lit = self.op_array.add_literal(Value::Long(idx));
                        self.op_array.emit(Op {
                            opcode: OpCode::RegisterConstAttrs,
                            op1: OperandType::Const(idx_lit),
                            op2: OperandType::Unused,
                            result: OperandType::Unused,
                            line: stmt.span.line,
                        });
                    }
                    let name_idx = self
                        .op_array
                        .add_literal(Value::String(PhpString::from_vec(fqn)));
                    let define_idx = self
                        .op_array
                        .add_literal(Value::String(PhpString::from_bytes(b"define")));
                    let arg_count_idx = self.op_array.add_literal(Value::Long(2));
                    self.op_array.emit(Op {
                        opcode: OpCode::InitFCall,
                        op1: OperandType::Const(define_idx),
                        op2: OperandType::Const(arg_count_idx),
                        result: OperandType::Unused,
                        line: stmt.span.line,
                    });
                    // Send const name as first arg
                    let pos0 = self.op_array.add_literal(Value::Long(0));
                    self.op_array.emit(Op {
                        opcode: OpCode::SendVal,
                        op1: OperandType::Const(name_idx),
                        op2: OperandType::Const(pos0),
                        result: OperandType::Unused,
                        line: stmt.span.line,
                    });
                    // Send value as second arg
                    let val_op = self.compile_const_expr_value(value)?;
                    let pos1 = self.op_array.add_literal(Value::Long(1));
                    self.op_array.emit(Op {
                        opcode: OpCode::SendVal,
                        op1: val_op,
                        op2: OperandType::Const(pos1),
                        result: OperandType::Unused,
                        line: stmt.span.line,
                    });
                    // Call define()
                    let tmp = self.op_array.alloc_temp();
                    self.op_array.emit(Op {
                        opcode: OpCode::DoFCall,
                        op1: OperandType::Unused,
                        op2: OperandType::Unused,
                        result: OperandType::Tmp(tmp),
                        line: stmt.span.line,
                    });
                }
                // If body exists, compile it (a declare(ticks) block only
                // applies inside it).
                if let Some(body_stmts) = body {
                    let saved_ticks = new_ticks.map(|n| TICKS.with(|t| t.replace(n)));
                    let r = body_stmts.iter().try_for_each(|s| self.compile_stmt(s));
                    if let Some(t) = saved_ticks {
                        TICKS.with(|c| c.set(t));
                    }
                    r?;
                } else if let Some(n) = new_ticks {
                    TICKS.with(|t| t.set(n));
                }
                Ok(())
            }

            StmtKind::StaticVar(vars) => {
                for (name, default) in vars {
                    if name == b"this" {
                        return Err(CompileError {
                            message: "Cannot use $this as static variable".into(),
                            line: stmt.span.line,
                        });
                    }
                    let cv = self.op_array.get_or_create_cv(name);
                    // Create a key for the static variable: "funcname::varname"
                    // ("class::method::varname" for methods: each declaring
                    // class has its own statics).
                    let mut key = Vec::new();
                    if self.op_array.name.is_empty() {
                        // Top-level code of a file or eval()'d string: its
                        // own op_array, so its own statics.
                        if self.main_static_id == 0 {
                            static NEXT: std::sync::atomic::AtomicU64 =
                                std::sync::atomic::AtomicU64::new(1);
                            self.main_static_id =
                                NEXT.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                        }
                        key.extend_from_slice(format!("\0main#{}", self.main_static_id).as_bytes());
                    }
                    if let Some(sc) = &self.op_array.scope_class {
                        if !self.op_array.name.starts_with(b"{closure") {
                            key.extend_from_slice(sc);
                            key.extend_from_slice(b"::");
                        }
                    }
                    key.extend_from_slice(&self.op_array.name);
                    key.extend_from_slice(b"::");
                    key.extend_from_slice(name);
                    // zend_compile_static_var_common()
                    let dup = self.op_array.ops.iter().any(|o| {
                        o.opcode == OpCode::StaticVarInit
                            && matches!(o.result, OperandType::Const(k)
                                if matches!(self.op_array.literals.get(k as usize),
                                    Some(Value::String(s)) if s.as_bytes() == key.as_slice()))
                    });
                    // A closure's `use` variables live in the same static table.
                    let dup = dup
                        || (name.as_slice() != b"this"
                            && self
                                .op_array
                                .closure_capture_names
                                .iter()
                                .any(|n| n.as_slice() == name.as_slice()));
                    if dup {
                        return Err(CompileError {
                            message: format!(
                                "Duplicate declaration of static variable ${}",
                                String::from_utf8_lossy(name)
                            ),
                            line: stmt.span.line,
                        });
                    }
                    let key_idx = self
                        .op_array
                        .add_literal(Value::String(PhpString::from_vec(key)));
                    // A non-constant initializer runs only on first execution
                    // (PHP 8.3+): guard it like ZEND_BIND_INIT_STATIC_OR_JMP.
                    let guard = match default {
                        Some(e) if Self::eval_const_expr(e).is_none() => {
                            Some(self.op_array.emit(Op {
                                opcode: OpCode::StaticVarInitOrJmp,
                                op1: OperandType::Cv(cv),
                                op2: OperandType::JmpTarget(0),
                                result: OperandType::Const(key_idx),
                                line: stmt.span.line,
                            }))
                        }
                        _ => None,
                    };
                    if let Some(v) = default.as_ref().and_then(Self::eval_const_expr) {
                        self.op_array
                            .static_defaults
                            .get_or_insert_with(Default::default)
                            .push((key_idx, v));
                    }
                    let default_val = if let Some(expr) = default {
                        self.compile_expr(expr)?
                    } else {
                        let idx = self.op_array.add_literal(Value::Null);
                        OperandType::Const(idx)
                    };
                    if let Some(g) = guard {
                        let target = self.op_array.current_offset();
                        self.op_array.ops[g as usize].op2 = OperandType::JmpTarget(target);
                    }
                    self.op_array.emit(Op {
                        opcode: OpCode::StaticVarInit,
                        op1: OperandType::Cv(cv),
                        op2: default_val,
                        result: OperandType::Const(key_idx),
                        line: stmt.span.line,
                    });
                }
                Ok(())
            }

            StmtKind::Global(vars) => {
                for name in vars {
                    if name == b"this" {
                        return Err(CompileError {
                            message: "Cannot use $this as global variable".into(),
                            line: stmt.span.line,
                        });
                    }
                    let cv = self.op_array.get_or_create_cv(name);
                    let name_idx = self
                        .op_array
                        .add_literal(Value::String(PhpString::from_vec(name.clone())));
                    self.op_array.emit(Op {
                        opcode: OpCode::BindGlobal,
                        op1: OperandType::Cv(cv),
                        op2: OperandType::Const(name_idx),
                        result: OperandType::Unused,
                        line: stmt.span.line,
                    });
                }
                Ok(())
            }

            StmtKind::GlobalDynamic(exprs) => {
                for e in exprs {
                    match &e.kind {
                        ExprKind::Variable(name) => {
                            let st = Statement {
                                kind: StmtKind::Global(vec![name.clone()]),
                                span: stmt.span,
                            };
                            self.compile_stmt(&st)?;
                        }
                        ExprKind::DynamicVariable(inner) => {
                            // The local variable named by the expression is bound.
                            let name_op = self.compile_expr(inner)?;
                            self.op_array.emit(Op {
                                opcode: OpCode::BindGlobal,
                                op1: OperandType::Unused,
                                op2: name_op,
                                result: OperandType::Unused,
                                line: stmt.span.line,
                            });
                        }
                        _ => {}
                    }
                }
                Ok(())
            }

            StmtKind::Unset(exprs) => {
                for expr in exprs {
                    if expr_is_in_nullsafe_chain(expr) {
                        return Err(CompileError {
                            message: "Can't use nullsafe operator in write context".into(),
                            line: stmt.span.line,
                        });
                    }
                    // zend_compile_unset() -> zend_ensure_writable_variable()
                    let call_msg = match &expr.kind {
                        ExprKind::FunctionCall { .. } => {
                            Some("Can't use function return value in write context")
                        }
                        ExprKind::MethodCall { .. }
                        | ExprKind::StaticMethodCall { .. }
                        | ExprKind::DynamicStaticMethodCall { .. } => {
                            Some("Can't use method return value in write context")
                        }
                        _ => None,
                    };
                    if let Some(msg) = call_msg {
                        return Err(CompileError {
                            message: msg.into(),
                            line: expr.span.line,
                        });
                    }
                    // zend_compile_var_inner(): the base of an unset
                    // property/dimension chain must be writable.
                    let mut root = expr;
                    loop {
                        match &root.kind {
                            ExprKind::ArrayAccess { array, .. } => root = array,
                            ExprKind::PropertyAccess { object, .. } => root = object,
                            _ => break,
                        }
                    }
                    if !std::ptr::eq(root, expr)
                        && matches!(
                            root.kind,
                            ExprKind::ClassConstAccess { .. }
                                | ExprKind::DynamicClassConstAccess { .. }
                                | ExprKind::ConstantAccess(_)
                                | ExprKind::Identifier(_)
                                | ExprKind::Int(_)
                                | ExprKind::Float(_)
                                | ExprKind::String(_)
                                | ExprKind::InterpolatedString(_)
                                | ExprKind::True
                                | ExprKind::False
                                | ExprKind::Null
                                | ExprKind::Array(_)
                                | ExprKind::New { .. }
                        )
                    {
                        return Err(CompileError {
                            message: "Cannot use temporary expression in write context".into(),
                            line: stmt.span.line,
                        });
                    }
                    match &expr.kind {
                        ExprKind::ArrayAccess { array, index } => {
                            // unset($arr[$key]) - remove element from array
                            if index.is_none() {
                                return Err(CompileError {
                                    message: "Cannot use [] for unsetting".into(),
                                    line: stmt.span.line,
                                });
                            }
                            let arr_operand = self.compile_dim_write_base_mode(
                                array,
                                crate::fetch_w::DimFetch::Unset,
                            )?;
                            if let Some(idx_expr) = index {
                                let idx_operand = self.compile_expr(idx_expr)?;
                                self.op_array.emit(Op {
                                    opcode: OpCode::ArrayUnset,
                                    op1: arr_operand,
                                    op2: idx_operand,
                                    result: OperandType::Unused,
                                    line: stmt.span.line,
                                });
                            }
                        }
                        ExprKind::PropertyAccess {
                            object, property, ..
                        } => {
                            // unset($obj->prop) - remove property
                            let obj_operand = self.compile_obj_write_base_mode(
                                object,
                                crate::fetch_w::DimFetch::Unset,
                            )?;
                            let prop_operand = self.compile_property_name(property)?;
                            self.op_array.emit(Op {
                                opcode: OpCode::PropertyUnset,
                                op1: obj_operand,
                                op2: prop_operand,
                                result: OperandType::Unused,
                                line: stmt.span.line,
                            });
                        }
                        ExprKind::Variable(name) if name == b"GLOBALS" => {
                            return Err(CompileError {
                                message: "$GLOBALS can only be modified using the $GLOBALS[$name] = $value syntax".to_string(),
                                line: stmt.span.line,
                            });
                        }
                        ExprKind::StaticPropertyAccess { .. }
                        | ExprKind::DynamicStaticPropertyAccess { .. } => {
                            // unset(C::$p) throws at runtime (ZEND_UNSET_STATIC_PROP)
                            let (class_op, name_op) = self.compile_static_prop_operands(expr)?;
                            self.op_array.emit(Op {
                                opcode: OpCode::StaticPropUnset,
                                op1: class_op,
                                op2: name_op,
                                result: OperandType::Unused,
                                line: stmt.span.line,
                            });
                        }
                        ExprKind::Variable(name) if name == b"this" => {
                            return Err(CompileError {
                                message: "Cannot unset $this".into(),
                                line: stmt.span.line,
                            });
                        }
                        ExprKind::DynamicVariable(inner)
                            if Self::static_dynvar_name(inner).is_none() =>
                        {
                            // unset($$name): ZEND_UNSET_VAR
                            let name_op = self.compile_expr(inner)?;
                            self.op_array.emit(Op {
                                opcode: OpCode::VarVarUnset,
                                op1: name_op,
                                op2: OperandType::Unused,
                                result: OperandType::Unused,
                                line: stmt.span.line,
                            });
                        }
                        _ => {
                            // unset($var) - directly set variable to Undef (breaks reference links)
                            let operand = self.compile_expr(expr)?;
                            self.op_array.emit(Op {
                                opcode: OpCode::UnsetCv,
                                op1: operand,
                                op2: OperandType::Unused,
                                result: OperandType::Unused,
                                line: stmt.span.line,
                            });
                        }
                    }
                }
                Ok(())
            }

            StmtKind::Throw(expr) => {
                let val = self.compile_expr(expr)?;
                self.op_array.emit(Op {
                    opcode: OpCode::Throw,
                    op1: val,
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line: stmt.span.line,
                });
                Ok(())
            }

            StmtKind::TryCatch {
                try_body,
                catches,
                finally_body,
            } => {
                // Check for try without catch or finally
                if catches.is_empty() && finally_body.is_none() {
                    return Err(CompileError {
                        message: "Cannot use try without catch or finally".into(),
                        line: stmt.span.line,
                    });
                }

                // The finally block's slot: what is pending while it runs.
                let finally_slot = if finally_body.is_some() {
                    Some(self.op_array.alloc_temp())
                } else {
                    None
                };
                // Emit TryBegin with jump target for catch handler
                let try_begin = self.op_array.emit(Op {
                    opcode: OpCode::TryBegin,
                    op1: OperandType::JmpTarget(0), // catch target (patched)
                    op2: OperandType::JmpTarget(0), // finally target (patched)
                    result: OperandType::Unused,
                    line: stmt.span.line,
                });

                // If there's a finally block, push a placeholder target
                // so return statements inside try know to defer
                let has_finally = finally_body.is_some();
                if has_finally {
                    self.finally_targets.push(0); // placeholder, patched below
                    self.try_finally_counter += 1;
                    self.try_finally_ids.push(self.try_finally_counter);
                    self.jumps.finally_stubs.push(Vec::new());
                }

                // Compile try body
                let try_tmp_start = self.op_array.temp_count;
                self.handler_regions.push((try_begin, has_finally));
                for s in try_body {
                    if let Err(e) = self.compile_stmt(s) {
                        self.handler_regions.pop();
                        return Err(e);
                    }
                }
                self.handler_regions.pop();
                let try_tmp_end = self.op_array.temp_count;

                // End of try: clear exception handler and jump to finally/end
                self.op_array.emit(Op {
                    opcode: OpCode::TryEnd,
                    op1: OperandType::Unused,
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line: stmt.span.line,
                });
                let jmp_after_try = self.op_array.emit(Op {
                    opcode: OpCode::Jmp,
                    op1: OperandType::JmpTarget(0), // patched to finally/end
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line: stmt.span.line,
                });

                // Compile catch blocks
                let catch_start = self.op_array.current_offset();
                let mut end_of_catch_jumps = Vec::new();

                // If there's a finally block, push a second exception handler
                // so that re-thrown exceptions from catch-miss go through finally
                let finally_guard = if finally_body.is_some() {
                    Some(self.op_array.emit(Op {
                        opcode: OpCode::TryBegin,
                        op1: OperandType::JmpTarget(0), // no catch - patched to finally
                        op2: OperandType::JmpTarget(0), // finally target - patched below
                        result: OperandType::Unused,
                        line: stmt.span.line,
                    }))
                } else {
                    None
                };
                if let Some(g) = finally_guard {
                    self.handler_regions.push((g, true));
                }

                // Store exception in a temp for type checking
                let exc_tmp = self.op_array.alloc_temp();
                self.op_array.emit(Op {
                    opcode: OpCode::CatchException,
                    op1: OperandType::Tmp(exc_tmp),
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line: stmt.span.line,
                });
                // Temporaries of the abandoned try body are dead now (PHP frees
                // live ranges while unwinding, running destructors before catch).
                if try_tmp_end > try_tmp_start {
                    self.op_array.emit(Op {
                        opcode: OpCode::FreeTmps,
                        op1: OperandType::Tmp(try_tmp_start),
                        op2: OperandType::Tmp(try_tmp_end),
                        result: OperandType::Unused,
                        line: stmt.span.line,
                    });
                }

                for catch in catches.iter() {
                    for type_parts in &catch.types {
                        if type_parts.len() == 1
                            && (type_parts[0].eq_ignore_ascii_case(b"self")
                                || type_parts[0].eq_ignore_ascii_case(b"parent")
                                || type_parts[0].eq_ignore_ascii_case(b"static"))
                        {
                            return Err(CompileError {
                                message: "Bad class name in the catch statement".into(),
                                line: catch.line,
                            });
                        }
                    }
                    // Type check: skip this catch if exception doesn't match
                    let mut next_catch_jumps = Vec::new();

                    if !catch.types.is_empty()
                        && !(catch.types.len() == 1
                            && catch.types[0].len() == 1
                            && catch.types[0][0].eq_ignore_ascii_case(b"Throwable"))
                    {
                        // Check if exception matches any of the catch types
                        let mut match_jumps = Vec::new();
                        for type_parts in &catch.types {
                            // Join qualified name parts
                            let raw_type_name: Vec<u8> = if type_parts.len() == 1 {
                                type_parts[0].clone()
                            } else {
                                type_parts.join(&b'\\')
                            };
                            let type_name = self.resolve_class_name(&raw_type_name);
                            let type_idx = self
                                .op_array
                                .add_literal(Value::String(PhpString::from_vec(type_name)));
                            let check_tmp = self.op_array.alloc_temp();
                            self.op_array.emit(Op {
                                opcode: OpCode::TypeCheck,
                                op1: OperandType::Tmp(exc_tmp),
                                op2: OperandType::Const(type_idx),
                                result: OperandType::Tmp(check_tmp),
                                line: catch.line,
                            });
                            let match_jmp = self.op_array.emit(Op {
                                opcode: OpCode::JmpNz,
                                op1: OperandType::Tmp(check_tmp),
                                op2: OperandType::JmpTarget(0),
                                result: OperandType::Unused,
                                line: catch.line,
                            });
                            match_jumps.push(match_jmp);
                        }

                        // None matched - jump to next catch
                        let skip_jmp = self.op_array.emit(Op {
                            opcode: OpCode::Jmp,
                            op1: OperandType::JmpTarget(0),
                            op2: OperandType::Unused,
                            result: OperandType::Unused,
                            line: catch.line,
                        });
                        next_catch_jumps.push(skip_jmp);

                        // Patch match jumps to here (catch body start)
                        let body_start = self.op_array.current_offset();
                        for jmp in match_jumps {
                            self.op_array.patch_jump(jmp, body_start);
                        }
                    }

                    // Assign exception to variable if specified
                    if let Some(var_name) = &catch.variable {
                        if var_name == b"this" {
                            return Err(CompileError {
                                message: "Cannot re-assign $this".into(),
                                line: catch.line,
                            });
                        }
                        let cv = self.op_array.get_or_create_cv(var_name);
                        self.op_array.emit(Op {
                            opcode: OpCode::Assign,
                            op1: OperandType::Cv(cv),
                            op2: OperandType::Tmp(exc_tmp),
                            result: OperandType::Unused,
                            line: catch.line,
                        });
                    } else {
                        // `catch (E)` without a variable releases the exception.
                        self.op_array.emit(Op {
                            opcode: OpCode::FreeTmps,
                            op1: OperandType::Tmp(exc_tmp),
                            op2: OperandType::Tmp(exc_tmp + 1),
                            result: OperandType::Unused,
                            line: catch.line,
                        });
                    }

                    for s in &catch.body {
                        self.compile_stmt(s)?;
                    }

                    // Catch body completed normally: drop the finally guard
                    // handler before entering the finally block.
                    if finally_guard.is_some() {
                        self.op_array.emit(Op {
                            opcode: OpCode::TryEnd,
                            op1: OperandType::Unused,
                            op2: OperandType::Unused,
                            result: OperandType::Unused,
                            line: stmt.span.line,
                        });
                    }

                    // Jump to finally/end after catch body
                    let jmp = self.op_array.emit(Op {
                        opcode: OpCode::Jmp,
                        op1: OperandType::JmpTarget(0),
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: stmt.span.line,
                    });
                    end_of_catch_jumps.push(jmp);

                    // Patch next-catch jumps
                    let next_catch_start = self.op_array.current_offset();
                    for jmp in next_catch_jumps {
                        self.op_array.patch_jump(jmp, next_catch_start);
                    }
                }

                // If no catch matched, re-throw the exception
                self.op_array.emit(Op {
                    opcode: OpCode::Throw,
                    op1: OperandType::Tmp(exc_tmp),
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line: stmt.span.line,
                });
                // End the finally guard before the rethrow
                if finally_guard.is_some() {
                    self.handler_regions.pop();
                    self.op_array.emit(Op {
                        opcode: OpCode::TryEnd,
                        op1: OperandType::Unused,
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: stmt.span.line,
                    });
                }

                // Patch TryBegin to point to catch start
                self.op_array.ops[try_begin as usize].op1 = OperandType::JmpTarget(catch_start);

                // Compile finally block
                let finally_or_end = if let Some(finally_stmts) = finally_body {
                    let finally_start = self.op_array.current_offset();
                    let slot = OperandType::Tmp(finally_slot.unwrap_or(0));
                    self.op_array.emit(Op {
                        opcode: OpCode::FinallyEnter,
                        op1: slot,
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: stmt.span.line,
                    });

                    // Patch the finally target placeholder for return deferral
                    if let Some(target) = self.finally_targets.last_mut() {
                        *target = finally_start;
                    }
                    // Now go back and patch any SaveReturn+Jmp or SaveJump+Jmp that used the placeholder
                    // Actually, we pushed 0 and return/break/continue statements jumped to 0.
                    // We need to patch those jumps. Let's find them:
                    let ops_len = self.op_array.ops.len();
                    for i in (try_begin as usize)..ops_len {
                        if self.op_array.ops[i].opcode == OpCode::Jmp {
                            if let OperandType::JmpTarget(0) = self.op_array.ops[i].op1 {
                                // Check if preceded by SaveReturn or SaveJump
                                if i > 0
                                    && (self.op_array.ops[i - 1].opcode == OpCode::SaveReturn
                                        || self.op_array.ops[i - 1].opcode == OpCode::SaveJump)
                                {
                                    self.op_array.ops[i].op1 =
                                        OperandType::JmpTarget(finally_start);
                                }
                            }
                        }
                    }

                    // Pop the finally target BEFORE compiling finally body
                    // so that returns inside finally don't loop back to finally
                    self.finally_targets.pop();
                    self.try_finally_ids.pop();

                    self.finally_id_counter += 1;
                    self.finally_path.push(self.finally_id_counter);
                    for s in finally_stmts {
                        if let Err(e) = self.compile_stmt(s) {
                            self.finally_path.pop();
                            return Err(e);
                        }
                    }
                    self.finally_path.pop();

                    // After finally, check for deferred return
                    // Store finally_start in op1 so ReturnDeferred knows which handler(s) to pop
                    self.op_array.emit(Op {
                        opcode: OpCode::ReturnDeferred,
                        op1: OperandType::JmpTarget(finally_start),
                        op2: slot,
                        result: OperandType::Unused,
                        line: stmt.span.line,
                    });

                    // Patch TryBegin's finally target
                    self.op_array.ops[try_begin as usize].op2 =
                        OperandType::JmpTarget(finally_start);

                    // Patch the finally guard to point to finally
                    if let Some(guard_pos) = finally_guard {
                        self.op_array.ops[guard_pos as usize].op1 =
                            OperandType::JmpTarget(finally_start); // catch goes to finally
                        self.op_array.ops[guard_pos as usize].op2 =
                            OperandType::JmpTarget(finally_start); // finally target
                    }

                    self.op_array.current_offset()
                } else {
                    let end = self.op_array.current_offset();
                    self.op_array.ops[try_begin as usize].op2 = OperandType::JmpTarget(end);
                    end
                };

                // Patch all jump-to-end targets
                // When there's a finally block, normal flow must go through it
                if has_finally {
                    // Find the finally_start from TryBegin's op2
                    if let OperandType::JmpTarget(fs) = self.op_array.ops[try_begin as usize].op2 {
                        self.op_array.patch_jump(jmp_after_try, fs);
                        for jmp in end_of_catch_jumps {
                            self.op_array.patch_jump(jmp, fs);
                        }
                    } else {
                        self.op_array.patch_jump(jmp_after_try, finally_or_end);
                        for jmp in end_of_catch_jumps {
                            self.op_array.patch_jump(jmp, finally_or_end);
                        }
                    }
                } else {
                    self.op_array.patch_jump(jmp_after_try, finally_or_end);
                    for jmp in end_of_catch_jumps {
                        self.op_array.patch_jump(jmp, finally_or_end);
                    }
                }
                // Jumps out of loops resumed after the finally block.
                if has_finally {
                    let stubs = self.jumps.finally_stubs.pop().unwrap_or_default();
                    if !stubs.is_empty() {
                        let skip = self.op_array.emit(Op {
                            opcode: OpCode::Jmp,
                            op1: OperandType::JmpTarget(0),
                            op2: OperandType::Unused,
                            result: OperandType::Unused,
                            line: stmt.span.line,
                        });
                        for (save_at, target_index, is_continue, line) in stubs {
                            let here = self.op_array.current_offset();
                            self.op_array.ops[save_at as usize].op1 = OperandType::JmpTarget(here);
                            self.emit_loop_exit(target_index, is_continue, line);
                        }
                        let end = self.op_array.current_offset();
                        self.op_array.patch_jump(skip, end);
                    }
                }
                Ok(())
            }

            StmtKind::ClassDecl {
                name,
                modifiers,
                extends,
                implements,
                body,
                enum_backing_type,
                attributes: class_attributes,
                end_line: class_end_line,
                doc_comment: class_doc_comment,
            } => {
                // Determine qualified name: anonymous classes use NUL-byte PHP names
                let is_anonymous = name.starts_with(b"__anonymous_class_");
                // Disallow non-anonymous class declarations inside *class method* bodies.
                // PHP allows class declarations inside plain functions and closures, but a
                // class declared inside a class method is a fatal "Class declarations may not
                // be nested" error. Anonymous classes are allowed everywhere since they are
                // expressions, not declarations.
                if !is_anonymous && self.is_in_class_method {
                    return Err(CompileError {
                        message: "Class declarations may not be nested".into(),
                        line: stmt.span.line,
                    });
                }
                if !is_anonymous && self.in_main_pass {
                    self.note_symbol_decl(&UseKind::Normal, name, stmt.span.line)?;
                }
                let qualified_name = if is_anonymous {
                    // Look up from pre-built map (built before hoisting pass)
                    self.anon_class_name_map
                        .get(name.as_slice())
                        .cloned()
                        .unwrap_or_else(|| {
                            // Fallback: generate on the fly if map doesn't have it
                            let counter_part = &name[b"__anonymous_class_".len()..];
                            let counter: u32 = std::str::from_utf8(counter_part)
                                .ok()
                                .and_then(|s| s.parse().ok())
                                .unwrap_or(0);
                            let mut anon_name = b"class@anonymous\x00".to_vec();
                            anon_name.extend_from_slice(&self.source_file);
                            anon_name.push(b':');
                            anon_name.extend_from_slice(stmt.span.line.to_string().as_bytes());
                            anon_name.push(b'$');
                            anon_name.extend_from_slice(format!("{:x}", counter).as_bytes());
                            anon_name
                        })
                } else {
                    // Prefix class name with namespace
                    self.prefix_with_namespace(name)
                };
                // Check for reserved class names
                let name_lower: Vec<u8> = name.iter().map(|b| b.to_ascii_lowercase()).collect();
                let (article, kind) = if modifiers.is_interface {
                    ("an", "interface")
                } else if modifiers.is_trait {
                    ("a", "trait")
                } else if modifiers.is_enum {
                    ("an", "enum")
                } else {
                    ("a", "class")
                };
                if !is_anonymous {
                    // Single-underscore name was deprecated in 8.4.
                    if name == b"_" {
                        push_pending_compile_deprecated(
                            format!(
                                "Using \"_\" as {} {} name is deprecated since 8.4",
                                article, kind
                            ),
                            stmt.span.line,
                        );
                    }
                    if is_reserved_class_name(&name_lower) {
                        return Err(CompileError {
                            message: format!(
                                "Cannot use \"{}\" as {} {} name as it is reserved",
                                String::from_utf8_lossy(name),
                                article,
                                kind
                            ),
                            line: stmt.span.line,
                        });
                    }
                }
                // Member declaration checks done by zend_compile_class_decl's members
                // (in declaration order).
                {
                    let cname = String::from_utf8_lossy(&qualified_name).to_string();
                    let mut seen_consts: Vec<Vec<u8>> = Vec::new();
                    for member in body.iter() {
                        // Property defaults and enum case values are constant
                        // expressions without `new`.
                        let init = match member {
                            ClassMember::Property {
                                default: Some(d), ..
                            } => Some(d),
                            ClassMember::EnumCase { value: Some(v), .. } => Some(v),
                            _ => None,
                        };
                        if let Some(e) = init {
                            if let Some(message) = Self::const_expr_error(e, false) {
                                return Err(CompileError {
                                    message,
                                    line: e.span.line,
                                });
                            }
                        }
                        match member {
                            ClassMember::ClassConstant {
                                name: cn,
                                value,
                                visibility,
                                ..
                            } => {
                                let line = value.span.line;
                                if modifiers.is_interface
                                    && !matches!(visibility, Visibility::Public)
                                {
                                    return Err(CompileError {
                                        message: format!(
                                            "Access type for interface constant {}::{} must be public",
                                            cname,
                                            String::from_utf8_lossy(cn)
                                        ),
                                        line,
                                    });
                                }
                                if let Some(message) = Self::const_expr_error(value, false) {
                                    return Err(CompileError { message, line });
                                }
                                if seen_consts.iter().any(|c| c == cn) {
                                    return Err(CompileError {
                                        message: format!(
                                            "Cannot redefine class constant {}::{}",
                                            cname,
                                            String::from_utf8_lossy(cn)
                                        ),
                                        line,
                                    });
                                }
                                seen_consts.push(cn.clone());
                            }
                            ClassMember::Property {
                                get_hook,
                                set_hook,
                                is_abstract,
                                default,
                                get_hook_abstract,
                                set_hook_abstract,
                                ..
                            } if modifiers.is_interface
                                && get_hook.is_none()
                                && set_hook.is_none()
                                && !*is_abstract
                                && !*get_hook_abstract
                                && !*set_hook_abstract =>
                            {
                                return Err(CompileError {
                                    message: "Interfaces may only include hooked properties".into(),
                                    line: default
                                        .as_ref()
                                        .map(|d| d.span.line)
                                        .unwrap_or(stmt.span.line),
                                });
                            }
                            ClassMember::Method {
                                name: mn,
                                body: mbody,
                                visibility,
                                line,
                                ..
                            } if modifiers.is_interface => {
                                if !matches!(visibility, Visibility::Public) {
                                    return Err(CompileError {
                                        message: format!(
                                            "Access type for interface method {}::{}() must be public",
                                            cname,
                                            String::from_utf8_lossy(mn)
                                        ),
                                        line: *line,
                                    });
                                }
                                if mbody.is_some() {
                                    return Err(CompileError {
                                        message: format!(
                                            "Interface function {}::{}() cannot contain body",
                                            cname,
                                            String::from_utf8_lossy(mn)
                                        ),
                                        line: *line,
                                    });
                                }
                            }
                            ClassMember::Method {
                                name: mn,
                                visibility: Visibility::Private,
                                is_final: true,
                                line,
                                ..
                            } if !mn.eq_ignore_ascii_case(b"__construct") => {
                                let msg = "Private methods cannot be final as they are never overridden by other classes".to_string();
                                push_compile_warning(msg.clone(), *line);
                                push_pending_compile_warning(msg, *line);
                            }
                            _ => {}
                        }
                    }
                }
                let mut class = ClassEntry::new(qualified_name.clone());
                class.start_line = stmt.span.line;
                class.end_line = if *class_end_line > 0 {
                    *class_end_line
                } else {
                    stmt.span.line
                };
                if let Some(dc) = class_doc_comment.as_ref() {
                    class.doc_comment = Some(String::from_utf8_lossy(dc).into_owned());
                }
                // Resolve parent class name - also check for reserved names
                if let Some(p) = extends.as_ref() {
                    let p_lower: Vec<u8> = p.iter().map(|b| b.to_ascii_lowercase()).collect();
                    if p_lower == b"self" || p_lower == b"parent" || p_lower == b"static" {
                        let kind_name = if modifiers.is_interface {
                            "interface"
                        } else {
                            "class"
                        };
                        return Err(CompileError {
                            message: format!(
                                "Cannot use \"{}\" as {} name, as it is reserved",
                                String::from_utf8_lossy(p),
                                kind_name
                            ),
                            line: stmt.span.line,
                        });
                    }
                }
                class.parent = extends.as_ref().map(|p| self.resolve_class_name(p));
                // Resolve interface names - also check for reserved names
                for iface in implements.iter() {
                    let iface_lower: Vec<u8> =
                        iface.iter().map(|b| b.to_ascii_lowercase()).collect();
                    if iface_lower == b"self"
                        || iface_lower == b"parent"
                        || iface_lower == b"static"
                    {
                        return Err(CompileError {
                            message: format!(
                                "Cannot use \"{}\" as interface name, as it is reserved",
                                String::from_utf8_lossy(iface)
                            ),
                            line: stmt.span.line,
                        });
                    }
                }
                // Check for duplicate interface implementations
                {
                    let mut seen: Vec<Vec<u8>> = Vec::new();
                    for iface in implements.iter() {
                        let resolved = self.resolve_class_name(iface);
                        let lower: Vec<u8> =
                            resolved.iter().map(|b| b.to_ascii_lowercase()).collect();
                        if seen.contains(&lower) {
                            let kind = if modifiers.is_enum {
                                "Enum"
                            } else if modifiers.is_interface {
                                "Interface"
                            } else {
                                "Class"
                            };
                            let iface_display = String::from_utf8_lossy(iface);
                            return Err(CompileError {
                                message: format!(
                                    "{} {} cannot implement previously implemented interface {}",
                                    kind,
                                    String::from_utf8_lossy(name),
                                    iface_display
                                ),
                                line: stmt.span.line,
                            });
                        }
                        seen.push(lower);
                    }
                }
                class.interfaces = implements
                    .iter()
                    .map(|i| self.resolve_class_name(i))
                    .collect();
                class.is_abstract = modifiers.is_abstract;
                class.is_final = modifiers.is_final;
                class.is_readonly = modifiers.is_readonly;
                class.is_interface = modifiers.is_interface;
                class.is_trait = modifiers.is_trait;
                class.is_enum = modifiers.is_enum;
                class.enum_backing_type = enum_backing_type.clone();
                // Set current_class so self:: is resolved in class attributes and members
                let saved_class = self.current_class.take();
                let saved_in_trait_body =
                    std::mem::replace(&mut self.in_trait_body, modifiers.is_trait);
                let saved_parent = self.current_parent_class.take();
                self.current_class = Some(qualified_name.clone());
                if let Some(ext) = extends {
                    self.current_parent_class = Some(self.resolve_class_name(ext));
                }
                class.attributes = self.compile_attributes_target(class_attributes, "class");

                // Enums automatically implement UnitEnum (and BackedEnum if backed)
                if modifiers.is_enum {
                    class.interfaces.push(b"UnitEnum".to_vec());
                    if enum_backing_type.is_some() {
                        class.interfaces.push(b"BackedEnum".to_vec());
                    }
                }

                // Validate enum backing type
                if let Some(bt) = &enum_backing_type {
                    if !bt.eq_ignore_ascii_case(b"int") && !bt.eq_ignore_ascii_case(b"string") {
                        return Err(CompileError {
                            message: format!(
                                "Enum backing type must be int or string, {} given",
                                String::from_utf8_lossy(bt)
                            ),
                            line: stmt.span.line,
                        });
                    }
                }

                for member in body {
                    self.const_property_name = match member {
                        ClassMember::Property { name, .. } => name.clone(),
                        _ => Vec::new(),
                    };
                    match member {
                        ClassMember::Property {
                            name: prop_name,
                            line: prop_line,
                            type_hint,
                            default,
                            visibility,
                            set_visibility,
                            is_static,
                            is_readonly,
                            is_abstract: prop_is_abstract,
                            is_final: prop_is_final,
                            get_hook,
                            set_hook,
                            get_hook_final,
                            set_hook_final,
                            get_hook_abstract,
                            set_hook_abstract,
                            attributes,
                            doc_comment: prop_doc_comment,
                            set_hook_type,
                            get_hook_by_ref,
                            hook_attrs,
                            ..
                        } => {
                            // Enums cannot include properties
                            if modifiers.is_enum {
                                return Err(CompileError {
                                    message: format!(
                                        "Enum {} cannot include properties",
                                        String::from_utf8_lossy(name)
                                    ),
                                    line: *prop_line,
                                });
                            }
                            // Validate type hint for redundancy and standalone constraints
                            if let Some(hint) = type_hint {
                                if let Some(err) = validate_type_hint_full(
                                    hint,
                                    Some(&qualified_name),
                                    class.parent.as_deref(),
                                )
                                .or_else(|| self.type_redundancy_error(hint, *prop_line))
                                .or_else(|| relative_type_in_intersection(hint, modifiers.is_trait))
                                {
                                    return Err(CompileError {
                                        message: err,
                                        line: *prop_line,
                                    });
                                }
                            }
                            // Properties cannot have type callable
                            if let Some(hint) = type_hint {
                                if type_hint_has_callable(hint) {
                                    return Err(CompileError {
                                        message: format!(
                                            "Property {}::${} cannot have type {}",
                                            String::from_utf8_lossy(name),
                                            String::from_utf8_lossy(prop_name),
                                            type_hint_display(hint)
                                        ),
                                        line: *prop_line,
                                    });
                                }
                                // Properties cannot have type void
                                let check_void = |h: &TypeHint| -> bool {
                                    match h {
                                        TypeHint::Simple(n) => n.eq_ignore_ascii_case(b"void"),
                                        _ => false,
                                    }
                                };
                                if check_void(hint) {
                                    return Err(CompileError {
                                        message: format!(
                                            "Property {}::${} cannot have type void",
                                            String::from_utf8_lossy(name),
                                            String::from_utf8_lossy(prop_name)
                                        ),
                                        line: *prop_line,
                                    });
                                }
                                // Properties cannot have type never
                                let check_never = |h: &TypeHint| -> bool {
                                    match h {
                                        TypeHint::Simple(n) => n.eq_ignore_ascii_case(b"never"),
                                        _ => false,
                                    }
                                };
                                if check_never(hint) {
                                    return Err(CompileError {
                                        message: format!(
                                            "Property {}::${} cannot have type never",
                                            String::from_utf8_lossy(name),
                                            String::from_utf8_lossy(prop_name)
                                        ),
                                        line: *prop_line,
                                    });
                                }
                            }
                            // Readonly property validations
                            let prop_is_readonly = *is_readonly || modifiers.is_readonly;
                            if prop_is_readonly {
                                // Readonly properties must have a type declaration
                                if type_hint.is_none() {
                                    return Err(CompileError {
                                        message: format!(
                                            "Readonly property {}::${} must have type",
                                            String::from_utf8_lossy(name),
                                            String::from_utf8_lossy(prop_name)
                                        ),
                                        line: *prop_line,
                                    });
                                }
                                // Readonly properties cannot be static
                                if *is_static {
                                    return Err(CompileError {
                                        message: format!(
                                            "Static property {}::${} cannot be readonly",
                                            String::from_utf8_lossy(name),
                                            String::from_utf8_lossy(prop_name)
                                        ),
                                        line: *prop_line,
                                    });
                                }
                                // Readonly properties cannot have a default value
                                if default.is_some() {
                                    return Err(CompileError {
                                        message: format!(
                                            "Readonly property {}::${} cannot have default value",
                                            String::from_utf8_lossy(name),
                                            String::from_utf8_lossy(prop_name)
                                        ),
                                        line: *prop_line,
                                    });
                                }
                            }
                            // Hooked properties cannot be readonly
                            if prop_is_readonly && (get_hook.is_some() || set_hook.is_some()) {
                                return Err(CompileError {
                                    message: "Hooked properties cannot be readonly".to_string(),
                                    line: *prop_line,
                                });
                            }
                            // Check: null default on typed non-nullable property
                            if let (Some(hint), Some(expr)) = (type_hint, default) {
                                if matches!(expr.kind, ExprKind::Null) {
                                    // Check if the type includes null
                                    if let TypeHint::Intersection(_) = hint {
                                        let pt = type_hint_to_param_type_with_ns(
                                            hint,
                                            &self.current_namespace,
                                            &self.use_map,
                                        );
                                        let tstr = crate::vm::variance::type_to_string(
                                            &crate::vm::variance::TypeView::from_param_type(&pt),
                                            None,
                                        );
                                        return Err(CompileError {
                                            message: format!(
                                                "Cannot use null as default value for property {}::${} of type {}",
                                                String::from_utf8_lossy(&qualified_name),
                                                String::from_utf8_lossy(prop_name),
                                                tstr
                                            ),
                                            line: *prop_line,
                                        });
                                    }
                                    let type_allows_null = match hint {
                                        TypeHint::Nullable(_) => true,
                                        TypeHint::Simple(n) => {
                                            let l: Vec<u8> = n.iter().map(|b| b.to_ascii_lowercase()).collect();
                                            l == b"null" || l == b"mixed"
                                        }
                                        TypeHint::Union(types) => {
                                            types.iter().any(|t| matches!(t, TypeHint::Simple(n) if {
                                                let l: Vec<u8> = n.iter().map(|b| b.to_ascii_lowercase()).collect();
                                                l == b"null"
                                            }))
                                        }
                                        _ => false,
                                    };
                                    if !type_allows_null {
                                        // Format the type name for the error message
                                        let type_name = match hint {
                                            TypeHint::Simple(n) => {
                                                String::from_utf8_lossy(n).to_string()
                                            }
                                            TypeHint::Union(types) => types
                                                .iter()
                                                .map(|t| match t {
                                                    TypeHint::Simple(n) => {
                                                        String::from_utf8_lossy(n).to_string()
                                                    }
                                                    _ => "?".to_string(),
                                                })
                                                .collect::<Vec<_>>()
                                                .join("|"),
                                            TypeHint::Intersection(types) => types
                                                .iter()
                                                .map(|t| match t {
                                                    TypeHint::Simple(n) => {
                                                        String::from_utf8_lossy(n).to_string()
                                                    }
                                                    _ => "?".to_string(),
                                                })
                                                .collect::<Vec<_>>()
                                                .join("&"),
                                            TypeHint::Nullable(inner) => {
                                                format!(
                                                    "?{}",
                                                    match inner.as_ref() {
                                                        TypeHint::Simple(n) =>
                                                            String::from_utf8_lossy(n).to_string(),
                                                        _ => "?".to_string(),
                                                    }
                                                )
                                            }
                                        };
                                        let nullable_type_name = match hint {
                                            TypeHint::Union(types) => {
                                                let mut parts: Vec<String> = types
                                                    .iter()
                                                    .map(|t| match t {
                                                        TypeHint::Simple(n) => {
                                                            String::from_utf8_lossy(n).to_string()
                                                        }
                                                        _ => "?".to_string(),
                                                    })
                                                    .collect();
                                                parts.push("null".to_string());
                                                parts.join("|")
                                            }
                                            _ => format!("?{}", type_name),
                                        };
                                        return Err(CompileError {
                                            message: format!(
                                                "Default value for property of type {} may not be null. Use the nullable type {} to allow null default value",
                                                type_name, nullable_type_name
                                            ),
                                            line: *prop_line,
                                        });
                                    }
                                }
                            }
                            // zend_is_valid_default_value for literal defaults of typed properties
                            let mut widened_default: Option<Value> = None;
                            if let (Some(hint), Some(expr)) = (type_hint, default) {
                                let pt = type_hint_to_param_type_with_ns(
                                    hint,
                                    &self.current_namespace,
                                    &self.use_map,
                                );
                                match Self::check_literal_default(&pt, expr) {
                                    Err((_, vn)) => {
                                        let tstr = crate::vm::variance::type_to_string(
                                            &crate::vm::variance::TypeView::from_param_type(&pt),
                                            None,
                                        );
                                        return Err(CompileError {
                                            message: format!(
                                                "Cannot use {} as default value for property {}::${} of type {}",
                                                vn,
                                                String::from_utf8_lossy(&qualified_name),
                                                String::from_utf8_lossy(prop_name),
                                                tstr
                                            ),
                                            line: *prop_line,
                                        });
                                    }
                                    Ok(Some(v)) => widened_default = Some(v),
                                    Ok(None) => {}
                                }
                            }
                            if let Some(msg) = default
                                .as_ref()
                                .and_then(|e| Self::const_expr_error(e, false))
                            {
                                return Err(CompileError {
                                    message: msg,
                                    line: default.as_ref().map(|e| e.span.line).unwrap_or(0),
                                });
                            }
                            let default_val = if let Some(expr) = default {
                                // Compile the default value expression (constants only)
                                match &expr.kind {
                                    _ if modifiers.is_trait
                                        && trait_const_expr_uses_scope(expr) =>
                                    {
                                        self.compile_const_thunk(
                                            expr,
                                            &mut class.const_closures,
                                            &qualified_name,
                                            extends.as_deref(),
                                        )?
                                    }
                                    ExprKind::Int(n) => Value::Long(*n),
                                    ExprKind::Float(f) => Value::Double(*f),
                                    ExprKind::String(s) => {
                                        Value::String(PhpString::from_vec(s.clone()))
                                    }
                                    ExprKind::True => Value::True,
                                    ExprKind::False => Value::False,
                                    ExprKind::Null => Value::Null,
                                    ExprKind::Array(elements) => {
                                        let mut arr = crate::array::PhpArray::new();
                                        let mut all_const = true;
                                        for elem in elements {
                                            let val = Self::eval_const_expr(&elem.value)
                                                .or_else(|| {
                                                    Self::eval_class_const_expr(
                                                        &elem.value,
                                                        &class,
                                                        &qualified_name,
                                                        extends.as_deref(),
                                                        self,
                                                    )
                                                })
                                                .or_else(|| {
                                                    // Create deferred marker for ClassConstAccess
                                                    if let ExprKind::ClassConstAccess {
                                                        class: class_expr,
                                                        constant,
                                                    } = &elem.value.kind
                                                    {
                                                        let cname = match &class_expr.kind {
                                                            ExprKind::Identifier(n) => {
                                                                let resolved =
                                                                    self.resolve_class_name(n);
                                                                if resolved
                                                                    .eq_ignore_ascii_case(b"self")
                                                                {
                                                                    qualified_name.clone()
                                                                } else if resolved
                                                                    .eq_ignore_ascii_case(b"parent")
                                                                {
                                                                    extends
                                                                        .as_ref()
                                                                        .map(|p| {
                                                                            self.resolve_class_name(
                                                                                p,
                                                                            )
                                                                        })
                                                                        .unwrap_or(resolved)
                                                                } else {
                                                                    resolved
                                                                }
                                                            }
                                                            _ => qualified_name.clone(),
                                                        };
                                                        if elem.unpack {
                                                            let mut marker =
                                                                b"__deferred_spread__::".to_vec();
                                                            marker.extend_from_slice(&cname);
                                                            marker.extend_from_slice(b"::");
                                                            marker.extend_from_slice(constant);
                                                            Some(Value::String(
                                                                PhpString::from_vec(marker),
                                                            ))
                                                        } else {
                                                            let mut marker =
                                                                b"__deferred_const__::".to_vec();
                                                            marker.extend_from_slice(&cname);
                                                            marker.extend_from_slice(b"::");
                                                            marker.extend_from_slice(constant);
                                                            Some(Value::String(
                                                                PhpString::from_vec(marker),
                                                            ))
                                                        }
                                                    } else {
                                                        None
                                                    }
                                                });
                                            if let Some(v) = val {
                                                if elem.unpack {
                                                    // Spread operator in static property default
                                                    match v {
                                                        Value::Array(src_arr) => {
                                                            for (k, sv) in src_arr.borrow().iter() {
                                                                match k {
                                                                    crate::array::ArrayKey::Int(_) => { arr.push(sv.clone()); }
                                                                    crate::array::ArrayKey::String(_) => { arr.set(k.clone(), sv.clone()); }
                                                                }
                                                            }
                                                        }
                                                        Value::String(ref s)
                                                            if s.as_bytes().starts_with(
                                                                b"__deferred_spread__::",
                                                            ) =>
                                                        {
                                                            // Already a spread marker, store as-is
                                                            arr.push(v);
                                                        }
                                                        _ => {
                                                            // Already has a deferred_const marker - convert to spread
                                                            if let Value::String(ref s) = v {
                                                                if s.as_bytes().starts_with(
                                                                    b"__deferred_const__::",
                                                                ) {
                                                                    let mut spread_marker =
                                                                        b"__deferred_spread__::"
                                                                            .to_vec();
                                                                    spread_marker.extend_from_slice(&s.as_bytes()[b"__deferred_const__::".len()..]);
                                                                    arr.push(Value::String(
                                                                        PhpString::from_vec(
                                                                            spread_marker,
                                                                        ),
                                                                    ));
                                                                } else {
                                                                    all_const = false;
                                                                    break;
                                                                }
                                                            } else {
                                                                all_const = false;
                                                                break;
                                                            }
                                                        }
                                                    }
                                                } else if let Some(key_expr) = &elem.key {
                                                    if let Some(k) = Self::eval_const_expr(key_expr)
                                                    {
                                                        let key = match k {
                                                            Value::Long(n) => {
                                                                crate::array::ArrayKey::Int(n)
                                                            }
                                                            Value::String(s) => {
                                                                crate::array::ArrayKey::String(s)
                                                            }
                                                            _ => {
                                                                all_const = false;
                                                                break;
                                                            }
                                                        };
                                                        arr.set(key, v);
                                                    } else {
                                                        all_const = false;
                                                        break;
                                                    }
                                                } else {
                                                    arr.push(v);
                                                }
                                            } else {
                                                all_const = false;
                                                break;
                                            }
                                        }
                                        let arr = Value::Array(std::rc::Rc::new(
                                            std::cell::RefCell::new(arr),
                                        ));
                                        if all_const && !value_has_marker(&arr) {
                                            arr
                                        } else {
                                            self.compile_const_thunk(
                                                expr,
                                                &mut class.const_closures,
                                                &qualified_name,
                                                extends.as_deref(),
                                            )?
                                        }
                                    }
                                    ExprKind::UnaryOp {
                                        op: UnaryOp::Negate,
                                        operand,
                                        ..
                                    } => match Self::eval_const_expr(operand) {
                                        Some(Value::Long(n)) => Value::Long(-n),
                                        Some(Value::Double(f)) => Value::Double(-f),
                                        _ => self.compile_const_thunk(
                                            expr,
                                            &mut class.const_closures,
                                            &qualified_name,
                                            extends.as_deref(),
                                        )?,
                                    },
                                    ExprKind::ClassConstAccess {
                                        class: cc_class,
                                        constant,
                                    } => {
                                        // Handle self::CONST, ClassName::CONST in property defaults
                                        let class_name = match &cc_class.kind {
                                            ExprKind::Identifier(name) => {
                                                let resolved = self.resolve_class_name(name);
                                                if resolved.eq_ignore_ascii_case(b"self") {
                                                    qualified_name.clone()
                                                } else if resolved.eq_ignore_ascii_case(b"parent") {
                                                    if extends.is_none()
                                                        && !class.is_trait
                                                        && constant.eq_ignore_ascii_case(b"class")
                                                    {
                                                        return Err(CompileError {
                                                            message: "Cannot use \"parent\" when current class scope has no parent".into(),
                                                            line: cc_class.span.line,
                                                        });
                                                    }
                                                    extends
                                                        .as_ref()
                                                        .map(|p| self.resolve_class_name(p))
                                                        .unwrap_or(resolved)
                                                } else {
                                                    resolved
                                                }
                                            }
                                            _ => qualified_name.clone(),
                                        };
                                        if constant.eq_ignore_ascii_case(b"class")
                                            && !class_name.eq_ignore_ascii_case(b"static")
                                        {
                                            // C::class / self::class: compile-time name.
                                            Value::String(PhpString::from_vec(class_name))
                                        } else {
                                            // Resolved on first use (zend_update_class_constants).
                                            self.compile_const_thunk(
                                                expr,
                                                &mut class.const_closures,
                                                &qualified_name,
                                                extends.as_deref(),
                                            )?
                                        }
                                    }
                                    ExprKind::BinaryOp {
                                        op, left, right, ..
                                    } => {
                                        let l = Self::eval_const_expr(left).or_else(|| {
                                            Self::eval_class_const_expr(
                                                left,
                                                &class,
                                                &qualified_name,
                                                extends.as_deref(),
                                                self,
                                            )
                                        });
                                        let r = Self::eval_const_expr(right).or_else(|| {
                                            Self::eval_class_const_expr(
                                                right,
                                                &class,
                                                &qualified_name,
                                                extends.as_deref(),
                                                self,
                                            )
                                        });
                                        // Helper: resolve an operand, producing a deferred marker for ClassConstAccess if needed
                                        let resolve_or_defer_prop = |operand: &Expr, resolved: Option<Value>| -> Option<Value> {
                                            if let Some(v) = resolved {
                                                return Some(v);
                                            }
                                            if let ExprKind::ClassConstAccess { class: class_expr, constant } = &operand.kind {
                                                let class_name = match &class_expr.kind {
                                                    ExprKind::Identifier(ident_name) => {
                                                        let resolved_name = self.resolve_class_name(ident_name);
                                                        if resolved_name.eq_ignore_ascii_case(b"self") {
                                                            qualified_name.clone()
                                                        } else if resolved_name.eq_ignore_ascii_case(b"parent") {
                                                            extends.as_ref().map(|p| self.resolve_class_name(p)).unwrap_or(resolved_name)
                                                        } else {
                                                            resolved_name
                                                        }
                                                    }
                                                    _ => qualified_name.clone(),
                                                };
                                                let mut marker = b"__deferred_const__::".to_vec();
                                                marker.extend_from_slice(&class_name);
                                                marker.push(b':');
                                                marker.push(b':');
                                                marker.extend_from_slice(constant);
                                                return Some(Value::String(PhpString::from_vec(marker)));
                                            }
                                            None
                                        };
                                        let lv = resolve_or_defer_prop(left, l);
                                        let rv = resolve_or_defer_prop(right, r);
                                        if let (Some(lv), Some(rv)) = (lv, rv) {
                                            // Anything not foldable here (deferred operands,
                                            // runtime errors like division by zero) is
                                            // evaluated lazily.
                                            if value_has_marker(&lv)
                                                || value_has_marker(&rv)
                                                || matches!(op, BinaryOp::Div | BinaryOp::Mod)
                                            {
                                                self.compile_const_thunk(
                                                    expr,
                                                    &mut class.const_closures,
                                                    &qualified_name,
                                                    extends.as_deref(),
                                                )?
                                            } else {
                                                match op {
                                                    BinaryOp::Add => lv.add(&rv),
                                                    BinaryOp::Sub => lv.sub(&rv),
                                                    BinaryOp::Mul => lv.mul(&rv),
                                                    BinaryOp::Concat => {
                                                        let mut result =
                                                            lv.to_php_string().as_bytes().to_vec();
                                                        result.extend_from_slice(
                                                            rv.to_php_string().as_bytes(),
                                                        );
                                                        Value::String(PhpString::from_vec(result))
                                                    }
                                                    BinaryOp::BitwiseOr => {
                                                        Value::Long(lv.to_long() | rv.to_long())
                                                    }
                                                    BinaryOp::BitwiseAnd => {
                                                        Value::Long(lv.to_long() & rv.to_long())
                                                    }
                                                    BinaryOp::BitwiseXor => {
                                                        Value::Long(lv.to_long() ^ rv.to_long())
                                                    }
                                                    BinaryOp::ShiftLeft => {
                                                        let n = rv.to_long();
                                                        Value::Long(if (0..64).contains(&n) {
                                                            lv.to_long().wrapping_shl(n as u32)
                                                        } else {
                                                            0
                                                        })
                                                    }
                                                    BinaryOp::ShiftRight => {
                                                        let (a, n) = (lv.to_long(), rv.to_long());
                                                        Value::Long(if (0..64).contains(&n) {
                                                            a >> n
                                                        } else if a < 0 {
                                                            -1
                                                        } else {
                                                            0
                                                        })
                                                    }
                                                    BinaryOp::Div => {
                                                        lv.div(&rv).unwrap_or(Value::Null)
                                                    }
                                                    BinaryOp::Mod => {
                                                        lv.modulo(&rv).unwrap_or(Value::Null)
                                                    }
                                                    BinaryOp::Pow => lv.pow(&rv),
                                                    _ => self.compile_const_thunk(
                                                        expr,
                                                        &mut class.const_closures,
                                                        &qualified_name,
                                                        extends.as_deref(),
                                                    )?,
                                                }
                                            }
                                        } else {
                                            self.compile_const_thunk(
                                                expr,
                                                &mut class.const_closures,
                                                &qualified_name,
                                                extends.as_deref(),
                                            )?
                                        }
                                    }
                                    ExprKind::Identifier(cname) => {
                                        let lower: Vec<u8> =
                                            cname.iter().map(|c| c.to_ascii_lowercase()).collect();
                                        let v = self.resolve_class_const_magic(
                                            &lower,
                                            &qualified_name,
                                            expr.span.line,
                                        );
                                        if matches!(v, Value::Null) && lower != b"null" {
                                            // User constant: resolved when the object is created.
                                            let mut marker =
                                                b"__deferred_global_const__::".to_vec();
                                            let bare = if cname.first() == Some(&b'\\') {
                                                &cname[1..]
                                            } else {
                                                &cname[..]
                                            };
                                            if !self.current_namespace.is_empty()
                                                && cname.first() != Some(&b'\\')
                                            {
                                                marker.extend_from_slice(&self.current_namespace);
                                                marker.push(b'\\');
                                            }
                                            marker.extend_from_slice(bare);
                                            Value::String(PhpString::from_vec(marker))
                                        } else {
                                            v
                                        }
                                    }
                                    ExprKind::Closure {
                                        params: closure_params,
                                        body: closure_body,
                                        is_static: closure_is_static,
                                        attributes: closure_attrs,
                                        ..
                                    } => {
                                        // Closure in property default
                                        let global_id = next_closure_id();
                                        let closure_name =
                                            format!("__closure_{}", global_id).into_bytes();
                                        let is_generator = stmts_contain_yield(closure_body);
                                        // Compute display_name with no method context (property default).
                                        let display_name = {
                                            let mut s = b"{closure:".to_vec();
                                            s.extend_from_slice(&self.source_file);
                                            s.extend_from_slice(
                                                format!(":{}}}", expr.span.line).as_bytes(),
                                            );
                                            s
                                        };
                                        let mut closure_compiler = Compiler::new();
                                        closure_compiler.op_array.name = closure_name.clone();
                                        closure_compiler.op_array.display_name = display_name;
                                        closure_compiler.op_array.filename =
                                            self.source_file.clone();
                                        closure_compiler.op_array.is_generator = is_generator;
                                        closure_compiler.op_array.is_static_closure =
                                            *closure_is_static;
                                        closure_compiler.op_array.decl_line = expr.span.line;
                                        closure_compiler.op_array.strict_types =
                                            self.op_array.strict_types;
                                        closure_compiler.op_array.attributes =
                                            self.compile_attributes(closure_attrs);
                                        closure_compiler.source_file = self.source_file.clone();
                                        closure_compiler.current_class =
                                            Some(qualified_name.clone());
                                        closure_compiler.current_parent_class =
                                            self.current_parent_class.clone();
                                        closure_compiler.op_array.scope_class = Some(
                                            qualified_name
                                                .iter()
                                                .map(|b| b.to_ascii_lowercase())
                                                .collect(),
                                        );
                                        closure_compiler.op_array.param_count =
                                            closure_params.len() as u32;
                                        closure_compiler.op_array.closure_params = closure_params
                                            .iter()
                                            .map(|p| (p.name.clone(), p.by_ref))
                                            .collect();
                                        closure_compiler.op_array.required_param_count = {
                                            let mut last_req: i64 = -1;
                                            for (i, p) in closure_params.iter().enumerate() {
                                                if !p.variadic && p.default.is_none() {
                                                    last_req = i as i64;
                                                }
                                            }
                                            (last_req + 1) as u32
                                        };
                                        closure_compiler.op_array.by_ref_params =
                                            closure_params.iter().map(|p| p.by_ref).collect();
                                        closure_compiler.op_array.param_has_default =
                                            closure_params
                                                .iter()
                                                .map(|p| p.default.is_some())
                                                .collect();
                                        for p in closure_params {
                                            let cv =
                                                closure_compiler.op_array.get_or_create_cv(&p.name);
                                            if p.variadic {
                                                closure_compiler.op_array.variadic_param = Some(cv);
                                            }
                                        }
                                        for s in closure_body {
                                            closure_compiler.compile_stmt(s)?;
                                        }
                                        closure_compiler.check_pending_gotos()?;
                                        let null_idx =
                                            closure_compiler.op_array.add_literal(Value::Null);
                                        closure_compiler.op_array.emit(crate::opcode::Op {
                                            opcode: OpCode::Return,
                                            op1: OperandType::Const(null_idx),
                                            op2: OperandType::Unused,
                                            result: OperandType::Unused,
                                            line: 0,
                                        });
                                        class.const_closures.push(closure_compiler.op_array);
                                        let mut marker = b"__deferred_closure__::".to_vec();
                                        marker.extend_from_slice(&closure_name);
                                        Value::String(PhpString::from_vec(marker))
                                    }
                                    ExprKind::FirstClassCallable(target) => {
                                        // FCC in property default
                                        let global_id = next_closure_id();
                                        let closure_name =
                                            format!("__closure_fcc_{}", global_id).into_bytes();
                                        let mut cc = Compiler::new();
                                        cc.op_array.name = closure_name.clone();
                                        cc.op_array.strict_types = self.op_array.strict_types;
                                        cc.current_class = Some(qualified_name.clone());
                                        cc.current_parent_class = self.current_parent_class.clone();
                                        cc.op_array.scope_class = Some(
                                            qualified_name
                                                .iter()
                                                .map(|b| b.to_ascii_lowercase())
                                                .collect(),
                                        );
                                        cc.source_file = self.source_file.clone();
                                        let args_cv = cc.op_array.get_or_create_cv(b"args");
                                        cc.op_array.param_count = 1;
                                        cc.op_array.required_param_count = 0;
                                        cc.op_array.variadic_param = Some(args_cv);
                                        match target {
                                            CallableTarget::Function(name_expr) => {
                                                if let ExprKind::Identifier(n) = &name_expr.kind {
                                                    let resolved_name =
                                                        self.resolve_function_name(n);
                                                    cc.op_array.fcc_target_name =
                                                        Some(resolved_name.clone());
                                                    cc.op_array.fcc_desc = Some(
                                                        [b"f:".as_slice(), &resolved_name].concat(),
                                                    );
                                                    let name_idx =
                                                        cc.op_array.add_literal(Value::String(
                                                            PhpString::from_vec(resolved_name),
                                                        ));
                                                    let arg_count_idx =
                                                        cc.op_array.add_literal(Value::Long(0));
                                                    cc.op_array.emit(crate::opcode::Op {
                                                        opcode: OpCode::InitFCall,
                                                        op1: OperandType::Const(name_idx),
                                                        op2: OperandType::Const(arg_count_idx),
                                                        result: OperandType::Unused,
                                                        line: expr.span.line,
                                                    });
                                                    cc.op_array.emit(crate::opcode::Op {
                                                        opcode: OpCode::SendUnpack,
                                                        op1: OperandType::Cv(args_cv),
                                                        op2: OperandType::Unused,
                                                        result: OperandType::Unused,
                                                        line: expr.span.line,
                                                    });
                                                    let result_tmp = cc.op_array.alloc_temp();
                                                    cc.op_array.emit(crate::opcode::Op {
                                                        opcode: OpCode::DoFCall,
                                                        op1: OperandType::Unused,
                                                        op2: OperandType::Unused,
                                                        result: OperandType::Tmp(result_tmp),
                                                        line: expr.span.line,
                                                    });
                                                    cc.op_array.emit(crate::opcode::Op {
                                                        opcode: OpCode::Return,
                                                        op1: OperandType::Tmp(result_tmp),
                                                        op2: OperandType::Unused,
                                                        result: OperandType::Unused,
                                                        line: expr.span.line,
                                                    });
                                                }
                                            }
                                            CallableTarget::StaticMethod {
                                                class: class_expr,
                                                method,
                                            } => {
                                                if let ExprKind::Identifier(cn) = &class_expr.kind {
                                                    let class_n = self.resolve_class_name(cn);
                                                    let resolved =
                                                        if class_n.eq_ignore_ascii_case(b"self") {
                                                            qualified_name.clone()
                                                        } else if class_n
                                                            .eq_ignore_ascii_case(b"parent")
                                                        {
                                                            self.current_parent_class
                                                                .clone()
                                                                .unwrap_or(class_n.clone())
                                                        } else {
                                                            class_n
                                                        };
                                                    let mut func_name = resolved;
                                                    func_name.extend_from_slice(b"::");
                                                    func_name.extend_from_slice(method);
                                                    cc.op_array.fcc_target_name =
                                                        Some(func_name.clone());
                                                    cc.op_array.fcc_desc = Some(
                                                        [b"S:".as_slice(), &func_name].concat(),
                                                    );
                                                    let name_idx =
                                                        cc.op_array.add_literal(Value::String(
                                                            PhpString::from_vec(func_name),
                                                        ));
                                                    let arg_count_idx =
                                                        cc.op_array.add_literal(Value::Long(0));
                                                    cc.op_array.emit(crate::opcode::Op {
                                                        opcode: OpCode::InitFCall,
                                                        op1: OperandType::Const(name_idx),
                                                        op2: OperandType::Const(arg_count_idx),
                                                        result: OperandType::Unused,
                                                        line: expr.span.line,
                                                    });
                                                    cc.op_array.emit(crate::opcode::Op {
                                                        opcode: OpCode::SendUnpack,
                                                        op1: OperandType::Cv(args_cv),
                                                        op2: OperandType::Unused,
                                                        result: OperandType::Unused,
                                                        line: expr.span.line,
                                                    });
                                                    let result_tmp = cc.op_array.alloc_temp();
                                                    cc.op_array.emit(crate::opcode::Op {
                                                        opcode: OpCode::DoFCall,
                                                        op1: OperandType::Unused,
                                                        op2: OperandType::Unused,
                                                        result: OperandType::Tmp(result_tmp),
                                                        line: expr.span.line,
                                                    });
                                                    cc.op_array.emit(crate::opcode::Op {
                                                        opcode: OpCode::Return,
                                                        op1: OperandType::Tmp(result_tmp),
                                                        op2: OperandType::Unused,
                                                        result: OperandType::Unused,
                                                        line: expr.span.line,
                                                    });
                                                }
                                            }
                                            _ => {}
                                        }
                                        class.const_closures.push(cc.op_array);
                                        let mut marker = b"__deferred_closure__::".to_vec();
                                        marker.extend_from_slice(&closure_name);
                                        Value::String(PhpString::from_vec(marker))
                                    }
                                    _ => self.compile_const_thunk(
                                        expr,
                                        &mut class.const_closures,
                                        &qualified_name,
                                        extends.as_deref(),
                                    )?,
                                }
                            } else {
                                // No default value: typed properties should be Undef (uninitialized),
                                // untyped properties default to Null
                                if type_hint.is_some() {
                                    Value::Undef
                                } else {
                                    Value::Null
                                }
                            };
                            let default_val = widened_default.unwrap_or(default_val);
                            let vis = match visibility {
                                Visibility::Public => ObjVisibility::Public,
                                Visibility::Protected => ObjVisibility::Protected,
                                Visibility::Private => ObjVisibility::Private,
                            };
                            if *is_static {
                                class
                                    .static_properties
                                    .insert(prop_name.clone(), default_val.clone());
                            }
                            // Asymmetric visibility validation
                            let obj_set_vis = set_visibility.map(|sv| match sv {
                                Visibility::Public => ObjVisibility::Public,
                                Visibility::Protected => ObjVisibility::Protected,
                                Visibility::Private => ObjVisibility::Private,
                            });
                            if obj_set_vis.is_some() {
                                // Asymmetric visibility requires a type
                                if type_hint.is_none() {
                                    return Err(CompileError {
                                        message: format!(
                                            "Property with asymmetric visibility {}::${} must have type",
                                            String::from_utf8_lossy(name),
                                            String::from_utf8_lossy(prop_name)
                                        ),
                                        line: stmt.span.line,
                                    });
                                }
                                // Set visibility must not be wider than read visibility
                                let vis_level = |v: &ObjVisibility| match v {
                                    ObjVisibility::Public => 0,
                                    ObjVisibility::Protected => 1,
                                    ObjVisibility::Private => 2,
                                };
                                if let Some(ref sv) = obj_set_vis {
                                    if vis_level(sv) < vis_level(&vis) {
                                        return Err(CompileError {
                                            message: format!(
                                                "Visibility of property {}::${} must not be weaker than set visibility",
                                                String::from_utf8_lossy(name),
                                                String::from_utf8_lossy(prop_name)
                                            ),
                                            line: stmt.span.line,
                                        });
                                    }
                                }
                            }
                            let declaring_class_lower: Vec<u8> = qualified_name
                                .iter()
                                .map(|b| b.to_ascii_lowercase())
                                .collect();
                            let prop_type = type_hint.as_ref().map(|hint| {
                                type_hint_to_param_type_with_ns(
                                    hint,
                                    &self.current_namespace,
                                    &self.use_map,
                                )
                            });
                            // Check for duplicate property names
                            if class.properties.iter().any(|p| p.name == *prop_name) {
                                return Err(CompileError {
                                    message: format!(
                                        "Cannot redeclare {}::${}",
                                        String::from_utf8_lossy(name),
                                        String::from_utf8_lossy(prop_name)
                                    ),
                                    line: stmt.span.line,
                                });
                            }
                            // Determine if property is virtual (hooks don't access backing store)
                            let hooks_would_be_virtual = if get_hook.is_some() || set_hook.is_some()
                            {
                                let get_uses_backing = get_hook
                                    .as_ref()
                                    .map(|body| stmts_reference_backing_store(body, prop_name))
                                    .unwrap_or(false);
                                let set_uses_backing = set_hook
                                    .as_ref()
                                    .map(|(_, body)| stmts_reference_backing_store(body, prop_name))
                                    .unwrap_or(false);
                                !get_uses_backing && !set_uses_backing
                            } else {
                                false
                            };
                            // Virtual properties cannot have a default value — but only
                            // when the property doesn't inherit a backing slot from a parent.
                            // We can't determine that at compile time, so defer this check
                            // to link time (in vm.rs after inheritance is resolved).
                            let prop_is_virtual = hooks_would_be_virtual;
                            // Abstract+final is not allowed
                            if *prop_is_abstract && *prop_is_final {
                                return Err(CompileError {
                                    message:
                                        "Cannot use the final modifier on an abstract property"
                                            .to_string(),
                                    line: stmt.span.line,
                                });
                            }
                            // Final+private is not allowed
                            if *prop_is_final
                                && matches!(visibility, goro_parser::ast::Visibility::Private)
                            {
                                return Err(CompileError {
                                    message: "Property cannot be both final and private"
                                        .to_string(),
                                    line: stmt.span.line,
                                });
                            }
                            // Hook-level checks: final+private, final+abstract, abstract+private
                            // `final+private` must be checked before `final+abstract` because the test
                            // `private $prop { final get; }` is both, but the expected error is
                            // "cannot be both final and private".
                            if (*get_hook_final || *set_hook_final)
                                && matches!(visibility, goro_parser::ast::Visibility::Private)
                            {
                                return Err(CompileError {
                                    message: "Property hook cannot be both final and private"
                                        .to_string(),
                                    line: stmt.span.line,
                                });
                            }
                            if (*get_hook_final && *get_hook_abstract)
                                || (*set_hook_final && *set_hook_abstract)
                            {
                                return Err(CompileError {
                                    message: "Property hook cannot be both abstract and final"
                                        .to_string(),
                                    line: stmt.span.line,
                                });
                            }
                            if *prop_is_abstract
                                && matches!(visibility, goro_parser::ast::Visibility::Private)
                            {
                                return Err(CompileError {
                                    message: "Property hook cannot be both abstract and private"
                                        .to_string(),
                                    line: stmt.span.line,
                                });
                            }
                            // Abstract property in non-abstract, non-interface, non-trait class
                            // Only the hooks declared with `;` (no body) are actually abstract;
                            // `get { }` / `set { }` with an empty body are concrete.
                            if *prop_is_abstract
                                && !modifiers.is_abstract
                                && !modifiers.is_interface
                                && !modifiers.is_trait
                            {
                                let has_g = *get_hook_abstract;
                                let has_s = *set_hook_abstract;
                                let count = (has_g as usize) + (has_s as usize);
                                if count > 0 {
                                    let (plural, is_plural) = if count == 1 {
                                        ("method", false)
                                    } else {
                                        ("methods", true)
                                    };
                                    let mut parts: Vec<String> = Vec::new();
                                    if has_g {
                                        parts.push(format!(
                                            "{}::${}::get",
                                            String::from_utf8_lossy(name),
                                            String::from_utf8_lossy(prop_name)
                                        ));
                                    }
                                    if has_s {
                                        parts.push(format!(
                                            "{}::${}::set",
                                            String::from_utf8_lossy(name),
                                            String::from_utf8_lossy(prop_name)
                                        ));
                                    }
                                    let remaining_word = if is_plural {
                                        "remaining methods"
                                    } else {
                                        "remaining method"
                                    };
                                    return Err(CompileError {
                                        message: format!(
                                            "Class {} contains {} abstract {} and must therefore be declared abstract or implement the {} ({})",
                                            String::from_utf8_lossy(name),
                                            count,
                                            plural,
                                            remaining_word,
                                            parts.join(", "),
                                        ),
                                        line: stmt.span.line,
                                    });
                                }
                            }
                            class.properties.push(PropertyDef {
                                name: prop_name.clone(),
                                default: default_val,
                                is_static: *is_static,
                                visibility: vis,
                                set_visibility: obj_set_vis,
                                declaring_class: declaring_class_lower.clone(),
                                is_readonly: prop_is_readonly,
                                property_type: prop_type.clone(),
                                has_get_hook: get_hook.is_some(),
                                has_set_hook: set_hook.is_some(),
                                is_virtual: prop_is_virtual,
                                is_abstract: *prop_is_abstract,
                                is_final: *prop_is_final,
                                attributes: self.compile_attributes_target(attributes, "property"),
                                doc_comment: prop_doc_comment
                                    .as_ref()
                                    .map(|d| String::from_utf8_lossy(d).into_owned()),
                            });

                            // Compile property get hook as a method: __property_get_$propname
                            if let Some(hook_body) = get_hook {
                                let hook_method_name = format!(
                                    "__property_get_{}",
                                    String::from_utf8_lossy(prop_name)
                                );
                                // Display name for __METHOD__: $prop::get
                                let hook_display_name =
                                    format!("${}::get", String::from_utf8_lossy(prop_name));
                                let mut hook_compiler = Compiler::new();
                                hook_compiler.current_namespace = self.current_namespace.clone();
                                hook_compiler.use_map = self.use_map.clone();
                                hook_compiler.use_function_map = self.use_function_map.clone();
                                hook_compiler.use_const_map = self.use_const_map.clone();
                                hook_compiler.op_array.name = hook_display_name.into_bytes();
                                hook_compiler.op_array.decl_line = stmt.span.line;
                                hook_compiler.op_array.strict_types = self.op_array.strict_types;
                                // The get hook's return type is the property type.
                                hook_compiler.op_array.return_type = prop_type.clone();
                                hook_compiler.op_array.returns_by_ref = *get_hook_by_ref;
                                hook_compiler.op_array.is_generator =
                                    stmts_contain_yield(hook_body);
                                hook_compiler.source_file = self.source_file.clone();
                                hook_compiler.current_class = Some(qualified_name.clone());
                                hook_compiler.current_parent_class = class.parent.clone();
                                hook_compiler.op_array.scope_class = Some(
                                    qualified_name
                                        .iter()
                                        .map(|b| b.to_ascii_lowercase())
                                        .collect(),
                                );
                                hook_compiler.anon_class_name_map =
                                    self.anon_class_name_map.clone();

                                // $this is CV 0
                                hook_compiler.op_array.get_or_create_cv(b"this");
                                hook_compiler.op_array.param_count = 1; // just $this
                                hook_compiler.op_array.required_param_count = 0;

                                for s in hook_body {
                                    hook_compiler.compile_stmt(s)?;
                                }
                                hook_compiler.check_pending_gotos()?;

                                // Implicit return null
                                let null_idx = hook_compiler.op_array.add_literal(Value::Null);
                                hook_compiler.op_array.emit(Op {
                                    opcode: OpCode::Return,
                                    op1: OperandType::Const(null_idx),
                                    op2: OperandType::Unused,
                                    result: OperandType::Unused,
                                    line: 0,
                                });

                                let lower_hook_name: Vec<u8> = hook_method_name
                                    .bytes()
                                    .map(|b| b.to_ascii_lowercase())
                                    .collect();
                                let get_attrs =
                                    self.compile_hook_attributes(&hook_attrs.get);
                                class.methods.insert(
                                    lower_hook_name,
                                    MethodDef {
                                        name: hook_method_name.into_bytes(),
                                        op_array: std::rc::Rc::new(hook_compiler.op_array),
                                        param_count: 0,
                                        is_static: false,
                                        is_abstract: *get_hook_abstract,
                                        is_final: *get_hook_final,
                                        visibility: ObjVisibility::Public,
                                        declaring_class: declaring_class_lower.clone(),
                                        doc_comment: None,
                                        attributes: get_attrs,
                                    },
                                );
                            }
                            // Compile property set hook as a method: __property_set_$propname
                            if let Some((param_name, hook_body)) = set_hook {
                                let hook_method_name = format!(
                                    "__property_set_{}",
                                    String::from_utf8_lossy(prop_name)
                                );
                                // Display name for __METHOD__: $prop::set
                                let hook_display_name =
                                    format!("${}::set", String::from_utf8_lossy(prop_name));
                                let mut hook_compiler = Compiler::new();
                                hook_compiler.current_namespace = self.current_namespace.clone();
                                hook_compiler.use_map = self.use_map.clone();
                                hook_compiler.use_function_map = self.use_function_map.clone();
                                hook_compiler.use_const_map = self.use_const_map.clone();
                                hook_compiler.op_array.name = hook_display_name.into_bytes();
                                hook_compiler.op_array.decl_line = stmt.span.line;
                                hook_compiler.op_array.strict_types = self.op_array.strict_types;
                                hook_compiler.source_file = self.source_file.clone();
                                hook_compiler.current_class = Some(qualified_name.clone());
                                hook_compiler.current_parent_class = class.parent.clone();
                                hook_compiler.op_array.scope_class = Some(
                                    qualified_name
                                        .iter()
                                        .map(|b| b.to_ascii_lowercase())
                                        .collect(),
                                );
                                hook_compiler.anon_class_name_map =
                                    self.anon_class_name_map.clone();

                                // $this is CV 0
                                hook_compiler.op_array.get_or_create_cv(b"this");
                                // $value (or custom param name) is CV 1
                                hook_compiler.op_array.get_or_create_cv(param_name);
                                // Explicit `set(Type $value)` parameter type (used by
                                // inheritance/variance checks).
                                if let Some(th) = set_hook_type {
                                    let pt = type_hint_to_param_type_with_ns(
                                        th,
                                        &self.current_namespace,
                                        &self.use_map,
                                    );
                                    hook_compiler.op_array.param_types = vec![
                                        None,
                                        Some(ParamTypeInfo {
                                            param_name: param_name.clone(),
                                            param_type: pt,
                                            implicitly_nullable: false,
                                        }),
                                    ];
                                } else if let Some(pt) = prop_type.clone() {
                                    // An implicit `$value` parameter has the
                                    // property's type.
                                    hook_compiler.op_array.param_types = vec![
                                        None,
                                        Some(ParamTypeInfo {
                                            param_name: param_name.clone(),
                                            param_type: pt,
                                            implicitly_nullable: false,
                                        }),
                                    ];
                                }
                                // (a set hook returns void)
                                hook_compiler.op_array.return_type =
                                    Some(ParamType::Simple(b"void".to_vec()));
                                hook_compiler.op_array.param_count = 2; // $this + $value
                                hook_compiler.op_array.param_attributes =
                                    vec![self.compile_attributes_target(
                                        &hook_attrs.set_param,
                                        "parameter",
                                    )];
                                let set_attrs =
                                    self.compile_hook_attributes(&hook_attrs.set);
                                hook_compiler.op_array.required_param_count = 1; // $value is required

                                for s in hook_body {
                                    hook_compiler.compile_stmt(s)?;
                                }
                                hook_compiler.check_pending_gotos()?;

                                // Implicit return null
                                let null_idx = hook_compiler.op_array.add_literal(Value::Null);
                                hook_compiler.op_array.emit(Op {
                                    opcode: OpCode::Return,
                                    op1: OperandType::Const(null_idx),
                                    op2: OperandType::Unused,
                                    result: OperandType::Unused,
                                    line: 0,
                                });

                                let lower_hook_name: Vec<u8> = hook_method_name
                                    .bytes()
                                    .map(|b| b.to_ascii_lowercase())
                                    .collect();
                                class.methods.insert(
                                    lower_hook_name,
                                    MethodDef {
                                        name: hook_method_name.into_bytes(),
                                        op_array: std::rc::Rc::new(hook_compiler.op_array),
                                        param_count: 1, // $value
                                        is_static: false,
                                        is_abstract: *set_hook_abstract,
                                        is_final: *set_hook_final,
                                        visibility: ObjVisibility::Public,
                                        declaring_class: declaring_class_lower,
                                        doc_comment: None,
                                        attributes: set_attrs,
                                    },
                                );
                            }
                        }
                        ClassMember::Method {
                            name: method_name,
                            params,
                            return_type: method_return_type,
                            body: method_body,
                            visibility,
                            is_static,
                            is_abstract,
                            is_final: method_is_final,
                            line: method_line,
                            end_line: method_end_line,
                            attributes: method_attributes,
                            doc_comment: method_doc_comment,
                            returns_by_ref: method_returns_by_ref,
                        } => {
                            check_duplicate_params(params, *method_line)?;
                            // Check: a method cannot be both abstract and final
                            if *is_abstract && *method_is_final {
                                return Err(CompileError {
                                    message: "Cannot use the final modifier on an abstract method"
                                        .to_string(),
                                    line: *method_line,
                                });
                            }
                            // NoDiscard validation on special methods.
                            {
                                let has_nodiscard = method_attributes.iter().any(|a| {
                                    let last = a.name.last().map(|s| s.as_slice()).unwrap_or(&[]);
                                    let bare: &[u8] = if last.first() == Some(&b'\\') {
                                        &last[1..]
                                    } else {
                                        last
                                    };
                                    bare.eq_ignore_ascii_case(b"NoDiscard")
                                });
                                if has_nodiscard {
                                    let mn_lower_v: Vec<u8> = method_name
                                        .iter()
                                        .map(|b| b.to_ascii_lowercase())
                                        .collect();
                                    let class_display = String::from_utf8_lossy(name).to_string();
                                    let method_display =
                                        String::from_utf8_lossy(method_name).to_string();
                                    if mn_lower_v == b"__construct" {
                                        return Err(CompileError {
                                            message: format!(
                                                "Method {}::{} cannot be #[\\NoDiscard]",
                                                class_display, method_display
                                            ),
                                            line: *method_line,
                                        });
                                    }
                                    if mn_lower_v == b"__clone" {
                                        return Err(CompileError {
                                            message: format!(
                                                "Method {}::{} cannot be #[\\NoDiscard]",
                                                class_display, method_display
                                            ),
                                            line: *method_line,
                                        });
                                    }
                                    // void/never return type validation
                                    if let Some(hint) = method_return_type {
                                        if let goro_parser::ast::TypeHint::Simple(s) = hint {
                                            if s.eq_ignore_ascii_case(b"never") {
                                                return Err(CompileError {
                                                    message: "A never returning function does not return a value, but #[\\NoDiscard] requires a return value".to_string(),
                                                    line: *method_line,
                                                });
                                            }
                                            if s.eq_ignore_ascii_case(b"void") {
                                                return Err(CompileError {
                                                    message: "A void function does not return a value, but #[\\NoDiscard] requires a return value".to_string(),
                                                    line: *method_line,
                                                });
                                            }
                                        }
                                    }
                                }
                            }
                            // Check: interface methods must not be final
                            if modifiers.is_interface && *method_is_final {
                                return Err(CompileError {
                                    message: format!(
                                        "Interface method {}::{}() must not be final",
                                        String::from_utf8_lossy(name),
                                        String::from_utf8_lossy(method_name)
                                    ),
                                    line: *method_line,
                                });
                            }
                            // Check: interface methods must not be abstract (they are implicitly abstract)
                            if modifiers.is_interface && *is_abstract {
                                return Err(CompileError {
                                    message: format!(
                                        "Interface method {}::{}() must not be abstract",
                                        String::from_utf8_lossy(name),
                                        String::from_utf8_lossy(method_name)
                                    ),
                                    line: *method_line,
                                });
                            }
                            // Check: abstract method cannot be private (except in traits, since PHP 8.0)
                            if *is_abstract
                                && matches!(visibility, goro_parser::ast::Visibility::Private)
                                && !modifiers.is_trait
                            {
                                return Err(CompileError {
                                    message: format!(
                                        "Abstract function {}::{}() cannot be declared private",
                                        String::from_utf8_lossy(name),
                                        String::from_utf8_lossy(method_name)
                                    ),
                                    line: *method_line,
                                });
                            }
                            // Enums cannot have abstract methods
                            if modifiers.is_enum && *is_abstract {
                                return Err(CompileError {
                                    message: format!(
                                        "Enum method {}::{}() must not be abstract",
                                        String::from_utf8_lossy(name),
                                        String::from_utf8_lossy(method_name)
                                    ),
                                    line: *method_line,
                                });
                            }
                            // Enums cannot include certain magic methods
                            if modifiers.is_enum {
                                let mn_lower: Vec<u8> =
                                    method_name.iter().map(|b| b.to_ascii_lowercase()).collect();
                                let forbidden_magic = matches!(
                                    mn_lower.as_slice(),
                                    b"__get"
                                        | b"__set"
                                        | b"__destruct"
                                        | b"__clone"
                                        | b"__sleep"
                                        | b"__wakeup"
                                        | b"__set_state"
                                        | b"__unserialize"
                                        | b"__serialize"
                                        | b"__isset"
                                        | b"__unset"
                                        | b"__debuginfo"
                                        | b"__construct"
                                        | b"__tostring"
                                );
                                if forbidden_magic {
                                    return Err(CompileError {
                                        message: format!(
                                            "Enum {} cannot include magic method {}",
                                            String::from_utf8_lossy(name),
                                            String::from_utf8_lossy(method_name)
                                        ),
                                        line: *method_line,
                                    });
                                }
                                // Backed enums cannot redeclare from/tryFrom, any enum cannot redeclare cases
                                let is_reserved_enum_method = if enum_backing_type.is_some() {
                                    matches!(mn_lower.as_slice(), b"from" | b"tryfrom" | b"cases")
                                } else {
                                    matches!(mn_lower.as_slice(), b"cases")
                                };
                                if is_reserved_enum_method {
                                    return Err(CompileError {
                                        message: format!(
                                            "Cannot redeclare {}::{}()",
                                            String::from_utf8_lossy(name),
                                            String::from_utf8_lossy(method_name)
                                        ),
                                        line: *method_line,
                                    });
                                }
                            }
                            // Enforce: __construct and __destruct cannot declare return types
                            {
                                let mn_lower: Vec<u8> =
                                    method_name.iter().map(|b| b.to_ascii_lowercase()).collect();
                                if method_return_type.is_some() {
                                    if mn_lower == b"__construct" || mn_lower == b"__destruct" {
                                        return Err(CompileError {
                                            message: format!(
                                                "Method {}::{}() cannot declare a return type",
                                                String::from_utf8_lossy(name),
                                                String::from_utf8_lossy(method_name)
                                            ),
                                            line: *method_line,
                                        });
                                    }
                                    // Magic method return type restrictions
                                    if let Some(rt) = method_return_type {
                                        let class_display = String::from_utf8_lossy(name);
                                        // Helper: check if a type hint matches a simple type name
                                        let is_simple_type =
                                            |hint: &TypeHint, expected: &[u8]| -> bool {
                                                match hint {
                                                    TypeHint::Simple(n) => {
                                                        n.eq_ignore_ascii_case(expected)
                                                    }
                                                    _ => false,
                                                }
                                            };
                                        // Helper: check if type is ?array (nullable array)
                                        let is_nullable_array = |hint: &TypeHint| -> bool {
                                            match hint {
                                                TypeHint::Simple(n) => {
                                                    n.eq_ignore_ascii_case(b"array")
                                                }
                                                TypeHint::Nullable(inner) => {
                                                    matches!(inner.as_ref(), TypeHint::Simple(n) if n.eq_ignore_ascii_case(b"array"))
                                                }
                                                TypeHint::Union(types) => {
                                                    // array|null or null|array
                                                    types.len() == 2
                                                        && types
                                                            .iter()
                                                            .any(|t| is_simple_type(t, b"array"))
                                                        && types
                                                            .iter()
                                                            .any(|t| is_simple_type(t, b"null"))
                                                }
                                                _ => false,
                                            }
                                        };
                                        // zend_check_magic_method_return_type: the declared type must be
                                        // a subset of the expected one (never is always allowed).
                                        let _ = (&is_simple_type, &is_nullable_array);
                                        {
                                            use crate::vm::variance::{
                                                T_ARRAY, T_BOOL, T_NEVER, T_NULL, T_OBJECT,
                                                T_STATIC, T_STRING, T_VOID, TypeView,
                                            };
                                            let expected: Option<u32> = match mn_lower.as_slice() {
                                                b"__clone" | b"__set" | b"__unset"
                                                | b"__unserialize" | b"__wakeup" => Some(T_VOID),
                                                b"__isset" => Some(T_BOOL),
                                                b"__tostring" => Some(T_STRING),
                                                b"__debuginfo" => Some(T_ARRAY | T_NULL),
                                                b"__serialize" | b"__sleep" => Some(T_ARRAY),
                                                b"__set_state" => Some(T_OBJECT),
                                                _ => None,
                                            };
                                            if let Some(exp) = expected {
                                                let pt = type_hint_to_param_type_with_ns(
                                                    rt,
                                                    &self.current_namespace,
                                                    &self.use_map,
                                                );
                                                let tv = TypeView::from_param_type(&pt);
                                                if tv.mask & T_NEVER == 0 {
                                                    let mut is_complex = !tv.elems.is_empty();
                                                    let mut extra = tv.mask & !exp;
                                                    if extra & T_STATIC != 0 {
                                                        extra &= !T_STATIC;
                                                        is_complex = true;
                                                    }
                                                    if extra != 0 || (is_complex && exp != T_OBJECT)
                                                    {
                                                        let exp_tv = TypeView {
                                                            mask: exp,
                                                            elems: Vec::new(),
                                                            is_intersection: false,
                                                        };
                                                        return Err(CompileError {
                                                            message: format!(
                                                                "{}::{}(): Return type must be {} when declared",
                                                                class_display,
                                                                String::from_utf8_lossy(
                                                                    method_name
                                                                ),
                                                                crate::vm::variance::type_to_string(
                                                                    &exp_tv, None
                                                                )
                                                            ),
                                                            line: *method_line,
                                                        });
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                            // Validate magic method argument counts, static modifiers, visibility, by-ref params, and param types
                            {
                                let mn_lower: Vec<u8> =
                                    method_name.iter().map(|b| b.to_ascii_lowercase()).collect();
                                let class_display = String::from_utf8_lossy(name).to_string();
                                let method_display =
                                    String::from_utf8_lossy(method_name).to_string();

                                // 1) Argument count / signature checks first (PHP checks these before static)
                                if matches!(
                                    mn_lower.as_slice(),
                                    b"__clone"
                                        | b"__destruct"
                                        | b"__tostring"
                                        | b"__serialize"
                                        | b"__sleep"
                                        | b"__wakeup"
                                ) && !params.is_empty()
                                {
                                    return Err(CompileError {
                                        message: format!(
                                            "Method {}::{}() cannot take arguments",
                                            class_display, method_display
                                        ),
                                        line: *method_line,
                                    });
                                }
                                if mn_lower == b"__isset" && params.len() != 1 {
                                    return Err(CompileError {
                                        message: format!(
                                            "Method {}::__isset() must take exactly 1 argument",
                                            class_display
                                        ),
                                        line: *method_line,
                                    });
                                }
                                if mn_lower == b"__unset" && params.len() != 1 {
                                    return Err(CompileError {
                                        message: format!(
                                            "Method {}::__unset() must take exactly 1 argument",
                                            class_display
                                        ),
                                        line: *method_line,
                                    });
                                }
                                if mn_lower == b"__get" && params.len() != 1 {
                                    return Err(CompileError {
                                        message: format!(
                                            "Method {}::__get() must take exactly 1 argument",
                                            class_display
                                        ),
                                        line: *method_line,
                                    });
                                }
                                if mn_lower == b"__set" && params.len() != 2 {
                                    return Err(CompileError {
                                        message: format!(
                                            "Method {}::__set() must take exactly 2 arguments",
                                            class_display
                                        ),
                                        line: *method_line,
                                    });
                                }
                                if mn_lower == b"__call" && params.len() != 2 {
                                    return Err(CompileError {
                                        message: format!(
                                            "Method {}::__call() must take exactly 2 arguments",
                                            class_display
                                        ),
                                        line: *method_line,
                                    });
                                }
                                if mn_lower == b"__callstatic" && params.len() != 2 {
                                    return Err(CompileError {
                                        message: format!(
                                            "Method {}::__callStatic() must take exactly 2 arguments",
                                            class_display
                                        ),
                                        line: *method_line,
                                    });
                                }
                                if mn_lower == b"__unserialize" && params.len() != 1 {
                                    return Err(CompileError {
                                        message: format!(
                                            "Method {}::__unserialize() must take exactly 1 argument",
                                            class_display
                                        ),
                                        line: *method_line,
                                    });
                                }
                                if mn_lower == b"__set_state" && params.len() != 1 {
                                    return Err(CompileError {
                                        message: format!(
                                            "Method {}::__set_state() must take exactly 1 argument",
                                            class_display
                                        ),
                                        line: *method_line,
                                    });
                                }

                                // 2) By-reference parameter checks
                                if matches!(
                                    mn_lower.as_slice(),
                                    b"__get"
                                        | b"__set"
                                        | b"__isset"
                                        | b"__unset"
                                        | b"__call"
                                        | b"__callstatic"
                                ) {
                                    if params.iter().any(|p| p.by_ref) {
                                        return Err(CompileError {
                                            message: format!(
                                                "Method {}::{}() cannot take arguments by reference",
                                                class_display, method_display
                                            ),
                                            line: *method_line,
                                        });
                                    }
                                }

                                // 3) Parameter type validation
                                if matches!(
                                    mn_lower.as_slice(),
                                    b"__get"
                                        | b"__set"
                                        | b"__isset"
                                        | b"__unset"
                                        | b"__call"
                                        | b"__callstatic"
                                ) {
                                    if let Some(param) = params.first() {
                                        if let Some(ref th) = param.type_hint {
                                            if !type_hint_admits(th, b"string") {
                                                return Err(CompileError {
                                                    message: format!(
                                                        "{}::{}(): Parameter #1 (${}) must be of type string when declared",
                                                        class_display,
                                                        method_display,
                                                        String::from_utf8_lossy(&param.name)
                                                    ),
                                                    line: *method_line,
                                                });
                                            }
                                        }
                                    }
                                }
                                if matches!(mn_lower.as_slice(), b"__call" | b"__callstatic") {
                                    if let Some(param) = params.get(1) {
                                        if let Some(ref th) = param.type_hint {
                                            if !type_hint_admits(th, b"array") {
                                                return Err(CompileError {
                                                    message: format!(
                                                        "{}::{}(): Parameter #2 (${}) must be of type array when declared",
                                                        class_display,
                                                        method_display,
                                                        String::from_utf8_lossy(&param.name)
                                                    ),
                                                    line: *method_line,
                                                });
                                            }
                                        }
                                    }
                                }
                                if mn_lower == b"__unserialize" {
                                    if let Some(param) = params.first() {
                                        if let Some(ref th) = param.type_hint {
                                            if !type_hint_admits(th, b"array") {
                                                return Err(CompileError {
                                                    message: format!(
                                                        "{}::__unserialize(): Parameter #1 (${}) must be of type array when declared",
                                                        class_display,
                                                        String::from_utf8_lossy(&param.name)
                                                    ),
                                                    line: *method_line,
                                                });
                                            }
                                        }
                                    }
                                }
                                if mn_lower == b"__set_state" {
                                    if let Some(param) = params.first() {
                                        if let Some(ref th) = param.type_hint {
                                            if !type_hint_admits(th, b"array") {
                                                return Err(CompileError {
                                                    message: format!(
                                                        "{}::__set_state(): Parameter #1 (${}) must be of type array when declared",
                                                        class_display,
                                                        String::from_utf8_lossy(&param.name)
                                                    ),
                                                    line: *method_line,
                                                });
                                            }
                                        }
                                    }
                                }

                                // 4) Cannot be static checks (after argument checks)
                                if matches!(
                                    mn_lower.as_slice(),
                                    b"__construct"
                                        | b"__destruct"
                                        | b"__clone"
                                        | b"__get"
                                        | b"__set"
                                        | b"__isset"
                                        | b"__unset"
                                        | b"__call"
                                        | b"__tostring"
                                        | b"__debuginfo"
                                        | b"__invoke"
                                ) {
                                    if *is_static {
                                        return Err(CompileError {
                                            message: format!(
                                                "Method {}::{}() cannot be static",
                                                class_display, method_display
                                            ),
                                            line: *method_line,
                                        });
                                    }
                                }
                                if mn_lower == b"__callstatic" && !*is_static {
                                    return Err(CompileError {
                                        message: format!(
                                            "Method {}::__callstatic() must be static",
                                            class_display
                                        ),
                                        line: *method_line,
                                    });
                                }
                                if mn_lower == b"__set_state" && !*is_static {
                                    return Err(CompileError {
                                        message: format!(
                                            "Method {}::__set_state() must be static",
                                            class_display
                                        ),
                                        line: *method_line,
                                    });
                                }

                                // 5) Visibility warnings (must be public)
                                if matches!(
                                    mn_lower.as_slice(),
                                    b"__get"
                                        | b"__set"
                                        | b"__isset"
                                        | b"__unset"
                                        | b"__call"
                                        | b"__callstatic"
                                        | b"__tostring"
                                        | b"__debuginfo"
                                        | b"__serialize"
                                        | b"__unserialize"
                                        | b"__sleep"
                                        | b"__wakeup"
                                        | b"__set_state"
                                        | b"__invoke"
                                ) {
                                    if *visibility != Visibility::Public {
                                        push_compile_warning_tuple((
                                            format!(
                                                "The magic method {}::{}() must have public visibility",
                                                class_display, method_display
                                            ),
                                            *method_line,
                                        ));
                                    }
                                }
                            }
                            // Add promoted properties from constructor params
                            {
                                let mn_lower: Vec<u8> =
                                    method_name.iter().map(|b| b.to_ascii_lowercase()).collect();
                                // Check for promoted properties in non-constructors
                                if mn_lower != b"__construct" {
                                    for param in params {
                                        if is_promoted_param(param) {
                                            return Err(CompileError {
                                                message: "Cannot declare promoted property outside a constructor".to_string(),
                                                line: stmt.span.line,
                                            });
                                        }
                                    }
                                }
                                // Check for promoted properties in abstract constructors
                                if mn_lower == b"__construct"
                                    && (*is_abstract || modifiers.is_interface)
                                {
                                    for param in params {
                                        if is_promoted_param(param) {
                                            return Err(CompileError {
                                                message: "Cannot declare promoted property in an abstract constructor".to_string(),
                                                line: stmt.span.line,
                                            });
                                        }
                                    }
                                }
                                if mn_lower == b"__construct" {
                                    for param in params {
                                        if is_promoted_param(param) {
                                            let prop_vis = match param
                                                .visibility
                                                .as_ref()
                                                .unwrap_or(&Visibility::Public)
                                            {
                                                Visibility::Public => {
                                                    crate::object::Visibility::Public
                                                }
                                                Visibility::Protected => {
                                                    crate::object::Visibility::Protected
                                                }
                                                Visibility::Private => {
                                                    crate::object::Visibility::Private
                                                }
                                            };
                                            let obj_set_vis_cpp =
                                                param.set_visibility.as_ref().map(|sv| match sv {
                                                    Visibility::Public => ObjVisibility::Public,
                                                    Visibility::Protected => {
                                                        ObjVisibility::Protected
                                                    }
                                                    Visibility::Private => ObjVisibility::Private,
                                                });
                                            // Validate asymmetric visibility in CPP
                                            if obj_set_vis_cpp.is_some() {
                                                if param.type_hint.is_none() {
                                                    return Err(CompileError {
                                                        message: format!(
                                                            "Property with asymmetric visibility {}::${} must have type",
                                                            String::from_utf8_lossy(name),
                                                            String::from_utf8_lossy(&param.name)
                                                        ),
                                                        line: *method_line,
                                                    });
                                                }
                                                let vis_level = |v: &ObjVisibility| match v {
                                                    ObjVisibility::Public => 0,
                                                    ObjVisibility::Protected => 1,
                                                    ObjVisibility::Private => 2,
                                                };
                                                if let Some(ref sv) = obj_set_vis_cpp {
                                                    if vis_level(sv) < vis_level(&prop_vis) {
                                                        return Err(CompileError {
                                                            message: format!(
                                                                "Visibility of property {}::${} must not be weaker than set visibility",
                                                                String::from_utf8_lossy(name),
                                                                String::from_utf8_lossy(
                                                                    &param.name
                                                                )
                                                            ),
                                                            line: *method_line,
                                                        });
                                                    }
                                                }
                                            }
                                            // Readonly promoted properties must have a type
                                            if (param.readonly || modifiers.is_readonly)
                                                && param.type_hint.is_none()
                                            {
                                                return Err(CompileError {
                                                    message: format!(
                                                        "Readonly property {}::${} must have type",
                                                        String::from_utf8_lossy(name),
                                                        String::from_utf8_lossy(&param.name)
                                                    ),
                                                    line: *method_line,
                                                });
                                            }
                                            // Hooked promoted properties cannot be readonly (PHP-8.4 rule)
                                            if (param.readonly || modifiers.is_readonly)
                                                && (param.get_hook.is_some()
                                                    || param.set_hook.is_some())
                                            {
                                                return Err(CompileError {
                                                    message: "Hooked properties cannot be readonly"
                                                        .to_string(),
                                                    line: *method_line,
                                                });
                                            }
                                            let declaring_class_lower: Vec<u8> = qualified_name
                                                .iter()
                                                .map(|b| b.to_ascii_lowercase())
                                                .collect();
                                            let promoted_prop_type =
                                                param.type_hint.as_ref().map(|hint| {
                                                    type_hint_to_param_type_with_ns(
                                                        hint,
                                                        &self.current_namespace,
                                                        &self.use_map,
                                                    )
                                                });
                                            if param.variadic {
                                                return Err(CompileError {
                                                    message:
                                                        "Cannot declare variadic promoted property"
                                                            .to_string(),
                                                    line: *method_line,
                                                });
                                            }
                                            // Check for duplicate property from promotion
                                            if class.properties.iter().any(|p| p.name == param.name)
                                            {
                                                return Err(CompileError {
                                                    message: format!(
                                                        "Cannot redeclare {}::${}",
                                                        String::from_utf8_lossy(name),
                                                        String::from_utf8_lossy(&param.name)
                                                    ),
                                                    line: *method_line,
                                                });
                                            }
                                            if let Some(hint) = param
                                                .type_hint
                                                .as_ref()
                                                .filter(|h| type_hint_has_callable(h))
                                            {
                                                return Err(CompileError {
                                                    message: format!(
                                                        "Property {}::${} cannot have type {}",
                                                        String::from_utf8_lossy(name),
                                                        String::from_utf8_lossy(&param.name),
                                                        type_hint_display(hint)
                                                    ),
                                                    line: param.line,
                                                });
                                            }
                                            let prop_attrs =
                                                self.promoted_attrs(&param.attributes, 8, 32);
                                            // (validated with the parameter's)
                                            let pa =
                                                self.compile_attributes_target(&prop_attrs, "");
                                            // Promoted typed properties start as Undef (constructor sets the value)
                                            // Promoted untyped properties get Null as default
                                            let promoted_default = if promoted_prop_type.is_some() {
                                                Value::Undef
                                            } else {
                                                Value::Null
                                            };
                                            let prom_has_get_hook = param.get_hook.is_some();
                                            let prom_has_set_hook = param.set_hook.is_some();
                                            // Determine if promoted property with hooks is virtual
                                            let prom_is_virtual =
                                                if prom_has_get_hook || prom_has_set_hook {
                                                    let get_uses_backing = param
                                                        .get_hook
                                                        .as_ref()
                                                        .map(|body| {
                                                            stmts_reference_backing_store(
                                                                body,
                                                                &param.name,
                                                            )
                                                        })
                                                        .unwrap_or(false);
                                                    let set_uses_backing = param
                                                        .set_hook
                                                        .as_ref()
                                                        .map(|(_, body)| {
                                                            stmts_reference_backing_store(
                                                                body,
                                                                &param.name,
                                                            )
                                                        })
                                                        .unwrap_or(false);
                                                    !get_uses_backing && !set_uses_backing
                                                } else {
                                                    false
                                                };
                                            class.properties.push(PropertyDef {
                                                name: param.name.clone(),
                                                default: if prom_is_virtual {
                                                    Value::Undef
                                                } else {
                                                    promoted_default
                                                },
                                                is_static: false,
                                                visibility: prop_vis,
                                                set_visibility: obj_set_vis_cpp,
                                                declaring_class: declaring_class_lower.clone(),
                                                is_readonly: param.readonly
                                                    || modifiers.is_readonly,
                                                property_type: promoted_prop_type.clone(),
                                                has_get_hook: prom_has_get_hook,
                                                has_set_hook: prom_has_set_hook,
                                                is_virtual: prom_is_virtual,
                                                is_abstract: false,
                                                is_final: param.is_final,
                                                attributes: pa,
                                                doc_comment: param.doc_comment.as_ref().map(|d| {
                                                    String::from_utf8_lossy(d).into_owned()
                                                }),
                                            });
                                            // Compile promoted property get hook
                                            if let Some(hook_body) = &param.get_hook {
                                                let hook_method_name = format!(
                                                    "__property_get_{}",
                                                    String::from_utf8_lossy(&param.name)
                                                );
                                                let hook_display_name = format!(
                                                    "${}::get",
                                                    String::from_utf8_lossy(&param.name)
                                                );
                                                let mut hook_compiler = Compiler::new();
                                                hook_compiler.current_namespace =
                                                    self.current_namespace.clone();
                                                hook_compiler.use_map = self.use_map.clone();
                                                hook_compiler.use_function_map =
                                                    self.use_function_map.clone();
                                                hook_compiler.use_const_map =
                                                    self.use_const_map.clone();
                                                hook_compiler.op_array.name =
                                                    hook_display_name.into_bytes();
                                                hook_compiler.op_array.decl_line = *method_line;
                                                hook_compiler.op_array.strict_types =
                                                    self.op_array.strict_types;
                                                hook_compiler.op_array.return_type =
                                                    promoted_prop_type.clone();
                                                hook_compiler.op_array.returns_by_ref =
                                                    param.get_hook_by_ref;
                                                hook_compiler.source_file =
                                                    self.source_file.clone();
                                                hook_compiler.current_class =
                                                    Some(qualified_name.clone());
                                                hook_compiler.current_parent_class =
                                                    class.parent.clone();
                                                hook_compiler.op_array.scope_class = Some(
                                                    qualified_name
                                                        .iter()
                                                        .map(|b| b.to_ascii_lowercase())
                                                        .collect(),
                                                );
                                                hook_compiler.anon_class_name_map =
                                                    self.anon_class_name_map.clone();
                                                hook_compiler.op_array.get_or_create_cv(b"this");
                                                hook_compiler.op_array.param_count = 1;
                                                hook_compiler.op_array.required_param_count = 0;
                                                for s in hook_body.iter() {
                                                    hook_compiler.compile_stmt(s)?;
                                                }
                                                hook_compiler.check_pending_gotos()?;
                                                let null_idx =
                                                    hook_compiler.op_array.add_literal(Value::Null);
                                                hook_compiler.op_array.emit(Op {
                                                    opcode: OpCode::Return,
                                                    op1: OperandType::Const(null_idx),
                                                    op2: OperandType::Unused,
                                                    result: OperandType::Unused,
                                                    line: 0,
                                                });
                                                let lower_hook_name: Vec<u8> = hook_method_name
                                                    .bytes()
                                                    .map(|b| b.to_ascii_lowercase())
                                                    .collect();
                                                let get_attrs = self.compile_hook_attributes(
                                                    &param.hook_attrs.get,
                                                );
                                                class.methods.insert(
                                                    lower_hook_name,
                                                    MethodDef {
                                                        name: hook_method_name.into_bytes(),
                                                        op_array: std::rc::Rc::new(
                                                            hook_compiler.op_array,
                                                        ),
                                                        param_count: 0,
                                                        is_static: false,
                                                        is_abstract: false,
                                                        is_final: param.get_hook_final,
                                                        visibility: ObjVisibility::Public,
                                                        declaring_class: declaring_class_lower
                                                            .clone(),
                                                        doc_comment: None,
                                                        attributes: get_attrs,
                                                    },
                                                );
                                            }
                                            // Compile promoted property set hook
                                            if let Some((set_param_name, hook_body)) =
                                                &param.set_hook
                                            {
                                                let hook_method_name = format!(
                                                    "__property_set_{}",
                                                    String::from_utf8_lossy(&param.name)
                                                );
                                                let hook_display_name = format!(
                                                    "${}::set",
                                                    String::from_utf8_lossy(&param.name)
                                                );
                                                let mut hook_compiler = Compiler::new();
                                                hook_compiler.current_namespace =
                                                    self.current_namespace.clone();
                                                hook_compiler.use_map = self.use_map.clone();
                                                hook_compiler.use_function_map =
                                                    self.use_function_map.clone();
                                                hook_compiler.use_const_map =
                                                    self.use_const_map.clone();
                                                hook_compiler.op_array.name =
                                                    hook_display_name.into_bytes();
                                                hook_compiler.op_array.decl_line = *method_line;
                                                hook_compiler.op_array.strict_types =
                                                    self.op_array.strict_types;
                                                hook_compiler.source_file =
                                                    self.source_file.clone();
                                                hook_compiler.current_class =
                                                    Some(qualified_name.clone());
                                                hook_compiler.current_parent_class =
                                                    class.parent.clone();
                                                hook_compiler.op_array.scope_class = Some(
                                                    qualified_name
                                                        .iter()
                                                        .map(|b| b.to_ascii_lowercase())
                                                        .collect(),
                                                );
                                                hook_compiler.anon_class_name_map =
                                                    self.anon_class_name_map.clone();
                                                hook_compiler.op_array.get_or_create_cv(b"this");
                                                hook_compiler
                                                    .op_array
                                                    .get_or_create_cv(set_param_name);
                                                hook_compiler.op_array.param_count = 2;
                                                hook_compiler.op_array.param_attributes =
                                                    vec![self.compile_attributes_target(
                                                        &param.hook_attrs.set_param,
                                                        "parameter",
                                                    )];
                                                let set_attrs = self.compile_hook_attributes(
                                                    &param.hook_attrs.set,
                                                );
                                                hook_compiler.op_array.required_param_count = 1;
                                                for s in hook_body.iter() {
                                                    hook_compiler.compile_stmt(s)?;
                                                }
                                                hook_compiler.check_pending_gotos()?;
                                                let null_idx =
                                                    hook_compiler.op_array.add_literal(Value::Null);
                                                hook_compiler.op_array.emit(Op {
                                                    opcode: OpCode::Return,
                                                    op1: OperandType::Const(null_idx),
                                                    op2: OperandType::Unused,
                                                    result: OperandType::Unused,
                                                    line: 0,
                                                });
                                                let lower_hook_name: Vec<u8> = hook_method_name
                                                    .bytes()
                                                    .map(|b| b.to_ascii_lowercase())
                                                    .collect();
                                                class.methods.insert(
                                                    lower_hook_name,
                                                    MethodDef {
                                                        name: hook_method_name.into_bytes(),
                                                        op_array: std::rc::Rc::new(
                                                            hook_compiler.op_array,
                                                        ),
                                                        param_count: 1,
                                                        is_static: false,
                                                        is_abstract: false,
                                                        is_final: param.set_hook_final,
                                                        visibility: ObjVisibility::Public,
                                                        declaring_class: declaring_class_lower
                                                            .clone(),
                                                        doc_comment: None,
                                                        attributes: set_attrs,
                                                    },
                                                );
                                            }
                                        }
                                    }
                                }
                            }

                            // Check for parent/static type in abstract methods without a body
                            if method_body.is_none() || *is_abstract {
                                // Check return type for parent in class with no parent
                                if let Some(hint) = method_return_type {
                                    if class.parent.is_none() && !modifiers.is_trait {
                                        if let Some(err) = check_parent_type_without_parent(hint) {
                                            return Err(CompileError {
                                                message: err,
                                                line: *method_line,
                                            });
                                        }
                                    }
                                    // Validate type hint
                                    if let Some(err) = validate_type_hint_full(
                                        hint,
                                        Some(&qualified_name),
                                        class.parent.as_deref(),
                                    )
                                    .or_else(|| self.type_redundancy_error(hint, *method_line))
                                    .or_else(|| {
                                        relative_type_in_intersection(hint, modifiers.is_trait)
                                    }) {
                                        return Err(CompileError {
                                            message: err,
                                            line: *method_line,
                                        });
                                    }
                                }
                                // Check parameter types
                                for param in params.iter() {
                                    if let Some(hint) = &param.type_hint {
                                        if class.parent.is_none() && !modifiers.is_trait {
                                            if let Some(err) =
                                                check_parent_type_without_parent(hint)
                                            {
                                                return Err(CompileError {
                                                    message: err,
                                                    line: *method_line,
                                                });
                                            }
                                        }
                                        if let Some(err) = validate_type_hint_full(
                                            hint,
                                            Some(&qualified_name),
                                            class.parent.as_deref(),
                                        )
                                        .or_else(|| self.type_redundancy_error(hint, *method_line))
                                        .or_else(|| {
                                            relative_type_in_intersection(hint, modifiers.is_trait)
                                        }) {
                                            return Err(CompileError {
                                                message: err,
                                                line: *method_line,
                                            });
                                        }
                                        // "static" cannot be used as a parameter type (only as return type)
                                        if check_static_param_type(hint) {
                                            return Err(CompileError {
                                                message:
                                                    "Cannot use the static modifier on a parameter"
                                                        .to_string(),
                                                line: *method_line,
                                            });
                                        }
                                    }
                                }
                            }

                            if let Some(body_stmts) = method_body {
                                // Check if method body contains yield
                                let method_is_generator = stmts_contain_yield(body_stmts);

                                let mut method_compiler = Compiler::new();
                                method_compiler.current_namespace = self.current_namespace.clone();
                                method_compiler.use_map = self.use_map.clone();
                                method_compiler.use_function_map = self.use_function_map.clone();
                                method_compiler.use_const_map = self.use_const_map.clone();
                                method_compiler.op_array.name = method_name.clone();
                                method_compiler.op_array.is_generator = method_is_generator;
                                method_compiler.is_in_trait = modifiers.is_trait;
                                method_compiler.is_in_class_method = true;
                                method_compiler.this_always_bound = !*is_static;
                                method_compiler.op_array.decl_line = *method_line;
                                method_compiler.op_array.returns_by_ref = *method_returns_by_ref;
                                method_compiler.op_array.end_line = if *method_end_line > 0 {
                                    *method_end_line
                                } else {
                                    *method_line
                                };
                                method_compiler.op_array.doc_comment = method_doc_comment.clone();
                                method_compiler.op_array.filename = self.source_file.clone();
                                method_compiler.op_array.strict_types = self.op_array.strict_types;
                                method_compiler.source_file = self.source_file.clone();
                                if let Some(hint) = method_return_type {
                                    // Check for parent type in a class/interface with no parent (not traits - they allow parent)
                                    if class.parent.is_none() && !modifiers.is_trait {
                                        if let Some(err) = check_parent_type_without_parent(hint) {
                                            return Err(CompileError {
                                                message: err,
                                                line: *method_line,
                                            });
                                        }
                                    }
                                    // Validate return type hint
                                    if let Some(err) = validate_type_hint_full(
                                        hint,
                                        Some(&qualified_name),
                                        class.parent.as_deref(),
                                    )
                                    .or_else(|| self.type_redundancy_error(hint, *method_line))
                                    .or_else(|| {
                                        relative_type_in_intersection(hint, modifiers.is_trait)
                                    }) {
                                        return Err(CompileError {
                                            message: err,
                                            line: *method_line,
                                        });
                                    }
                                    method_compiler.op_array.return_type =
                                        Some(type_hint_to_param_type_with_ns(
                                            hint,
                                            &self.current_namespace,
                                            &self.use_map,
                                        ));
                                    // Check for 'never' return type
                                    if let TypeHint::Simple(name) = hint {
                                        let name_lower: Vec<u8> =
                                            name.iter().map(|b| b.to_ascii_lowercase()).collect();
                                        if name_lower == b"never" {
                                            method_compiler.has_never_return = true;
                                        }
                                    }
                                } else if method_name.eq_ignore_ascii_case(b"__tostring") {
                                    // __toString() implicitly returns string
                                    // (zend_add_magic_method()'s arg_info).
                                    method_compiler.op_array.return_type =
                                        Some(crate::opcode::ParamType::Simple(b"string".to_vec()));
                                }
                                method_compiler.current_class = Some(qualified_name.clone());
                                method_compiler.current_parent_class = class.parent.clone();
                                method_compiler.op_array.returns_by_ref = *method_returns_by_ref;
                                method_compiler.op_array.scope_class = Some(
                                    qualified_name
                                        .iter()
                                        .map(|b| b.to_ascii_lowercase())
                                        .collect(),
                                );
                                method_compiler.anon_class_name_map =
                                    self.anon_class_name_map.clone();

                                // First CV is always $this (for non-static methods)
                                if !is_static {
                                    method_compiler.op_array.get_or_create_cv(b"this");
                                }

                                // Set up parameter CVs with default values
                                // Set param_count and required_param_count for the method
                                method_compiler.op_array.param_count =
                                    params.len() as u32 + if *is_static { 0 } else { 1 }; // +1 for $this
                                method_compiler.op_array.required_param_count = {
                                    let mut last_req: i64 = -1;
                                    for (i, p) in params.iter().enumerate() {
                                        if !p.variadic && p.default.is_none() {
                                            last_req = i as i64;
                                        }
                                    }
                                    (last_req + 1) as u32
                                };
                                // Record by-ref params (offset by 1 for non-static methods due to $this)
                                if *is_static {
                                    method_compiler.op_array.by_ref_params =
                                        params.iter().map(|p| p.by_ref).collect();
                                    method_compiler.op_array.param_has_default =
                                        params.iter().map(|p| p.default.is_some()).collect();
                                } else {
                                    let mut by_ref = vec![false]; // $this is not by-ref
                                    by_ref.extend(params.iter().map(|p| p.by_ref));
                                    method_compiler.op_array.by_ref_params = by_ref;
                                    let mut has_default = vec![false]; // $this has no default
                                    has_default.extend(params.iter().map(|p| p.default.is_some()));
                                    method_compiler.op_array.param_has_default = has_default;
                                }
                                // Compile parameter attributes
                                method_compiler.op_array.param_attributes = params
                                    .iter()
                                    .map(|p| {
                                        let promoted = p.visibility.is_some()
                                            || p.set_visibility.is_some()
                                            || p.readonly
                                            || p.is_final
                                            || p.get_hook.is_some()
                                            || p.set_hook.is_some();
                                        if promoted {
                                            let a = self.promoted_attrs(&p.attributes, 32, 8);
                                            self.compile_attributes_target(&a, "parameter")
                                        } else {
                                            self.compile_attributes_target(
                                                &p.attributes,
                                                "parameter",
                                            )
                                        }
                                    })
                                    .collect();

                                for param in params {
                                    // Check for $this as parameter name
                                    if param.name == b"this" {
                                        return Err(CompileError {
                                            message: "Cannot use $this as parameter".into(),
                                            line: *method_line,
                                        });
                                    }
                                    // Validate parameter type hint
                                    if let Some(hint) = &param.type_hint {
                                        // Check for parent type in a class/interface with no parent (not traits)
                                        if class.parent.is_none() && !modifiers.is_trait {
                                            if let Some(err) =
                                                check_parent_type_without_parent(hint)
                                            {
                                                return Err(CompileError {
                                                    message: err,
                                                    line: *method_line,
                                                });
                                            }
                                        }
                                        if let Some(err) = validate_type_hint_full(
                                            hint,
                                            Some(&qualified_name),
                                            class.parent.as_deref(),
                                        )
                                        .or_else(|| self.type_redundancy_error(hint, *method_line))
                                        .or_else(|| {
                                            relative_type_in_intersection(hint, modifiers.is_trait)
                                        }) {
                                            return Err(CompileError {
                                                message: err,
                                                line: *method_line,
                                            });
                                        }
                                        // "static" cannot be used as a parameter type (only as return type)
                                        if check_static_param_type(hint) {
                                            return Err(CompileError {
                                                message:
                                                    "Cannot use the static modifier on a parameter"
                                                        .to_string(),
                                                line: *method_line,
                                            });
                                        }
                                    }

                                    let cv = method_compiler.op_array.get_or_create_cv(&param.name);

                                    // Handle variadic parameter
                                    if param.variadic {
                                        method_compiler.op_array.variadic_param = Some(cv);
                                    }

                                    // Store parameter type info
                                    // Constructor-promoted properties: fatal error for null default with non-nullable type
                                    if is_promoted_param(param) {
                                        if let Some(hint) = &param.type_hint {
                                            if let Some(default_expr) = &param.default {
                                                let pt_tmp = type_hint_to_param_type_with_ns(
                                                    hint,
                                                    &self.current_namespace,
                                                    &self.use_map,
                                                );
                                                if matches!(default_expr.kind, ExprKind::Null)
                                                    && !is_type_nullable_or_mixed(&pt_tmp)
                                                {
                                                    return Err(CompileError {
                                                        message: format!(
                                                            "Cannot use null as default value for parameter ${} of type {}",
                                                            String::from_utf8_lossy(&param.name),
                                                            type_hint_display(hint)
                                                        ),
                                                        line: default_expr.span.line,
                                                    });
                                                }
                                            }
                                        }
                                    }
                                    let type_info = param.type_hint.as_ref().map(|hint| {
                                        let mut pt = type_hint_to_param_type_with_ns(
                                            hint,
                                            &self.current_namespace,
                                            &self.use_map,
                                        );
                                        let mut is_implicitly_nullable = false;
                                        if param.visibility.is_none() {
                                            if let Some(default_expr) = &param.default {
                                                if matches!(default_expr.kind, ExprKind::Null)
                                                    && !is_type_nullable_or_mixed(&pt)
                                                {
                                                    pt = ParamType::Nullable(Box::new(pt));
                                                    is_implicitly_nullable = true;
                                                }
                                            }
                                        }
                                        ParamTypeInfo {
                                            param_type: pt,
                                            param_name: param.name.clone(),
                                            implicitly_nullable: is_implicitly_nullable,
                                        }
                                    });
                                    while method_compiler.op_array.param_types.len() <= cv as usize
                                    {
                                        method_compiler.op_array.param_types.push(None);
                                    }
                                    method_compiler.op_array.param_types[cv as usize] = type_info;

                                    if let Some(default_expr) = &param.default {
                                        let default_repr = self.default_value_repr_scoped(
                                            default_expr,
                                            if modifiers.is_trait {
                                                None
                                            } else {
                                                Some(&qualified_name)
                                            },
                                        );
                                        method_compiler
                                            .op_array
                                            .set_param_default_repr(cv, default_repr);
                                        let undef_idx =
                                            method_compiler.op_array.add_literal(Value::Undef);
                                        let check_tmp = method_compiler.op_array.alloc_temp();
                                        method_compiler.op_array.emit(Op {
                                            opcode: OpCode::Identical,
                                            op1: OperandType::Cv(cv),
                                            op2: OperandType::Const(undef_idx),
                                            result: OperandType::Tmp(check_tmp),
                                            line: 0,
                                        });
                                        let jmp_skip = method_compiler.op_array.emit(Op {
                                            opcode: OpCode::JmpZ,
                                            op1: OperandType::Tmp(check_tmp),
                                            op2: OperandType::JmpTarget(0),
                                            result: OperandType::Unused,
                                            line: 0,
                                        });
                                        let default_val = method_compiler
                                            .compile_const_expr_value(default_expr)?;
                                        if !matches!(default_expr.kind, ExprKind::Null) {
                                            let pcv = method_compiler
                                                .op_array
                                                .get_or_create_cv(&param.name)
                                                as usize;
                                            if let Some(Some(pti)) = method_compiler
                                                .op_array
                                                .param_types
                                                .get(pcv)
                                                .cloned()
                                            {
                                                match Self::check_literal_default(
                                                    &pti.param_type,
                                                    default_expr,
                                                ) {
                                                    Err((tn, _)) => {
                                                        return Err(CompileError {
                                                            message: format!("Cannot use {} as default value for parameter ${} of type {}", tn,
                                                                String::from_utf8_lossy(&param.name),
                                                                crate::vm::variance::type_to_string(&crate::vm::variance::TypeView::from_param_type(&pti.param_type), None)),
                                                            line: default_expr.span.line,
                                                        });
                                                    }
                                                    Ok(Some(widened)) => {
                                                        if let OperandType::Const(li) = default_val
                                                        {
                                                            method_compiler.op_array.literals
                                                                [li as usize] = widened;
                                                        }
                                                    }
                                                    Ok(None) => {}
                                                }
                                            }
                                        }
                                        method_compiler.op_array.emit(Op {
                                            opcode: OpCode::Assign,
                                            op1: OperandType::Cv(cv),
                                            op2: default_val,
                                            result: OperandType::Unused,
                                            line: 0,
                                        });
                                        Self::emit_recv_default_check(
                                            &mut method_compiler.op_array,
                                            cv,
                                            default_expr,
                                        );
                                        let after = method_compiler.op_array.current_offset();
                                        method_compiler.op_array.patch_jump(jmp_skip, after);
                                    }
                                }

                                // Constructor promotion: for params with visibility,
                                // emit $this->$name = $param at the start of the body
                                let method_name_lower: Vec<u8> =
                                    method_name.iter().map(|b| b.to_ascii_lowercase()).collect();
                                if method_name_lower == b"__construct" {
                                    for param in params {
                                        if is_promoted_param(param) {
                                            // Promoted param: assign to $this->name
                                            let this_cv = 0u32; // $this is always CV 0
                                            let param_cv = method_compiler
                                                .op_array
                                                .get_or_create_cv(&param.name);
                                            let prop_name_idx = method_compiler
                                                .op_array
                                                .add_literal(Value::String(PhpString::from_vec(
                                                    param.name.clone(),
                                                )));
                                            method_compiler.op_array.emit(Op {
                                                // A by-ref promoted parameter binds the property to the reference.
                                                opcode: if param.by_ref {
                                                    OpCode::PropertySetRef
                                                } else {
                                                    OpCode::PropertySet
                                                },
                                                op1: OperandType::Cv(this_cv),
                                                op2: OperandType::Cv(param_cv),
                                                result: OperandType::Const(prop_name_idx),
                                                line: 0,
                                            });
                                        }
                                    }
                                }

                                for s in body_stmts {
                                    method_compiler.compile_stmt(s)?;
                                }
                                method_compiler.check_pending_gotos()?;

                                // Implicit return null
                                let implicit_line = method_compiler.op_array.end_line;
                                method_compiler.emit_by_ref_return_notice(None, implicit_line);
                                let null_idx = method_compiler.op_array.add_literal(Value::Null);
                                method_compiler.op_array.emit(Op {
                                    opcode: OpCode::Return,
                                    op1: OperandType::Const(null_idx),
                                    op2: OperandType::Unused,
                                    result: OperandType::Unused,
                                    line: 0,
                                });

                                let vis = match visibility {
                                    Visibility::Public => ObjVisibility::Public,
                                    Visibility::Protected => ObjVisibility::Protected,
                                    Visibility::Private => ObjVisibility::Private,
                                };

                                let param_count = params.len();
                                let lower_name: Vec<u8> =
                                    method_name.iter().map(|b| b.to_ascii_lowercase()).collect();
                                // Check for duplicate method names
                                if class.methods.contains_key(&lower_name) {
                                    return Err(CompileError {
                                        message: format!(
                                            "Cannot redeclare {}::{}()",
                                            String::from_utf8_lossy(name),
                                            String::from_utf8_lossy(method_name)
                                        ),
                                        line: *method_line,
                                    });
                                }
                                let declaring_class_lower: Vec<u8> = qualified_name
                                    .iter()
                                    .map(|b| b.to_ascii_lowercase())
                                    .collect();
                                let mut concrete_op_array = method_compiler.op_array;
                                concrete_op_array.end_line = if *method_end_line > 0 {
                                    *method_end_line
                                } else {
                                    *method_line
                                };
                                class.methods.insert(
                                    lower_name,
                                    MethodDef {
                                        name: method_name.clone(),
                                        op_array: std::rc::Rc::new(concrete_op_array),
                                        param_count,
                                        is_static: *is_static,
                                        is_abstract: *is_abstract,
                                        is_final: *method_is_final,
                                        visibility: vis,
                                        declaring_class: declaring_class_lower,
                                        doc_comment: method_doc_comment
                                            .as_ref()
                                            .map(|d| String::from_utf8_lossy(d).into_owned()),
                                        attributes: self
                                            .compile_attributes_target(method_attributes, "method"),
                                    },
                                );
                            } else {
                                // Non-abstract method without body in a concrete class
                                if !*is_abstract
                                    && !modifiers.is_abstract
                                    && !modifiers.is_interface
                                {
                                    return Err(CompileError {
                                        message: format!(
                                            "Non-abstract method {}::{}() must contain body",
                                            String::from_utf8_lossy(name),
                                            String::from_utf8_lossy(method_name)
                                        ),
                                        line: *method_line,
                                    });
                                }
                                // Abstract method or interface method (no body)
                                let vis = match visibility {
                                    Visibility::Public => ObjVisibility::Public,
                                    Visibility::Protected => ObjVisibility::Protected,
                                    Visibility::Private => ObjVisibility::Private,
                                };
                                let param_count = params.len();
                                let lower_name: Vec<u8> =
                                    method_name.iter().map(|b| b.to_ascii_lowercase()).collect();
                                let declaring_class_lower: Vec<u8> = qualified_name
                                    .iter()
                                    .map(|b| b.to_ascii_lowercase())
                                    .collect();
                                let mut abstract_op_array = OpArray::new();
                                abstract_op_array.decl_line = *method_line;
                                abstract_op_array.returns_by_ref = *method_returns_by_ref;
                                abstract_op_array.end_line = if *method_end_line > 0 {
                                    *method_end_line
                                } else {
                                    *method_line
                                };
                                abstract_op_array.filename = self.source_file.clone();
                                abstract_op_array.name = method_name.clone();
                                abstract_op_array.scope_class = Some(declaring_class_lower.clone());
                                // Populate parameter information for abstract methods
                                // This is needed for method signature compatibility checks
                                if !is_static {
                                    abstract_op_array.get_or_create_cv(b"this");
                                }
                                abstract_op_array.param_count =
                                    params.len() as u32 + if *is_static { 0 } else { 1 };
                                abstract_op_array.required_param_count = {
                                    let mut last_req: i64 = -1;
                                    for (i, p) in params.iter().enumerate() {
                                        if !p.variadic && p.default.is_none() {
                                            last_req = i as i64;
                                        }
                                    }
                                    (last_req + 1) as u32
                                };
                                if *is_static {
                                    abstract_op_array.by_ref_params =
                                        params.iter().map(|p| p.by_ref).collect();
                                    abstract_op_array.param_has_default =
                                        params.iter().map(|p| p.default.is_some()).collect();
                                } else {
                                    let mut by_ref = vec![false];
                                    by_ref.extend(params.iter().map(|p| p.by_ref));
                                    abstract_op_array.by_ref_params = by_ref;
                                    let mut has_default = vec![false];
                                    has_default.extend(params.iter().map(|p| p.default.is_some()));
                                    abstract_op_array.param_has_default = has_default;
                                }
                                abstract_op_array.param_attributes = params
                                    .iter()
                                    .map(|p| {
                                        self.compile_attributes_target(&p.attributes, "parameter")
                                    })
                                    .collect();
                                for param in params {
                                    let cv = abstract_op_array.get_or_create_cv(&param.name);
                                    if param.variadic {
                                        abstract_op_array.variadic_param = Some(cv);
                                    }
                                    let type_info = param.type_hint.as_ref().map(|hint| {
                                        let mut pt = type_hint_to_param_type_with_ns(
                                            hint,
                                            &self.current_namespace,
                                            &self.use_map,
                                        );
                                        let mut is_implicitly_nullable = false;
                                        if let Some(default_expr) = &param.default {
                                            if matches!(default_expr.kind, ExprKind::Null)
                                                && !is_type_nullable_or_mixed(&pt)
                                            {
                                                pt = ParamType::Nullable(Box::new(pt));
                                                is_implicitly_nullable = true;
                                            }
                                        }
                                        crate::opcode::ParamTypeInfo {
                                            param_type: pt,
                                            param_name: param.name.clone(),
                                            implicitly_nullable: is_implicitly_nullable,
                                        }
                                    });
                                    // Store at CV index (cv already accounts for $this offset)
                                    while abstract_op_array.param_types.len() <= cv as usize {
                                        abstract_op_array.param_types.push(None);
                                    }
                                    abstract_op_array.param_types[cv as usize] = type_info;
                                }
                                // Compile default-value preludes (not executed) so the
                                // defaults are known for signatures and reflection.
                                if params.iter().any(|p| p.default.is_some()) {
                                    let mut dc = Compiler::new();
                                    dc.current_namespace = self.current_namespace.clone();
                                    dc.use_map = self.use_map.clone();
                                    dc.use_function_map = self.use_function_map.clone();
                                    dc.use_const_map = self.use_const_map.clone();
                                    dc.current_class = Some(qualified_name.clone());
                                    dc.current_parent_class = class.parent.clone();
                                    dc.source_file = self.source_file.clone();
                                    dc.op_array = std::mem::take(&mut abstract_op_array);
                                    for param in params {
                                        if let Some(default_expr) = &param.default {
                                            let cv = dc.op_array.get_or_create_cv(&param.name);
                                            let undef_idx = dc.op_array.add_literal(Value::Undef);
                                            let check_tmp = dc.op_array.alloc_temp();
                                            let mark = dc.op_array.ops.len();
                                            dc.op_array.emit(Op {
                                                opcode: OpCode::Identical,
                                                op1: OperandType::Cv(cv),
                                                op2: OperandType::Const(undef_idx),
                                                result: OperandType::Tmp(check_tmp),
                                                line: 0,
                                            });
                                            let jmp_skip = dc.op_array.emit(Op {
                                                opcode: OpCode::JmpZ,
                                                op1: OperandType::Tmp(check_tmp),
                                                op2: OperandType::JmpTarget(0),
                                                result: OperandType::Unused,
                                                line: 0,
                                            });
                                            if let Ok(default_val) =
                                                dc.compile_const_expr_value(default_expr)
                                            {
                                                dc.op_array.emit(Op {
                                                    opcode: OpCode::Assign,
                                                    op1: OperandType::Cv(cv),
                                                    op2: default_val,
                                                    result: OperandType::Unused,
                                                    line: 0,
                                                });
                                                let after = dc.op_array.current_offset();
                                                dc.op_array.patch_jump(jmp_skip, after);
                                            } else {
                                                dc.op_array.ops.truncate(mark);
                                            }
                                        }
                                    }
                                    abstract_op_array = dc.op_array;
                                }
                                // Set return type
                                if let Some(hint) = method_return_type {
                                    abstract_op_array.return_type =
                                        Some(type_hint_to_param_type_with_ns(
                                            hint,
                                            &self.current_namespace,
                                            &self.use_map,
                                        ));
                                }
                                class.methods.insert(
                                    lower_name,
                                    MethodDef {
                                        name: method_name.clone(),
                                        op_array: std::rc::Rc::new(abstract_op_array),
                                        param_count,
                                        is_static: *is_static,
                                        is_abstract: true,
                                        is_final: *method_is_final,
                                        visibility: vis,
                                        declaring_class: declaring_class_lower,
                                        doc_comment: method_doc_comment
                                            .as_ref()
                                            .map(|d| String::from_utf8_lossy(d).into_owned()),
                                        attributes: self
                                            .compile_attributes_target(method_attributes, "method"),
                                    },
                                );
                            }
                        }
                        ClassMember::ClassConstant {
                            name: const_name,
                            value: const_expr,
                            visibility: const_visibility,
                            is_final: const_is_final,
                            attributes: const_attributes,
                            type_hint: const_type_hint,
                            doc_comment: const_doc_comment,
                            ..
                        } => {
                            if let Some(msg) = Self::const_expr_error(const_expr, false) {
                                return Err(CompileError {
                                    message: msg,
                                    line: const_expr.span.line,
                                });
                            }
                            let val = if modifiers.is_trait
                                && trait_const_expr_uses_scope(const_expr)
                            {
                                self.compile_const_thunk(
                                    const_expr,
                                    &mut class.const_closures,
                                    &qualified_name,
                                    extends.as_deref(),
                                )?
                            } else if let Some(v) = Self::eval_const_expr(const_expr) {
                                v
                            } else {
                                // Handle class constant references like self::B, ClassName::CONST
                                match &const_expr.kind {
                                    ExprKind::ClassConstAccess {
                                        class: class_expr,
                                        constant,
                                    } => {
                                        // First try to resolve from the same class's already-compiled constants
                                        if let Some(val) = Self::eval_class_const_expr(
                                            const_expr,
                                            &class,
                                            &qualified_name,
                                            extends.as_deref(),
                                            self,
                                        )
                                        .filter(|v| !value_has_marker(v))
                                        {
                                            val
                                        } else if !matches!(
                                            class_expr.kind,
                                            ExprKind::Identifier(_)
                                        ) || !constant.eq_ignore_ascii_case(b"class")
                                        {
                                            // Resolved lazily on first access.
                                            self.compile_const_thunk(
                                                const_expr,
                                                &mut class.const_closures,
                                                &qualified_name,
                                                extends.as_deref(),
                                            )?
                                        } else {
                                            // Store as a deferred constant reference marker
                                            // Format: __deferred_const__::ClassName::CONSTANT_NAME
                                            let class_name = match &class_expr.kind {
                                                ExprKind::Identifier(name) => {
                                                    let resolved = self.resolve_class_name(name);
                                                    if resolved.eq_ignore_ascii_case(b"self") {
                                                        qualified_name.clone()
                                                    } else if resolved
                                                        .eq_ignore_ascii_case(b"parent")
                                                    {
                                                        if extends.is_none() && !class.is_trait {
                                                            return Err(CompileError {
                                                                message: "Cannot use \"parent\" when current class scope has no parent".into(),
                                                                line: class_expr.span.line,
                                                            });
                                                        }
                                                        extends
                                                            .as_ref()
                                                            .map(|p| self.resolve_class_name(p))
                                                            .unwrap_or(resolved)
                                                    } else {
                                                        resolved
                                                    }
                                                }
                                                _ => qualified_name.clone(),
                                            };
                                            let mut marker = b"__deferred_const__::".to_vec();
                                            marker.extend_from_slice(&class_name);
                                            marker.push(b':');
                                            marker.push(b':');
                                            marker.extend_from_slice(constant);
                                            Value::String(PhpString::from_vec(marker))
                                        }
                                    }
                                    ExprKind::BinaryOp { .. } => {
                                        // Recursive helper handles nested binops, ConstantAccess,
                                        // ClassConstAccess, and produces a __deferred_binop__ marker
                                        // when any subexpression must be resolved at runtime.
                                        // A fully folded value is kept; anything that has
                                        // to be resolved at runtime becomes a thunk.
                                        match self.eval_or_defer_in_class_const(
                                            const_expr,
                                            &class,
                                            &qualified_name,
                                            extends.as_deref(),
                                        ) {
                                            Some(v) if !value_has_marker(&v) => v,
                                            _ => self.compile_const_thunk(
                                                const_expr,
                                                &mut class.const_closures,
                                                &qualified_name,
                                                extends.as_deref(),
                                            )?,
                                        }
                                    }
                                    ExprKind::ConstantAccess(parts) => {
                                        // Handle magic constants and known constants in class constant context
                                        let name_lower: Vec<u8> =
                                            parts.iter().flat_map(|p| p.iter()).copied().collect();
                                        let name_lower_lc: Vec<u8> = name_lower
                                            .iter()
                                            .map(|c| c.to_ascii_lowercase())
                                            .collect();
                                        let magic_val = self.resolve_class_const_magic(
                                            &name_lower_lc,
                                            &qualified_name,
                                            const_expr.span.line,
                                        );
                                        if !matches!(magic_val, Value::Null) {
                                            magic_val
                                        } else {
                                            // A global constant: resolved on first access.
                                            self.compile_const_thunk(
                                                const_expr,
                                                &mut class.const_closures,
                                                &qualified_name,
                                                extends.as_deref(),
                                            )?
                                        }
                                    }
                                    ExprKind::Identifier(name) => {
                                        let name_lower_lc: Vec<u8> =
                                            name.iter().map(|c| c.to_ascii_lowercase()).collect();
                                        let magic_val = self.resolve_class_const_magic(
                                            &name_lower_lc,
                                            &qualified_name,
                                            const_expr.span.line,
                                        );
                                        if !matches!(magic_val, Value::Null) {
                                            magic_val
                                        } else {
                                            // A global constant: resolved on first access.
                                            self.compile_const_thunk(
                                                const_expr,
                                                &mut class.const_closures,
                                                &qualified_name,
                                                extends.as_deref(),
                                            )?
                                        }
                                    }
                                    ExprKind::Array(elements) => {
                                        // Handle arrays containing class constant references
                                        let mut arr = crate::array::PhpArray::new();
                                        let mut ok = true;
                                        for elem in elements {
                                            // Try to evaluate each element, with class context fallback
                                            let val = Self::eval_const_expr(&elem.value)
                                                .or_else(|| {
                                                    Self::eval_class_const_expr(
                                                        &elem.value,
                                                        &class,
                                                        &qualified_name,
                                                        extends.as_deref(),
                                                        self,
                                                    )
                                                })
                                                .or_else(|| {
                                                    // Handle magic constants like __CLASS__ in array context
                                                    match &elem.value.kind {
                                                        ExprKind::ConstantAccess(parts) => {
                                                            let name_lower: Vec<u8> = parts
                                                                .iter()
                                                                .flat_map(|p| p.iter())
                                                                .copied()
                                                                .collect();
                                                            let name_lower_lc: Vec<u8> = name_lower
                                                                .iter()
                                                                .map(|c| c.to_ascii_lowercase())
                                                                .collect();
                                                            let v = self.resolve_class_const_magic(
                                                                &name_lower_lc,
                                                                &qualified_name,
                                                                elem.value.span.line,
                                                            );
                                                            if matches!(v, Value::Null) {
                                                                None
                                                            } else {
                                                                Some(v)
                                                            }
                                                        }
                                                        ExprKind::Identifier(n) => {
                                                            let name_lower_lc: Vec<u8> = n
                                                                .iter()
                                                                .map(|c| c.to_ascii_lowercase())
                                                                .collect();
                                                            let v = self.resolve_class_const_magic(
                                                                &name_lower_lc,
                                                                &qualified_name,
                                                                elem.value.span.line,
                                                            );
                                                            if matches!(v, Value::Null) {
                                                                None
                                                            } else {
                                                                Some(v)
                                                            }
                                                        }
                                                        _ => None,
                                                    }
                                                })
                                                .or_else(|| {
                                                    // Create deferred marker for class const references
                                                    if let ExprKind::ClassConstAccess {
                                                        class: class_expr,
                                                        constant,
                                                    } = &elem.value.kind
                                                    {
                                                        let cname = match &class_expr.kind {
                                                            ExprKind::Identifier(n) => {
                                                                let resolved =
                                                                    self.resolve_class_name(n);
                                                                if resolved
                                                                    .eq_ignore_ascii_case(b"self")
                                                                {
                                                                    qualified_name.clone()
                                                                } else if resolved
                                                                    .eq_ignore_ascii_case(b"parent")
                                                                {
                                                                    extends
                                                                        .as_ref()
                                                                        .map(|p| {
                                                                            self.resolve_class_name(
                                                                                p,
                                                                            )
                                                                        })
                                                                        .unwrap_or(resolved)
                                                                } else {
                                                                    resolved
                                                                }
                                                            }
                                                            _ => qualified_name.clone(),
                                                        };
                                                        let mut marker =
                                                            b"__deferred_const__::".to_vec();
                                                        marker.extend_from_slice(&cname);
                                                        marker.push(b':');
                                                        marker.push(b':');
                                                        marker.extend_from_slice(constant);
                                                        Some(Value::String(PhpString::from_vec(
                                                            marker,
                                                        )))
                                                    } else {
                                                        None
                                                    }
                                                });
                                            if let Some(v) = val {
                                                if elem.unpack {
                                                    // Spread operator in class constant array
                                                    match v {
                                                        Value::Array(src_arr) => {
                                                            // Spread literal array
                                                            let src_borrow = src_arr.borrow();
                                                            for (k, sv) in src_borrow.iter() {
                                                                arr.set(k.clone(), sv.clone());
                                                            }
                                                        }
                                                        Value::String(ref s)
                                                            if s.as_bytes().starts_with(
                                                                b"__deferred_const__::",
                                                            ) =>
                                                        {
                                                            // Deferred spread: store with special marker
                                                            let mut spread_marker =
                                                                b"__deferred_spread__::".to_vec();
                                                            spread_marker.extend_from_slice(
                                                                &s.as_bytes()
                                                                    [b"__deferred_const__::"
                                                                        .len()..],
                                                            );
                                                            // Store as a special element that will be resolved/expanded at runtime
                                                            // Use a sentinel key to mark it (runtime will need to expand these)
                                                            arr.push(Value::String(
                                                                PhpString::from_vec(spread_marker),
                                                            ));
                                                        }
                                                        _ => {
                                                            // Non-array spread in constant expression
                                                            ok = false;
                                                            break;
                                                        }
                                                    }
                                                } else if let Some(key_expr) = &elem.key {
                                                    let k = Self::eval_const_expr(key_expr)
                                                        .or_else(|| {
                                                            Self::eval_class_const_expr(
                                                                key_expr,
                                                                &class,
                                                                &qualified_name,
                                                                extends.as_deref(),
                                                                self,
                                                            )
                                                        });
                                                    if let Some(k) = k {
                                                        let key = match k {
                                                            Value::Long(n) => {
                                                                crate::array::ArrayKey::Int(n)
                                                            }
                                                            Value::String(s) => {
                                                                crate::array::ArrayKey::String(s)
                                                            }
                                                            _ => {
                                                                ok = false;
                                                                break;
                                                            }
                                                        };
                                                        arr.set(key, v);
                                                    } else {
                                                        ok = false;
                                                        break;
                                                    }
                                                } else {
                                                    arr.push(v);
                                                }
                                            } else {
                                                ok = false;
                                                break;
                                            }
                                        }
                                        let arr = Value::Array(std::rc::Rc::new(
                                            std::cell::RefCell::new(arr),
                                        ));
                                        if ok && !value_has_marker(&arr) {
                                            arr
                                        } else {
                                            self.compile_const_thunk(
                                                const_expr,
                                                &mut class.const_closures,
                                                &qualified_name,
                                                extends.as_deref(),
                                            )?
                                        }
                                    }
                                    ExprKind::UnaryOp {
                                        op: UnaryOp::Negate,
                                        operand,
                                        ..
                                    } => {
                                        let inner = Self::eval_const_expr(operand).or_else(|| {
                                            Self::eval_class_const_expr(
                                                operand,
                                                &class,
                                                &qualified_name,
                                                extends.as_deref(),
                                                self,
                                            )
                                        });
                                        match inner {
                                            Some(Value::Long(n)) => Value::Long(-n),
                                            Some(Value::Double(f)) => Value::Double(-f),
                                            _ => self.compile_const_thunk(
                                                const_expr,
                                                &mut class.const_closures,
                                                &qualified_name,
                                                extends.as_deref(),
                                            )?,
                                        }
                                    }
                                    ExprKind::Closure {
                                        params: closure_params,
                                        body: closure_body,
                                        use_vars: _closure_use_vars,
                                        is_static: closure_is_static,
                                        attributes: closure_attrs,
                                        ..
                                    } => {
                                        // Compile closure for const expression
                                        let global_id = next_closure_id();
                                        let closure_name =
                                            format!("__closure_{}", global_id).into_bytes();
                                        let is_generator = stmts_contain_yield(closure_body);
                                        // Const-expression closures have no surrounding method context.
                                        let display_name = {
                                            let mut s = b"{closure:".to_vec();
                                            s.extend_from_slice(&self.source_file);
                                            s.extend_from_slice(
                                                format!(":{}}}", const_expr.span.line).as_bytes(),
                                            );
                                            s
                                        };
                                        let mut closure_compiler = Compiler::new();
                                        closure_compiler.op_array.name = closure_name.clone();
                                        closure_compiler.op_array.display_name = display_name;
                                        closure_compiler.op_array.filename =
                                            self.source_file.clone();
                                        closure_compiler.op_array.is_generator = is_generator;
                                        closure_compiler.op_array.is_static_closure =
                                            *closure_is_static;
                                        closure_compiler.op_array.decl_line = const_expr.span.line;
                                        closure_compiler.op_array.strict_types =
                                            self.op_array.strict_types;
                                        closure_compiler.op_array.attributes =
                                            self.compile_attributes(closure_attrs);
                                        closure_compiler.source_file = self.source_file.clone();
                                        closure_compiler.current_class =
                                            Some(qualified_name.clone());
                                        closure_compiler.current_parent_class =
                                            self.current_parent_class.clone();
                                        closure_compiler.op_array.scope_class = Some(
                                            qualified_name
                                                .iter()
                                                .map(|b| b.to_ascii_lowercase())
                                                .collect(),
                                        );
                                        // Compile params and body
                                        closure_compiler.op_array.param_count =
                                            closure_params.len() as u32;
                                        closure_compiler.op_array.closure_params = closure_params
                                            .iter()
                                            .map(|p| (p.name.clone(), p.by_ref))
                                            .collect();
                                        closure_compiler.op_array.required_param_count = {
                                            let mut last_req: i64 = -1;
                                            for (i, p) in closure_params.iter().enumerate() {
                                                if !p.variadic && p.default.is_none() {
                                                    last_req = i as i64;
                                                }
                                            }
                                            (last_req + 1) as u32
                                        };
                                        closure_compiler.op_array.by_ref_params =
                                            closure_params.iter().map(|p| p.by_ref).collect();
                                        closure_compiler.op_array.param_has_default =
                                            closure_params
                                                .iter()
                                                .map(|p| p.default.is_some())
                                                .collect();
                                        for p in closure_params {
                                            let cv =
                                                closure_compiler.op_array.get_or_create_cv(&p.name);
                                            if p.variadic {
                                                closure_compiler.op_array.variadic_param = Some(cv);
                                            }
                                        }
                                        for s in closure_body {
                                            closure_compiler.compile_stmt(s)?;
                                        }
                                        closure_compiler.check_pending_gotos()?;
                                        // Add implicit return null
                                        let null_idx =
                                            closure_compiler.op_array.add_literal(Value::Null);
                                        closure_compiler.op_array.emit(crate::opcode::Op {
                                            opcode: OpCode::Return,
                                            op1: OperandType::Const(null_idx),
                                            op2: OperandType::Unused,
                                            result: OperandType::Unused,
                                            line: 0,
                                        });
                                        // Store the closure as a class child function
                                        class.const_closures.push(closure_compiler.op_array);
                                        // Create a deferred closure marker
                                        let mut marker = b"__deferred_closure__::".to_vec();
                                        marker.extend_from_slice(&closure_name);
                                        Value::String(PhpString::from_vec(marker))
                                    }
                                    ExprKind::FirstClassCallable(target) => {
                                        // FCC in const expression: compile and store as deferred
                                        let global_id = next_closure_id();
                                        let closure_name =
                                            format!("__closure_fcc_{}", global_id).into_bytes();
                                        let mut cc = Compiler::new();
                                        cc.op_array.name = closure_name.clone();
                                        cc.op_array.strict_types = self.op_array.strict_types;
                                        cc.current_class = Some(qualified_name.clone());
                                        cc.current_parent_class = self.current_parent_class.clone();
                                        cc.op_array.scope_class = Some(
                                            qualified_name
                                                .iter()
                                                .map(|b| b.to_ascii_lowercase())
                                                .collect(),
                                        );
                                        cc.source_file = self.source_file.clone();
                                        // Set up variadic ...$args parameter
                                        let args_cv = cc.op_array.get_or_create_cv(b"args");
                                        cc.op_array.param_count = 1;
                                        cc.op_array.required_param_count = 0;
                                        cc.op_array.variadic_param = Some(args_cv);
                                        // Emit call inside closure body based on target
                                        match target {
                                            CallableTarget::Function(name_expr) => {
                                                if let ExprKind::Identifier(n) = &name_expr.kind {
                                                    let resolved_name =
                                                        self.resolve_function_name(n);
                                                    cc.op_array.fcc_target_name =
                                                        Some(resolved_name.clone());
                                                    cc.op_array.fcc_desc = Some(
                                                        [b"f:".as_slice(), &resolved_name].concat(),
                                                    );
                                                    let name_idx =
                                                        cc.op_array.add_literal(Value::String(
                                                            PhpString::from_vec(resolved_name),
                                                        ));
                                                    let arg_count_idx =
                                                        cc.op_array.add_literal(Value::Long(0));
                                                    cc.op_array.emit(crate::opcode::Op {
                                                        opcode: OpCode::InitFCall,
                                                        op1: OperandType::Const(name_idx),
                                                        op2: OperandType::Const(arg_count_idx),
                                                        result: OperandType::Unused,
                                                        line: const_expr.span.line,
                                                    });
                                                    cc.op_array.emit(crate::opcode::Op {
                                                        opcode: OpCode::SendUnpack,
                                                        op1: OperandType::Cv(args_cv),
                                                        op2: OperandType::Unused,
                                                        result: OperandType::Unused,
                                                        line: const_expr.span.line,
                                                    });
                                                    let result_tmp = cc.op_array.alloc_temp();
                                                    cc.op_array.emit(crate::opcode::Op {
                                                        opcode: OpCode::DoFCall,
                                                        op1: OperandType::Unused,
                                                        op2: OperandType::Unused,
                                                        result: OperandType::Tmp(result_tmp),
                                                        line: const_expr.span.line,
                                                    });
                                                    cc.op_array.emit(crate::opcode::Op {
                                                        opcode: OpCode::Return,
                                                        op1: OperandType::Tmp(result_tmp),
                                                        op2: OperandType::Unused,
                                                        result: OperandType::Unused,
                                                        line: const_expr.span.line,
                                                    });
                                                }
                                            }
                                            CallableTarget::StaticMethod {
                                                class: class_expr,
                                                method,
                                            } => {
                                                if let ExprKind::Identifier(cn) = &class_expr.kind {
                                                    let class_name = self.resolve_class_name(cn);
                                                    let resolved = if class_name
                                                        .eq_ignore_ascii_case(b"self")
                                                    {
                                                        qualified_name.clone()
                                                    } else if class_name
                                                        .eq_ignore_ascii_case(b"parent")
                                                    {
                                                        self.current_parent_class
                                                            .clone()
                                                            .unwrap_or(class_name.clone())
                                                    } else {
                                                        class_name
                                                    };
                                                    let mut func_name = resolved;
                                                    func_name.extend_from_slice(b"::");
                                                    func_name.extend_from_slice(method);
                                                    cc.op_array.fcc_target_name =
                                                        Some(func_name.clone());
                                                    cc.op_array.fcc_desc = Some(
                                                        [b"S:".as_slice(), &func_name].concat(),
                                                    );
                                                    let name_idx =
                                                        cc.op_array.add_literal(Value::String(
                                                            PhpString::from_vec(func_name),
                                                        ));
                                                    let arg_count_idx =
                                                        cc.op_array.add_literal(Value::Long(0));
                                                    cc.op_array.emit(crate::opcode::Op {
                                                        opcode: OpCode::InitFCall,
                                                        op1: OperandType::Const(name_idx),
                                                        op2: OperandType::Const(arg_count_idx),
                                                        result: OperandType::Unused,
                                                        line: const_expr.span.line,
                                                    });
                                                    cc.op_array.emit(crate::opcode::Op {
                                                        opcode: OpCode::SendUnpack,
                                                        op1: OperandType::Cv(args_cv),
                                                        op2: OperandType::Unused,
                                                        result: OperandType::Unused,
                                                        line: const_expr.span.line,
                                                    });
                                                    let result_tmp = cc.op_array.alloc_temp();
                                                    cc.op_array.emit(crate::opcode::Op {
                                                        opcode: OpCode::DoFCall,
                                                        op1: OperandType::Unused,
                                                        op2: OperandType::Unused,
                                                        result: OperandType::Tmp(result_tmp),
                                                        line: const_expr.span.line,
                                                    });
                                                    cc.op_array.emit(crate::opcode::Op {
                                                        opcode: OpCode::Return,
                                                        op1: OperandType::Tmp(result_tmp),
                                                        op2: OperandType::Unused,
                                                        result: OperandType::Unused,
                                                        line: const_expr.span.line,
                                                    });
                                                }
                                            }
                                            _ => {}
                                        }
                                        class.const_closures.push(cc.op_array);
                                        let mut marker = b"__deferred_closure__::".to_vec();
                                        marker.extend_from_slice(&closure_name);
                                        Value::String(PhpString::from_vec(marker))
                                    }
                                    ExprKind::New {
                                        class: new_class,
                                        args: _new_args,
                                    } => {
                                        // new Foo() in const expression - store as deferred
                                        if let ExprKind::Identifier(cn) = &new_class.kind {
                                            let resolved = self.resolve_class_name(cn);
                                            let mut marker = b"__deferred_new__::".to_vec();
                                            marker.extend_from_slice(&resolved);
                                            Value::String(PhpString::from_vec(marker))
                                        } else {
                                            self.compile_const_thunk(
                                                const_expr,
                                                &mut class.const_closures,
                                                &qualified_name,
                                                extends.as_deref(),
                                            )?
                                        }
                                    }
                                    _ => self.compile_const_thunk(
                                        const_expr,
                                        &mut class.const_closures,
                                        &qualified_name,
                                        extends.as_deref(),
                                    )?,
                                }
                            };
                            let mut val = val;
                            if let Some(hint) = const_type_hint.as_ref() {
                                use crate::vm::variance::{
                                    T_ANY, T_CALLABLE, T_NEVER, T_VOID, TypeView,
                                };
                                let pt = type_hint_to_param_type_with_ns(
                                    hint,
                                    &self.current_namespace,
                                    &self.use_map,
                                );
                                let tv = TypeView::from_param_type(&pt);
                                let tstr = crate::vm::variance::type_to_string(&tv, None);
                                if tv.mask != T_ANY
                                    && tv.mask & (T_CALLABLE | T_VOID | T_NEVER) != 0
                                {
                                    return Err(CompileError {
                                        message: format!(
                                            "Class constant {}::{} cannot have type {}",
                                            String::from_utf8_lossy(&qualified_name),
                                            String::from_utf8_lossy(const_name),
                                            tstr
                                        ),
                                        line: stmt.span.line,
                                    });
                                }
                                match Self::check_literal_default(&pt, const_expr) {
                                    Err((tn, _)) => {
                                        return Err(CompileError {
                                            message: format!(
                                                "Cannot use {} as value for class constant {}::{} of type {}",
                                                tn,
                                                String::from_utf8_lossy(&qualified_name),
                                                String::from_utf8_lossy(const_name),
                                                tstr
                                            ),
                                            line: stmt.span.line,
                                        });
                                    }
                                    Ok(Some(v)) => val = v,
                                    Ok(None) => {}
                                }
                            }
                            class.constants.insert(const_name.clone(), val);
                            // Store constant metadata (visibility, final)
                            let const_vis = match const_visibility {
                                goro_parser::ast::Visibility::Public => {
                                    crate::object::Visibility::Public
                                }
                                goro_parser::ast::Visibility::Protected => {
                                    crate::object::Visibility::Protected
                                }
                                goro_parser::ast::Visibility::Private => {
                                    crate::object::Visibility::Private
                                }
                            };
                            let declaring_class_lower: Vec<u8> = qualified_name
                                .iter()
                                .map(|b| b.to_ascii_lowercase())
                                .collect();
                            let const_attrs = self.compile_attributes(const_attributes);
                            let declared_type = const_type_hint.as_ref().map(|hint| {
                                type_hint_to_param_type_with_ns(
                                    hint,
                                    &self.current_namespace,
                                    &self.use_map,
                                )
                            });
                            // Collect class constant references in the value expression so
                            // accessing this constant can re-emit #[\Deprecated] banners for
                            // any deprecated constants it depends on.
                            let mut refs = Vec::new();
                            Self::collect_class_const_refs(
                                const_expr,
                                &qualified_name,
                                extends.as_deref(),
                                self,
                                &mut refs,
                            );
                            class.constants_meta.insert(
                                const_name.clone(),
                                crate::object::ConstantMeta {
                                    visibility: const_vis,
                                    is_final: *const_is_final,
                                    declaring_class: declaring_class_lower,
                                    attributes: const_attrs,
                                    declared_type,
                                    doc_comment: const_doc_comment
                                        .as_ref()
                                        .map(|d| String::from_utf8_lossy(d).into_owned()),
                                    referenced_constants: refs,
                                },
                            );
                            // Private constants cannot be final
                            if *const_is_final && const_vis == crate::object::Visibility::Private {
                                return Err(CompileError {
                                    message: format!(
                                        "Private constant {}::{} cannot be final as it is not visible to other classes",
                                        String::from_utf8_lossy(name),
                                        String::from_utf8_lossy(const_name)
                                    ),
                                    line: stmt.span.line,
                                });
                            }
                        }
                        ClassMember::EnumCase {
                            name: case_name,
                            value,
                            attributes: case_attributes,
                            doc_comment: case_doc_comment,
                        } => {
                            // 'case' can only be used in enums
                            if !modifiers.is_enum {
                                return Err(CompileError {
                                    message: "Case can only be used in enums".to_string(),
                                    line: stmt.span.line,
                                });
                            }
                            // Backed enum cases must have values, unit enum cases must not
                            if enum_backing_type.is_some() && value.is_none() {
                                return Err(CompileError {
                                    message: format!(
                                        "Case {} of backed enum {} must have a value",
                                        String::from_utf8_lossy(case_name),
                                        String::from_utf8_lossy(name)
                                    ),
                                    line: stmt.span.line,
                                });
                            }
                            if enum_backing_type.is_none() && value.is_some() {
                                return Err(CompileError {
                                    message: format!(
                                        "Case {} of non-backed enum {} must not have a value",
                                        String::from_utf8_lossy(case_name),
                                        String::from_utf8_lossy(name)
                                    ),
                                    line: stmt.span.line,
                                });
                            }
                            // Enum cases: store the backing value for backed enums
                            let backing_value = if let Some(val_expr) = value {
                                if let Some(v) = Self::eval_const_expr(val_expr) {
                                    v
                                } else {
                                    // Handle class constant references and magic constants like class constant defaults
                                    match &val_expr.kind {
                                        ExprKind::ClassConstAccess {
                                            class: class_expr,
                                            constant,
                                        } => {
                                            // Try to resolve from same class or other classes
                                            if let Some(val) = Self::eval_class_const_expr(
                                                val_expr,
                                                &class,
                                                &qualified_name,
                                                extends.as_deref(),
                                                self,
                                            ) {
                                                val
                                            } else {
                                                let class_name = match &class_expr.kind {
                                                    ExprKind::Identifier(cn) => {
                                                        let resolved = self.resolve_class_name(cn);
                                                        if resolved.eq_ignore_ascii_case(b"self") {
                                                            qualified_name.clone()
                                                        } else if resolved
                                                            .eq_ignore_ascii_case(b"parent")
                                                        {
                                                            extends
                                                                .as_ref()
                                                                .map(|p| self.resolve_class_name(p))
                                                                .unwrap_or(resolved)
                                                        } else {
                                                            resolved
                                                        }
                                                    }
                                                    _ => qualified_name.clone(),
                                                };
                                                let mut marker = b"__deferred_const__::".to_vec();
                                                marker.extend_from_slice(&class_name);
                                                marker.push(b':');
                                                marker.push(b':');
                                                marker.extend_from_slice(constant);
                                                Value::String(PhpString::from_vec(marker))
                                            }
                                        }
                                        ExprKind::ConstantAccess(parts) => {
                                            let name_lower: Vec<u8> = parts
                                                .iter()
                                                .flat_map(|p| p.iter())
                                                .copied()
                                                .collect();
                                            let name_lower_lc: Vec<u8> = name_lower
                                                .iter()
                                                .map(|c| c.to_ascii_lowercase())
                                                .collect();
                                            self.enum_case_const_value(
                                                val_expr,
                                                &name_lower_lc,
                                                &mut class.const_closures,
                                                &qualified_name,
                                                extends.as_deref(),
                                            )?
                                        }
                                        ExprKind::Identifier(ident_name) => {
                                            let name_lower_lc: Vec<u8> = ident_name
                                                .iter()
                                                .map(|c| c.to_ascii_lowercase())
                                                .collect();
                                            self.enum_case_const_value(
                                                val_expr,
                                                &name_lower_lc,
                                                &mut class.const_closures,
                                                &qualified_name,
                                                extends.as_deref(),
                                            )?
                                        }
                                        ExprKind::BinaryOp {
                                            op, left, right, ..
                                        } => {
                                            let l = Self::eval_const_expr(left).or_else(|| {
                                                Self::eval_class_const_expr(
                                                    left,
                                                    &class,
                                                    &qualified_name,
                                                    extends.as_deref(),
                                                    self,
                                                )
                                            });
                                            let r = Self::eval_const_expr(right).or_else(|| {
                                                Self::eval_class_const_expr(
                                                    right,
                                                    &class,
                                                    &qualified_name,
                                                    extends.as_deref(),
                                                    self,
                                                )
                                            });
                                            // Only numbers are folded here: other operands
                                            // may warn or throw when the constant is
                                            // evaluated (string % int, division by zero).
                                            let foldable = |lv: &Value, rv: &Value| {
                                                let num = |v: &Value| {
                                                    matches!(v, Value::Long(_) | Value::Double(_))
                                                };
                                                if matches!(op, BinaryOp::Concat) {
                                                    return true;
                                                }
                                                num(lv)
                                                    && num(rv)
                                                    && !(matches!(
                                                        op,
                                                        BinaryOp::Div | BinaryOp::Mod
                                                    ) && rv.to_double() == 0.0)
                                            };
                                            let (l, r) = match (l, r) {
                                                (Some(lv), Some(rv)) if foldable(&lv, &rv) => {
                                                    (Some(lv), Some(rv))
                                                }
                                                _ => (None, None),
                                            };
                                            if let (Some(lv), Some(rv)) = (l, r) {
                                                match op {
                                                    BinaryOp::Add => lv.add(&rv),
                                                    BinaryOp::Sub => lv.sub(&rv),
                                                    BinaryOp::Mul => lv.mul(&rv),
                                                    BinaryOp::Concat => {
                                                        let mut result =
                                                            lv.to_php_string().as_bytes().to_vec();
                                                        result.extend_from_slice(
                                                            rv.to_php_string().as_bytes(),
                                                        );
                                                        Value::String(PhpString::from_vec(result))
                                                    }
                                                    BinaryOp::BitwiseOr => {
                                                        Value::Long(lv.to_long() | rv.to_long())
                                                    }
                                                    BinaryOp::BitwiseAnd => {
                                                        Value::Long(lv.to_long() & rv.to_long())
                                                    }
                                                    BinaryOp::BitwiseXor => {
                                                        Value::Long(lv.to_long() ^ rv.to_long())
                                                    }
                                                    BinaryOp::ShiftLeft => {
                                                        let n = rv.to_long();
                                                        Value::Long(if (0..64).contains(&n) {
                                                            lv.to_long().wrapping_shl(n as u32)
                                                        } else {
                                                            0
                                                        })
                                                    }
                                                    BinaryOp::ShiftRight => {
                                                        let (a, n) = (lv.to_long(), rv.to_long());
                                                        Value::Long(if (0..64).contains(&n) {
                                                            a >> n
                                                        } else if a < 0 {
                                                            -1
                                                        } else {
                                                            0
                                                        })
                                                    }
                                                    BinaryOp::Div => {
                                                        lv.div(&rv).unwrap_or(Value::Null)
                                                    }
                                                    BinaryOp::Mod => {
                                                        lv.modulo(&rv).unwrap_or(Value::Null)
                                                    }
                                                    BinaryOp::Pow => lv.pow(&rv),
                                                    _ => self.compile_const_thunk(
                                                        val_expr,
                                                        &mut class.const_closures,
                                                        &qualified_name,
                                                        extends.as_deref(),
                                                    )?,
                                                }
                                            } else {
                                                self.compile_const_thunk(
                                                    val_expr,
                                                    &mut class.const_closures,
                                                    &qualified_name,
                                                    extends.as_deref(),
                                                )?
                                            }
                                        }
                                        // Anything else is evaluated on first use.
                                        _ => self.compile_const_thunk(
                                            val_expr,
                                            &mut class.const_closures,
                                            &qualified_name,
                                            extends.as_deref(),
                                        )?,
                                    }
                                }
                            } else {
                                Value::Null
                            };
                            // Duplicate backing values are reported lazily, when the
                            // enum's backing table is first built (zend_enum_build_backed_enum_table).
                            // Validate backing type matches
                            if let Some(bt) = &enum_backing_type {
                                if bt.eq_ignore_ascii_case(b"int")
                                    && !matches!(backing_value, Value::Long(_) | Value::Null)
                                {
                                    // Type mismatch: string value for int-backed enum
                                    // (Null means unit enum case, which is already handled above)
                                }
                                if bt.eq_ignore_ascii_case(b"string")
                                    && !matches!(backing_value, Value::String(_) | Value::Null)
                                {
                                    // Type mismatch: int value for string-backed enum
                                }
                            }
                            // Store in enum_cases list for runtime enum object creation
                            class
                                .enum_cases
                                .push((case_name.clone(), backing_value.clone()));
                            // Store a special marker constant "__enum_case__::CaseName"
                            // The VM will detect this and create/return enum case objects
                            let marker = Value::String(crate::string::PhpString::from_vec(
                                [b"__enum_case__::" as &[u8], case_name.as_slice()].concat(),
                            ));
                            class.constants.insert(case_name.clone(), marker);
                            // Insert metadata so getDocComment() works on enum cases via
                            // ReflectionClassConstant / ReflectionEnumUnitCase / BackedCase.
                            let declaring_class_lower_ec: Vec<u8> = qualified_name
                                .iter()
                                .map(|b| b.to_ascii_lowercase())
                                .collect();
                            let case_attrs_compiled =
                                self.compile_attributes_target(case_attributes, "constant");
                            class.constants_meta.insert(
                                case_name.clone(),
                                crate::object::ConstantMeta {
                                    visibility: crate::object::Visibility::Public,
                                    is_final: false,
                                    declaring_class: declaring_class_lower_ec,
                                    attributes: case_attrs_compiled,
                                    declared_type: None,
                                    doc_comment: case_doc_comment
                                        .as_ref()
                                        .map(|d| String::from_utf8_lossy(d).into_owned()),
                                    referenced_constants: Vec::new(),
                                },
                            );
                        }
                        ClassMember::TraitUse {
                            traits,
                            adaptations,
                        } => {
                            // Interfaces cannot use traits
                            if modifiers.is_interface {
                                let trait_list: Vec<String> = traits
                                    .iter()
                                    .map(|t| String::from_utf8_lossy(t).to_string())
                                    .collect();
                                return Err(CompileError {
                                    message: format!(
                                        "Cannot use traits inside of interfaces. {} is used in {}",
                                        trait_list.first().unwrap_or(&String::new()),
                                        String::from_utf8_lossy(name)
                                    ),
                                    line: stmt.span.line,
                                });
                            }
                            for trait_name in traits {
                                class.traits.push(self.resolve_class_name(trait_name));
                            }
                            for adaptation in adaptations {
                                match adaptation {
                                    goro_parser::ast::TraitAdaptation::Alias {
                                        trait_name,
                                        method,
                                        new_name,
                                        new_visibility,
                                        new_final,
                                    } => {
                                        class.trait_adaptations.push(
                                            crate::object::TraitAdaptation::Alias {
                                                new_final: *new_final,
                                                trait_name: trait_name
                                                    .as_ref()
                                                    .map(|n| self.resolve_class_name(n)),
                                                method: method.clone(),
                                                new_name: new_name.clone(),
                                                new_visibility: new_visibility.as_ref().map(|v| {
                                                    match v {
                                                        goro_parser::ast::Visibility::Public => {
                                                            crate::object::Visibility::Public
                                                        }
                                                        goro_parser::ast::Visibility::Protected => {
                                                            crate::object::Visibility::Protected
                                                        }
                                                        goro_parser::ast::Visibility::Private => {
                                                            crate::object::Visibility::Private
                                                        }
                                                    }
                                                }),
                                            },
                                        );
                                    }
                                    goro_parser::ast::TraitAdaptation::Precedence {
                                        trait_name,
                                        method,
                                        instead_of,
                                    } => {
                                        class.trait_adaptations.push(
                                            crate::object::TraitAdaptation::Precedence {
                                                trait_name: self.resolve_class_name(trait_name),
                                                method: method.clone(),
                                                instead_of: instead_of
                                                    .iter()
                                                    .map(|n| self.resolve_class_name(n))
                                                    .collect(),
                                            },
                                        );
                                    }
                                }
                            }
                        }
                    }
                }

                self.const_property_name.clear();
                // Restore outer class scope
                self.current_class = saved_class;
                self.in_trait_body = saved_in_trait_body;
                self.current_parent_class = saved_parent;

                // Store the class and emit a DeclareClass opcode
                // Classes declared inside a function/method/closure body live on that
                // body's op_array (encoded as a negative index), since the sub-compiler's
                // compiled_classes are never handed to the VM.
                let class_idx: i64 = if self.is_top_level {
                    self.compiled_classes.push(class);
                    (self.compiled_classes.len() - 1) as i64
                } else {
                    self.op_array.local_classes.push(class);
                    -(self.op_array.local_classes.len() as i64)
                };

                let name_idx = self
                    .op_array
                    .add_literal(Value::String(PhpString::from_vec(qualified_name)));
                let idx_literal = self.op_array.add_literal(Value::Long(class_idx));
                // Early-binding attempt marker (result = Const(1)) for hoisted classes.
                let decl_result = if self.in_hoisting_pass {
                    OperandType::Const(self.op_array.add_literal(Value::Long(1)))
                } else {
                    OperandType::Unused
                };
                self.op_array.emit(Op {
                    opcode: OpCode::DeclareClass,
                    op1: OperandType::Const(name_idx),
                    op2: OperandType::Const(idx_literal),
                    result: decl_result,
                    line: stmt.span.line,
                });

                Ok(())
            }

            StmtKind::NamespaceDecl { name, body } => {
                // Set current namespace
                if let Some(parts) = name {
                    // Join namespace parts with backslash
                    let mut ns = Vec::new();
                    for (i, part) in parts.iter().enumerate() {
                        if i > 0 {
                            ns.push(b'\\');
                        }
                        ns.extend_from_slice(part);
                    }
                    self.current_namespace = ns;
                } else {
                    self.current_namespace = Vec::new();
                }
                // Clear use maps when entering a new namespace
                self.use_map = HashMap::new();
                self.use_function_map = HashMap::new();
                self.use_const_map = HashMap::new();

                // If this is a block namespace { ... }, compile the body
                if let Some(body_stmts) = body {
                    for s in body_stmts {
                        self.compile_stmt(s)?;
                    }
                    // After block namespace, reset to global
                    self.current_namespace = Vec::new();
                    self.use_map = HashMap::new();
                    self.use_function_map = HashMap::new();
                    self.use_const_map = HashMap::new();
                }
                Ok(())
            }

            StmtKind::UseDecl(items) => {
                for item in items {
                    // Build the fully qualified name from parts
                    let mut fqn = Vec::new();
                    for (i, part) in item.name.iter().enumerate() {
                        if i > 0 {
                            fqn.push(b'\\');
                        }
                        fqn.extend_from_slice(part);
                    }
                    // Determine the alias (short name)
                    let alias = if let Some(ref a) = item.alias {
                        a.clone()
                    } else {
                        // Last part of the name
                        item.name.last().cloned().unwrap_or_default()
                    };
                    let alias_lower: Vec<u8> =
                        alias.iter().map(|b| b.to_ascii_lowercase()).collect();
                    // Check for reserved names in use declarations (only for class imports)
                    if matches!(item.kind, UseKind::Normal) && is_reserved_class_name(&alias_lower)
                    {
                        return Err(CompileError {
                            message: format!(
                                "Cannot use {} as {} because '{}' is a special class name",
                                String::from_utf8_lossy(&fqn),
                                String::from_utf8_lossy(&alias),
                                String::from_utf8_lossy(&alias)
                            ),
                            line: stmt.span.line,
                        });
                    }
                    if self.in_main_pass {
                        if item.alias.is_none()
                            && item.name.len() == 1
                            && self.current_namespace.is_empty()
                        {
                            push_compile_warning_tuple((
                                format!(
                                    "The use statement with non-compound name '{}' has no effect",
                                    String::from_utf8_lossy(&alias)
                                ),
                                stmt.span.line,
                            ));
                        }
                        let type_str = match item.kind {
                            UseKind::Normal => "",
                            UseKind::Function => " function",
                            UseKind::Constant => " const",
                        };
                        let fqn_lower: Vec<u8> =
                            fqn.iter().map(|b| b.to_ascii_lowercase()).collect();
                        let already_imported = match item.kind {
                            UseKind::Normal => self.use_map.contains_key(&alias_lower),
                            UseKind::Function => self.use_function_map.contains_key(&alias_lower),
                            UseKind::Constant => self.use_const_map.contains_key(&alias),
                        };
                        let mut conflict = already_imported;
                        if !conflict {
                            // zend_have_seen_symbol(): a declaration of that name
                            // earlier in the file (constants: case-sensitive).
                            let lookup: &[u8] = if matches!(item.kind, UseKind::Constant) {
                                &alias
                            } else {
                                &alias_lower
                            };
                            let check: Vec<u8> = if self.current_namespace.is_empty() {
                                lookup.to_vec()
                            } else {
                                let mut c: Vec<u8> = self
                                    .current_namespace
                                    .iter()
                                    .map(|b| b.to_ascii_lowercase())
                                    .collect();
                                c.push(b'\\');
                                c.extend_from_slice(lookup);
                                c
                            };
                            let seen = match item.kind {
                                UseKind::Normal => self.seen_class_symbols.contains(&check),
                                UseKind::Function => self.seen_function_symbols.contains(&check),
                                UseKind::Constant => self.seen_const_symbols.contains(&check),
                            };
                            if seen && !check.eq_ignore_ascii_case(&fqn_lower) {
                                conflict = true;
                            }
                        }
                        if conflict {
                            return Err(CompileError {
                                message: format!(
                                    "Cannot use{} {} as {} because the name is already in use",
                                    type_str,
                                    String::from_utf8_lossy(&fqn),
                                    String::from_utf8_lossy(&alias)
                                ),
                                line: stmt.span.line,
                            });
                        }
                    }
                    match item.kind {
                        UseKind::Normal => {
                            self.use_map.insert(alias_lower, fqn);
                        }
                        UseKind::Function => {
                            self.use_function_map.insert(alias_lower, fqn);
                        }
                        UseKind::Constant => {
                            self.use_const_map.insert(alias.clone(), fqn);
                        }
                    }
                }
                Ok(())
            }

            StmtKind::Label(name) => {
                // Check for duplicate labels
                if self.label_offsets.contains_key(name) {
                    let label_display = String::from_utf8_lossy(name);
                    return Err(CompileError {
                        message: format!("Label '{}' already defined", label_display),
                        line: stmt.span.line,
                    });
                }
                // Loop variables freed by forward gotos to this label stay
                // alive for the loops that enclose it.
                let depth = self.loop_stack.len();
                let frees = std::mem::take(&mut self.jumps.pending_goto_frees);
                for (label, loop_index, start, end) in frees {
                    if &label != name {
                        self.jumps
                            .pending_goto_frees
                            .push((label, loop_index, start, end));
                    } else if loop_index < depth {
                        for op in &mut self.op_array.ops[start as usize..end as usize] {
                            op.opcode = OpCode::Nop;
                        }
                    }
                }
                self.jumps.label_loop_depth.insert(name.clone(), depth);
                let offset = self.op_array.current_offset();
                self.label_offsets.insert(name.clone(), offset);
                self.label_finally_paths
                    .insert(name.clone(), self.finally_path.clone());
                let loop_path = self.loop_stack.iter().map(|l| l.id).collect();
                self.label_loop_paths.insert(name.clone(), loop_path);
                self.label_try_finally
                    .insert(name.clone(), self.try_finally_ids.clone());
                self.label_handler_paths
                    .insert(name.clone(), self.handler_regions.clone());
                // Forward gotos that may leave try/finally regions.
                let mut fin_jmps = Vec::new();
                let pending = std::mem::take(&mut self.jumps.pending_finally_gotos);
                for (label, save_at, jmp_at, regions) in pending {
                    if &label != name {
                        self.jumps
                            .pending_finally_gotos
                            .push((label, save_at, jmp_at, regions));
                        continue;
                    }
                    fin_jmps.push(jmp_at);
                    let levels = Self::regions_left(&regions, &self.try_finally_ids);
                    if levels == 0 {
                        // Stays inside its try/finally: a plain jump.
                        self.op_array.ops[save_at as usize].opcode = OpCode::Nop;
                        self.op_array.patch_jump(jmp_at, offset);
                    } else {
                        let lv = self.op_array.add_literal(Value::Long(levels as i64));
                        self.op_array.ops[save_at as usize].op1 = OperandType::JmpTarget(offset);
                        self.op_array.ops[save_at as usize].op2 = OperandType::Const(lv);
                    }
                }
                // Patch any pending gotos that reference this label
                if let Some(gotos) = self.jumps.pending_gotos.remove(name) {
                    for (goto_offset, _line) in gotos {
                        if !fin_jmps.contains(&goto_offset) {
                            self.op_array.patch_jump(goto_offset, offset);
                        }
                    }
                }
                Ok(())
            }
            StmtKind::Goto(name) => {
                self.goto_finally_paths.push((
                    name.clone(),
                    self.finally_path.clone(),
                    stmt.span.line,
                ));
                let loop_path = self.loop_stack.iter().map(|l| l.id).collect();
                self.goto_loop_paths
                    .push((name.clone(), loop_path, stmt.span.line));
                // The loops it leaves free their variables first
                // (zend_resolve_goto_label() keeps the frees of the loops the
                // label is in).
                match self.jumps.label_loop_depth.get(name).copied() {
                    Some(d) => {
                        self.emit_loop_frees(d, OperandType::Unused, stmt.span.line);
                    }
                    None => {
                        for (i, start, end) in
                            self.emit_loop_frees(0, OperandType::Unused, stmt.span.line)
                        {
                            self.jumps
                                .pending_goto_frees
                                .push((name.clone(), i, start, end));
                        }
                    }
                }
                // A goto leaving try/finally regions runs their finally
                // blocks first (like break/continue).
                let levels_known = self
                    .label_try_finally
                    .get(name)
                    .map(|l| Self::regions_left(&self.try_finally_ids, l));
                let backward = self.label_offsets.get(name).copied();
                if !self.try_finally_ids.is_empty()
                    && (backward.is_none() || levels_known.unwrap_or(0) > 0)
                {
                    let lv = self
                        .op_array
                        .add_literal(Value::Long(levels_known.unwrap_or(0) as i64));
                    let save_at = self.op_array.emit(Op {
                        opcode: OpCode::SaveJump,
                        op1: OperandType::JmpTarget(backward.unwrap_or(0)),
                        op2: OperandType::Const(lv),
                        result: OperandType::Unused,
                        line: stmt.span.line,
                    });
                    // Patched to the innermost finally block when it is compiled.
                    let jmp = self.op_array.emit(Op {
                        opcode: OpCode::Jmp,
                        op1: OperandType::JmpTarget(0),
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: stmt.span.line,
                    });
                    if backward.is_none() {
                        self.jumps.pending_finally_gotos.push((
                            name.clone(),
                            save_at,
                            jmp,
                            self.try_finally_ids.clone(),
                        ));
                        self.jumps
                            .pending_gotos
                            .entry(name.clone())
                            .or_default()
                            .push((jmp, stmt.span.line));
                    }
                } else if let Some(target) = backward {
                    // Label already seen - emit jump
                    let to = self
                        .label_handler_paths
                        .get(name)
                        .cloned()
                        .unwrap_or_default();
                    match Self::goto_handler_change(&self.handler_regions, &to) {
                        // (the try blocks it enters may not have their catch
                        // targets yet: a landing pad at the end pushes them)
                        Some((_, enter)) if !enter.is_empty() => {
                            let jmp = self.op_array.emit(Op {
                                opcode: OpCode::Jmp,
                                op1: OperandType::JmpTarget(target),
                                op2: OperandType::Unused,
                                result: OperandType::Unused,
                                line: stmt.span.line,
                            });
                            self.goto_handler_paths.push((
                                jmp,
                                name.clone(),
                                self.handler_regions.clone(),
                            ));
                        }
                        change => {
                            if let Some((pops, _)) = change {
                                self.emit_handler_change(pops, &[], stmt.span.line);
                            }
                            self.op_array.emit(Op {
                                opcode: OpCode::Jmp,
                                op1: OperandType::JmpTarget(target),
                                op2: OperandType::Unused,
                                result: OperandType::Unused,
                                line: stmt.span.line,
                            });
                        }
                    }
                } else {
                    // Label not yet seen - emit placeholder jump
                    let jmp = self.op_array.emit(Op {
                        opcode: OpCode::Jmp,
                        op1: OperandType::JmpTarget(0),
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: stmt.span.line,
                    });
                    self.goto_handler_paths
                        .push((jmp, name.clone(), self.handler_regions.clone()));
                    self.jumps
                        .pending_gotos
                        .entry(name.clone())
                        .or_default()
                        .push((jmp, stmt.span.line));
                }
                Ok(())
            }
        }
    }

    /// Compile list/array destructuring assignment from a source array operand.
    /// Recursively handles nested list() and [] patterns.
    /// Compile the object part of `isset($a->b->c)`: each intermediate
    /// non-nullsafe property fetch is guarded by PropertyIsset (so magic
    /// __isset runs before __get); failed checks jump to `patches`.
    fn compile_isset_prop_chain(
        &mut self,
        expr: &Expr,
        line: u32,
        patches: &mut Vec<u32>,
    ) -> CompileResult<OperandType> {
        if let ExprKind::PropertyAccess {
            object,
            property,
            nullsafe,
        } = &expr.kind
        {
            {
                let base = self.compile_isset_prop_chain(object, line, patches)?;
                let base = self.snapshot_cv(base, line);
                if *nullsafe {
                    // `?->` on null: the whole chain is null
                    let not_null = self.op_array.alloc_temp();
                    self.op_array.emit(Op {
                        opcode: OpCode::IssetCheck,
                        op1: base,
                        op2: OperandType::Unused,
                        result: OperandType::Tmp(not_null),
                        line,
                    });
                    let jmp = self.op_array.emit(Op {
                        opcode: OpCode::JmpZ,
                        op1: OperandType::Tmp(not_null),
                        op2: OperandType::JmpTarget(0),
                        result: OperandType::Unused,
                        line,
                    });
                    patches.push(jmp);
                }
                let prop_op = self.compile_property_name(property)?;
                let prop_op = self.snapshot_cv(prop_op, line);
                let isset_tmp = self.op_array.alloc_temp();
                self.op_array.emit(Op {
                    opcode: OpCode::PropertyIssetFetch,
                    op1: base,
                    op2: prop_op,
                    result: OperandType::Tmp(isset_tmp),
                    line,
                });
                let jmp = self.op_array.emit(Op {
                    opcode: OpCode::JmpZ,
                    op1: OperandType::Tmp(isset_tmp),
                    op2: OperandType::JmpTarget(0),
                    result: OperandType::Unused,
                    line,
                });
                patches.push(jmp);
                let get_tmp = self.op_array.alloc_temp();
                self.op_array.emit(Op {
                    opcode: OpCode::PropertyGet,
                    op1: base,
                    op2: prop_op,
                    result: OperandType::Tmp(get_tmp),
                    line,
                });
                return Ok(OperandType::Tmp(get_tmp));
            }
        }
        self.compile_expr(expr)
    }

    /// Mark the call whose result is `op` as fetched by reference: a by-ref
    /// function then returns the reference itself.
    fn mark_ref_call(&mut self, op: &OperandType) {
        if let OperandType::Tmp(_) = op {
            if let Some(call) = self
                .op_array
                .ops
                .iter_mut()
                .rev()
                .find(|o| o.opcode == OpCode::DoFCall && o.result == *op)
            {
                let lit = self.op_array.literals.len() as u32;
                self.op_array.literals.push(Value::True);
                call.op2 = OperandType::Const(lit);
            }
        }
    }

    /// Turn the StaticPropFetch producing `op` into a by-reference fetch.
    fn ref_static_prop(&mut self, op: &OperandType) {
        if let OperandType::Tmp(_) = op {
            if let Some(f) = self.op_array.ops.iter_mut().rev().find(|o| o.result == *op) {
                if f.opcode == OpCode::StaticPropFetch {
                    f.opcode = OpCode::StaticPropGetRef;
                }
            }
        }
    }

    fn is_call_expr(e: &Expr) -> bool {
        // (a pipe is a call: zend_is_call())
        matches!(
            e.kind,
            ExprKind::FunctionCall { .. }
                | ExprKind::MethodCall { .. }
                | ExprKind::StaticMethodCall { .. }
                | ExprKind::DynamicStaticMethodCall { .. }
                | ExprKind::Pipe { .. }
        )
    }

    /// Compile `expr` in a reference context (the operand of a by-ref
    /// return): variables, elements and properties yield a reference,
    /// calls keep a returned reference; anything else is a plain value.
    #[inline(never)]
    fn compile_ref_fetch(&mut self, expr: &Expr) -> CompileResult<OperandType> {
        let line = expr.span.line;
        match &expr.kind {
            ExprKind::Variable(name) if name != b"this" && name != b"GLOBALS" => {
                let cv = self.op_array.get_or_create_cv(name);
                self.op_array.emit(Op {
                    opcode: OpCode::MakeRef,
                    op1: OperandType::Cv(cv),
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line,
                });
                Ok(OperandType::Cv(cv))
            }
            ExprKind::ArrayAccess { array, index } => Ok(OperandType::Tmp(self.compile_dim_ref(
                array,
                index.as_deref(),
                line,
            )?)),
            ExprKind::PropertyAccess {
                object,
                property,
                nullsafe: false,
            } => Ok(OperandType::Tmp(
                self.compile_property_ref(object, property, line)?,
            )),
            ExprKind::StaticPropertyAccess { .. } => {
                let v = self.compile_expr(expr)?;
                self.ref_static_prop(&v);
                Ok(v)
            }
            _ if Self::is_call_expr(expr) => {
                let v = self.compile_expr(expr)?;
                self.mark_ref_call(&v);
                // Returning a by-value call result from a by-ref function.
                let msg_idx = self
                    .op_array
                    .add_literal(Value::String(PhpString::from_bytes(
                        b"Only variable references should be returned by reference",
                    )));
                let cond_idx = self.op_array.add_literal(Value::Long(1));
                self.op_array.emit(Op {
                    opcode: OpCode::EmitNotice,
                    op1: OperandType::Const(msg_idx),
                    op2: OperandType::Const(cond_idx),
                    result: OperandType::Unused,
                    line,
                });
                Ok(v)
            }
            _ => self.compile_expr(expr),
        }
    }

    /// Copy a plain variable operand into a tmp so that a magic method run
    /// between two uses of it (offsetExists/__isset, then offsetGet/__get)
    /// cannot change what the second use sees.
    /// Compile a dimension key inside isset()/empty()/`??`: only the
    /// dimension fetch is quiet, the key is read normally (and an undefined
    /// key variable warns). With `snapshot`, a CV key is copied while
    /// unsilenced.
    fn compile_key_unsilenced(&mut self, e: &Expr, snapshot: bool) -> CompileResult<OperandType> {
        if matches!(e.kind, ExprKind::Int(_) | ExprKind::String(_)) {
            return self.compile_expr(e);
        }
        let line = e.span.line;
        let bracket = |c: &mut Self, opcode| {
            c.op_array.emit(Op {
                opcode,
                op1: OperandType::Unused,
                op2: OperandType::Unused,
                result: OperandType::Unused,
                line,
            });
        };
        bracket(self, OpCode::ErrorRestore);
        let r = self.compile_expr(e).map(|op| {
            let before = self.op_array.ops.len();
            let op = if snapshot {
                self.snapshot_cv(op, line)
            } else {
                op
            };
            // The copy reads the key like QM_ASSIGN (an undefined CV warns).
            if self.op_array.ops.len() > before {
                if let Some(last) = self.op_array.ops.last_mut() {
                    if last.opcode == OpCode::QmAssign {
                        let lit = self.op_array.literals.len() as u32;
                        self.op_array.literals.push(Value::True);
                        last.op2 = OperandType::Const(lit);
                    }
                }
            }
            op
        });
        bracket(self, OpCode::ErrorSuppress);
        r
    }

    fn snapshot_cv(&mut self, op: OperandType, line: u32) -> OperandType {
        if let OperandType::Cv(i) = op {
            let name = self
                .op_array
                .cv_names
                .get(i as usize)
                .cloned()
                .unwrap_or_default();
            if name == b"this" || name == b"GLOBALS" || crate::vm::is_auto_global_name(&name) {
                return op;
            }
            let t = self.op_array.alloc_temp();
            self.op_array.emit(Op {
                opcode: OpCode::QmAssign,
                op1: op,
                op2: OperandType::Unused,
                result: OperandType::Tmp(t),
                line,
            });
            return OperandType::Tmp(t);
        }
        op
    }

    /// A list() / [] destructuring target that writes $GLOBALS itself.
    fn list_writes_globals(elems: &[ArrayElement]) -> bool {
        elems.iter().any(|e| match &e.value.kind {
            ExprKind::Variable(n) => n == b"GLOBALS",
            ExprKind::Array(sub) => Self::list_writes_globals(sub),
            _ => false,
        })
    }

    /// The value of a `... = &v` expression: the referenced value, read
    /// after the binding (so destructors run by it are observed).
    fn ref_assign_result(&mut self, op: OperandType, discarded: bool, line: u32) -> OperandType {
        if discarded || !matches!(op, OperandType::Tmp(_)) {
            return op;
        }
        let t = self.op_array.alloc_temp();
        self.op_array.emit(Op {
            opcode: OpCode::QmAssign,
            op1: op,
            op2: OperandType::Unused,
            result: OperandType::Tmp(t),
            line,
        });
        OperandType::Tmp(t)
    }

    /// Whether a destructuring target list assigns the variable `name`.
    fn list_targets_var(elems: &[ArrayElement], name: &[u8]) -> bool {
        elems.iter().any(|e| match &e.value.kind {
            ExprKind::Variable(n) => n == name,
            ExprKind::Array(sub) => Self::list_targets_var(sub, name),
            _ => false,
        })
    }

    /// The number of by-reference elements of a destructuring target.
    fn list_ref_count(elems: &[ArrayElement]) -> usize {
        elems
            .iter()
            .map(|e| match &e.value.kind {
                ExprKind::Array(sub) => Self::list_ref_count(sub),
                _ => e.by_ref as usize,
            })
            .sum()
    }

    fn list_has_ref(elems: &[ArrayElement]) -> bool {
        elems.iter().any(|e| {
            e.by_ref || matches!(&e.value.kind, ExprKind::Array(sub) if Self::list_has_ref(sub))
        })
    }

    /// Destructuring that contains `&` elements: each element is bound
    /// directly against `src[key]` (which must be a writable place).
    fn compile_list_destructure_ref(
        &mut self,
        elems: &[ArrayElement],
        src: &Expr,
        line: u32,
    ) -> CompileResult<()> {
        if elems.is_empty()
            || elems
                .iter()
                .all(|e| matches!(&e.value.kind, ExprKind::Null))
        {
            return Err(CompileError {
                message: "Cannot use empty list".into(),
                line,
            });
        }
        let has_keyed = elems.iter().any(|e| e.key.is_some());
        let has_unkeyed = elems
            .iter()
            .any(|e| e.key.is_none() && !matches!(&e.value.kind, ExprKind::Null));
        if has_keyed && has_unkeyed {
            return Err(CompileError {
                message: "Cannot mix keyed and unkeyed array entries in assignments".into(),
                line,
            });
        }
        for (i, elem) in elems.iter().enumerate() {
            if matches!(&elem.value.kind, ExprKind::Null) {
                continue;
            }
            let span = elem.value.span;
            let key = elem.key.clone().unwrap_or(Expr {
                kind: ExprKind::Int(i as i64),
                span,
            });
            let sub = Expr {
                kind: ExprKind::ArrayAccess {
                    array: Box::new(src.clone()),
                    index: Some(Box::new(key)),
                },
                span,
            };
            let e = match &elem.value.kind {
                ExprKind::Array(nested) => {
                    self.compile_list_destructure_ref(nested, &sub, line)?;
                    continue;
                }
                _ if elem.by_ref => Expr {
                    kind: ExprKind::AssignRef {
                        target: Box::new(elem.value.clone()),
                        value: Box::new(sub),
                    },
                    span,
                },
                _ => Expr {
                    kind: ExprKind::Assign {
                        target: Box::new(elem.value.clone()),
                        value: Box::new(sub),
                    },
                    span,
                },
            };
            let t0 = self.op_array.temp_count;
            self.compile_expr(&e)?;
            let _ = t0;
        }
        Ok(())
    }

    fn compile_list_destructure(
        &mut self,
        elems: &[ArrayElement],
        arr_op: OperandType,
        line: u32,
    ) -> CompileResult<()> {
        // Spread operator is not allowed in destructuring assignments
        for elem in elems.iter() {
            if elem.unpack {
                return Err(CompileError {
                    message: "Spread operator is not supported in assignments".into(),
                    line,
                });
            }
        }

        // Check for empty list (all elements are empty/null placeholders)
        let all_empty = elems
            .iter()
            .all(|e| matches!(&e.value.kind, ExprKind::Null));
        if elems.is_empty() || all_empty {
            return Err(CompileError {
                message: "Cannot use empty list".into(),
                line,
            });
        }

        // Check for mixed keyed and unkeyed elements
        let has_keyed = elems.iter().any(|e| e.key.is_some());
        let has_unkeyed = elems
            .iter()
            .any(|e| e.key.is_none() && !matches!(&e.value.kind, ExprKind::Null));
        if has_keyed && has_unkeyed {
            return Err(CompileError {
                message: "Cannot mix keyed and unkeyed array entries in assignments".into(),
                line,
            });
        }

        // Check for empty elements in keyed list
        if has_keyed {
            for elem in elems.iter() {
                if elem.key.is_none() && matches!(&elem.value.kind, ExprKind::Null) {
                    return Err(CompileError {
                        message: "Cannot use empty array entries in keyed array assignment".into(),
                        line,
                    });
                }
            }
        }

        for (i, elem) in elems.iter().enumerate() {
            let idx_op = if let Some(key_expr) = &elem.key {
                self.compile_expr(key_expr)?
            } else {
                let idx_const = self.op_array.add_literal(Value::Long(i as i64));
                OperandType::Const(idx_const)
            };

            if let ExprKind::Variable(name) = &elem.value.kind {
                let cv = self.op_array.get_or_create_cv(name);
                let tmp = self.op_array.alloc_temp();
                self.op_array.emit(Op {
                    opcode: OpCode::ListGet,
                    op1: arr_op,
                    op2: idx_op,
                    result: OperandType::Tmp(tmp),
                    line,
                });
                self.op_array.emit(Op {
                    opcode: OpCode::Assign,
                    op1: OperandType::Cv(cv),
                    op2: OperandType::Tmp(tmp),
                    result: OperandType::Unused,
                    line,
                });
            } else {
                // Check for nested destructuring
                let nested_elems = match &elem.value.kind {
                    ExprKind::Array(elems) => Some(elems.clone()),
                    ExprKind::FunctionCall { name, args } if matches!(&name.kind, ExprKind::Identifier(n) if n.eq_ignore_ascii_case(b"list")) => {
                        Some(
                            args.iter()
                                .map(|a| ArrayElement {
                                    key: a.name.as_ref().map(|n| Expr {
                                        kind: ExprKind::String(n.clone()),
                                        span: a.value.span,
                                    }),
                                    value: a.value.clone(),
                                    unpack: false,
                                    by_ref: false,
                                })
                                .collect(),
                        )
                    }
                    ExprKind::Null => None, // Skip empty slots
                    _ => None,
                };
                if let Some(nested) = nested_elems {
                    let sub_arr = self.op_array.alloc_temp();
                    self.op_array.emit(Op {
                        opcode: OpCode::ListGet,
                        op1: arr_op,
                        op2: idx_op,
                        result: OperandType::Tmp(sub_arr),
                        line,
                    });
                    self.compile_list_destructure(&nested, OperandType::Tmp(sub_arr), line)?;
                } else if !matches!(&elem.value.kind, ExprKind::Null) {
                    // zend_verify_list_assign_target() and
                    // zend_ensure_writable_variable().
                    let msg = match &elem.value.kind {
                        ExprKind::FunctionCall { .. } | ExprKind::Pipe { .. } => {
                            Some("Can't use function return value in write context")
                        }
                        ExprKind::MethodCall { .. }
                        | ExprKind::StaticMethodCall { .. }
                        | ExprKind::DynamicStaticMethodCall { .. } => {
                            Some("Can't use method return value in write context")
                        }
                        ExprKind::ArrayAccess { .. }
                        | ExprKind::PropertyAccess { .. }
                        | ExprKind::StaticPropertyAccess { .. }
                        | ExprKind::DynamicStaticPropertyAccess { .. }
                        | ExprKind::DynamicVariable(_)
                        | ExprKind::Variable(_) => None,
                        _ => Some("Assignments can only happen to writable values"),
                    };
                    if let Some(msg) = msg {
                        return Err(CompileError {
                            message: msg.into(),
                            line,
                        });
                    }
                    // Handle complex lvalues: $arr[0], $obj->prop, etc.
                    let tmp = self.op_array.alloc_temp();
                    self.op_array.emit(Op {
                        opcode: OpCode::ListGet,
                        op1: arr_op,
                        op2: idx_op,
                        result: OperandType::Tmp(tmp),
                        line,
                    });
                    // Compile the assignment to the complex target
                    self.compile_assign_tmp_to_target(&elem.value, tmp, line)?;
                }
            }
        }
        Ok(())
    }

    /// Assign the value in `tmp` to a non-variable target expression
    /// (`$a[k]`, `$o->p`, `C::$p`, `$$v`): list elements, foreach targets.
    fn compile_assign_tmp_to_target(
        &mut self,
        target: &Expr,
        tmp: u32,
        line: u32,
    ) -> CompileResult<()> {
        match &target.kind {
            ExprKind::ArrayAccess { array, index } => {
                // $arr[idx] = value or $arr[] = value
                let arr_target = self.compile_dim_write_base(array)?;
                if let Some(idx_expr) = index {
                    let key_op = self.compile_expr(idx_expr)?;
                    self.op_array.emit(Op {
                        opcode: OpCode::ArraySet,
                        op1: arr_target,
                        op2: OperandType::Tmp(tmp),
                        result: key_op,
                        line,
                    });
                } else {
                    // $arr[] = value (append)
                    self.op_array.emit(Op {
                        opcode: OpCode::ArrayAppend,
                        op1: arr_target,
                        op2: OperandType::Tmp(tmp),
                        result: OperandType::Unused,
                        line,
                    });
                }
            }
            ExprKind::PropertyAccess {
                object, property, ..
            } => {
                // $obj->prop = value
                let obj_op = self.compile_expr(object)?;
                let prop_op = match &property.kind {
                    ExprKind::Identifier(name) => {
                        let name_idx = self
                            .op_array
                            .add_literal(Value::String(PhpString::from_vec(name.clone())));
                        OperandType::Const(name_idx)
                    }
                    _ => self.compile_expr(property)?,
                };
                self.op_array.emit(Op {
                    opcode: OpCode::PropertySet,
                    op1: obj_op,
                    op2: OperandType::Tmp(tmp),
                    result: prop_op,
                    line,
                });
            }
            ExprKind::StaticPropertyAccess { .. }
            | ExprKind::DynamicStaticPropertyAccess { .. } => {
                // [C::$p] = ... destructuring target
                let (class_op, name_op) = self.compile_static_prop_operands(target)?;
                self.op_array.emit(Op {
                    opcode: OpCode::StaticPropSet,
                    op1: class_op,
                    op2: OperandType::Tmp(tmp),
                    result: name_op,
                    line,
                });
            }
            ExprKind::DynamicVariable(inner) => {
                // $$var = value
                let name_op = self.compile_expr(inner)?;
                self.op_array.emit(Op {
                    opcode: OpCode::VarVarSet,
                    op1: name_op,
                    op2: OperandType::Tmp(tmp),
                    result: OperandType::Unused,
                    line,
                });
            }
            _ => {
                // Unsupported target - silently skip for now
            }
        }
        Ok(())
    }

    /// Compile an expression, returning the operand that holds the result
    /// Resolve the class part of a static-property access to an operand: a
    /// `Const` literal for a named class (with self/parent resolved and `static`
    /// left for late static binding), or a compiled operand for a dynamic class
    /// expression. Mirrors the resolution used by StaticPropGet/StaticPropSet.
    /// PHP's zend_ensure_valid_class_fetch_type: inside a free function the
    /// (empty) class scope is known at compile time, so self/parent/static
    /// are rejected.
    /// `X::class` for a named class (zend_compile_class_name): self/parent
    /// resolve at compile time only when the scope is known.
    #[inline(never)]
    fn compile_class_name_const(
        &mut self,
        class_name: &[u8],
        class_line: u32,
        line: u32,
    ) -> CompileResult<OperandType> {
        let is_self = class_name.eq_ignore_ascii_case(b"self");
        let is_parent = class_name.eq_ignore_ascii_case(b"parent");
        let is_static = class_name.eq_ignore_ascii_case(b"static");
        // zend_try_compile_const_expr_resolve_class_name():
        // self/parent resolve at compile time only when the
        // scope is known; otherwise ZEND_FETCH_CLASS_NAME runs.
        let known = self.is_scope_known() && self.current_class.is_some();
        if is_parent && known && self.current_parent_class.is_none() {
            return Err(CompileError {
                message: "Cannot use \"parent\" when current class scope has no parent".into(),
                line: class_line,
            });
        }
        let runtime = is_static
            || (is_parent && !known)
            || (is_self
                && (self.current_class.is_none() || (self.in_const_expr && self.is_in_trait)));
        if runtime {
            let mut kind = if self.in_const_expr && !is_static {
                b"const:".to_vec()
            } else {
                Vec::new()
            };
            kind.extend_from_slice(&class_name.to_ascii_lowercase());
            let kind_idx = self
                .op_array
                .add_literal(Value::String(PhpString::from_vec(kind)));
            let tmp = self.op_array.alloc_temp();
            self.op_array.emit(Op {
                opcode: OpCode::GetClassName,
                op1: OperandType::Unused,
                op2: OperandType::Const(kind_idx),
                result: OperandType::Tmp(tmp),
                line,
            });
            return Ok(OperandType::Tmp(tmp));
        }
        if is_parent {
            let parent = self.current_parent_class.clone().unwrap_or_default();
            let idx = self
                .op_array
                .add_literal(Value::String(PhpString::from_vec(parent)));
            return Ok(OperandType::Const(idx));
        }
        let resolved = if is_self {
            self.current_class.clone().unwrap_or_default()
        } else {
            class_name.to_vec()
        };
        let idx = self
            .op_array
            .add_literal(Value::String(PhpString::from_vec(resolved)));
        // Track self::class for trait patching
        if is_self && self.is_in_trait {
            self.op_array.class_const_literals.push(idx);
        }
        Ok(OperandType::Const(idx))
    }

    /// zend_is_scope_known(): whether self/parent are fixed at compile time
    /// (not in closures, which can be rebound, nor in file-level code, which
    /// inherits the including scope, nor in traits).
    fn is_scope_known(&self) -> bool {
        let n = &self.op_array.name;
        if n.starts_with(b"__closure_") || n.starts_with(b"__arrow_") {
            return false;
        }
        if self.current_class.is_none() {
            return self.in_free_function;
        }
        !self.is_in_trait
    }

    fn check_class_ref_scope(&self, name: &[u8], line: u32) -> CompileResult<()> {
        if self.in_free_function && self.current_class.is_none() {
            for kw in ["self", "parent", "static"] {
                if name.eq_ignore_ascii_case(kw.as_bytes()) {
                    return Err(CompileError {
                        message: format!("Cannot use \"{}\" when no class scope is active", kw),
                        line,
                    });
                }
            }
        }
        Ok(())
    }

    /// In a by-reference function, returning anything other than a variable
    /// (or nothing) raises "Only variable references should be returned by
    /// reference" at runtime. Call results are checked at runtime by PHP and
    /// are left alone here.
    fn emit_by_ref_return_notice(&mut self, value: Option<&Expr>, line: u32) {
        if !self.op_array.returns_by_ref || self.op_array.is_generator {
            return;
        }
        // The return type check runs first in PHP and may throw; since we
        // emit the notice before the Return op, only do so when there is no
        // (non-void) return type to verify.
        if let Some(rt) = &self.op_array.return_type {
            if !matches!(rt, ParamType::Simple(n) if n.eq_ignore_ascii_case(b"void")) {
                return;
            }
        }
        let is_var = match value {
            None => false,
            Some(e) => matches!(
                e.kind,
                ExprKind::Variable(_)
                    | ExprKind::PropertyAccess { .. }
                    | ExprKind::StaticPropertyAccess { .. }
                    | ExprKind::ArrayAccess { .. }
                    | ExprKind::FunctionCall { .. }
                    | ExprKind::MethodCall { .. }
                    | ExprKind::StaticMethodCall { .. }
                    | ExprKind::Pipe { .. }
                    | ExprKind::DynamicStaticPropertyAccess { .. }
                    | ExprKind::DynamicVariable(_)
                    | ExprKind::Assign { .. }
            ),
        };
        if is_var {
            return;
        }
        let msg_idx = self
            .op_array
            .add_literal(Value::String(PhpString::from_bytes(
                b"Only variable references should be returned by reference",
            )));
        self.op_array.emit(Op {
            opcode: OpCode::EmitNotice,
            op1: OperandType::Const(msg_idx),
            op2: OperandType::Unused,
            result: OperandType::Unused,
            line,
        });
    }

    /// `$x = &f()`: PHP raises "Only variables should be assigned by
    /// reference" when the callee does not return by reference.
    #[inline(never)]
    fn emit_assign_ref_call_notice(&mut self, value: &Expr, line: u32) {
        if !matches!(
            value.kind,
            ExprKind::FunctionCall { .. }
                | ExprKind::MethodCall { .. }
                | ExprKind::StaticMethodCall { .. }
        ) {
            return;
        }
        let msg_idx = self
            .op_array
            .add_literal(Value::String(PhpString::from_bytes(
                b"Only variables should be assigned by reference",
            )));
        let cond_idx = self.op_array.add_literal(Value::Long(1));
        self.op_array.emit(Op {
            opcode: OpCode::EmitNotice,
            op1: OperandType::Const(msg_idx),
            op2: OperandType::Const(cond_idx),
            result: OperandType::Unused,
            line,
        });
    }

    /// Emit PropertyGetRef for `$obj->prop` in a reference context and return
    /// the tmp holding the Reference.
    fn compile_property_ref(
        &mut self,
        object: &Expr,
        property: &Expr,
        line: u32,
    ) -> CompileResult<u32> {
        let obj = self.compile_expr(object)?;
        let name = self.compile_property_name(property)?;
        let ref_tmp = self.op_array.alloc_temp();
        self.op_array.emit(Op {
            opcode: OpCode::PropertyGetRef,
            op1: obj,
            op2: name,
            result: OperandType::Tmp(ref_tmp),
            line,
        });
        Ok(ref_tmp)
    }

    /// Compile the object operand of a property write (`<obj>->p = v`,
    /// `<obj>->p op= v`, ...): a property or element container is fetched for
    /// writing (FETCH_OBJ_W / FETCH_DIM_W), so the write reaches it.
    fn compile_obj_write_base(&mut self, object: &Expr) -> CompileResult<OperandType> {
        self.compile_obj_write_base_mode(object, crate::fetch_w::DimFetch::W)
    }

    /// compile_obj_write_base() for a write context: W (assignments), Rw
    /// (compound assignments / increments), Unset (unset()).
    fn compile_obj_write_base_mode(
        &mut self,
        object: &Expr,
        mode: crate::fetch_w::DimFetch,
    ) -> CompileResult<OperandType> {
        use crate::fetch_w::DimFetch;
        match &object.kind {
            ExprKind::PropertyAccess {
                object: inner,
                property,
                nullsafe: false,
            } => {
                let obj = self.compile_obj_write_base_mode(inner, mode)?;
                let name = self.compile_property_name(property)?;
                let tmp = self.op_array.alloc_temp();
                self.op_array.emit(Op {
                    opcode: match mode {
                        DimFetch::Unset => OpCode::PropertyGetWUnset,
                        DimFetch::Rw => OpCode::PropertyGetWObjRW,
                        _ => OpCode::PropertyGetWObj,
                    },
                    op1: obj,
                    op2: name,
                    result: OperandType::Tmp(tmp),
                    line: object.span.line,
                });
                Ok(OperandType::Tmp(tmp))
            }
            // `$a[]->p = v`: the appended element is fetched for an object
            // write (it is null: the property write then fails).
            ExprKind::ArrayAccess { index: None, .. } => {
                self.compile_dim_write_base_mode(object, DimFetch::Obj)
            }
            ExprKind::ArrayAccess {
                array,
                index: Some(index),
            } => {
                let container = self.compile_dim_write_base_mode(
                    array,
                    match mode {
                        DimFetch::Unset => DimFetch::Unset,
                        DimFetch::Rw => DimFetch::Rw,
                        _ => DimFetch::W,
                    },
                )?;
                let key = self.compile_expr(index)?;
                let tmp = self.op_array.alloc_temp();
                self.op_array.emit(Op {
                    opcode: match mode {
                        DimFetch::Unset => OpCode::ArrayGetWUnset,
                        DimFetch::Rw => OpCode::ArrayGetWObjRW,
                        _ => OpCode::ArrayGetWObj,
                    },
                    op1: container,
                    op2: key,
                    result: OperandType::Tmp(tmp),
                    line: object.span.line,
                });
                Ok(OperandType::Tmp(tmp))
            }
            ExprKind::DynamicVariable(inner) => {
                self.compile_dynvar_fetch(inner, Self::dynvar_mode(mode), object.span.line)
            }
            _ => self.compile_expr(object),
        }
    }

    /// The VarVarFetch mode of a write fetch.
    fn dynvar_mode(mode: crate::fetch_w::DimFetch) -> i64 {
        use crate::fetch_w::DimFetch;
        match mode {
            DimFetch::Rw => 1,
            DimFetch::Unset => 2,
            DimFetch::W | DimFetch::Obj | DimFetch::ObjRw => 0,
        }
    }

    /// `&$array[index]` (`index == None` is `&$array[]`): fetch the container
    /// for writing and get (creating) the element's reference into a tmp.
    #[inline(never)]
    fn compile_dim_ref(
        &mut self,
        array: &Expr,
        index: Option<&Expr>,
        line: u32,
    ) -> CompileResult<u32> {
        let arr = self.compile_dim_write_base(array)?;
        let idx = match index {
            Some(i) => self.compile_expr(i)?,
            None => OperandType::Unused,
        };
        let t = self.op_array.alloc_temp();
        self.op_array.emit(Op {
            opcode: OpCode::ArrayGetRef,
            op1: arr,
            op2: idx,
            result: OperandType::Tmp(t),
            line,
        });
        Ok(t)
    }

    /// Compile `expr` for an isset/empty check (BP_VAR_IS): a property is
    /// fetched with PropertyGetIs so __isset() gates __get().
    fn compile_is_fetch(&mut self, expr: &Expr) -> CompileResult<OperandType> {
        if let ExprKind::PropertyAccess {
            object,
            property,
            nullsafe: false,
        } = &expr.kind
        {
            let obj = self.compile_expr(object)?;
            let name = self.compile_property_name(property)?;
            let tmp = self.op_array.alloc_temp();
            self.op_array.emit(Op {
                opcode: OpCode::PropertyGetIs,
                op1: obj,
                op2: name,
                result: OperandType::Tmp(tmp),
                line: expr.span.line,
            });
            return Ok(OperandType::Tmp(tmp));
        }
        self.compile_expr(expr)
    }

    /// `<target> = v` / `<target> op= v` whose target keys are computed
    /// first (kept out of compile_expr to keep its stack frame small).
    ///
    /// Two mechanisms evaluate parts of an assignment target once, ahead of
    /// the code that uses them:
    ///
    /// - this one (keys before value): the target is rewritten into an
    ///   equivalent lvalue whose computed keys / property names / bases are
    ///   reserved `\0memoN` variables aliased (`tmp_aliases`) to temporaries
    ///   evaluated now, then the rewritten assignment is compiled once. A key
    ///   that is itself a fetch (`$a[$b[0]] = v`) is evaluated by value, and
    ///   a key yielding a variable is copied, since the value expression may
    ///   change it before the write.
    /// - `??=` (compile_assign_coalesce, zend_compile_memoized_expr): the
    ///   same target subtree is compiled twice, for isset and for write,
    ///   with operands of its sub-expressions recorded by AST node address
    ///   in the first pass and reused in the second. The fetch path itself
    ///   (variables, dims, properties) is compiled again in the second pass
    ///   because its fetch mode differs.
    ///
    /// They are kept separate: the `??=` scheme needs the target compiled
    /// twice from the very same nodes and deliberately does not memoize
    /// dim/property nodes, while keys-before-value must snapshot such nodes
    /// when they appear as keys; merging them would need a walker that tells
    /// key positions from path positions and per-mode copy rules, for no
    /// behavioural gain.
    #[inline(never)]
    fn compile_assign_memoized(
        &mut self,
        expr: &Expr,
        target: &Expr,
        value: &Expr,
        op: Option<BinaryOp>,
    ) -> CompileResult<OperandType> {
        let saved = self.tmp_aliases.len();
        let memo = Box::new(self.memoize_lvalue(target)?);
        let value = Box::new(value.clone());
        let kind = match op {
            None => ExprKind::Assign {
                target: memo,
                value,
            },
            Some(op) => ExprKind::CompoundAssign {
                op,
                target: memo,
                value,
            },
        };
        let r = self.compile_expr(&Expr {
            span: expr.span,
            kind,
        });
        self.tmp_aliases.truncate(saved);
        r
    }

    /// The key of `$a[k] op= v` / `$a[k]++` (FETCH_DIM_RW reads it once):
    /// literals the conversion warns about are put in a temporary, so that
    /// the read leaves the converted key there for the write-back.
    fn dim_rw_key(&mut self, k: OperandType, line: u32) -> OperandType {
        // (A variable key is read once by the VM: see Vm::dim_rw_key.)
        let copy = match k {
            OperandType::Const(i) => matches!(
                self.op_array.literals.get(i as usize),
                Some(Value::Null | Value::Double(_) | Value::True | Value::False)
            ),
            _ => false,
        };
        if !copy {
            return k;
        }
        let flag = self.op_array.add_literal(Value::True);
        let t = self.op_array.alloc_temp();
        self.op_array.emit(Op {
            opcode: OpCode::QmAssign,
            op1: k,
            op2: OperandType::Const(flag),
            result: OperandType::Tmp(t),
            line,
        });
        OperandType::Tmp(t)
    }

    /// A non-Unused op2 marking an opcode that reads its op1 quietly (no
    /// "Undefined variable" warning): BooleanNot of empty().
    fn quiet_operand_flag(&mut self) -> OperandType {
        OperandType::Const(self.op_array.add_literal(Value::True))
    }

    /// Whether an assignment target has keys / property names that must be
    /// evaluated before the assigned value (anything but literals and plain
    /// variables, which PHP reads when the target is fetched).
    fn lvalue_needs_memo(e: &Expr) -> bool {
        let simple = |k: &Expr| {
            matches!(
                k.kind,
                ExprKind::Int(_)
                    | ExprKind::Float(_)
                    | ExprKind::String(_)
                    | ExprKind::True
                    | ExprKind::False
                    | ExprKind::Null
                    | ExprKind::Variable(_)
                    | ExprKind::Identifier(_)
            )
        };
        match &e.kind {
            ExprKind::ArrayAccess { array, index } => {
                index.as_deref().map(|i| !simple(i)).unwrap_or(false)
                    || Self::lvalue_needs_memo(array)
            }
            ExprKind::PropertyAccess {
                object, property, ..
            } => {
                !simple(property)
                    || matches!(
                        object.kind,
                        ExprKind::ArrayAccess { .. } | ExprKind::PropertyAccess { .. }
                    ) && Self::lvalue_needs_memo(object)
            }
            _ => false,
        }
    }

    /// Rewrite an lvalue so that its keys, dynamic property names and
    /// non-variable bases are computed now (into aliased temporaries).
    fn memoize_lvalue(&mut self, e: &Expr) -> CompileResult<Expr> {
        Ok(match &e.kind {
            ExprKind::Variable(_) | ExprKind::StaticPropertyAccess { .. } => e.clone(),
            ExprKind::DynamicStaticPropertyAccess { class, property } => Expr {
                span: e.span,
                kind: ExprKind::DynamicStaticPropertyAccess {
                    class: class.clone(),
                    property: Box::new(self.memoize_operand(property)?),
                },
            },
            ExprKind::ArrayAccess { array, index } => {
                let array = self.memoize_lvalue(array)?;
                let index = match index {
                    Some(i) => Some(Box::new(self.memoize_operand(i)?)),
                    None => None,
                };
                Expr {
                    span: e.span,
                    kind: ExprKind::ArrayAccess {
                        array: Box::new(array),
                        index,
                    },
                }
            }
            ExprKind::PropertyAccess {
                object,
                property,
                nullsafe,
            } => {
                let object = self.memoize_lvalue(object)?;
                let property = match &property.kind {
                    ExprKind::Identifier(_) => (**property).clone(),
                    _ => self.memoize_operand(property)?,
                };
                Expr {
                    span: e.span,
                    kind: ExprKind::PropertyAccess {
                        object: Box::new(object),
                        property: Box::new(property),
                        nullsafe: *nullsafe,
                    },
                }
            }
            // The variable named is fetched when written (the name, a plain
            // variable, is read then).
            ExprKind::DynamicVariable(inner) => Expr {
                span: e.span,
                kind: ExprKind::DynamicVariable(Box::new(self.memoize_operand(inner)?)),
            },
            _ => self.memoize_operand(e)?,
        })
    }

    /// Evaluate `e` once into a temporary and return a reserved variable
    /// standing for it (literals and plain variables are kept as is).
    fn memoize_operand(&mut self, e: &Expr) -> CompileResult<Expr> {
        if matches!(
            e.kind,
            ExprKind::Int(_)
                | ExprKind::Float(_)
                | ExprKind::String(_)
                | ExprKind::True
                | ExprKind::False
                | ExprKind::Null
                | ExprKind::Variable(_)
                | ExprKind::Identifier(_)
        ) {
            return Ok(e.clone());
        }
        let v = self.compile_expr(e)?;
        // A fresh temporary already holds the value; anything else (a
        // variable written by the expression, ...) is copied now.
        let held = match v {
            OperandType::Tmp(_) | OperandType::Const(_) => v,
            other => {
                let t = self.op_array.alloc_temp();
                self.op_array.emit(Op {
                    opcode: OpCode::Assign,
                    op1: OperandType::Tmp(t),
                    op2: other,
                    result: OperandType::Unused,
                    line: e.span.line,
                });
                OperandType::Tmp(t)
            }
        };
        let mut name = b"\0memo".to_vec();
        name.extend_from_slice(self.tmp_aliases.len().to_string().as_bytes());
        self.tmp_aliases.push((name.clone(), held));
        Ok(Expr {
            span: e.span,
            kind: ExprKind::Variable(name),
        })
    }

    /// Compile the container of a dimension write. A property container
    /// (`$obj->p[...] = v`) is fetched for writing (FETCH_OBJ_W semantics).
    fn compile_dim_write_base(&mut self, array: &Expr) -> CompileResult<OperandType> {
        self.compile_dim_write_base_mode(array, crate::fetch_w::DimFetch::W)
    }

    /// Compile the container of a dimension write fetched for `mode`
    /// (FETCH_*_W for assignments, FETCH_*_RW for compound assignments and
    /// increments, FETCH_*_UNSET for unset()).
    #[inline(never)]
    fn compile_dim_write_base_mode(
        &mut self,
        array: &Expr,
        mode: crate::fetch_w::DimFetch,
    ) -> CompileResult<OperandType> {
        use crate::fetch_w::DimFetch;
        if matches!(
            array.kind,
            ExprKind::StaticPropertyAccess { .. } | ExprKind::DynamicStaticPropertyAccess { .. }
        ) {
            let tmp = self.emit_static_prop_fetch(OpCode::StaticPropFetchW, array)?;
            return Ok(OperandType::Tmp(tmp));
        }
        if let ExprKind::PropertyAccess {
            object,
            property,
            nullsafe: false,
        } = &array.kind
        {
            let obj = self.compile_obj_write_base_mode(
                object,
                if mode == DimFetch::Unset {
                    DimFetch::Unset
                } else {
                    DimFetch::W
                },
            )?;
            let name = self.compile_property_name(property)?;
            let tmp = self.op_array.alloc_temp();
            self.op_array.emit(Op {
                opcode: match mode {
                    DimFetch::W => OpCode::PropertyGetW,
                    DimFetch::Rw => OpCode::PropertyGetWRW,
                    DimFetch::Unset => OpCode::PropertyGetWUnset,
                    DimFetch::Obj | DimFetch::ObjRw => OpCode::PropertyGetWObj,
                },
                op1: obj,
                op2: name,
                result: OperandType::Tmp(tmp),
                line: array.span.line,
            });
            return Ok(OperandType::Tmp(tmp));
        }
        if let ExprKind::ArrayAccess {
            array: inner,
            index,
        } = &array.kind
        {
            // Nested dimension write: fetch the intermediate element for writing.
            // (the containers of an object write's element are arrays)
            let inner_mode = match mode {
                DimFetch::Obj => DimFetch::W,
                DimFetch::ObjRw => DimFetch::Rw,
                m => m,
            };
            let container = self.compile_dim_write_base_mode(inner, inner_mode)?;
            let key = match index {
                Some(idx) => self.compile_expr(idx)?,
                None => OperandType::Unused,
            };
            let tmp = self.op_array.alloc_temp();
            self.op_array.emit(Op {
                opcode: match mode {
                    DimFetch::W => OpCode::ArrayGetW,
                    DimFetch::Rw => OpCode::ArrayGetWRW,
                    DimFetch::Unset => OpCode::ArrayGetWUnset,
                    DimFetch::Obj => OpCode::ArrayGetWObj,
                    DimFetch::ObjRw => OpCode::ArrayGetWObjRW,
                },
                op1: container,
                op2: key,
                result: OperandType::Tmp(tmp),
                line: array.span.line,
            });
            return Ok(OperandType::Tmp(tmp));
        }
        if let ExprKind::DynamicVariable(inner) = &array.kind {
            return self.compile_dynvar_fetch(inner, Self::dynvar_mode(mode), array.span.line);
        }
        if Self::is_call_expr(array) {
            // `f()[k] = v`: a by-value result is a temporary of its own (the
            // write separates it from the array it came from); a returned
            // reference is written through.
            let v = self.compile_expr(array)?;
            let marker = self.op_array.add_literal(Value::Long(2));
            let t = self.op_array.alloc_temp();
            self.op_array.emit(Op {
                opcode: OpCode::QmAssign,
                op1: v,
                op2: OperandType::Const(marker),
                result: OperandType::Tmp(t),
                line: array.span.line,
            });
            return Ok(OperandType::Tmp(t));
        }
        self.compile_expr(array)
    }

    /// `\true` / `\false` / `\null`: the special constants.
    #[inline(never)]
    fn fq_special_constant(&mut self, name: &[u8]) -> Option<OperandType> {
        let v = match name.strip_prefix(b"\\")?.to_ascii_lowercase().as_slice() {
            b"true" => Value::True,
            b"false" => Value::False,
            b"null" => Value::Null,
            _ => return None,
        };
        Some(OperandType::Const(self.op_array.add_literal(v)))
    }

    /// ZEND_YIELD of a call result in a by-ref generator: a returned
    /// reference is yielded, a value gets the notice. (Out of line: see
    /// compile_append_incdec.)
    #[inline(never)]
    fn compile_yield_ref_call(&mut self, val_expr: &Expr, line: u32) -> CompileResult<OperandType> {
        let v = self.compile_expr(val_expr)?;
        self.mark_ref_call(&v);
        let msg_idx = self
            .op_array
            .add_literal(Value::String(PhpString::from_bytes(
                b"Only variable references should be yielded by reference",
            )));
        let cond_idx = self.op_array.add_literal(Value::Long(1));
        self.op_array.emit(Op {
            opcode: OpCode::EmitNotice,
            op1: OperandType::Const(msg_idx),
            op2: OperandType::Const(cond_idx),
            result: OperandType::Unused,
            line,
        });
        Ok(v)
    }

    /// The opcode of a plain (not short-circuiting) binary operator.
    fn plain_binop_opcode(op: &BinaryOp) -> Option<OpCode> {
        Some(match op {
            BinaryOp::Add => OpCode::Add,
            BinaryOp::Sub => OpCode::Sub,
            BinaryOp::Mul => OpCode::Mul,
            BinaryOp::Div => OpCode::Div,
            BinaryOp::Mod => OpCode::Mod,
            BinaryOp::Pow => OpCode::Pow,
            BinaryOp::Concat => OpCode::Concat,
            BinaryOp::BitwiseAnd => OpCode::BitwiseAnd,
            BinaryOp::BitwiseOr => OpCode::BitwiseOr,
            BinaryOp::BitwiseXor => OpCode::BitwiseXor,
            BinaryOp::ShiftLeft => OpCode::ShiftLeft,
            BinaryOp::ShiftRight => OpCode::ShiftRight,
            BinaryOp::Equal => OpCode::Equal,
            BinaryOp::Identical => OpCode::Identical,
            BinaryOp::NotEqual => OpCode::NotEqual,
            BinaryOp::NotIdentical => OpCode::NotIdentical,
            BinaryOp::Less => OpCode::Less,
            BinaryOp::Greater => OpCode::Greater,
            BinaryOp::LessEqual => OpCode::LessEqual,
            BinaryOp::GreaterEqual => OpCode::GreaterEqual,
            BinaryOp::Spaceship => OpCode::Spaceship,
            BinaryOp::LogicalXor => OpCode::BoolXor,
            BinaryOp::BooleanAnd
            | BinaryOp::BooleanOr
            | BinaryOp::LogicalAnd
            | BinaryOp::LogicalOr
            | BinaryOp::Coalesce => return None,
        })
    }

    /// A plain binary operator and the left-deep chain of plain operators
    /// below it (`$a + 1 + 1 + ...`), compiled iteratively in the order the
    /// recursive compilation has (left operand, right operand, operator):
    /// deep expressions do not recurse through compile_expr.
    #[inline(never)]
    fn compile_binary_chain(&mut self, expr: &Expr) -> CompileResult<OperandType> {
        // zend_try_ct_eval_binary_op(): a concatenation of literals is a
        // literal (an interned string).
        if let Some(bytes) = Self::fold_concat_chain(expr) {
            let idx = self
                .op_array
                .add_literal(Value::String(PhpString::from_vec(bytes)));
            return Ok(OperandType::Const(idx));
        }
        let mut spine: Vec<&Expr> = vec![expr];
        if self.memoize_mode == 0 {
            loop {
                let ExprKind::BinaryOp { left, .. } = &spine[spine.len() - 1].kind else {
                    unreachable!()
                };
                match &left.kind {
                    ExprKind::BinaryOp { op, .. } if Self::plain_binop_opcode(op).is_some() => {
                        spine.push(left)
                    }
                    _ => break,
                }
            }
        }
        let mut acc: Option<OperandType> = None;
        for node in spine.into_iter().rev() {
            let ExprKind::BinaryOp { op, left, right } = &node.kind else {
                unreachable!()
            };
            // (compile_expr's entry for this node)
            self.zend_lineno = node.span.line;
            let l = match acc {
                Some(l) => l,
                None => self.compile_expr(left)?,
            };
            let r = self.compile_expr(right)?;
            let opcode = Self::plain_binop_opcode(op).expect("plain binary operator");
            let line = self.zend_lineno.max(node.span.line);
            acc = Some(self.emit_binary_op(opcode, left, right, l, r, line));
        }
        Ok(acc.expect("binary operator"))
    }

    /// The value of a (left-deep) chain of `.` over string and integer
    /// literals, if it is one.
    fn fold_concat_chain(expr: &Expr) -> Option<Vec<u8>> {
        fn leaf(e: &Expr) -> Option<Vec<u8>> {
            match &e.kind {
                ExprKind::String(s) => Some(s.clone()),
                ExprKind::Int(n) => Some(n.to_string().into_bytes()),
                ExprKind::BinaryOp {
                    op: BinaryOp::Concat,
                    ..
                } => Compiler::fold_concat_chain(e),
                _ => None,
            }
        }
        let mut parts: Vec<Vec<u8>> = Vec::new();
        let mut cur = expr;
        loop {
            match &cur.kind {
                ExprKind::BinaryOp {
                    op: BinaryOp::Concat,
                    left,
                    right,
                } => {
                    parts.push(leaf(right)?);
                    cur = left;
                }
                _ => {
                    parts.push(leaf(cur)?);
                    break;
                }
            }
        }
        if parts.len() < 2 {
            return None;
        }
        let mut out = Vec::with_capacity(parts.iter().map(|p| p.len()).sum());
        for p in parts.iter().rev() {
            out.extend_from_slice(p);
        }
        Some(out)
    }

    /// Emit binary operator `opcode` into a new temporary. (Out of line:
    /// compile_expr recurses through the operands of deep expressions and
    /// its frame must stay small.)
    #[inline(never)]
    fn emit_binary_op(
        &mut self,
        opcode: OpCode,
        left: &Expr,
        right: &Expr,
        l: OperandType,
        r: OperandType,
        line: u32,
    ) -> OperandType {
        let tmp = self.op_array.alloc_temp();
        let (l, r) = Self::commutative_operands(opcode, left, right, l, r);
        self.op_array.emit(Op {
            opcode,
            op1: l,
            op2: r,
            result: OperandType::Tmp(tmp),
            line,
        });
        OperandType::Tmp(tmp)
    }

    /// zend_vm_set_opcode_handler(): the operands of a commutative opcode
    /// are swapped when op1's type sorts before op2's (CONST < TMP < VAR <
    /// CV), which shows in its errors and warnings. Ranked by the operand
    /// expressions: a constant array literal is a CONST although goro
    /// builds it in a temporary. (Out of line: see compile_append_incdec.)
    #[inline(never)]
    fn commutative_operands(
        opcode: OpCode,
        left: &Expr,
        right: &Expr,
        l: OperandType,
        r: OperandType,
    ) -> (OperandType, OperandType) {
        if !matches!(
            opcode,
            OpCode::Mul
                | OpCode::BitwiseAnd
                | OpCode::BitwiseOr
                | OpCode::BitwiseXor
                | OpCode::BoolXor
        ) {
            return (l, r);
        }
        let rank = |e: &Expr, o: &OperandType| {
            if Self::eval_const_expr(e).is_some() {
                1
            } else if matches!(o, OperandType::Cv(_)) {
                8
            } else if matches!(
                e.kind,
                ExprKind::New { .. }
                    | ExprKind::FunctionCall { .. }
                    | ExprKind::MethodCall { .. }
                    | ExprKind::StaticMethodCall { .. }
                    | ExprKind::DynamicStaticMethodCall { .. }
            ) {
                4 // IS_VAR
            } else {
                2
            }
        };
        if rank(left, &l) < rank(right, &r) {
            (r, l)
        } else {
            (l, r)
        }
    }

    /// `$a[]++` / `--$a[]`: FETCH_DIM_RW appends a null element, which is
    /// then incremented/decremented in place. (Out of line: compile_expr
    /// recurses deeply and its frame must stay small.)
    #[inline(never)]
    fn compile_append_incdec(
        &mut self,
        array: &Expr,
        op: &UnaryOp,
        line: u32,
    ) -> CompileResult<OperandType> {
        let arr_op = self.compile_dim_write_base_mode(array, crate::fetch_w::DimFetch::Rw)?;
        let is_inc = matches!(op, UnaryOp::PostIncrement | UnaryOp::PreIncrement);
        let new_val = if is_inc { Value::Long(1) } else { Value::Null };
        let new_idx = self.op_array.add_literal(new_val);
        self.op_array.emit(Op {
            opcode: OpCode::ArrayAppend,
            op1: arr_op,
            op2: OperandType::Const(new_idx),
            result: OperandType::Unused,
            line,
        });
        let null_idx = self.op_array.add_literal(Value::Null);
        let old_tmp = self.op_array.alloc_temp();
        self.op_array.emit(Op {
            opcode: OpCode::Assign,
            op1: OperandType::Tmp(old_tmp),
            op2: OperandType::Const(null_idx),
            result: OperandType::Unused,
            line,
        });
        if !is_inc {
            // "Decrement on type null has no effect"
            let t = self.op_array.alloc_temp();
            self.op_array.emit(Op {
                opcode: OpCode::PostDecrement,
                op1: OperandType::Tmp(old_tmp),
                op2: OperandType::Unused,
                result: OperandType::Tmp(t),
                line,
            });
        }
        Ok(match op {
            UnaryOp::PreIncrement => OperandType::Const(new_idx),
            _ => OperandType::Tmp(old_tmp),
        })
    }

    /// Emit `throw new \Error($msg)`.
    fn compile_throw_error(&mut self, msg: &[u8], line: u32) -> CompileResult<()> {
        let span = goro_parser::token::Span::new(0, 0, line);
        let e = Expr {
            span,
            kind: ExprKind::ThrowExpr(Box::new(Expr {
                span,
                kind: ExprKind::New {
                    class: Box::new(Expr {
                        span,
                        kind: ExprKind::Identifier(b"\\Error".to_vec()),
                    }),
                    args: vec![Argument {
                        name: None,
                        value: Expr {
                            span,
                            kind: ExprKind::String(msg.to_vec()),
                        },
                        unpack: false,
                    }],
                },
            })),
        };
        self.compile_expr(&e)?;
        Ok(())
    }

    fn compile_static_class_operand(&mut self, class: &Expr) -> CompileResult<OperandType> {
        match &class.kind {
            ExprKind::Identifier(name) => {
                self.check_class_ref_scope(name, class.span.line)?;
                let resolved = self.resolve_class_name(name);
                let is_self = resolved.eq_ignore_ascii_case(b"self");
                let class_name = if is_self {
                    self.current_class.clone().unwrap_or(resolved)
                } else if resolved.eq_ignore_ascii_case(b"static") {
                    b"static".to_vec()
                } else if resolved.eq_ignore_ascii_case(b"parent") {
                    self.current_parent_class.clone().unwrap_or(resolved)
                } else {
                    resolved
                };
                let idx = self
                    .op_array
                    .add_literal(Value::String(PhpString::from_vec(class_name)));
                if is_self && self.is_in_trait {
                    self.op_array.class_const_literals.push(idx);
                }
                Ok(OperandType::Const(idx))
            }
            _ => {
                if is_illegal_class_literal(class) {
                    return Err(CompileError {
                        message: "Illegal class name".into(),
                        line: class.span.line,
                    });
                }
                if self.in_engine_silence() {
                    // isset($cls::$p): the class operand is fetched normally.
                    return self.compile_key_unsilenced(class, true);
                }
                self.compile_expr(class)
            }
        }
    }

    /// Class and property-name operands of a `C::$p` / `C::$$p` expression.
    fn compile_static_prop_operands(
        &mut self,
        expr: &Expr,
    ) -> CompileResult<(OperandType, OperandType)> {
        match &expr.kind {
            ExprKind::StaticPropertyAccess { class, property } => {
                let class_op = self.compile_static_class_operand(class)?;
                let idx = self
                    .op_array
                    .add_literal(Value::String(PhpString::from_vec(property.clone())));
                Ok((class_op, OperandType::Const(idx)))
            }
            ExprKind::DynamicStaticPropertyAccess { class, property } => {
                let class_op = self.compile_static_class_operand(class)?;
                let name_op = self.compile_expr(property)?;
                Ok((class_op, name_op))
            }
            _ => Err(CompileError {
                message: "Expected a static property".into(),
                line: expr.span.line,
            }),
        }
    }

    /// Operand of isset() / empty(): `$this` itself is checked quietly
    /// (ZEND_ISSET_ISEMPTY_THIS).
    fn compile_isset_operand(&mut self, e: &Expr) -> CompileResult<OperandType> {
        if matches!(&e.kind, ExprKind::Variable(n) if n == b"this") {
            self.quiet_this = true;
            let r = self.compile_expr(e);
            self.quiet_this = false;
            return r;
        }
        self.compile_expr(e)
    }

    /// Compile a constant expression's value (see `in_const_expr`).
    /// zend_compile_pipe(): the operand is evaluated first and passed as a
    /// temporary (so by-reference parameters reject it); `f(...)`,
    /// `C::m(...)` and `$o->m(...)` become direct calls, anything else is
    /// evaluated next and called.
    #[inline(never)]
    fn compile_pipe(
        &mut self,
        expr: &Expr,
        value: &Expr,
        callable: &Expr,
    ) -> CompileResult<OperandType> {
        if matches!(
            callable.kind,
            ExprKind::ArrowFunction {
                parenthesized: false,
                ..
            }
        ) {
            return Err(CompileError {
                message: "Arrow functions on the right hand side of |> must be parenthesized"
                    .into(),
                line: callable.span.line,
            });
        }
        let saved = self.tmp_aliases.len();
        let hold = |c: &mut Self, v: OperandType, line: u32| -> Expr {
            let held = match v {
                OperandType::Tmp(_) | OperandType::Const(_) => v,
                other => {
                    let t = c.op_array.alloc_temp();
                    c.op_array.emit(Op {
                        opcode: OpCode::Assign,
                        op1: OperandType::Tmp(t),
                        op2: other,
                        result: OperandType::Unused,
                        line,
                    });
                    OperandType::Tmp(t)
                }
            };
            let mut name = PIPE_ALIAS_PREFIX.to_vec();
            name.extend_from_slice(c.tmp_aliases.len().to_string().as_bytes());
            c.tmp_aliases.push((name.clone(), held));
            Expr {
                span: expr.span,
                kind: ExprKind::Variable(name),
            }
        };
        let v = self.compile_expr(value)?;
        let arg = vec![Argument {
            name: None,
            value: hold(self, v, value.span.line),
            unpack: false,
        }];
        let kind = match &callable.kind {
            ExprKind::FirstClassCallable(CallableTarget::Function(name))
                if !matches!(&name.kind, ExprKind::Identifier(n)
                    if n.strip_prefix(b"\\").unwrap_or(n).eq_ignore_ascii_case(b"assert")) =>
            {
                ExprKind::FunctionCall {
                    name: name.clone(),
                    args: arg,
                }
            }
            ExprKind::FirstClassCallable(CallableTarget::StaticMethod { class, method }) => {
                ExprKind::StaticMethodCall {
                    class: class.clone(),
                    method: method.clone(),
                    args: arg,
                    method_line: 0,
                }
            }
            ExprKind::FirstClassCallable(CallableTarget::Method {
                object,
                method,
                nullsafe: false,
            }) => ExprKind::MethodCall {
                object: object.clone(),
                method: method.clone(),
                args: arg,
                nullsafe: false,
            },
            _ => {
                let c = self.compile_expr(callable)?;
                ExprKind::FunctionCall {
                    name: Box::new(hold(self, c, callable.span.line)),
                    args: arg,
                }
            }
        };
        let r = self.compile_expr(&Expr {
            kind,
            span: expr.span,
        });
        self.tmp_aliases.truncate(saved);
        r
    }

    /// An expression whose value is unused (for-loop expression lists):
    /// #[\NoDiscard] calls warn as in an expression statement.
    fn compile_discarded_expr(&mut self, expr: &Expr) -> CompileResult<OperandType> {
        let prev = self.is_discarding_result;
        self.is_discarding_result = matches!(
            expr.kind,
            ExprKind::FunctionCall { .. }
                | ExprKind::MethodCall { .. }
                | ExprKind::StaticMethodCall { .. }
        );
        let r = self.compile_expr(expr);
        self.is_discarding_result = prev;
        r
    }

    fn compile_const_expr_value(&mut self, e: &Expr) -> CompileResult<OperandType> {
        let prev = std::mem::replace(&mut self.in_const_expr, true);
        let r = self.compile_expr(e);
        self.in_const_expr = prev;
        r
    }

    fn is_static_prop_expr(e: &Expr) -> bool {
        matches!(
            e.kind,
            ExprKind::StaticPropertyAccess { .. } | ExprKind::DynamicStaticPropertyAccess { .. }
        )
    }

    /// `C::$p` in an isset-like context (`??`): StaticPropIsset, a JmpZ to
    /// be patched to the "not set" path, then the fetch. Returns the temp
    /// holding the value and the index of the JmpZ.
    fn compile_static_prop_quiet(&mut self, e: &Expr) -> CompileResult<(u32, u32)> {
        let (class_op, name_op) = self.compile_static_prop_operands(e)?;
        let set_tmp = self.op_array.alloc_temp();
        self.op_array.emit(Op {
            opcode: OpCode::StaticPropIsset,
            op1: class_op,
            op2: name_op,
            result: OperandType::Tmp(set_tmp),
            line: e.span.line,
        });
        let jmp = self.op_array.emit(Op {
            opcode: OpCode::JmpZ,
            op1: OperandType::Tmp(set_tmp),
            op2: OperandType::JmpTarget(0),
            result: OperandType::Unused,
            line: e.span.line,
        });
        let tmp = self.op_array.alloc_temp();
        self.op_array.emit(Op {
            opcode: OpCode::StaticPropFetch,
            op1: class_op,
            op2: name_op,
            result: OperandType::Tmp(tmp),
            line: e.span.line,
        });
        Ok((tmp, jmp))
    }

    /// Emit a static property fetch (`opcode` selects the fetch mode) into
    /// a fresh temp and return it.
    fn emit_static_prop_fetch(&mut self, opcode: OpCode, expr: &Expr) -> CompileResult<u32> {
        let (class_op, name_op) = self.compile_static_prop_operands(expr)?;
        let tmp = self.op_array.alloc_temp();
        self.op_array.emit(Op {
            opcode,
            op1: class_op,
            op2: name_op,
            result: OperandType::Tmp(tmp),
            line: expr.span.line,
        });
        Ok(tmp)
    }

    /// zend_compile_var_inner() in write context: the base of a dimension
    /// or property chain being written must itself be a variable or a call
    /// (`"abc"[0] = 1`, `[1][0]++`, `(new A)->x = 1` are compile errors).
    #[inline(never)]
    fn check_writable_base(&self, target: &Expr) -> CompileResult<()> {
        let mut root = target;
        loop {
            match &root.kind {
                ExprKind::ArrayAccess { array, .. } => root = array,
                ExprKind::PropertyAccess {
                    object,
                    nullsafe: false,
                    ..
                } => root = object,
                _ => break,
            }
        }
        if !std::ptr::eq(root, target) && self.is_special_builtin_call(root) {
            return Err(Self::builtin_write_context_error(root.span.line));
        }
        if std::ptr::eq(root, target)
            || matches!(
                root.kind,
                ExprKind::Variable(_)
                    | ExprKind::DynamicVariable(_)
                    | ExprKind::StaticPropertyAccess { .. }
                    | ExprKind::DynamicStaticPropertyAccess { .. }
                    | ExprKind::PropertyAccess { .. }
                    | ExprKind::FunctionCall { .. }
                    | ExprKind::MethodCall { .. }
                    | ExprKind::StaticMethodCall { .. }
                    | ExprKind::DynamicStaticMethodCall { .. }
            )
        {
            return Ok(());
        }
        Err(CompileError {
            message: "Cannot use temporary expression in write context".into(),
            line: target.span.line,
        })
    }

    /// zend_separate_if_call_and_write(): a call compiled to a VM builtin
    /// yields a TMP, which cannot be written through or referenced.
    /// "The (unset) cast is no longer supported"
    #[inline(never)]
    fn unset_cast_error(line: u32) -> CompileError {
        CompileError {
            message: "The (unset) cast is no longer supported".into(),
            line,
        }
    }

    #[inline(never)]
    fn builtin_write_context_error(line: u32) -> CompileError {
        CompileError {
            message: "Cannot use result of built-in function in write context".into(),
            line,
        }
    }

    /// A call zend_try_compile_special_func() turns into an opcode (the
    /// commonly used subset): a global internal function, unqualified only
    /// outside a namespace, called with plain positional arguments.
    #[inline(never)]
    fn is_special_builtin_call(&self, e: &Expr) -> bool {
        let ExprKind::FunctionCall { name, args } = &e.kind else {
            return false;
        };
        let ExprKind::Identifier(n) = &name.kind else {
            return false;
        };
        let n: &[u8] = match n.strip_prefix(b"\\") {
            Some(rest) => rest,
            None if self.current_namespace.is_empty() => n,
            None => return false,
        };
        if n.contains(&b'\\') || args.iter().any(|a| a.unpack || a.name.is_some()) {
            return false;
        }
        let lower = n.to_ascii_lowercase();
        let argc = args.len();
        match lower.as_slice() {
            b"strlen" | b"is_null" | b"is_bool" | b"is_long" | b"is_int" | b"is_integer"
            | b"is_float" | b"is_double" | b"is_string" | b"is_array" | b"is_object"
            | b"is_resource" | b"is_scalar" | b"boolval" | b"intval" | b"floatval"
            | b"doubleval" | b"strval" | b"gettype" => argc == 1,
            b"count" | b"sizeof" => argc == 1,
            b"get_called_class" | b"func_num_args" | b"func_get_args" => argc == 0,
            _ => false,
        }
    }

    /// The writability checks of zend_compile_var_inner() on the targets
    /// of an assignment / increment. (Out of line: see emit_binary_op.)
    #[inline(never)]
    fn check_write_targets(&self, expr: &Expr) -> CompileResult<()> {
        match &expr.kind {
            ExprKind::Assign { target, .. } | ExprKind::CompoundAssign { target, .. } => {
                self.check_writable_base(target)
            }
            ExprKind::AssignRef { target, value } => {
                self.check_writable_base(target)?;
                self.check_writable_base(value)?;
                if self.is_special_builtin_call(value) {
                    return Err(Self::builtin_write_context_error(value.span.line));
                }
                Ok(())
            }
            ExprKind::UnaryOp {
                op:
                    UnaryOp::PreIncrement
                    | UnaryOp::PreDecrement
                    | UnaryOp::PostIncrement
                    | UnaryOp::PostDecrement,
                operand,
                ..
            } => self.check_writable_base(operand),
            _ => Ok(()),
        }
    }

    /// A chain of property fetches / method calls / dimension fetches with
    /// a `?->`: a null object at a `?->` makes the whole chain null.
    #[inline(never)]
    fn compile_nullsafe_chain(&mut self, expr: &Expr) -> CompileResult<OperandType> {
        let outer = self.nullsafe_chain.replace(Vec::new());
        self.chain_base = true;
        let r = self.compile_expr(expr);
        let jumps = std::mem::replace(&mut self.nullsafe_chain, outer).unwrap_or_default();
        let r = r?;
        if jumps.is_empty() {
            return Ok(r);
        }
        let line = expr.span.line;
        let t = match r {
            OperandType::Tmp(t) => t,
            other => {
                let t = self.op_array.alloc_temp();
                self.op_array.emit(Op {
                    opcode: OpCode::Assign,
                    op1: OperandType::Tmp(t),
                    op2: other,
                    result: OperandType::Unused,
                    line,
                });
                t
            }
        };
        let skip = self.op_array.emit(Op {
            opcode: OpCode::Jmp,
            op1: OperandType::JmpTarget(0),
            op2: OperandType::Unused,
            result: OperandType::Unused,
            line,
        });
        let null_at = self.op_array.current_offset();
        for j in jumps {
            self.op_array.patch_jump(j, null_at);
        }
        let null_idx = self.op_array.add_literal(Value::Null);
        self.op_array.emit(Op {
            opcode: OpCode::Assign,
            op1: OperandType::Tmp(t),
            op2: OperandType::Const(null_idx),
            result: OperandType::Unused,
            line,
        });
        let end = self.op_array.current_offset();
        self.op_array.patch_jump(skip, end);
        Ok(OperandType::Tmp(t))
    }

    /// A read of a property / dimension chain whose outer names or keys are
    /// evaluated before the inner fetches (zend_delayed_compile_var(): the
    /// FETCH_OBJ_R / FETCH_DIM_R of the inner levels are emitted after the
    /// outer names and keys), when that order is observable.
    fn needs_delayed_chain(expr: &Expr) -> bool {
        let simple = |e: &Expr| {
            matches!(
                e.kind,
                ExprKind::Identifier(_)
                    | ExprKind::Int(_)
                    | ExprKind::String(_)
                    | ExprKind::Float(_)
                    | ExprKind::True
                    | ExprKind::False
                    | ExprKind::Null
            )
        };
        let mut e = expr;
        let mut depth = 0;
        let mut outer_dynamic = false;
        loop {
            let (inner, key) = match &e.kind {
                ExprKind::PropertyAccess {
                    object,
                    property,
                    nullsafe: false,
                } => (object, property),
                ExprKind::ArrayAccess {
                    array,
                    index: Some(index),
                } => (array, index),
                _ => break,
            };
            let inner_is_level = matches!(
                inner.kind,
                ExprKind::PropertyAccess {
                    nullsafe: false,
                    ..
                } | ExprKind::ArrayAccess { index: Some(_), .. }
            );
            if inner_is_level && !simple(key) {
                outer_dynamic = true;
            }
            depth += 1;
            e = inner;
        }
        depth >= 2 && outer_dynamic && !expr_is_in_nullsafe_chain(expr)
    }

    /// See needs_delayed_chain: the base, then every name / key from the
    /// innermost level out, then the fetches.
    #[inline(never)]
    fn compile_delayed_chain(&mut self, expr: &Expr) -> CompileResult<OperandType> {
        // Levels from the outermost in.
        let mut levels: Vec<&Expr> = Vec::new();
        let mut e = expr;
        loop {
            match &e.kind {
                ExprKind::PropertyAccess {
                    object,
                    nullsafe: false,
                    ..
                } => {
                    levels.push(e);
                    e = object;
                }
                ExprKind::ArrayAccess {
                    array,
                    index: Some(_),
                } => {
                    levels.push(e);
                    e = array;
                }
                _ => break,
            }
        }
        let mut cur = self.compile_expr(e)?;
        // (opcode, key, line) of each fetch, innermost first
        let mut fetches: Vec<(OpCode, OperandType, u32)> = Vec::with_capacity(levels.len());
        for level in levels.iter().rev() {
            match &level.kind {
                ExprKind::PropertyAccess { property, .. } => {
                    let name = self.compile_prop_name(property)?;
                    fetches.push((OpCode::PropertyGet, name, level.span.line));
                }
                ExprKind::ArrayAccess {
                    index: Some(idx), ..
                } => {
                    let key = self.compile_expr(idx)?;
                    // FETCH_DIM_R takes the line once its key is compiled.
                    fetches.push((OpCode::ArrayGet, key, self.zend_lineno.max(level.span.line)));
                }
                _ => unreachable!(),
            }
        }
        for (opcode, key, line) in fetches {
            let tmp = self.op_array.alloc_temp();
            self.op_array.emit(Op {
                opcode,
                op1: cur,
                op2: key,
                result: OperandType::Tmp(tmp),
                line,
            });
            cur = OperandType::Tmp(tmp);
        }
        Ok(cur)
    }

    /// The name operand of a property read `$o->name` / `$o->{expr}`. A
    /// constant array name is converted at compile time (with the "Array to
    /// string conversion" warning, zend_compile_prop()).
    #[inline(never)]
    fn compile_prop_name(&mut self, property: &Expr) -> CompileResult<OperandType> {
        match &property.kind {
            ExprKind::Identifier(name) => Ok(OperandType::Const(
                self.op_array
                    .add_literal(Value::String(PhpString::from_vec(name.clone()))),
            )),
            ExprKind::Array(_) if Self::eval_const_expr(property).is_some() => {
                push_compile_warning("Array to string conversion".to_string(), property.span.line);
                Ok(OperandType::Const(self.op_array.add_literal(
                    Value::String(PhpString::from_bytes(b"Array")),
                )))
            }
            // Dynamic property name: $obj->$prop
            _ => self.compile_expr(property),
        }
    }

    /// The null check of `?->` on `obj`: its jump joins the chain's
    /// short-circuit (None), or is returned to be handled locally.
    #[inline(never)]
    fn emit_nullsafe_check(&mut self, obj: OperandType, line: u32) -> Option<u32> {
        let null_idx = self.op_array.add_literal(Value::Null);
        let is_null_tmp = self.op_array.alloc_temp();
        self.op_array.emit(Op {
            opcode: OpCode::Identical,
            op1: obj,
            op2: OperandType::Const(null_idx),
            result: OperandType::Tmp(is_null_tmp),
            line,
        });
        let jmp = self.op_array.emit(Op {
            opcode: OpCode::JmpNz,
            op1: OperandType::Tmp(is_null_tmp),
            op2: OperandType::JmpTarget(0),
            result: OperandType::Unused,
            line,
        });
        match self.nullsafe_chain.as_mut() {
            Some(list) => {
                list.push(jmp);
                None
            }
            None => Some(jmp),
        }
    }

    fn compile_expr(&mut self, expr: &Expr) -> CompileResult<OperandType> {
        // zend_check_stack_limit()
        if let Err(size) = crate::stack::enter_compile() {
            return Err(CompileError {
                message: format!(
                    "Maximum call stack size of {} bytes (zend.max_allowed_stack_size - zend.reserved_stack_size) reached during compilation. Try splitting expression",
                    size
                ),
                line: expr.span.line,
            });
        }
        let r = crate::stack::with_room(|| self.compile_expr_inner(expr)).unwrap_or_else(|_| {
            Err(CompileError {
                message: "Maximum nesting depth exceeded".into(),
                line: expr.span.line,
            })
        });
        crate::stack::leave_compile();
        r
    }

    fn compile_expr_inner(&mut self, expr: &Expr) -> CompileResult<OperandType> {
        self.zend_lineno = expr.span.line;
        if !std::mem::take(&mut self.chain_base)
            && matches!(
                expr.kind,
                ExprKind::PropertyAccess { .. }
                    | ExprKind::MethodCall { .. }
                    | ExprKind::ArrayAccess { .. }
            )
            && expr_is_in_nullsafe_chain(expr)
        {
            return self.compile_nullsafe_chain(expr);
        }
        if self.memoize_mode == 0 && !self.in_const_expr && Self::needs_delayed_chain(expr) {
            return self.compile_delayed_chain(expr);
        }
        if self.memoize_mode != 0
            && Self::is_memoizable(expr)
            && expr as *const Expr as usize != self.memoize_root
        {
            return self.compile_memoized_expr(expr);
        }
        self.check_write_targets(expr)?;
        match &expr.kind {
            ExprKind::Int(n) => {
                let idx = self.op_array.add_literal(Value::Long(*n));
                Ok(OperandType::Const(idx))
            }
            ExprKind::Float(f) => {
                let idx = self.op_array.add_literal(Value::Double(*f));
                Ok(OperandType::Const(idx))
            }
            ExprKind::String(s) => {
                let idx = self
                    .op_array
                    .add_literal(Value::String(PhpString::from_vec(s.clone())));
                Ok(OperandType::Const(idx))
            }
            ExprKind::True => {
                let idx = self.op_array.add_literal(Value::True);
                Ok(OperandType::Const(idx))
            }
            ExprKind::False => {
                let idx = self.op_array.add_literal(Value::False);
                Ok(OperandType::Const(idx))
            }
            ExprKind::Null => {
                let idx = self.op_array.add_literal(Value::Null);
                Ok(OperandType::Const(idx))
            }

            ExprKind::Variable(name) => {
                if !self.tmp_aliases.is_empty() {
                    if let Some((_, op)) = self.tmp_aliases.iter().rev().find(|(n, _)| n == name) {
                        return Ok(*op);
                    }
                }
                let cv = self.op_array.get_or_create_cv(name);
                // zend_try_compile_cv(): reading the variable the http://
                // wrapper used to set is deprecated (unless assigned first
                // or a parameter).
                if name == b"http_response_header"
                    && !self.hrh_assigned
                    && cv >= self.op_array.param_count
                {
                    push_compile_deprecated(
                        "The predefined locally scoped $http_response_header variable is deprecated, call http_get_last_response_headers() instead".to_string(),
                        expr.span.line,
                    );
                }
                if name == b"this" && !self.this_always_bound && !self.quiet_this {
                    // "Using $this when not in object context" unless bound.
                    self.op_array.emit(Op {
                        opcode: OpCode::CheckThis,
                        op1: OperandType::Cv(cv),
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });
                }
                Ok(OperandType::Cv(cv))
            }

            ExprKind::Assign { target, value } if matches!(&target.kind, ExprKind::DynamicVariable(i) if Self::static_dynvar_name(i).is_none()) => {
                self.compile_assign_dynvar(expr, target, value)
            }
            ExprKind::Assign { target, value } => {
                if matches!(&target.kind, ExprKind::Variable(n) if n == b"http_response_header") {
                    self.hrh_assigned = true;
                }
                let result_discarded = std::mem::take(&mut self.assign_result_discarded);
                // Check for nullsafe in write context
                if expr_is_in_nullsafe_chain(target) {
                    return Err(CompileError {
                        message: "Can't use nullsafe operator in write context".into(),
                        line: target.span.line,
                    });
                }
                // $GLOBALS can only be modified using $GLOBALS[$name] = $value syntax
                if matches!(&target.kind, ExprKind::Variable(name) if name == b"GLOBALS") {
                    return Err(CompileError {
                        message: "$GLOBALS can only be modified using the $GLOBALS[$name] = $value syntax".to_string(),
                        line: expr.span.line,
                    });
                }
                let list_globals = match &target.kind {
                    ExprKind::FunctionCall { name, args } if matches!(&name.kind, ExprKind::Identifier(n) if n.eq_ignore_ascii_case(b"list")) => {
                        args.iter().any(
                            |a| matches!(&a.value.kind, ExprKind::Variable(n) if n == b"GLOBALS"),
                        )
                    }
                    _ => false,
                };
                if list_globals {
                    return Err(CompileError { message: "$GLOBALS can only be modified using the $GLOBALS[$name] = $value syntax".to_string(), line: expr.span.line });
                }
                if let ExprKind::Array(elems) = &target.kind {
                    if Self::list_writes_globals(elems) && !Self::list_has_ref(elems) {
                        return Err(CompileError { message: "$GLOBALS can only be modified using the $GLOBALS[$name] = $value syntax".to_string(), line: expr.span.line });
                    }
                }
                if matches!(&target.kind, ExprKind::ArrayAccess { array, index: None } if matches!(&array.kind, ExprKind::Variable(n) if n == b"GLOBALS"))
                {
                    return Err(CompileError {
                        message: "Cannot append to $GLOBALS".into(),
                        line: expr.span.line,
                    });
                }
                // $this cannot be re-assigned inside a method body.
                if let ExprKind::Variable(target_name) = &target.kind {
                    if target_name == b"this" && self.current_class.is_some() {
                        return Err(CompileError {
                            message: "Cannot re-assign $this".into(),
                            line: expr.span.line,
                        });
                    }
                }
                // Computed keys / names of the target are evaluated before the
                // assigned value (the target's fetches are delayed past it).
                if Self::lvalue_needs_memo(target) {
                    return self.compile_assign_memoized(expr, target, value, None);
                }
                // Destructuring with by-reference elements: [&$a, $b] = $src
                if let ExprKind::Array(elems) = &target.kind {
                    if Self::list_has_ref(elems) {
                        // The source variable is itself a target: it is
                        // fetched once (bound to a hidden variable), so
                        // rebinding it does not change what is destructured.
                        let self_target = matches!(&value.kind, ExprKind::Variable(n) if Self::list_targets_var(elems, n));
                        let is_call = matches!(
                            &value.kind,
                            ExprKind::FunctionCall { .. }
                                | ExprKind::MethodCall { .. }
                                | ExprKind::StaticMethodCall { .. }
                                | ExprKind::DynamicStaticMethodCall { .. }
                        );
                        if self_target || is_call {
                            let mut hname = b"\0vv".to_vec();
                            hname.extend_from_slice(self.dynvar_count.to_string().as_bytes());
                            self.dynvar_count += 1;
                            let hcv = self.op_array.get_or_create_cv(&hname);
                            let line = expr.span.line;
                            let val = self.compile_expr(value)?;
                            if is_call {
                                self.mark_ref_call(&val);
                                // FETCH_LIST_W of a by-value temporary.
                                let msg_idx =
                                    self.op_array
                                        .add_literal(Value::String(PhpString::from_bytes(
                                        b"Attempting to set reference to non referenceable value",
                                    )));
                                let cond_idx = self.op_array.add_literal(Value::Long(1));
                                for _ in 0..Self::list_ref_count(elems) {
                                    self.op_array.emit(Op {
                                        opcode: OpCode::EmitNotice,
                                        op1: OperandType::Const(msg_idx),
                                        op2: OperandType::Const(cond_idx),
                                        result: OperandType::Unused,
                                        line,
                                    });
                                }
                            }
                            self.op_array.emit(Op {
                                opcode: OpCode::AssignRef,
                                op1: OperandType::Cv(hcv),
                                op2: val,
                                result: OperandType::Unused,
                                line,
                            });
                            let hidden = Expr {
                                kind: ExprKind::Variable(hname),
                                span: value.span,
                            };
                            self.compile_list_destructure_ref(elems, &hidden, line)?;
                            let t = self.op_array.alloc_temp();
                            self.op_array.emit(Op {
                                opcode: OpCode::Assign,
                                op1: OperandType::Tmp(t),
                                op2: OperandType::Cv(hcv),
                                result: OperandType::Unused,
                                line,
                            });
                            self.op_array.emit(Op {
                                opcode: OpCode::UnsetCv,
                                op1: OperandType::Cv(hcv),
                                op2: OperandType::Unused,
                                result: OperandType::Unused,
                                line,
                            });
                            return Ok(OperandType::Tmp(t));
                        }
                        match &value.kind {
                            ExprKind::Variable(_)
                            | ExprKind::ArrayAccess { .. }
                            | ExprKind::PropertyAccess { .. }
                            | ExprKind::StaticPropertyAccess { .. }
                            | ExprKind::DynamicVariable(_) => {
                                self.compile_list_destructure_ref(elems, value, expr.span.line)?;
                                return self.compile_expr(value);
                            }
                            ExprKind::FunctionCall { .. }
                            | ExprKind::MethodCall { .. }
                            | ExprKind::StaticMethodCall { .. }
                            | ExprKind::DynamicStaticMethodCall { .. } => {}
                            _ => {
                                return Err(CompileError {
                                    message: "Cannot assign reference to non referenceable value"
                                        .into(),
                                    line: expr.span.line,
                                });
                            }
                        }
                    }
                }
                // zend_delayed_compile_var(): a dynamic static property name
                // (`C::${f()} = g()`) is evaluated before the value.
                let pre_static =
                    if matches!(target.kind, ExprKind::DynamicStaticPropertyAccess { .. }) {
                        Some(self.compile_static_prop_operands(target)?)
                    } else {
                        None
                    };
                let mut val = self.compile_expr(value)?;
                // The value of `$o->p = $v` is the value assigned, even if a
                // magic method / lazy initializer run by the store changes $v:
                // read the variable once.
                let simple = |e: &Expr| {
                    matches!(
                        e.kind,
                        ExprKind::Variable(_)
                            | ExprKind::Identifier(_)
                            | ExprKind::Int(_)
                            | ExprKind::String(_)
                    )
                };
                let target_simple = match &target.kind {
                    ExprKind::PropertyAccess {
                        object, property, ..
                    } => simple(object) && simple(property),
                    ExprKind::ArrayAccess { array, index } => {
                        simple(array) && index.as_ref().is_none_or(|i| simple(i))
                    }
                    ExprKind::StaticPropertyAccess { class, .. } => simple(class),
                    ExprKind::DynamicVariable(inner) => simple(inner),
                    _ => false,
                };
                // `$s[i] = v` used as a value is the byte written when $s is
                // a string: ArraySet stores it into the value's tmp.
                let dim_result = !result_discarded
                    && matches!(target.kind, ExprKind::ArrayAccess { index: Some(_), .. })
                    && !matches!(val, OperandType::Tmp(_));
                if dim_result
                    || (!result_discarded && matches!(val, OperandType::Cv(_)) && target_simple)
                {
                    let t = self.op_array.alloc_temp();
                    self.op_array.emit(Op {
                        opcode: OpCode::Assign,
                        op1: OperandType::Tmp(t),
                        op2: val,
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });
                    val = OperandType::Tmp(t);
                }
                match &target.kind {
                    ExprKind::Variable(name) => {
                        let cv = self.op_array.get_or_create_cv(name);
                        // The value of `$a = v` is the assigned value, even if a
                        // destructor run by the assignment changes $a (GH-10168).
                        let result = if result_discarded {
                            OperandType::Unused
                        } else {
                            OperandType::Tmp(self.op_array.alloc_temp())
                        };
                        self.op_array.emit(Op {
                            opcode: OpCode::Assign,
                            op1: OperandType::Cv(cv),
                            op2: val,
                            result,
                            line: expr.span.line,
                        });
                        Ok(if result_discarded {
                            OperandType::Cv(cv)
                        } else {
                            result
                        })
                    }
                    ExprKind::ArrayAccess { array, index } => {
                        // $arr[$key] = $val  →  ArraySet
                        let arr_op = self.compile_dim_write_base(array)?;
                        if let Some(idx_expr) = index {
                            let idx_op = self.compile_expr(idx_expr)?;
                            self.op_array.emit(Op {
                                opcode: OpCode::ArraySet,
                                op1: arr_op,
                                op2: val,
                                result: idx_op,
                                line: expr.span.line,
                            });
                        } else {
                            self.op_array.emit(Op {
                                opcode: OpCode::ArrayAppend,
                                op1: arr_op,
                                op2: val,
                                result: OperandType::Unused,
                                line: expr.span.line,
                            });
                        }
                        // C::$p[k] = v: an array the write created from a
                        // null/unset C::$p is stored back into the property.
                        if let (ExprKind::StaticPropertyAccess { .. }, OperandType::Tmp(_)) =
                            (&array.kind, &arr_op)
                        {
                            let fetch = self
                                .op_array
                                .ops
                                .iter()
                                .rev()
                                .find(|o| o.result == arr_op && o.opcode == OpCode::StaticPropFetch)
                                .map(|o| (o.op1, o.op2));
                            if let Some((cls, name)) = fetch {
                                self.op_array.emit(Op {
                                    opcode: OpCode::StaticPropSet,
                                    op1: cls,
                                    op2: arr_op,
                                    result: name,
                                    line: expr.span.line,
                                });
                            }
                        }
                        Ok(val)
                    }
                    ExprKind::PropertyAccess {
                        object, property, ..
                    } => {
                        let obj = self.compile_obj_write_base(object)?;
                        let prop_operand = match &property.kind {
                            ExprKind::Identifier(name) => {
                                let name_idx = self
                                    .op_array
                                    .add_literal(Value::String(PhpString::from_vec(name.clone())));
                                OperandType::Const(name_idx)
                            }
                            _ => self.compile_expr(property)?,
                        };
                        // The expression's value is the (possibly coerced) value
                        // stored in a typed property: give it its own tmp, which
                        // PropertySet updates.
                        let val = if result_discarded || matches!(val, OperandType::Tmp(_)) {
                            val
                        } else {
                            let t = self.op_array.alloc_temp();
                            self.op_array.emit(Op {
                                opcode: OpCode::QmAssign,
                                op1: val,
                                op2: OperandType::Unused,
                                result: OperandType::Tmp(t),
                                line: expr.span.line,
                            });
                            OperandType::Tmp(t)
                        };
                        self.op_array.emit(Op {
                            opcode: OpCode::PropertySet,
                            op1: obj,
                            op2: val,
                            result: prop_operand,
                            line: expr.span.line,
                        });
                        Ok(val)
                    }
                    ExprKind::StaticPropertyAccess { .. }
                    | ExprKind::DynamicStaticPropertyAccess { .. } => {
                        // C::$p = value. The value goes through a temp: StaticPropSet
                        // stores the (type-coerced) assigned value back into it, which
                        // is the expression's result.
                        let val = if matches!(val, OperandType::Tmp(_)) {
                            val
                        } else {
                            let t = self.op_array.alloc_temp();
                            self.op_array.emit(Op {
                                opcode: OpCode::Assign,
                                op1: OperandType::Tmp(t),
                                op2: val,
                                result: OperandType::Unused,
                                line: expr.span.line,
                            });
                            OperandType::Tmp(t)
                        };
                        let (class_op, name_op) = match pre_static {
                            Some(ops) => ops,
                            None => self.compile_static_prop_operands(target)?,
                        };
                        self.op_array.emit(Op {
                            opcode: OpCode::StaticPropSet,
                            op1: class_op,
                            op2: val,
                            result: name_op,
                            line: expr.span.line,
                        });
                        Ok(val)
                    }
                    ExprKind::DynamicVariable(inner) => {
                        let name_op = self.compile_expr(inner)?;
                        self.op_array.emit(Op {
                            opcode: OpCode::VarVarSet,
                            op1: name_op,
                            op2: val,
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                        Ok(val)
                    }
                    _ => {
                        // Check for destructuring: list($a, $b) = $arr or [$a, $b] = $arr
                        // Also supports keyed: ["a" => $x, "b" => $y] = $arr
                        let elems: Vec<_> = match &target.kind {
                            ExprKind::Array(elems) => elems.clone(),
                            ExprKind::FunctionCall { name, args } if matches!(&name.kind, ExprKind::Identifier(n) if n.eq_ignore_ascii_case(b"list")) => {
                                args.iter()
                                    .map(|a| ArrayElement {
                                        key: None,
                                        value: a.value.clone(),
                                        unpack: false,
                                        by_ref: false,
                                    })
                                    .collect()
                            }
                            _ => {
                                let msg = match &target.kind {
                                    ExprKind::FunctionCall { .. } => {
                                        "Can't use function return value in write context"
                                    }
                                    ExprKind::MethodCall { .. }
                                    | ExprKind::StaticMethodCall { .. }
                                    | ExprKind::DynamicStaticMethodCall { .. } => {
                                        "Can't use method return value in write context"
                                    }
                                    _ => "Can't use function return value in write context",
                                };
                                return Err(CompileError {
                                    message: msg.into(),
                                    line: expr.span.line,
                                });
                            }
                        };

                        // Snapshot a CV source: `[$a, $b] = $a` must read the
                        // original array, not $a after its first element is assigned.
                        let arr_op = if matches!(val, OperandType::Cv(_)) {
                            let t = self.op_array.alloc_temp();
                            self.op_array.emit(Op {
                                opcode: OpCode::LoadConst,
                                op1: val,
                                op2: OperandType::Unused,
                                result: OperandType::Tmp(t),
                                line: expr.span.line,
                            });
                            OperandType::Tmp(t)
                        } else {
                            val
                        };
                        self.compile_list_destructure(&elems, arr_op, expr.span.line)?;
                        Ok(arr_op)
                    }
                }
            }

            ExprKind::CompoundAssign { op, target, value } => {
                // Check for nullsafe in write context
                if expr_is_in_nullsafe_chain(target) {
                    return Err(CompileError {
                        message: "Can't use nullsafe operator in write context".into(),
                        line: target.span.line,
                    });
                }
                // $GLOBALS can only be modified using $GLOBALS[$name] = $value syntax
                if matches!(&target.kind, ExprKind::Variable(name) if name == b"GLOBALS") {
                    return Err(CompileError {
                        message: "$GLOBALS can only be modified using the $GLOBALS[$name] = $value syntax".to_string(),
                        line: expr.span.line,
                    });
                }
                if matches!(&target.kind, ExprKind::DynamicVariable(i) if Self::static_dynvar_name(i).is_none())
                    && *op != BinaryOp::Coalesce
                {
                    return self.compile_compound_dynvar(expr, *op, target, value);
                }
                if *op == BinaryOp::Coalesce {
                    return self.compile_assign_coalesce(expr, target, value);
                }
                // Computed keys / names of the target are evaluated before
                // the operand (ASSIGN_DIM_OP / ASSIGN_OBJ_OP).
                if Self::lvalue_needs_memo(target) {
                    return self.compile_assign_memoized(expr, target, value, Some(*op));
                }
                let val = self.compile_expr(value)?;
                match &target.kind {
                    ExprKind::Variable(name) => {
                        let cv = self.op_array.get_or_create_cv(name);
                        let opcode = match op {
                            BinaryOp::Add => OpCode::AssignAdd,
                            BinaryOp::Sub => OpCode::AssignSub,
                            BinaryOp::Mul => OpCode::AssignMul,
                            BinaryOp::Div => OpCode::AssignDiv,
                            BinaryOp::Mod => OpCode::AssignMod,
                            BinaryOp::Pow => OpCode::AssignPow,
                            BinaryOp::Concat => OpCode::AssignConcat,
                            BinaryOp::BitwiseAnd => OpCode::AssignBitwiseAnd,
                            BinaryOp::BitwiseOr => OpCode::AssignBitwiseOr,
                            BinaryOp::BitwiseXor => OpCode::AssignBitwiseXor,
                            BinaryOp::ShiftLeft => OpCode::AssignShiftLeft,
                            BinaryOp::ShiftRight => OpCode::AssignShiftRight,
                            _ => {
                                return Err(CompileError {
                                    message: format!("unsupported compound assignment: {:?}", op),
                                    line: expr.span.line,
                                });
                            }
                        };
                        self.op_array.emit(Op {
                            opcode,
                            op1: OperandType::Cv(cv),
                            op2: val,
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                        Ok(OperandType::Cv(cv))
                    }
                    ExprKind::ArrayAccess { array, index } => {
                        // $arr[$key] op= $val
                        // Read current: tmp = $arr[$key]
                        // Compute: tmp2 = tmp op $val
                        // Write back: $arr[$key] = tmp2
                        let arr =
                            self.compile_dim_write_base_mode(array, crate::fetch_w::DimFetch::Rw)?;
                        let idx = if let Some(idx_expr) = index {
                            let k = self.compile_expr(idx_expr)?;
                            self.dim_rw_key(k, expr.span.line)
                        } else {
                            // $arr[] op= val: the new element starts as null
                            // (offsetGet(null) on ArrayAccess objects), then
                            // `null op val` is appended.
                            OperandType::Unused
                        };

                        let read_tmp = self.op_array.alloc_temp();
                        self.op_array.emit(Op {
                            opcode: OpCode::ArrayGetRW,
                            op1: arr,
                            op2: idx,
                            result: OperandType::Tmp(read_tmp),
                            line: expr.span.line,
                        });

                        let result_tmp = self.op_array.alloc_temp();
                        let bin_opcode = match op {
                            BinaryOp::Add => OpCode::Add,
                            BinaryOp::Sub => OpCode::Sub,
                            BinaryOp::Mul => OpCode::Mul,
                            BinaryOp::Div => OpCode::Div,
                            BinaryOp::Mod => OpCode::Mod,
                            BinaryOp::Pow => OpCode::Pow,
                            BinaryOp::Concat => OpCode::Concat,
                            BinaryOp::BitwiseAnd => OpCode::BitwiseAnd,
                            BinaryOp::BitwiseOr => OpCode::BitwiseOr,
                            BinaryOp::BitwiseXor => OpCode::BitwiseXor,
                            BinaryOp::ShiftLeft => OpCode::ShiftLeft,
                            BinaryOp::ShiftRight => OpCode::ShiftRight,
                            _ => OpCode::Add,
                        };
                        self.op_array.emit(Op {
                            opcode: bin_opcode,
                            op1: OperandType::Tmp(read_tmp),
                            op2: val,
                            result: OperandType::Tmp(result_tmp),
                            line: expr.span.line,
                        });

                        if matches!(idx, OperandType::Unused) {
                            self.op_array.emit(Op {
                                opcode: OpCode::ArrayAppend,
                                op1: arr,
                                op2: OperandType::Tmp(result_tmp),
                                result: OperandType::Unused,
                                line: expr.span.line,
                            });
                        } else {
                            self.op_array.emit(Op {
                                opcode: OpCode::ArraySet,
                                op1: arr,
                                op2: OperandType::Tmp(result_tmp),
                                result: idx,
                                line: expr.span.line,
                            });
                        }
                        Ok(OperandType::Tmp(result_tmp))
                    }
                    ExprKind::PropertyAccess {
                        object, property, ..
                    } => {
                        // $obj->prop op= $val
                        let obj =
                            self.compile_obj_write_base_mode(object, crate::fetch_w::DimFetch::Rw)?;
                        // Dynamic names ($obj->$name op= $val) are evaluated once.
                        let name_operand = match &property.kind {
                            ExprKind::Identifier(name) => {
                                let name_idx = self
                                    .op_array
                                    .add_literal(Value::String(PhpString::from_vec(name.clone())));
                                OperandType::Const(name_idx)
                            }
                            _ => self.compile_expr(property)?,
                        };

                        let read_tmp = self.op_array.alloc_temp();
                        self.op_array.emit(Op {
                            opcode: OpCode::PropertyGetRW,
                            op1: obj,
                            op2: name_operand,
                            result: OperandType::Tmp(read_tmp),
                            line: expr.span.line,
                        });

                        let result_tmp = self.op_array.alloc_temp();
                        let bin_opcode = match op {
                            BinaryOp::Add => OpCode::Add,
                            BinaryOp::Sub => OpCode::Sub,
                            BinaryOp::Mul => OpCode::Mul,
                            BinaryOp::Div => OpCode::Div,
                            BinaryOp::Mod => OpCode::Mod,
                            BinaryOp::Pow => OpCode::Pow,
                            BinaryOp::Concat => OpCode::Concat,
                            BinaryOp::BitwiseAnd => OpCode::BitwiseAnd,
                            BinaryOp::BitwiseOr => OpCode::BitwiseOr,
                            BinaryOp::BitwiseXor => OpCode::BitwiseXor,
                            BinaryOp::ShiftLeft => OpCode::ShiftLeft,
                            BinaryOp::ShiftRight => OpCode::ShiftRight,
                            _ => OpCode::Add,
                        };
                        self.op_array.emit(Op {
                            opcode: bin_opcode,
                            op1: OperandType::Tmp(read_tmp),
                            op2: val,
                            result: OperandType::Tmp(result_tmp),
                            line: expr.span.line,
                        });

                        self.op_array.emit(Op {
                            opcode: OpCode::PropertySet,
                            op1: obj,
                            op2: OperandType::Tmp(result_tmp),
                            result: name_operand,
                            line: expr.span.line,
                        });
                        Ok(OperandType::Tmp(result_tmp))
                    }
                    ExprKind::StaticPropertyAccess { class, property } => {
                        // self::$n op= $val — read-modify-write the static property.
                        let class_operand = self.compile_static_class_operand(class)?;
                        let prop_idx = self
                            .op_array
                            .add_literal(Value::String(PhpString::from_vec(property.clone())));
                        let read_tmp = self.op_array.alloc_temp();
                        self.op_array.emit(Op {
                            opcode: OpCode::StaticPropFetchRW,
                            op1: class_operand,
                            op2: OperandType::Const(prop_idx),
                            result: OperandType::Tmp(read_tmp),
                            line: expr.span.line,
                        });
                        let result_tmp = self.op_array.alloc_temp();
                        let bin_opcode = compound_binary_opcode(op);
                        self.op_array.emit(Op {
                            opcode: bin_opcode,
                            op1: OperandType::Tmp(read_tmp),
                            op2: val,
                            result: OperandType::Tmp(result_tmp),
                            line: expr.span.line,
                        });
                        self.op_array.emit(Op {
                            opcode: OpCode::StaticPropSet,
                            op1: class_operand,
                            op2: OperandType::Tmp(result_tmp),
                            result: OperandType::Const(prop_idx),
                            line: expr.span.line,
                        });
                        Ok(OperandType::Tmp(result_tmp))
                    }
                    ExprKind::DynamicStaticPropertyAccess { class, property } => {
                        // self::$$x op= $val
                        let class_operand = self.compile_static_class_operand(class)?;
                        let prop_op = self.compile_expr(property)?;
                        let read_tmp = self.op_array.alloc_temp();
                        self.op_array.emit(Op {
                            opcode: OpCode::StaticPropFetchRW,
                            op1: class_operand,
                            op2: prop_op,
                            result: OperandType::Tmp(read_tmp),
                            line: expr.span.line,
                        });
                        let result_tmp = self.op_array.alloc_temp();
                        let bin_opcode = compound_binary_opcode(op);
                        self.op_array.emit(Op {
                            opcode: bin_opcode,
                            op1: OperandType::Tmp(read_tmp),
                            op2: val,
                            result: OperandType::Tmp(result_tmp),
                            line: expr.span.line,
                        });
                        self.op_array.emit(Op {
                            opcode: OpCode::StaticPropSet,
                            op1: class_operand,
                            op2: OperandType::Tmp(result_tmp),
                            result: prop_op,
                            line: expr.span.line,
                        });
                        Ok(OperandType::Tmp(result_tmp))
                    }
                    _ => {
                        // For any other target, try to compile it as read-modify-write
                        let target_val = self.compile_expr(target)?;
                        let result_tmp = self.op_array.alloc_temp();
                        let bin_opcode = match op {
                            BinaryOp::Add => OpCode::Add,
                            BinaryOp::Sub => OpCode::Sub,
                            BinaryOp::Mul => OpCode::Mul,
                            BinaryOp::Div => OpCode::Div,
                            BinaryOp::Mod => OpCode::Mod,
                            BinaryOp::Pow => OpCode::Pow,
                            BinaryOp::Concat => OpCode::Concat,
                            BinaryOp::BitwiseAnd => OpCode::BitwiseAnd,
                            BinaryOp::BitwiseOr => OpCode::BitwiseOr,
                            BinaryOp::BitwiseXor => OpCode::BitwiseXor,
                            BinaryOp::ShiftLeft => OpCode::ShiftLeft,
                            BinaryOp::ShiftRight => OpCode::ShiftRight,
                            _ => OpCode::Add,
                        };
                        self.op_array.emit(Op {
                            opcode: bin_opcode,
                            op1: target_val,
                            op2: val,
                            result: OperandType::Tmp(result_tmp),
                            line: expr.span.line,
                        });
                        Ok(OperandType::Tmp(result_tmp))
                    }
                }
            }

            ExprKind::BinaryOp { op, left, right } => {
                // Short-circuit boolean operators
                match op {
                    BinaryOp::BooleanAnd | BinaryOp::LogicalAnd => {
                        let l = self.compile_expr(left)?;
                        // A constant left operand that decides the result
                        // leaves the right one uncompiled
                        // (zend_compile_short_circuiting).
                        if let OperandType::Const(i) = l {
                            if let Some(v) = self.op_array.literals.get(i as usize) {
                                if !v.is_truthy() {
                                    let idx = self.op_array.add_literal(Value::False);
                                    return Ok(OperandType::Const(idx));
                                }
                            }
                        }
                        let result_tmp = self.op_array.alloc_temp();
                        // If left is false, short-circuit: result = false
                        let jmp_false = self.op_array.emit(Op {
                            opcode: OpCode::JmpZ,
                            op1: l,
                            op2: OperandType::JmpTarget(0),
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                        // Left was truthy, evaluate right
                        let r = self.compile_expr(right)?;
                        // Result is truthiness of right
                        self.op_array.emit(Op {
                            opcode: OpCode::CastBool,
                            op1: r,
                            op2: OperandType::Unused,
                            result: OperandType::Tmp(result_tmp),
                            line: expr.span.line,
                        });
                        let jmp_end = self.op_array.emit(Op {
                            opcode: OpCode::Jmp,
                            op1: OperandType::JmpTarget(0),
                            op2: OperandType::Unused,
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                        // Short-circuit: result = false
                        let false_target = self.op_array.current_offset();
                        self.op_array.patch_jump(jmp_false, false_target);
                        let false_idx = self.op_array.add_literal(Value::False);
                        self.op_array.emit(Op {
                            opcode: OpCode::Assign,
                            op1: OperandType::Tmp(result_tmp),
                            op2: OperandType::Const(false_idx),
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                        let end = self.op_array.current_offset();
                        self.op_array.patch_jump(jmp_end, end);
                        return Ok(OperandType::Tmp(result_tmp));
                    }
                    BinaryOp::BooleanOr | BinaryOp::LogicalOr => {
                        let l = self.compile_expr(left)?;
                        // A constant left operand that decides the result
                        // leaves the right one uncompiled
                        // (zend_compile_short_circuiting).
                        if let OperandType::Const(i) = l {
                            if let Some(v) = self.op_array.literals.get(i as usize) {
                                if v.is_truthy() {
                                    let idx = self.op_array.add_literal(Value::True);
                                    return Ok(OperandType::Const(idx));
                                }
                            }
                        }
                        let result_tmp = self.op_array.alloc_temp();
                        // If left is true, short-circuit: result = true
                        let jmp_true = self.op_array.emit(Op {
                            opcode: OpCode::JmpNz,
                            op1: l,
                            op2: OperandType::JmpTarget(0),
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                        // Left was falsy, evaluate right
                        let r = self.compile_expr(right)?;
                        self.op_array.emit(Op {
                            opcode: OpCode::CastBool,
                            op1: r,
                            op2: OperandType::Unused,
                            result: OperandType::Tmp(result_tmp),
                            line: expr.span.line,
                        });
                        let jmp_end = self.op_array.emit(Op {
                            opcode: OpCode::Jmp,
                            op1: OperandType::JmpTarget(0),
                            op2: OperandType::Unused,
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                        // Short-circuit: result = true
                        let true_target = self.op_array.current_offset();
                        self.op_array.patch_jump(jmp_true, true_target);
                        let true_idx = self.op_array.add_literal(Value::True);
                        self.op_array.emit(Op {
                            opcode: OpCode::Assign,
                            op1: OperandType::Tmp(result_tmp),
                            op2: OperandType::Const(true_idx),
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                        let end = self.op_array.current_offset();
                        self.op_array.patch_jump(jmp_end, end);
                        return Ok(OperandType::Tmp(result_tmp));
                    }
                    _ => {}
                }

                self.compile_binary_chain(expr)
            }

            ExprKind::UnaryOp {
                op,
                operand,
                prefix,
            } => {
                if matches!(&operand.kind, ExprKind::DynamicVariable(i) if Self::static_dynvar_name(i).is_none())
                    && matches!(
                        op,
                        UnaryOp::PostIncrement
                            | UnaryOp::PostDecrement
                            | UnaryOp::PreIncrement
                            | UnaryOp::PreDecrement
                    )
                {
                    return self.compile_incdec_dynvar(expr, *op, operand, *prefix);
                }
                // zend_compile_unary_pm(): `+x` / `-x` are `x * 1` / `x * -1`
                // (an undefined variable warns, arrays / objects / non-numeric
                // strings are unsupported operands of `*`).
                if matches!(op, UnaryOp::Plus | UnaryOp::Negate) {
                    let val = self.compile_expr(operand)?;
                    let factor =
                        self.op_array
                            .add_literal(Value::Long(if matches!(op, UnaryOp::Plus) {
                                1
                            } else {
                                -1
                            }));
                    let tmp = self.op_array.alloc_temp();
                    self.op_array.emit(Op {
                        opcode: OpCode::Mul,
                        op1: val,
                        op2: OperandType::Const(factor),
                        result: OperandType::Tmp(tmp),
                        line: expr.span.line,
                    });
                    return Ok(OperandType::Tmp(tmp));
                }

                // Handle increment/decrement on property access: $obj->prop++ etc.
                if matches!(
                    op,
                    UnaryOp::PostIncrement
                        | UnaryOp::PostDecrement
                        | UnaryOp::PreIncrement
                        | UnaryOp::PreDecrement
                ) {
                    if expr_is_in_nullsafe_chain(operand) {
                        return Err(CompileError {
                            message: "Can't use nullsafe operator in write context".into(),
                            line: operand.span.line,
                        });
                    }
                    // zend_ensure_writable_variable()
                    let call_msg = match &operand.kind {
                        ExprKind::FunctionCall { .. } => {
                            Some("Can't use function return value in write context")
                        }
                        ExprKind::MethodCall { .. }
                        | ExprKind::StaticMethodCall { .. }
                        | ExprKind::DynamicStaticMethodCall { .. } => {
                            Some("Can't use method return value in write context")
                        }
                        _ => None,
                    };
                    if let Some(msg) = call_msg {
                        return Err(CompileError {
                            message: msg.into(),
                            line: operand.span.line,
                        });
                    }

                    // Increment/decrement on array element: $arr[$key]++ / --$arr[$key]
                    // Without explicit read-modify-write the inc would land on a
                    // throwaway temp and the array element would never change.
                    // `$a[]++`: FETCH_DIM_RW appends a null element, which is then
                    // incremented/decremented in place.
                    if let ExprKind::ArrayAccess { array, index: None } = &operand.kind {
                        return self.compile_append_incdec(array, op, expr.span.line);
                    }
                    if let ExprKind::ArrayAccess { array, index } = &operand.kind {
                        let arr_op =
                            self.compile_dim_write_base_mode(array, crate::fetch_w::DimFetch::Rw)?;
                        let idx_op = if let Some(idx_expr) = index {
                            let k = self.compile_expr(idx_expr)?;
                            self.dim_rw_key(k, expr.span.line)
                        } else {
                            // $arr[]++: append-then-modify makes no sense here;
                            // fall through to plain unary handler.
                            return Err(CompileError {
                                message: "Cannot use [] for reading".into(),
                                line: operand.span.line,
                            });
                        };
                        // Fetch current value
                        let old_tmp = self.op_array.alloc_temp();
                        self.op_array.emit(Op {
                            opcode: OpCode::ArrayGetIncDec,
                            op1: arr_op,
                            op2: idx_op,
                            result: OperandType::Tmp(old_tmp),
                            line: expr.span.line,
                        });
                        // Increment/decrement (writes new to op1, old to result)
                        let new_tmp = self.op_array.alloc_temp();
                        let inc_opcode = match op {
                            UnaryOp::PostIncrement | UnaryOp::PreIncrement => OpCode::PostIncrement,
                            _ => OpCode::PostDecrement,
                        };
                        self.op_array.emit(Op {
                            opcode: inc_opcode,
                            op1: OperandType::Tmp(old_tmp),
                            op2: OperandType::Unused,
                            result: OperandType::Tmp(new_tmp),
                            line: expr.span.line,
                        });
                        // Write the new value (now in old_tmp) back to $arr[$key]
                        self.op_array.emit(Op {
                            opcode: OpCode::ArraySetIncDec,
                            op1: arr_op,
                            op2: OperandType::Tmp(old_tmp),
                            result: idx_op,
                            line: expr.span.line,
                        });
                        // Pre returns new value (old_tmp); Post returns old (new_tmp).
                        return match op {
                            UnaryOp::PostIncrement | UnaryOp::PostDecrement => {
                                Ok(OperandType::Tmp(new_tmp))
                            }
                            _ => Ok(OperandType::Tmp(old_tmp)),
                        };
                    }

                    if let ExprKind::PropertyAccess {
                        object, property, ..
                    } = &operand.kind
                    {
                        let obj_op =
                            self.compile_obj_write_base_mode(object, crate::fetch_w::DimFetch::Rw)?;
                        // Property name: a literal identifier, or an expression
                        // evaluated once ($obj->$name++, $obj->{'a'}++).
                        let name_op = match &property.kind {
                            ExprKind::Identifier(name) if !name.is_empty() => {
                                let idx = self
                                    .op_array
                                    .add_literal(Value::String(PhpString::from_vec(name.clone())));
                                OperandType::Const(idx)
                            }
                            _ => {
                                let v = self.compile_expr(property)?;
                                let t = self.op_array.alloc_temp();
                                self.op_array.emit(Op {
                                    opcode: OpCode::Assign,
                                    op1: OperandType::Tmp(t),
                                    op2: v,
                                    result: OperandType::Unused,
                                    line: expr.span.line,
                                });
                                OperandType::Tmp(t)
                            }
                        };
                        {
                            // Fetch current value
                            let old_tmp = self.op_array.alloc_temp();
                            self.op_array.emit(Op {
                                opcode: OpCode::PropertyGetIncDec,
                                op1: obj_op,
                                op2: name_op,
                                result: OperandType::Tmp(old_tmp),
                                line: expr.span.line,
                            });
                            // Increment/decrement
                            let new_tmp = self.op_array.alloc_temp();
                            let inc_opcode = match op {
                                UnaryOp::PostIncrement | UnaryOp::PreIncrement => {
                                    OpCode::PostIncrement
                                }
                                _ => OpCode::PostDecrement,
                            };
                            self.op_array.emit(Op {
                                opcode: inc_opcode,
                                op1: OperandType::Tmp(old_tmp),
                                op2: OperandType::Unused,
                                result: OperandType::Tmp(new_tmp),
                                line: expr.span.line,
                            });
                            // Write back to property (old_tmp now contains new value after PostInc/Dec modified it)
                            self.op_array.emit(Op {
                                opcode: OpCode::PropertySet,
                                op1: obj_op,
                                op2: OperandType::Tmp(old_tmp),
                                result: name_op,
                                line: expr.span.line,
                            });
                            // For post-inc/dec, return old value (new_tmp); for pre, return new value (old_tmp)
                            return match op {
                                UnaryOp::PostIncrement | UnaryOp::PostDecrement => {
                                    Ok(OperandType::Tmp(new_tmp))
                                }
                                _ => Ok(OperandType::Tmp(old_tmp)),
                            };
                        }
                    }

                    // Increment/decrement on a static property: self::$n++, C::$n--, etc.
                    // Without write-back here the increment would land on a throwaway
                    // temp and the static property would never change.
                    if let ExprKind::StaticPropertyAccess { class, property } = &operand.kind {
                        let class_operand = self.compile_static_class_operand(class)?;
                        let prop_idx = self
                            .op_array
                            .add_literal(Value::String(PhpString::from_vec(property.clone())));
                        let old_tmp = self.op_array.alloc_temp();
                        self.op_array.emit(Op {
                            opcode: OpCode::StaticPropFetchRW,
                            op1: class_operand,
                            op2: OperandType::Const(prop_idx),
                            result: OperandType::Tmp(old_tmp),
                            line: expr.span.line,
                        });
                        let new_tmp = self.op_array.alloc_temp();
                        let inc_opcode = match op {
                            UnaryOp::PostIncrement | UnaryOp::PreIncrement => OpCode::PostIncrement,
                            _ => OpCode::PostDecrement,
                        };
                        self.op_array.emit(Op {
                            opcode: inc_opcode,
                            op1: OperandType::Tmp(old_tmp),
                            op2: OperandType::Unused,
                            result: OperandType::Tmp(new_tmp),
                            line: expr.span.line,
                        });
                        // old_tmp now holds the new value (PostInc/Dec wrote it to op1)
                        self.op_array.emit(Op {
                            opcode: OpCode::StaticPropSet,
                            op1: class_operand,
                            op2: OperandType::Tmp(old_tmp),
                            result: OperandType::Const(prop_idx),
                            line: expr.span.line,
                        });
                        return match op {
                            UnaryOp::PostIncrement | UnaryOp::PostDecrement => {
                                Ok(OperandType::Tmp(new_tmp))
                            }
                            _ => Ok(OperandType::Tmp(old_tmp)),
                        };
                    }

                    // Increment/decrement on a dynamic static property: self::$$x++
                    if let ExprKind::DynamicStaticPropertyAccess { class, property } = &operand.kind
                    {
                        let class_operand = self.compile_static_class_operand(class)?;
                        let prop_op = self.compile_expr(property)?;
                        let old_tmp = self.op_array.alloc_temp();
                        self.op_array.emit(Op {
                            opcode: OpCode::StaticPropFetchRW,
                            op1: class_operand,
                            op2: prop_op,
                            result: OperandType::Tmp(old_tmp),
                            line: expr.span.line,
                        });
                        let new_tmp = self.op_array.alloc_temp();
                        let inc_opcode = match op {
                            UnaryOp::PostIncrement | UnaryOp::PreIncrement => OpCode::PostIncrement,
                            _ => OpCode::PostDecrement,
                        };
                        self.op_array.emit(Op {
                            opcode: inc_opcode,
                            op1: OperandType::Tmp(old_tmp),
                            op2: OperandType::Unused,
                            result: OperandType::Tmp(new_tmp),
                            line: expr.span.line,
                        });
                        self.op_array.emit(Op {
                            opcode: OpCode::StaticPropSet,
                            op1: class_operand,
                            op2: OperandType::Tmp(old_tmp),
                            result: prop_op,
                            line: expr.span.line,
                        });
                        return match op {
                            UnaryOp::PostIncrement | UnaryOp::PostDecrement => {
                                Ok(OperandType::Tmp(new_tmp))
                            }
                            _ => Ok(OperandType::Tmp(old_tmp)),
                        };
                    }
                }

                let val = self.compile_expr(operand)?;
                let tmp = self.op_array.alloc_temp();
                let opcode = match (op, prefix) {
                    (UnaryOp::Negate, true) => OpCode::Negate,
                    (UnaryOp::BooleanNot, true) => OpCode::BooleanNot,
                    (UnaryOp::BitwiseNot, true) => OpCode::BitwiseNot,
                    (UnaryOp::PreIncrement, true) => OpCode::PreIncrement,
                    (UnaryOp::PreDecrement, true) => OpCode::PreDecrement,
                    (UnaryOp::PostIncrement, false) => OpCode::PostIncrement,
                    (UnaryOp::PostDecrement, false) => OpCode::PostDecrement,
                    _ => OpCode::Nop,
                };
                self.op_array.emit(Op {
                    opcode,
                    op1: val,
                    op2: OperandType::Unused,
                    result: OperandType::Tmp(tmp),
                    line: expr.span.line,
                });
                Ok(OperandType::Tmp(tmp))
            }

            ExprKind::FunctionCall { name, .. } if matches!(&name.kind, ExprKind::String(s) if s.first() == Some(&b'\\')) => {
                self.compile_fq_string_call(expr)
            }
            ExprKind::FunctionCall { name, args } => {
                // Only this call's own result is discarded, not its arguments'.
                let discard_result = std::mem::take(&mut self.is_discarding_result);
                // Special case: compact() - build array from variable names
                if let ExprKind::Identifier(n) = &name.kind {
                    let func_lower: Vec<u8> = n.iter().map(|b| b.to_ascii_lowercase()).collect();
                    let unqualified = func_lower.strip_prefix(b"\\").unwrap_or(&func_lower);
                    if unqualified == b"get_defined_vars" && args.is_empty() {
                        // Reads the calling scope's variables.
                        let tmp = self.op_array.alloc_temp();
                        self.op_array.emit(Op {
                            opcode: OpCode::GetDefinedVars,
                            op1: OperandType::Unused,
                            op2: OperandType::Unused,
                            result: OperandType::Tmp(tmp),
                            line: expr.span.line,
                        });
                        return Ok(OperandType::Tmp(tmp));
                    }
                    if func_lower == b"extract" && !args.is_empty() {
                        // extract($array [, $flags [, $prefix]])
                        // Compile the array argument
                        let arr_operand = self.compile_expr(&args[0].value)?;
                        // Build a [flags, prefix] array in a tmp so the opcode
                        // can access both without growing the Op struct.
                        let meta_tmp = self.op_array.alloc_temp();
                        self.op_array.emit(Op {
                            opcode: OpCode::ArrayNew,
                            op1: OperandType::Unused,
                            op2: OperandType::Unused,
                            result: OperandType::Tmp(meta_tmp),
                            line: expr.span.line,
                        });
                        // Push flags (default 0 == EXTR_OVERWRITE)
                        let flags = if args.len() > 1 {
                            self.compile_expr(&args[1].value)?
                        } else {
                            let idx = self.op_array.add_literal(Value::Long(0));
                            OperandType::Const(idx)
                        };
                        self.op_array.emit(Op {
                            opcode: OpCode::ArrayAppend,
                            op1: OperandType::Tmp(meta_tmp),
                            op2: flags,
                            result: OperandType::Tmp(meta_tmp),
                            line: expr.span.line,
                        });
                        // Push prefix (null when not passed)
                        let prefix = if args.len() > 2 {
                            self.compile_expr(&args[2].value)?
                        } else {
                            let idx = self.op_array.add_literal(Value::Null);
                            OperandType::Const(idx)
                        };
                        self.op_array.emit(Op {
                            opcode: OpCode::ArrayAppend,
                            op1: OperandType::Tmp(meta_tmp),
                            op2: prefix,
                            result: OperandType::Tmp(meta_tmp),
                            line: expr.span.line,
                        });
                        let tmp = self.op_array.alloc_temp();
                        self.op_array.emit(Op {
                            opcode: OpCode::Extract,
                            op1: arr_operand,
                            op2: OperandType::Tmp(meta_tmp),
                            result: OperandType::Tmp(tmp),
                            line: expr.span.line,
                        });
                        return Ok(OperandType::Tmp(tmp));
                    }
                    if func_lower == b"compact"
                        && !args.is_empty()
                        && args.iter().all(|a| a.name.is_none() && !a.unpack)
                    {
                        // Make sure literal variable names have CV slots.
                        fn collect_names(e: &Expr, out: &mut Vec<Vec<u8>>) {
                            match &e.kind {
                                ExprKind::String(s) => out.push(s.clone()),
                                ExprKind::Array(elems) => {
                                    for el in elems {
                                        collect_names(&el.value, out);
                                    }
                                }
                                _ => {}
                            }
                        }
                        let mut names = Vec::new();
                        for arg in args {
                            collect_names(&arg.value, &mut names);
                        }
                        for n in &names {
                            if n.as_slice() != b"this" {
                                self.op_array.get_or_create_cv(n);
                            }
                        }
                        let args_tmp = self.op_array.alloc_temp();
                        self.op_array.emit(Op {
                            opcode: OpCode::ArrayNew,
                            op1: OperandType::Unused,
                            op2: OperandType::Unused,
                            result: OperandType::Tmp(args_tmp),
                            line: expr.span.line,
                        });
                        for arg in args {
                            let v = self.compile_expr(&arg.value)?;
                            self.op_array.emit(Op {
                                opcode: OpCode::ArrayAppend,
                                op1: OperandType::Tmp(args_tmp),
                                op2: v,
                                result: OperandType::Tmp(args_tmp),
                                line: expr.span.line,
                            });
                        }
                        let arr_tmp = self.op_array.alloc_temp();
                        self.op_array.emit(Op {
                            opcode: OpCode::CompactDyn,
                            op1: OperandType::Tmp(args_tmp),
                            op2: OperandType::Unused,
                            result: OperandType::Tmp(arr_tmp),
                            line: expr.span.line,
                        });
                        return Ok(OperandType::Tmp(arr_tmp));
                    }
                }

                // Special case: assert(expr) with one positional arg injects the source string
                // as a second argument at compile time (PHP behavior).
                if let ExprKind::Identifier(n) = &name.kind {
                    let func_lower: Vec<u8> = n.iter().map(|b| b.to_ascii_lowercase()).collect();
                    // `\assert(...)` is the same compile-time special case.
                    let func_lower: Vec<u8> = func_lower
                        .strip_prefix(b"\\")
                        .map(|r| r.to_vec())
                        .unwrap_or(func_lower);
                    if func_lower == b"assert"
                        && args.len() == 1
                        && args[0].name.is_none()
                        && !args[0].unpack
                    {
                        let expr_str = crate::ast_export::export_expr(&args[0].value);
                        let assert_str = format!("assert({})", expr_str);
                        // Emit: InitFCall("assert", 2)
                        let assert_name_idx = self
                            .op_array
                            .add_literal(Value::String(PhpString::from_bytes(b"assert")));
                        let arg_count_idx = self.op_array.add_literal(Value::Long(2));
                        self.op_array.emit(Op {
                            opcode: OpCode::InitFCall,
                            op1: OperandType::Const(assert_name_idx),
                            op2: OperandType::Const(arg_count_idx),
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                        // SendVal(expr, 0)
                        let val = self.compile_expr(&args[0].value)?;
                        let pos0 = self.op_array.add_literal(Value::Long(0));
                        self.op_array.emit(Op {
                            opcode: OpCode::SendVal,
                            op1: val,
                            op2: OperandType::Const(pos0),
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                        // SendVal(assert_str, 1)
                        let str_idx =
                            self.op_array
                                .add_literal(Value::String(PhpString::from_bytes(
                                    assert_str.as_bytes(),
                                )));
                        let pos1 = self.op_array.add_literal(Value::Long(1));
                        self.op_array.emit(Op {
                            opcode: OpCode::SendVal,
                            op1: OperandType::Const(str_idx),
                            op2: OperandType::Const(pos1),
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                        // DoFCall
                        let tmp = self.op_array.alloc_temp();
                        self.op_array.emit(Op {
                            opcode: OpCode::DoFCall,
                            op1: OperandType::Unused,
                            op2: OperandType::Unused,
                            result: OperandType::Tmp(tmp),
                            line: expr.span.line,
                        });
                        return Ok(OperandType::Tmp(tmp));
                    }
                }

                // Compile the function name
                let resolved_name = match &name.kind {
                    ExprKind::Identifier(n) => Some(self.resolve_function_name(n)),
                    _ => None,
                };
                let name_op = match &resolved_name {
                    Some(resolved) => {
                        let idx = self
                            .op_array
                            .add_literal(Value::String(PhpString::from_vec(resolved.clone())));
                        OperandType::Const(idx)
                    }
                    None => self.compile_expr(name)?,
                };

                // Init function call
                let arg_count_idx = self.op_array.add_literal(Value::Long(args.len() as i64));
                let no_fallback = match (&name.kind, &resolved_name) {
                    (ExprKind::Identifier(n), Some(r)) => self.fcall_no_fallback_flag(n, r),
                    _ => OperandType::Unused,
                };
                self.op_array.emit(Op {
                    opcode: OpCode::InitFCall,
                    op1: name_op,
                    op2: OperandType::Const(arg_count_idx),
                    result: no_fallback,
                    line: expr.span.line,
                });

                // Send arguments (pass function name for by-ref detection)
                let func_name_for_ref = if let Some(ref r) = resolved_name {
                    Some(r.as_slice())
                } else if let ExprKind::Identifier(ref n) = name.kind {
                    Some(n.as_slice())
                } else {
                    None
                };
                self.compile_send_args_with_name(args, expr.span.line, func_name_for_ref)?;

                // Do the call (op1 signals if result is being discarded for #[\NoDiscard])
                let tmp = self.op_array.alloc_temp();
                let discard_flag = if discard_result {
                    let idx = self.op_array.add_literal(Value::True);
                    OperandType::Const(idx)
                } else {
                    OperandType::Unused
                };
                self.op_array.emit(Op {
                    opcode: OpCode::DoFCall,
                    op1: discard_flag,
                    op2: OperandType::Unused,
                    result: OperandType::Tmp(tmp),
                    line: expr.span.line,
                });

                Ok(OperandType::Tmp(tmp))
            }

            ExprKind::Print(inner) => {
                let val = self.compile_expr(inner)?;
                let tmp = self.op_array.alloc_temp();
                self.op_array.emit(Op {
                    opcode: OpCode::Print,
                    op1: val,
                    op2: OperandType::Unused,
                    result: OperandType::Tmp(tmp),
                    line: expr.span.line,
                });
                Ok(OperandType::Tmp(tmp))
            }

            ExprKind::Exit(value) => {
                let exit_val = if let Some(val_expr) = value {
                    self.compile_expr(val_expr)?
                } else {
                    let zero = self.op_array.add_literal(Value::Long(0));
                    OperandType::Const(zero)
                };
                // Use ExitOp which checks at runtime: int values set exit code,
                // string values are echoed. Also signals script termination.
                self.op_array.emit(Op {
                    opcode: OpCode::ExitOp,
                    op1: exit_val,
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line: expr.span.line,
                });
                let zero = self.op_array.add_literal(Value::Long(0));
                self.op_array.emit(Op {
                    opcode: OpCode::Return,
                    op1: OperandType::Const(zero),
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line: expr.span.line,
                });
                let idx = self.op_array.add_literal(Value::Null);
                Ok(OperandType::Const(idx))
            }

            ExprKind::Cast(cast_type, inner) => {
                if matches!(cast_type, CastType::Unset) {
                    return Err(Self::unset_cast_error(expr.span.line));
                }
                if matches!(cast_type, CastType::Void) {
                    // (void) cast: evaluate inner expression for side effects, discard result
                    let _val = self.compile_expr(inner)?;
                    // Just return a Null literal - the expression was already evaluated
                    let null_idx = self.op_array.add_literal(Value::Null);
                    return Ok(OperandType::Const(null_idx));
                }
                let val = self.compile_expr(inner)?;
                let tmp = self.op_array.alloc_temp();
                let opcode = match cast_type {
                    CastType::Int => OpCode::CastInt,
                    CastType::Float => OpCode::CastFloat,
                    CastType::String => OpCode::CastString,
                    CastType::Bool => OpCode::CastBool,
                    CastType::Array => OpCode::CastArray,
                    CastType::Object => OpCode::CastObject,
                    CastType::Unset | CastType::Void => unreachable!(), // handled above
                };
                self.op_array.emit(Op {
                    opcode,
                    op1: val,
                    op2: OperandType::Unused,
                    result: OperandType::Tmp(tmp),
                    line: expr.span.line,
                });
                Ok(OperandType::Tmp(tmp))
            }

            ExprKind::Ternary {
                condition,
                if_true,
                if_false,
            } => {
                let cond = self.compile_expr(condition)?;
                let result_tmp = self.op_array.alloc_temp();

                let jmp_false = self.op_array.emit(Op {
                    opcode: OpCode::JmpZ,
                    op1: cond,
                    op2: OperandType::JmpTarget(0),
                    result: OperandType::Unused,
                    line: expr.span.line,
                });

                let true_val = if let Some(true_expr) = if_true {
                    self.compile_expr(true_expr)?
                } else {
                    cond // short ternary: $a ?: $b
                };
                self.op_array.emit(Op {
                    opcode: OpCode::Assign,
                    op1: OperandType::Tmp(result_tmp),
                    op2: true_val,
                    result: OperandType::Unused,
                    line: expr.span.line,
                });
                let jmp_end = self.op_array.emit(Op {
                    opcode: OpCode::Jmp,
                    op1: OperandType::JmpTarget(0),
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line: expr.span.line,
                });

                let false_start = self.op_array.current_offset();
                self.op_array.patch_jump(jmp_false, false_start);

                let false_val = self.compile_expr(if_false)?;
                self.op_array.emit(Op {
                    opcode: OpCode::Assign,
                    op1: OperandType::Tmp(result_tmp),
                    op2: false_val,
                    result: OperandType::Unused,
                    line: expr.span.line,
                });

                let end = self.op_array.current_offset();
                self.op_array.patch_jump(jmp_end, end);

                Ok(OperandType::Tmp(result_tmp))
            }

            ExprKind::Pipe { value, callable } => self.compile_pipe(expr, value, callable),
            ExprKind::ShellExec(call) => self.compile_expr(call),

            ExprKind::NullCoalesce { left, right } => {
                // $a ?? $b: if $a is not null, use $a, else use $b
                // Suppress warnings for the left side (undefined keys, undefined vars, etc.)
                self.op_array.emit(Op {
                    opcode: OpCode::ErrorSuppress,
                    op1: OperandType::Unused,
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line: expr.span.line,
                });

                let result_tmp = self.op_array.alloc_temp();

                // For ArrayAccess on objects, $obj[key] ?? default should call
                // offsetExists first, then offsetGet only if exists returns true
                if matches!(left.kind, ExprKind::ArrayAccess { .. }) {
                    // Flatten the chain of ArrayAccess nodes
                    let mut chain: Vec<&Expr> = Vec::new();
                    let mut base_expr: &Expr = left;
                    while let ExprKind::ArrayAccess { array, index } = &base_expr.kind {
                        if let Some(idx_expr) = index {
                            chain.push(idx_expr);
                        }
                        base_expr = array;
                    }
                    chain.reverse();

                    let mut jmp_to_right: Vec<usize> = Vec::new();
                    let base_op = if Self::is_static_prop_expr(base_expr) {
                        let (t, j) = self.compile_static_prop_quiet(base_expr)?;
                        jmp_to_right.push(j as usize);
                        OperandType::Tmp(t)
                    } else {
                        self.compile_expr(base_expr)?
                    };
                    let base_op = self.snapshot_cv(base_op, expr.span.line);
                    let mut current = base_op;

                    for idx_expr in chain.iter() {
                        let idx = self.compile_key_unsilenced(idx_expr, true)?;
                        // (snapshotted while unsilenced)

                        // Check offsetExists first (FETCH_DIM_IS)
                        let isset_tmp = self.op_array.alloc_temp();
                        self.op_array.emit(Op {
                            opcode: OpCode::ArrayIssetFetch,
                            op1: current,
                            op2: idx,
                            result: OperandType::Tmp(isset_tmp),
                            line: expr.span.line,
                        });
                        let jmp_pos = self.op_array.ops.len();
                        jmp_to_right.push(jmp_pos);
                        self.op_array.emit(Op {
                            opcode: OpCode::JmpZ,
                            op1: OperandType::Tmp(isset_tmp),
                            op2: OperandType::JmpTarget(0), // patched later
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });

                        // Get the value (only reached if exists)
                        let get_tmp = self.op_array.alloc_temp();
                        self.op_array.emit(Op {
                            opcode: OpCode::ArrayGet,
                            op1: current,
                            op2: idx,
                            result: OperandType::Tmp(get_tmp),
                            line: expr.span.line,
                        });
                        current = OperandType::Tmp(get_tmp);
                    }

                    // Final value check: even if key exists, the value might be null
                    let check_tmp = self.op_array.alloc_temp();
                    self.op_array.emit(Op {
                        opcode: OpCode::IssetCheck,
                        op1: current,
                        op2: OperandType::Unused,
                        result: OperandType::Tmp(check_tmp),
                        line: expr.span.line,
                    });
                    let jmp_null_pos = self.op_array.ops.len();
                    jmp_to_right.push(jmp_null_pos);
                    self.op_array.emit(Op {
                        opcode: OpCode::JmpZ,
                        op1: OperandType::Tmp(check_tmp),
                        op2: OperandType::JmpTarget(0), // patched later
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });

                    self.op_array.emit(Op {
                        opcode: OpCode::ErrorRestore,
                        op1: OperandType::Unused,
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });

                    // Not null: use left value
                    self.op_array.emit(Op {
                        opcode: OpCode::Assign,
                        op1: OperandType::Tmp(result_tmp),
                        op2: current,
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });
                    let jmp_end = self.op_array.emit(Op {
                        opcode: OpCode::Jmp,
                        op1: OperandType::JmpTarget(0),
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });

                    // Right side: use default value
                    let right_target = self.op_array.current_offset();
                    for jmp_pos in jmp_to_right {
                        self.op_array.ops[jmp_pos].op2 = OperandType::JmpTarget(right_target);
                    }
                    self.op_array.emit(Op {
                        opcode: OpCode::ErrorRestore,
                        op1: OperandType::Unused,
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });
                    let right_val = self.compile_expr(right)?;
                    self.op_array.emit(Op {
                        opcode: OpCode::Assign,
                        op1: OperandType::Tmp(result_tmp),
                        op2: right_val,
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });

                    let end = self.op_array.current_offset();
                    self.op_array.patch_jump(jmp_end, end);

                    return Ok(OperandType::Tmp(result_tmp));
                }

                // $a->b->c ?? d: property fetches in the chain go through
                // __isset before __get (FETCH_OBJ_IS semantics).
                let mut isset_patches: Vec<u32> = Vec::new();
                let left_val = if matches!(&left.kind, ExprKind::PropertyAccess { .. }) {
                    self.compile_isset_prop_chain(left, expr.span.line, &mut isset_patches)?
                } else if Self::is_static_prop_expr(left) {
                    let (t, j) = self.compile_static_prop_quiet(left)?;
                    isset_patches.push(j);
                    OperandType::Tmp(t)
                } else {
                    self.compile_expr(left)?
                };
                let mut isset_fail_jmp: Option<u32> = None;
                if !isset_patches.is_empty() {
                    let over = self.op_array.emit(Op {
                        opcode: OpCode::Jmp,
                        op1: OperandType::JmpTarget(0),
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });
                    let fail_label = self.op_array.current_offset();
                    for p in &isset_patches {
                        self.op_array.ops[*p as usize].op2 = OperandType::JmpTarget(fail_label);
                    }
                    self.op_array.emit(Op {
                        opcode: OpCode::ErrorRestore,
                        op1: OperandType::Unused,
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });
                    isset_fail_jmp = Some(self.op_array.emit(Op {
                        opcode: OpCode::Jmp,
                        op1: OperandType::JmpTarget(0),
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: expr.span.line,
                    }));
                    let after = self.op_array.current_offset();
                    self.op_array.patch_jump(over, after);
                }
                self.op_array.emit(Op {
                    opcode: OpCode::ErrorRestore,
                    op1: OperandType::Unused,
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line: expr.span.line,
                });

                // Check if left is set (not null and not undef)
                let check_tmp = self.op_array.alloc_temp();
                self.op_array.emit(Op {
                    opcode: OpCode::IssetCheck,
                    op1: left_val,
                    op2: OperandType::Unused,
                    result: OperandType::Tmp(check_tmp),
                    line: expr.span.line,
                });
                // If NOT set (null/undef), jump to use right side
                let jmp_null = self.op_array.emit(Op {
                    opcode: OpCode::JmpZ,
                    op1: OperandType::Tmp(check_tmp),
                    op2: OperandType::JmpTarget(0),
                    result: OperandType::Unused,
                    line: expr.span.line,
                });

                // Not null: use left
                self.op_array.emit(Op {
                    opcode: OpCode::Assign,
                    op1: OperandType::Tmp(result_tmp),
                    op2: left_val,
                    result: OperandType::Unused,
                    line: expr.span.line,
                });
                let jmp_end = self.op_array.emit(Op {
                    opcode: OpCode::Jmp,
                    op1: OperandType::JmpTarget(0),
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line: expr.span.line,
                });

                // Null: use right
                let null_target = self.op_array.current_offset();
                self.op_array.patch_jump(jmp_null, null_target);
                if let Some(j) = isset_fail_jmp {
                    self.op_array.patch_jump(j, null_target);
                }
                let right_val = self.compile_expr(right)?;
                self.op_array.emit(Op {
                    opcode: OpCode::Assign,
                    op1: OperandType::Tmp(result_tmp),
                    op2: right_val,
                    result: OperandType::Unused,
                    line: expr.span.line,
                });

                let end = self.op_array.current_offset();
                self.op_array.patch_jump(jmp_end, end);

                Ok(OperandType::Tmp(result_tmp))
            }

            ExprKind::Array(elements) => {
                let arr_tmp = self.op_array.alloc_temp();
                self.op_array.emit(Op {
                    opcode: OpCode::ArrayNew,
                    op1: OperandType::Unused,
                    op2: OperandType::Unused,
                    result: OperandType::Tmp(arr_tmp),
                    line: expr.span.line,
                });
                let elems_tmp_start = self.op_array.temp_count;
                let lits_start = self.op_array.literals.len();

                for elem in elements {
                    if elem.key.is_none()
                        && matches!(elem.value.kind, ExprKind::Null)
                        && elem.value.span.start == elem.value.span.end
                    {
                        return Err(CompileError {
                            message: "Cannot use empty array elements in arrays".into(),
                            line: elem.value.span.line,
                        });
                    }
                    if elem.unpack {
                        let val = self.compile_expr(&elem.value)?;
                        // Check for compile-time detectable non-array/non-traversable types
                        if let OperandType::Const(idx) = val {
                            if let Some(lit_val) = self.op_array.literals.get(idx as usize) {
                                let type_name: Option<&str> = match lit_val {
                                    Value::Long(_) => Some("int"),
                                    Value::Double(_) => Some("float"),
                                    Value::String(_) => Some("string"),
                                    Value::True => Some("true"),
                                    Value::False => Some("false"),
                                    Value::Null => Some("null"),
                                    _ => None,
                                };
                                if let Some(tname) = type_name {
                                    return Err(CompileError {
                                        message: format!(
                                            "Only arrays and Traversables can be unpacked, {} given",
                                            tname
                                        ),
                                        line: expr.span.line,
                                    });
                                }
                            }
                        }
                        // ...$arr - spread array elements into this array
                        self.op_array.emit(Op {
                            opcode: OpCode::ArraySpread,
                            op1: OperandType::Tmp(arr_tmp),
                            op2: val,
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                    } else if elem.by_ref {
                        // [&$var] or ['k' => &$var] — store reference into array slot
                        // Compile the value as a CV (must be a variable) and make it a reference
                        if let ExprKind::PropertyAccess {
                            object,
                            property,
                            nullsafe: false,
                        } = &elem.value.kind
                        {
                            // [&$obj->prop]: the element binds to the property slot.
                            // The key is compiled first (zend_compile_array).
                            let key = match &elem.key {
                                Some(k) => Some(self.compile_expr(k)?),
                                None => None,
                            };
                            let ref_tmp =
                                self.compile_property_ref(object, property, expr.span.line)?;
                            if let Some(key) = key {
                                self.op_array.emit(Op {
                                    opcode: OpCode::ArraySetRef,
                                    op1: OperandType::Tmp(arr_tmp),
                                    op2: OperandType::Tmp(ref_tmp),
                                    result: key,
                                    line: expr.span.line,
                                });
                            } else {
                                self.op_array.emit(Op {
                                    opcode: OpCode::ArrayAppendRef,
                                    op1: OperandType::Tmp(arr_tmp),
                                    op2: OperandType::Tmp(ref_tmp),
                                    result: OperandType::Unused,
                                    line: expr.span.line,
                                });
                            }
                            continue;
                        }
                        let key = match &elem.key {
                            Some(k) => Some(self.compile_expr(k)?),
                            None => None,
                        };
                        // [&$a[k]]: the element binds to the (created) dimension.
                        if let ExprKind::ArrayAccess { array, index } = &elem.value.kind {
                            let ref_tmp =
                                self.compile_dim_ref(array, index.as_deref(), expr.span.line)?;
                            self.op_array.emit(Op {
                                opcode: if key.is_some() {
                                    OpCode::ArraySetRef
                                } else {
                                    OpCode::ArrayAppendRef
                                },
                                op1: OperandType::Tmp(arr_tmp),
                                op2: OperandType::Tmp(ref_tmp),
                                result: key.unwrap_or(OperandType::Unused),
                                line: expr.span.line,
                            });
                            continue;
                        }
                        let val = self.compile_expr(&elem.value)?;
                        if let OperandType::Cv(cv) = val {
                            self.op_array.emit(Op {
                                opcode: OpCode::MakeRef,
                                op1: OperandType::Cv(cv),
                                op2: OperandType::Unused,
                                result: OperandType::Unused,
                                line: expr.span.line,
                            });
                            if let Some(key) = key {
                                self.op_array.emit(Op {
                                    opcode: OpCode::ArraySetRef,
                                    op1: OperandType::Tmp(arr_tmp),
                                    op2: OperandType::Cv(cv),
                                    result: key,
                                    line: expr.span.line,
                                });
                            } else {
                                self.op_array.emit(Op {
                                    opcode: OpCode::ArrayAppendRef,
                                    op1: OperandType::Tmp(arr_tmp),
                                    op2: OperandType::Cv(cv),
                                    result: OperandType::Unused,
                                    line: expr.span.line,
                                });
                            }
                        } else {
                            // Fallback: not a simple variable, treat as regular value
                            if let Some(key) = key {
                                self.op_array.emit(Op {
                                    opcode: OpCode::ArraySet,
                                    op1: OperandType::Tmp(arr_tmp),
                                    op2: val,
                                    result: key,
                                    line: expr.span.line,
                                });
                            } else {
                                self.op_array.emit(Op {
                                    opcode: OpCode::ArrayAppend,
                                    op1: OperandType::Tmp(arr_tmp),
                                    op2: val,
                                    result: OperandType::Unused,
                                    line: expr.span.line,
                                });
                            }
                        }
                    } else if let Some(key_expr) = &elem.key {
                        let key = self.compile_expr(key_expr)?;
                        let val = self.compile_expr(&elem.value)?;
                        self.op_array.emit(Op {
                            opcode: OpCode::ArraySet,
                            op1: OperandType::Tmp(arr_tmp),
                            op2: val,
                            result: key,
                            line: expr.span.line,
                        });
                    } else {
                        let val = self.compile_expr(&elem.value)?;
                        self.op_array.emit(Op {
                            opcode: OpCode::ArrayAppend,
                            op1: OperandType::Tmp(arr_tmp),
                            op2: val,
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                    }
                }
                // A compile-time constant array (zend_try_ct_eval_array) keeps
                // the strings of the AST, which are not interned (one-byte
                // and empty strings aside); only literal operands are.
                if Self::eval_const_expr(expr).is_some() {
                    for lit in &self.op_array.literals[lits_start..] {
                        if let Value::String(s) = lit {
                            s.unmark_interned();
                        }
                    }
                }
                // The element temporaries were copied into the array: release
                // them so the array holds the only reference (PHP moves TMPs
                // into ADD_ARRAY_ELEMENT).
                let elems_tmp_end = self.op_array.temp_count;
                if elems_tmp_end > elems_tmp_start {
                    self.op_array.emit(Op {
                        opcode: OpCode::FreeTmps,
                        op1: OperandType::Tmp(elems_tmp_start),
                        op2: OperandType::Tmp(elems_tmp_end),
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });
                }

                Ok(OperandType::Tmp(arr_tmp))
            }

            ExprKind::ArrayAccess { array, index } => {
                self.chain_base = true;
                let arr = self.compile_expr(array)?;
                if let Some(idx_expr) = index {
                    let idx = self.compile_expr(idx_expr)?;
                    if self.in_const_expr {
                        // No ArrayAccess::offsetGet() in a constant expression.
                        let dim = self.op_array.add_literal(Value::True);
                        self.op_array.emit(Op {
                            opcode: OpCode::ConstExprPropCheck,
                            op1: arr,
                            op2: OperandType::Const(dim),
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                    }
                    let tmp = self.op_array.alloc_temp();
                    self.op_array.emit(Op {
                        opcode: OpCode::ArrayGet,
                        op1: arr,
                        op2: idx,
                        result: OperandType::Tmp(tmp),
                        // FETCH_DIM_R is emitted once the key is compiled.
                        line: self.zend_lineno.max(expr.span.line),
                    });
                    Ok(OperandType::Tmp(tmp))
                } else {
                    Err(CompileError {
                        message: "Cannot use [] for reading".into(),
                        line: expr.span.line,
                    })
                }
            }

            ExprKind::InterpolatedString(parts) => {
                // Compile each part and concatenate
                let mut result: Option<OperandType> = None;
                // Whether the result is one expression yet (not a string)
                let mut lone_expr = false;
                for part in parts {
                    let part_op = match part {
                        // (an empty piece adds nothing to the rope)
                        StringPart::Literal(s) if s.is_empty() && parts.len() > 1 => continue,
                        StringPart::Literal(s) => {
                            let idx = self
                                .op_array
                                .add_literal(Value::String(PhpString::from_vec(s.clone())));
                            OperandType::Const(idx)
                        }
                        StringPart::Expr(e) => self.compile_expr(e)?,
                    };
                    lone_expr = result.is_none() && matches!(part, StringPart::Expr(_));
                    result = Some(if let Some(prev) = result {
                        let tmp = self.op_array.alloc_temp();
                        self.op_array.emit(Op {
                            opcode: OpCode::Concat,
                            op1: prev,
                            op2: part_op,
                            result: OperandType::Tmp(tmp),
                            line: expr.span.line,
                        });
                        OperandType::Tmp(tmp)
                    } else {
                        part_op
                    });
                }
                if let (true, Some(op)) = (lone_expr, result) {
                    let tmp = self.op_array.alloc_temp();
                    self.op_array.emit(Op {
                        opcode: OpCode::CastString,
                        op1: op,
                        op2: OperandType::Unused,
                        result: OperandType::Tmp(tmp),
                        line: expr.span.line,
                    });
                    return Ok(OperandType::Tmp(tmp));
                }
                Ok(result.unwrap_or_else(|| {
                    let idx = self.op_array.add_literal(Value::String(PhpString::empty()));
                    OperandType::Const(idx)
                }))
            }

            ExprKind::Suppress(inner) => {
                // @ operator: suppress error reporting during expression
                // evaluation. A Const op1 marks a user `@` (BEGIN_SILENCE) as
                // opposed to the engine's internal silencing.
                let marker = self.op_array.add_literal(Value::Long(1));
                self.op_array.emit(Op {
                    opcode: OpCode::ErrorSuppress,
                    op1: OperandType::Const(marker),
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line: expr.span.line,
                });
                let result = self.compile_expr(inner)?;
                // Store result in a temp so we can restore error reporting before returning
                let tmp = self.op_array.alloc_temp();
                self.op_array.emit(Op {
                    opcode: OpCode::Assign,
                    op1: OperandType::Tmp(tmp),
                    op2: result,
                    result: OperandType::Unused,
                    line: expr.span.line,
                });
                self.op_array.emit(Op {
                    opcode: OpCode::ErrorRestore,
                    op1: OperandType::Unused,
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line: expr.span.line,
                });
                Ok(OperandType::Tmp(tmp))
            }

            ExprKind::Match { subject, arms } => {
                let subj = self.compile_expr(subject)?;
                let subj_tmp = self.op_array.alloc_temp();
                self.op_array.emit(Op {
                    opcode: OpCode::Assign,
                    op1: OperandType::Tmp(subj_tmp),
                    op2: subj,
                    result: OperandType::Unused,
                    line: expr.span.line,
                });

                let result_tmp = self.op_array.alloc_temp();
                let mut end_jumps = Vec::new();

                for arm in arms {
                    if let Some(conditions) = &arm.conditions {
                        // Non-default arm: check each condition with ===
                        let mut arm_match_jumps = Vec::new();
                        for cond in conditions {
                            let cond_val = self.compile_expr(cond)?;
                            let cmp_tmp = self.op_array.alloc_temp();
                            self.op_array.emit(Op {
                                opcode: OpCode::Identical,
                                op1: OperandType::Tmp(subj_tmp),
                                op2: cond_val,
                                result: OperandType::Tmp(cmp_tmp),
                                line: expr.span.line,
                            });
                            let jmp = self.op_array.emit(Op {
                                opcode: OpCode::JmpNz,
                                op1: OperandType::Tmp(cmp_tmp),
                                op2: OperandType::JmpTarget(0),
                                result: OperandType::Unused,
                                line: expr.span.line,
                            });
                            arm_match_jumps.push(jmp);
                        }

                        // If none matched, jump to next arm
                        let jmp_next = self.op_array.emit(Op {
                            opcode: OpCode::Jmp,
                            op1: OperandType::JmpTarget(0),
                            op2: OperandType::Unused,
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });

                        // Patch match jumps to here (body start)
                        let body_start = self.op_array.current_offset();
                        for jmp in arm_match_jumps {
                            self.op_array.patch_jump(jmp, body_start);
                        }

                        // Compile body
                        let body_val = self.compile_expr(&arm.body)?;
                        self.op_array.emit(Op {
                            opcode: OpCode::Assign,
                            op1: OperandType::Tmp(result_tmp),
                            op2: body_val,
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                        let jmp_end = self.op_array.emit(Op {
                            opcode: OpCode::Jmp,
                            op1: OperandType::JmpTarget(0),
                            op2: OperandType::Unused,
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                        end_jumps.push(jmp_end);

                        // Patch "next arm" jump
                        let next_arm = self.op_array.current_offset();
                        self.op_array.patch_jump(jmp_next, next_arm);
                    } else {
                        // Default arm
                        let body_val = self.compile_expr(&arm.body)?;
                        self.op_array.emit(Op {
                            opcode: OpCode::Assign,
                            op1: OperandType::Tmp(result_tmp),
                            op2: body_val,
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                        let jmp_end = self.op_array.emit(Op {
                            opcode: OpCode::Jmp,
                            op1: OperandType::JmpTarget(0),
                            op2: OperandType::Unused,
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                        end_jumps.push(jmp_end);
                    }
                }

                // If no default arm was present, throw UnhandledMatchError
                let has_default = arms.iter().any(|a| a.conditions.is_none());
                if !has_default {
                    // Use MatchError opcode to throw UnhandledMatchError with the subject value
                    self.op_array.emit(Op {
                        opcode: OpCode::MatchError,
                        op1: OperandType::Tmp(subj_tmp),
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });
                }

                let end = self.op_array.current_offset();
                for jmp in end_jumps {
                    self.op_array.patch_jump(jmp, end);
                }

                Ok(OperandType::Tmp(result_tmp))
            }

            ExprKind::Identifier(name) => {
                // `\true` / `\false` / `\null` are the special constants.
                if let Some(op) = self.fq_special_constant(name) {
                    return Ok(op);
                }
                // A bare identifier used as an expression could be a constant
                // Check for well-known constants
                let lower: Vec<u8> = name.iter().map(|b| b.to_ascii_lowercase()).collect();
                // zend_try_ct_eval_const(): inside a namespace (or with a
                // `use const` alias) an unqualified name may name another
                // constant, so only magic and special constants fold.
                let special = matches!(lower.as_slice(), b"true" | b"false" | b"null")
                    || (lower.starts_with(b"__") && lower.ends_with(b"__"));
                let fold_key: &[u8] = if !special
                    && (!self.current_namespace.is_empty() || self.use_const_map.contains_key(name))
                {
                    b""
                } else {
                    &lower
                };
                let val = match fold_key {
                    // Magic constants
                    b"__line__" => Value::Long(expr.span.line as i64),
                    b"__file__" => {
                        if self.source_file.is_empty() {
                            Value::String(PhpString::from_bytes(b"unknown"))
                        } else {
                            Value::String(PhpString::from_vec(self.source_file.clone()))
                        }
                    }
                    b"__dir__" => {
                        if self.source_file.is_empty() {
                            Value::String(PhpString::from_bytes(b"."))
                        } else {
                            // Extract directory from file path
                            let path = String::from_utf8_lossy(&self.source_file);
                            let dir = if let Some(pos) = path.rfind('/') {
                                &path[..pos]
                            } else if let Some(pos) = path.rfind('\\') {
                                &path[..pos]
                            } else {
                                "."
                            };
                            Value::String(PhpString::from_string(dir.to_string()))
                        }
                    }
                    b"__property__" => {
                        // Inside a property hook (op_array named `$prop::get` /
                        // `$prop::set`) this is the property name, else "".
                        let n = &self.op_array.name;
                        let prop: &[u8] = if n.len() > 6
                            && n[0] == b'$'
                            && (n.ends_with(b"::get") || n.ends_with(b"::set"))
                        {
                            &n[1..n.len() - 5]
                        } else {
                            // (a property declaration's constant expression)
                            &self.const_property_name
                        };
                        Value::String(PhpString::from_vec(prop.to_vec()))
                    }
                    b"__function__" => {
                        // For closures, __FUNCTION__ is the canonical display name
                        // (e.g. {closure:file:line}); otherwise it's the bare op_array name.
                        let name = if !self.op_array.display_name.is_empty() {
                            self.op_array.display_name.clone()
                        } else {
                            self.op_array.name.clone()
                        };
                        Value::String(PhpString::from_vec(name))
                    }
                    b"__class__" if self.in_const_expr && self.is_in_trait => {
                        return self.compile_class_name_const(
                            b"self",
                            expr.span.line,
                            expr.span.line,
                        );
                    }
                    b"__class__" => {
                        let class_val = if let Some(ref class_name) = self.current_class {
                            Value::String(PhpString::from_vec(class_name.clone()))
                        } else {
                            Value::String(PhpString::empty())
                        };
                        // Track this literal as a __CLASS__ magic constant for trait patching
                        let idx = self.op_array.add_literal(class_val);
                        self.op_array.class_const_literals.push(idx);
                        return Ok(OperandType::Const(idx));
                    }
                    b"__method__" => {
                        // For closures, __METHOD__ is the canonical display name
                        // (e.g. {closure:Class::method():line}); the closure's
                        // display_name already embeds the surrounding scope so we
                        // don't prepend the class name a second time.
                        let method_val = if !self.op_array.display_name.is_empty() {
                            Value::String(PhpString::from_vec(self.op_array.display_name.clone()))
                        } else if let Some(ref class_name) = self.current_class {
                            let mut method = class_name.clone();
                            method.extend_from_slice(b"::");
                            method.extend_from_slice(&self.op_array.name);
                            Value::String(PhpString::from_vec(method))
                        } else if self.op_array.name.is_empty() || self.op_array.name == b"main" {
                            // __METHOD__ outside of a method returns ""
                            Value::String(PhpString::empty())
                        } else {
                            Value::String(PhpString::from_vec(self.op_array.name.clone()))
                        };
                        // Track this literal as a __CLASS__-derived constant for trait patching (for __METHOD__)
                        let idx = self.op_array.add_literal(method_val);
                        // __METHOD__ also needs patching (class part)
                        // We use a negative convention: store -(idx+1) for __METHOD__ literals
                        // Actually, let's just handle it in the trait patching code
                        return Ok(OperandType::Const(idx));
                    }
                    b"__namespace__" => {
                        Value::String(PhpString::from_vec(self.current_namespace.clone()))
                    }
                    b"__trait__" => match &self.current_class {
                        Some(t) if self.is_in_trait => {
                            Value::String(PhpString::from_vec(t.clone()))
                        }
                        _ => Value::String(PhpString::empty()),
                    },
                    // PHP constants
                    b"php_eol" => Value::String(PhpString::from_bytes(b"\n")),
                    b"php_int_max" => Value::Long(i64::MAX),
                    b"php_int_min" => Value::Long(i64::MIN),
                    b"php_int_size" => Value::Long(8),
                    b"php_float_max" => Value::Double(f64::MAX),
                    b"php_float_min" => Value::Double(f64::MIN_POSITIVE),
                    b"php_float_epsilon" => Value::Double(f64::EPSILON),
                    b"php_maxpathlen" => Value::Long(4096),
                    b"php_os" => Value::String(PhpString::from_bytes(b"Linux")),
                    b"php_os_family" => Value::String(PhpString::from_bytes(b"Linux")),
                    b"php_sapi" => Value::String(PhpString::from_bytes(b"cli")),
                    b"php_version" => Value::String(PhpString::from_bytes(b"8.5.4")),
                    b"php_major_version" => Value::Long(8),
                    b"php_minor_version" => Value::Long(5),
                    b"php_release_version" => Value::Long(4),
                    b"true" => Value::True,
                    b"false" => Value::False,
                    b"null" => Value::Null,
                    b"stdin" => Value::resource(1),
                    b"stdout" => Value::resource(2),
                    b"stderr" => Value::resource(3),
                    b"e_all" => Value::Long(30719), // PHP 8.4+: E_ALL excludes E_STRICT
                    b"e_error" => Value::Long(1),
                    b"e_warning" => Value::Long(2),
                    b"e_notice" => Value::Long(8),
                    // e_strict is not folded at compile time - goes through runtime ConstLookup
                    // so the deprecation warning is emitted
                    b"e_deprecated" => Value::Long(8192),
                    b"php_prefix_separator" | b"directory_separator" => {
                        Value::String(PhpString::from_bytes(if cfg!(windows) {
                            b"\\"
                        } else {
                            b"/"
                        }))
                    }
                    b"path_separator" => Value::String(PhpString::from_bytes(if cfg!(windows) {
                        b";"
                    } else {
                        b":"
                    })),
                    b"str_pad_right" => Value::Long(1),
                    b"str_pad_left" => Value::Long(0),
                    b"str_pad_both" => Value::Long(2),
                    b"sort_regular" => Value::Long(0),
                    b"sort_numeric" => Value::Long(1),
                    b"sort_string" => Value::Long(2),
                    b"sort_flag_case" => Value::Long(8),
                    b"sort_natural" => Value::Long(6),
                    b"sort_locale_string" => Value::Long(5),
                    b"sort_asc" => Value::Long(4),
                    b"sort_desc" => Value::Long(3),
                    b"array_filter_use_both" => Value::Long(1),
                    b"array_filter_use_key" => Value::Long(2),
                    b"array_unique_regular" => Value::Long(0),
                    b"count_normal" => Value::Long(0),
                    b"count_recursive" => Value::Long(1),
                    // Rounding mode constants
                    b"php_round_half_up" => Value::Long(1),
                    b"php_round_half_down" => Value::Long(2),
                    b"php_round_half_even" => Value::Long(3),
                    b"php_round_half_odd" => Value::Long(4),
                    b"php_round_ceiling" => Value::Long(5),
                    b"php_round_floor" => Value::Long(6),
                    b"php_round_toward_zero" => Value::Long(7),
                    b"php_round_away_from_zero" => Value::Long(8),
                    // INI
                    b"ini_user" => Value::Long(1),
                    b"ini_perdir" => Value::Long(2),
                    b"ini_system" => Value::Long(4),
                    b"ini_all" => Value::Long(7),
                    // HTML entity constants
                    b"ent_compat" => Value::Long(2),
                    b"ent_quotes" => Value::Long(3),
                    b"ent_noquotes" => Value::Long(0),
                    b"ent_html401" => Value::Long(0),
                    b"ent_xml1" => Value::Long(16),
                    b"ent_xhtml" => Value::Long(32),
                    b"ent_html5" => Value::Long(48),
                    b"ent_substitute" => Value::Long(8),
                    b"ent_disallowed" => Value::Long(128),
                    // EXTR_ constants
                    b"extr_overwrite" => Value::Long(0),
                    b"extr_skip" => Value::Long(1),
                    b"extr_prefix_same" => Value::Long(2),
                    b"extr_prefix_all" => Value::Long(3),
                    b"extr_prefix_invalid" => Value::Long(4),
                    b"extr_if_exists" => Value::Long(6),
                    b"extr_prefix_if_exists" => Value::Long(5),
                    b"extr_refs" => Value::Long(256),
                    _ => {
                        // Unknown identifier - emit runtime constant lookup
                        // Handle fully-qualified names (starting with \), use aliases, or namespace prefix
                        let qualified = if name.starts_with(b"\\") {
                            // Fully qualified: strip leading \
                            name[1..].to_vec()
                        } else if lower.starts_with(b"namespace\\") {
                            // namespace\foo is a namespace-relative name
                            // Replace "namespace\" with the current namespace
                            let rest = &name[b"namespace\\".len()..];
                            if self.current_namespace.is_empty() {
                                rest.to_vec()
                            } else {
                                let mut result = self.current_namespace.clone();
                                result.push(b'\\');
                                result.extend_from_slice(rest);
                                result
                            }
                        } else if name.contains(&b'\\') {
                            // Qualified name: check use aliases for first part
                            let first_sep = name.iter().position(|&b| b == b'\\').unwrap();
                            let first_part = &name[..first_sep];
                            let first_lower: Vec<u8> =
                                first_part.iter().map(|b| b.to_ascii_lowercase()).collect();
                            if let Some(resolved) = self.use_map.get(&first_lower) {
                                let mut result = resolved.clone();
                                result.extend_from_slice(&name[first_sep..]);
                                result
                            } else {
                                self.prefix_with_namespace(name)
                            }
                        } else {
                            // Unqualified: check use_const_map, then prefix with namespace
                            if let Some(resolved) = self.use_const_map.get(name) {
                                resolved.clone()
                            } else {
                                self.prefix_with_namespace(name)
                            }
                        };
                        // A qualified or imported name has no global
                        // fallback (op2 flags it).
                        let no_fallback = qualified.contains(&b'\\')
                            && (name.contains(&b'\\') || self.use_const_map.contains_key(name));
                        let name_idx = self
                            .op_array
                            .add_literal(Value::String(PhpString::from_vec(qualified)));
                        let tmp = self.op_array.alloc_temp();
                        let flag = if no_fallback {
                            OperandType::Const(self.op_array.add_literal(Value::True))
                        } else {
                            OperandType::Unused
                        };
                        self.op_array.emit(Op {
                            opcode: OpCode::ConstLookup,
                            op1: OperandType::Const(name_idx),
                            op2: flag,
                            result: OperandType::Tmp(tmp),
                            line: expr.span.line,
                        });
                        return Ok(OperandType::Tmp(tmp));
                    }
                };
                let idx = self.op_array.add_literal(val);
                Ok(OperandType::Const(idx))
            }

            ExprKind::New { class, args } => {
                // Get class name
                let mut is_self_new = false;
                let class_name = match &class.kind {
                    ExprKind::Identifier(name) => {
                        if name.eq_ignore_ascii_case(b"self") {
                            // Resolve self at compile time
                            is_self_new = true;
                            self.current_class.clone().unwrap_or(name.clone())
                        } else if name.eq_ignore_ascii_case(b"parent") {
                            self.current_parent_class
                                .clone()
                                .unwrap_or_else(|| b"parent".to_vec())
                        } else if name.eq_ignore_ascii_case(b"static") {
                            b"static".to_vec()
                        } else if name.starts_with(b"__anonymous_class_") {
                            // Anonymous class: look up the NUL-byte PHP name from the map
                            self.anon_class_name_map
                                .get(name.as_slice())
                                .cloned()
                                .unwrap_or_else(|| name.clone())
                        } else {
                            // Resolve through namespace (handles "static" correctly since
                            // resolve_class_name passes it through unchanged)
                            self.resolve_class_name(name)
                        }
                    }
                    _ => {
                        let class_operand = self.compile_expr(class)?;
                        let tmp = self.op_array.alloc_temp();

                        // Create the object with dynamic class name
                        self.op_array.emit(Op {
                            opcode: OpCode::NewObject,
                            op1: class_operand,
                            op2: OperandType::Unused,
                            result: OperandType::Tmp(tmp),
                            line: expr.span.line,
                        });

                        // Call constructor
                        {
                            let constructor_name = self
                                .op_array
                                .add_literal(Value::String(PhpString::from_bytes(b"__construct")));
                            self.op_array.emit(Op {
                                opcode: OpCode::InitMethodCall,
                                op1: OperandType::Tmp(tmp),
                                op2: OperandType::Const(constructor_name),
                                result: OperandType::Unused,
                                line: expr.span.line,
                            });
                            self.compile_send_args(args, expr.span.line)?;
                            let discard_tmp = self.op_array.alloc_temp();
                            self.op_array.emit(Op {
                                opcode: OpCode::DoFCall,
                                op1: OperandType::Unused,
                                op2: OperandType::Unused,
                                result: OperandType::Tmp(discard_tmp),
                                line: expr.span.line,
                            });
                        }

                        return Ok(OperandType::Tmp(tmp));
                    }
                };

                let name_idx = self
                    .op_array
                    .add_literal(Value::String(PhpString::from_vec(class_name)));
                // Track `new self()` for trait patching
                if is_self_new && self.is_in_trait {
                    self.op_array.class_const_literals.push(name_idx);
                }
                let tmp = self.op_array.alloc_temp();

                // Create the object
                self.op_array.emit(Op {
                    opcode: OpCode::NewObject,
                    op1: OperandType::Const(name_idx),
                    op2: OperandType::Unused,
                    result: OperandType::Tmp(tmp),
                    line: expr.span.line,
                });

                // Always call constructor (it may have default params or side effects)
                {
                    let constructor_name = self
                        .op_array
                        .add_literal(Value::String(PhpString::from_bytes(b"__construct")));
                    self.op_array.emit(Op {
                        opcode: OpCode::InitMethodCall,
                        op1: OperandType::Tmp(tmp),
                        op2: OperandType::Const(constructor_name),
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });
                    self.compile_send_args(args, expr.span.line)?;
                    let discard_tmp = self.op_array.alloc_temp();
                    // (on the class name's line, GH-8810)
                    let call_line = if class.span.line > 0 {
                        class.span.line
                    } else {
                        expr.span.line
                    };
                    self.op_array.emit(Op {
                        opcode: OpCode::DoFCall,
                        op1: OperandType::Unused,
                        op2: OperandType::Unused,
                        result: OperandType::Tmp(discard_tmp),
                        line: call_line,
                    });
                }

                Ok(OperandType::Tmp(tmp))
            }

            ExprKind::Instanceof { expr, class } => {
                let obj = self.compile_expr(expr)?;
                let class_name = match &class.kind {
                    ExprKind::Identifier(name) => self.resolve_class_name(name),
                    _ => {
                        // Dynamic class: `$x instanceof $y` (string or object)
                        let class_op = self.compile_expr(class)?;
                        let tmp = self.op_array.alloc_temp();
                        self.op_array.emit(Op {
                            opcode: OpCode::TypeCheck,
                            op1: obj,
                            op2: class_op,
                            result: OperandType::Tmp(tmp),
                            line: expr.span.line,
                        });
                        return Ok(OperandType::Tmp(tmp));
                    }
                };
                let name_idx = self
                    .op_array
                    .add_literal(Value::String(PhpString::from_vec(class_name)));
                let tmp = self.op_array.alloc_temp();
                self.op_array.emit(Op {
                    opcode: OpCode::TypeCheck,
                    op1: obj,
                    op2: OperandType::Const(name_idx),
                    result: OperandType::Tmp(tmp),
                    line: expr.span.line,
                });
                // INSTANCEOF frees a temporary operand.
                if let OperandType::Tmp(t) = obj {
                    self.op_array.emit(Op {
                        opcode: OpCode::FreeTmps,
                        op1: OperandType::Tmp(t),
                        op2: OperandType::Tmp(t + 1),
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });
                }
                Ok(OperandType::Tmp(tmp))
            }

            ExprKind::Include { kind, path } => {
                let path_op = self.compile_expr(path)?;
                let tmp = self.op_array.alloc_temp();
                // Encode include kind in op2: 0=include, 1=include_once, 2=require, 3=require_once
                let kind_val = match kind {
                    IncludeKind::Include => 0u32,
                    IncludeKind::IncludeOnce => 1u32,
                    IncludeKind::Require => 2u32,
                    IncludeKind::RequireOnce => 3u32,
                };
                self.op_array.emit(Op {
                    opcode: OpCode::IncludeFile,
                    op1: path_op,
                    op2: OperandType::Const(kind_val),
                    result: OperandType::Tmp(tmp),
                    line: expr.span.line,
                });
                Ok(OperandType::Tmp(tmp))
            }

            ExprKind::Eval(inner) => {
                let code_op = self.compile_expr(inner)?;
                let result = OperandType::Tmp(self.op_array.alloc_temp());
                self.op_array.emit(Op {
                    opcode: OpCode::Eval,
                    op1: code_op,
                    op2: OperandType::Unused,
                    result,
                    line: expr.span.line,
                });
                Ok(result)
            }

            ExprKind::Isset(exprs) => {
                // isset() returns true if all vars are set and not null
                // Validate: isset() can only take variables, properties, array accesses
                for check_expr in exprs {
                    if matches!(check_expr.kind, ExprKind::ArrayAccess { index: None, .. }) {
                        return Err(CompileError {
                            message: "Cannot use [] for reading".into(),
                            line: expr.span.line,
                        });
                    }
                    let is_valid = matches!(
                        check_expr.kind,
                        ExprKind::Variable(_)
                            | ExprKind::DynamicVariable(_)
                            | ExprKind::PropertyAccess { .. }
                            | ExprKind::StaticPropertyAccess { .. }
                            | ExprKind::DynamicStaticPropertyAccess { .. }
                            | ExprKind::ArrayAccess { .. }
                            | ExprKind::NullCoalesce { .. }
                    );
                    if !is_valid {
                        return Err(CompileError {
                            message: "Cannot use isset() on the result of an expression (you can use \"null !== expression\" instead)".to_string(),
                            line: expr.span.line,
                        });
                    }
                }
                if exprs.len() > 1 {
                    // php-src compiles isset($a, $b, ...) as
                    // isset($a) && isset($b) && ... : short-circuiting, bool result.
                    let mut iter = exprs.iter().rev();
                    let last = iter.next().unwrap();
                    let mut chain = Expr {
                        kind: ExprKind::Isset(vec![last.clone()]),
                        span: expr.span,
                    };
                    for e in iter {
                        chain = Expr {
                            kind: ExprKind::BinaryOp {
                                op: BinaryOp::BooleanAnd,
                                left: Box::new(Expr {
                                    kind: ExprKind::Isset(vec![e.clone()]),
                                    span: expr.span,
                                }),
                                right: Box::new(chain),
                            },
                            span: expr.span,
                        };
                    }
                    return self.compile_expr(&chain);
                }
                // Uses IssetCheck opcode that checks for both Undef and Null
                // Suppress warnings during isset check (e.g., Undefined array key)
                self.op_array.emit(Op {
                    opcode: OpCode::ErrorSuppress,
                    op1: OperandType::Unused,
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line: expr.span.line,
                });
                if exprs.len() == 1 {
                    // Check if expression is a property access -> use PropertyIsset
                    let is_prop_access = matches!(exprs[0].kind, ExprKind::PropertyAccess { .. });
                    if is_prop_access {
                        if let ExprKind::PropertyAccess {
                            object, property, ..
                        } = &exprs[0].kind
                        {
                            // For isset($aa[0]->foo), the inner object might be an ArrayAccess
                            // We need to check offsetExists first before calling offsetGet
                            let obj_operand = if matches!(object.kind, ExprKind::ArrayAccess { .. })
                            {
                                // Compile with isset-aware ArrayAccess handling
                                let mut chain: Vec<&Expr> = Vec::new();
                                let mut base_expr: &Expr = object;
                                while let ExprKind::ArrayAccess { array, index } = &base_expr.kind {
                                    if let Some(idx_expr) = index {
                                        chain.push(idx_expr);
                                    }
                                    base_expr = array;
                                }
                                chain.reverse();

                                let base_op = self.compile_expr(base_expr)?;
                                let result_tmp = self.op_array.alloc_temp();
                                let mut jmp_patches: Vec<usize> = Vec::new();
                                let mut current = base_op;

                                for idx_expr in chain.iter() {
                                    let idx = self.compile_key_unsilenced(idx_expr, false)?;
                                    let isset_tmp = self.op_array.alloc_temp();
                                    self.op_array.emit(Op {
                                        opcode: OpCode::ArrayIssetFetch,
                                        op1: current,
                                        op2: idx,
                                        result: OperandType::Tmp(isset_tmp),
                                        line: expr.span.line,
                                    });
                                    let jmp_pos = self.op_array.ops.len();
                                    jmp_patches.push(jmp_pos);
                                    self.op_array.emit(Op {
                                        opcode: OpCode::JmpZ,
                                        op1: OperandType::Tmp(isset_tmp),
                                        op2: OperandType::JmpTarget(0),
                                        result: OperandType::Unused,
                                        line: expr.span.line,
                                    });
                                    let get_tmp = self.op_array.alloc_temp();
                                    self.op_array.emit(Op {
                                        opcode: OpCode::ArrayGet,
                                        op1: current,
                                        op2: idx,
                                        result: OperandType::Tmp(get_tmp),
                                        line: expr.span.line,
                                    });
                                    current = OperandType::Tmp(get_tmp);
                                }

                                // Now do PropertyIsset on the result
                                let prop_operand = self.compile_property_name(property)?;
                                let tmp = self.op_array.alloc_temp();
                                self.op_array.emit(Op {
                                    opcode: OpCode::PropertyIsset,
                                    op1: current,
                                    op2: prop_operand,
                                    result: OperandType::Tmp(tmp),
                                    line: expr.span.line,
                                });
                                self.op_array.emit(Op {
                                    opcode: OpCode::Assign,
                                    op1: OperandType::Tmp(result_tmp),
                                    op2: OperandType::Tmp(tmp),
                                    result: OperandType::Unused,
                                    line: expr.span.line,
                                });

                                // Jump past false
                                let jmp_end_pos = self.op_array.ops.len();
                                self.op_array.emit(Op {
                                    opcode: OpCode::Jmp,
                                    op1: OperandType::JmpTarget(0),
                                    op2: OperandType::Unused,
                                    result: OperandType::Unused,
                                    line: expr.span.line,
                                });

                                // False label
                                let false_target = self.op_array.ops.len() as u32;
                                let false_lit = self.op_array.add_literal(Value::False);
                                self.op_array.emit(Op {
                                    opcode: OpCode::Assign,
                                    op1: OperandType::Tmp(result_tmp),
                                    op2: OperandType::Const(false_lit),
                                    result: OperandType::Unused,
                                    line: expr.span.line,
                                });
                                let end_target = self.op_array.ops.len() as u32;
                                for jmp_pos in jmp_patches {
                                    self.op_array.ops[jmp_pos].op2 =
                                        OperandType::JmpTarget(false_target);
                                }
                                self.op_array.ops[jmp_end_pos].op1 =
                                    OperandType::JmpTarget(end_target);

                                self.op_array.emit(Op {
                                    opcode: OpCode::ErrorRestore,
                                    op1: OperandType::Unused,
                                    op2: OperandType::Unused,
                                    result: OperandType::Unused,
                                    line: expr.span.line,
                                });
                                return Ok(OperandType::Tmp(result_tmp));
                            } else {
                                let mut patches = Vec::new();
                                let op = self.compile_isset_prop_chain(
                                    object,
                                    expr.span.line,
                                    &mut patches,
                                )?;
                                if !patches.is_empty() {
                                    // isset($a->b->c): intermediate fetches go through
                                    // __isset before __get (FETCH_OBJ_IS semantics).
                                    let prop_operand = self.compile_property_name(property)?;
                                    let tmp = self.op_array.alloc_temp();
                                    self.op_array.emit(Op {
                                        opcode: OpCode::PropertyIsset,
                                        op1: op,
                                        op2: prop_operand,
                                        result: OperandType::Tmp(tmp),
                                        line: expr.span.line,
                                    });
                                    let jmp_end = self.op_array.emit(Op {
                                        opcode: OpCode::Jmp,
                                        op1: OperandType::JmpTarget(0),
                                        op2: OperandType::Unused,
                                        result: OperandType::Unused,
                                        line: expr.span.line,
                                    });
                                    let false_target = self.op_array.current_offset();
                                    let false_lit = self.op_array.add_literal(Value::False);
                                    self.op_array.emit(Op {
                                        opcode: OpCode::Assign,
                                        op1: OperandType::Tmp(tmp),
                                        op2: OperandType::Const(false_lit),
                                        result: OperandType::Unused,
                                        line: expr.span.line,
                                    });
                                    let end_target = self.op_array.current_offset();
                                    for p in patches {
                                        self.op_array.ops[p as usize].op2 =
                                            OperandType::JmpTarget(false_target);
                                    }
                                    self.op_array.patch_jump(jmp_end, end_target);
                                    self.op_array.emit(Op {
                                        opcode: OpCode::ErrorRestore,
                                        op1: OperandType::Unused,
                                        op2: OperandType::Unused,
                                        result: OperandType::Unused,
                                        line: expr.span.line,
                                    });
                                    return Ok(OperandType::Tmp(tmp));
                                }
                                op
                            };
                            let prop_operand = self.compile_property_name(property)?;
                            let tmp = self.op_array.alloc_temp();
                            self.op_array.emit(Op {
                                opcode: OpCode::PropertyIsset,
                                op1: obj_operand,
                                op2: prop_operand,
                                result: OperandType::Tmp(tmp),
                                line: expr.span.line,
                            });
                            self.op_array.emit(Op {
                                opcode: OpCode::ErrorRestore,
                                op1: OperandType::Unused,
                                op2: OperandType::Unused,
                                result: OperandType::Unused,
                                line: expr.span.line,
                            });
                            return Ok(OperandType::Tmp(tmp));
                        }
                    }
                    // Check if expression is an array access -> use ArrayIsset
                    // This ensures objects implementing ArrayAccess call offsetExists()
                    // For nested access like isset($a[0][1][2]), we need to:
                    // 1. ArrayIsset($a, 0) - if false, jump to false label
                    // 2. ArrayGet($a, 0) -> tmp1
                    // 3. ArrayIsset(tmp1, 1) - if false, jump to false label
                    // 4. ArrayGet(tmp1, 1) -> tmp2
                    // 5. ArrayIsset(tmp2, 2) - final result
                    if matches!(exprs[0].kind, ExprKind::ArrayAccess { .. }) {
                        // Flatten the chain of ArrayAccess nodes
                        let mut chain: Vec<&Expr> = Vec::new(); // indices
                        let mut base_expr = &exprs[0];
                        while let ExprKind::ArrayAccess { array, index } = &base_expr.kind {
                            if let Some(idx_expr) = index {
                                chain.push(idx_expr);
                            }
                            base_expr = array;
                        }
                        chain.reverse(); // now chain[0] is the first index, chain[last] is the last

                        // Also check if base_expr is a PropertyAccess - handle isset($obj->prop[$key])
                        // For PropertyAccess we need FETCH_OBJ_IS semantics:
                        // first call __isset on the prop; if it returns false, the entire
                        // isset chain is false. Otherwise, fetch the property value via
                        // PropertyGet (which honors __get) and proceed with the array chain.
                        let result_tmp = self.op_array.alloc_temp();
                        let mut jmp_patches: Vec<usize> = Vec::new();
                        let base_op = if let ExprKind::PropertyAccess {
                            object, property, ..
                        } = &base_expr.kind
                        {
                            let obj_op = self.compile_expr(object)?;
                            let prop_op = self.compile_property_name(property)?;
                            let isset_tmp = self.op_array.alloc_temp();
                            self.op_array.emit(Op {
                                opcode: OpCode::PropertyIssetFetch,
                                op1: obj_op,
                                op2: prop_op,
                                result: OperandType::Tmp(isset_tmp),
                                line: expr.span.line,
                            });
                            // If isset on the property returned false, the whole chain is false.
                            let jmp_pos = self.op_array.ops.len();
                            jmp_patches.push(jmp_pos);
                            self.op_array.emit(Op {
                                opcode: OpCode::JmpZ,
                                op1: OperandType::Tmp(isset_tmp),
                                op2: OperandType::JmpTarget(0),
                                result: OperandType::Unused,
                                line: expr.span.line,
                            });
                            // Now actually fetch the property value (will invoke __get if needed).
                            let val_tmp = self.op_array.alloc_temp();
                            self.op_array.emit(Op {
                                opcode: OpCode::PropertyGet,
                                op1: obj_op,
                                op2: prop_op,
                                result: OperandType::Tmp(val_tmp),
                                line: expr.span.line,
                            });
                            OperandType::Tmp(val_tmp)
                        } else {
                            self.compile_expr(base_expr)?
                        };

                        let _false_label = self.op_array.ops.len() as u32 + 9999; // placeholder

                        let mut current = base_op;
                        for (i, idx_expr) in chain.iter().enumerate() {
                            let is_last = i == chain.len() - 1;
                            let idx = self.compile_key_unsilenced(idx_expr, false)?;

                            // Emit ArrayIsset (FETCH_DIM_IS for outer dimensions)
                            let isset_tmp = self.op_array.alloc_temp();
                            self.op_array.emit(Op {
                                opcode: if is_last {
                                    OpCode::ArrayIsset
                                } else {
                                    OpCode::ArrayIssetFetch
                                },
                                op1: current,
                                op2: idx,
                                result: OperandType::Tmp(isset_tmp),
                                line: expr.span.line,
                            });

                            if is_last {
                                // Final level: the result of ArrayIsset is the final result
                                self.op_array.emit(Op {
                                    opcode: OpCode::Assign,
                                    op1: OperandType::Tmp(result_tmp),
                                    op2: OperandType::Tmp(isset_tmp),
                                    result: OperandType::Unused,
                                    line: expr.span.line,
                                });
                            } else {
                                // Intermediate level: if false, jump to end
                                let jmp_pos = self.op_array.ops.len();
                                jmp_patches.push(jmp_pos);
                                self.op_array.emit(Op {
                                    opcode: OpCode::JmpZ,
                                    op1: OperandType::Tmp(isset_tmp),
                                    op2: OperandType::JmpTarget(0), // will be patched
                                    result: OperandType::Unused,
                                    line: expr.span.line,
                                });

                                // Emit ArrayGet to get the value for the next level
                                let get_tmp = self.op_array.alloc_temp();
                                self.op_array.emit(Op {
                                    opcode: OpCode::ArrayGet,
                                    op1: current,
                                    op2: idx,
                                    result: OperandType::Tmp(get_tmp),
                                    line: expr.span.line,
                                });
                                current = OperandType::Tmp(get_tmp);
                            }
                        }

                        // Jump past the false assignment
                        let jmp_end_pos = self.op_array.ops.len();
                        self.op_array.emit(Op {
                            opcode: OpCode::Jmp,
                            op1: OperandType::JmpTarget(0), // will be patched
                            op2: OperandType::Unused,
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });

                        // False label: set result to false
                        let false_target = self.op_array.ops.len() as u32;
                        let false_lit = self.op_array.add_literal(Value::False);
                        self.op_array.emit(Op {
                            opcode: OpCode::Assign,
                            op1: OperandType::Tmp(result_tmp),
                            op2: OperandType::Const(false_lit),
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });

                        // End label
                        let end_target = self.op_array.ops.len() as u32;

                        // Patch all jump positions
                        for jmp_pos in jmp_patches {
                            self.op_array.ops[jmp_pos].op2 = OperandType::JmpTarget(false_target);
                        }
                        self.op_array.ops[jmp_end_pos].op1 = OperandType::JmpTarget(end_target);

                        self.op_array.emit(Op {
                            opcode: OpCode::ErrorRestore,
                            op1: OperandType::Unused,
                            op2: OperandType::Unused,
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                        return Ok(OperandType::Tmp(result_tmp));
                    }
                    // isset(C::$p) / isset($obj::$p) — static property isset
                    // never throws, just returns bool.
                    if let ExprKind::StaticPropertyAccess { class, property } = &exprs[0].kind {
                        let class_operand = self.compile_static_class_operand(class)?;
                        let prop_idx = self
                            .op_array
                            .add_literal(Value::String(PhpString::from_vec(property.clone())));
                        let tmp = self.op_array.alloc_temp();
                        self.op_array.emit(Op {
                            opcode: OpCode::StaticPropIsset,
                            op1: class_operand,
                            op2: OperandType::Const(prop_idx),
                            result: OperandType::Tmp(tmp),
                            line: expr.span.line,
                        });
                        self.op_array.emit(Op {
                            opcode: OpCode::ErrorRestore,
                            op1: OperandType::Unused,
                            op2: OperandType::Unused,
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                        return Ok(OperandType::Tmp(tmp));
                    }
                    if let ExprKind::DynamicStaticPropertyAccess { class, property } =
                        &exprs[0].kind
                    {
                        let class_operand = self.compile_static_class_operand(class)?;
                        let prop_op = self.compile_expr(property)?;
                        let tmp = self.op_array.alloc_temp();
                        self.op_array.emit(Op {
                            opcode: OpCode::StaticPropIsset,
                            op1: class_operand,
                            op2: prop_op,
                            result: OperandType::Tmp(tmp),
                            line: expr.span.line,
                        });
                        self.op_array.emit(Op {
                            opcode: OpCode::ErrorRestore,
                            op1: OperandType::Unused,
                            op2: OperandType::Unused,
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                        return Ok(OperandType::Tmp(tmp));
                    }
                    let val = self.compile_isset_operand(&exprs[0])?;
                    let tmp = self.op_array.alloc_temp();
                    self.op_array.emit(Op {
                        opcode: OpCode::IssetCheck,
                        op1: val,
                        op2: OperandType::Unused,
                        result: OperandType::Tmp(tmp),
                        line: expr.span.line,
                    });
                    self.op_array.emit(Op {
                        opcode: OpCode::ErrorRestore,
                        op1: OperandType::Unused,
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });
                    Ok(OperandType::Tmp(tmp))
                } else {
                    unreachable!("multi-argument isset() is lowered to &&")
                }
            }

            ExprKind::Empty(inner) => {
                self.op_array.emit(Op {
                    opcode: OpCode::ErrorSuppress,
                    op1: OperandType::Unused,
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line: expr.span.line,
                });

                // For empty($obj[$key]), PHP calls offsetExists first.
                // If false -> empty is true. If true -> calls offsetGet, checks if value is empty.
                if matches!(inner.kind, ExprKind::ArrayAccess { .. }) {
                    let mut chain: Vec<&Expr> = Vec::new();
                    let mut base_expr: &Expr = inner;
                    while let ExprKind::ArrayAccess { array, index } = &base_expr.kind {
                        if let Some(idx_expr) = index {
                            chain.push(idx_expr);
                        }
                        base_expr = array;
                    }
                    chain.reverse();

                    let mut jmp_to_true: Vec<usize> = Vec::new(); // jumps when exists=false -> empty=true
                    let base_op = if Self::is_static_prop_expr(base_expr) {
                        let (t, j) = self.compile_static_prop_quiet(base_expr)?;
                        jmp_to_true.push(j as usize);
                        OperandType::Tmp(t)
                    } else {
                        self.compile_is_fetch(base_expr)?
                    };
                    let base_op = self.snapshot_cv(base_op, expr.span.line);
                    let result_tmp = self.op_array.alloc_temp();
                    let mut current = base_op;

                    for (i, idx_expr) in chain.iter().enumerate() {
                        let is_last = i == chain.len() - 1;
                        let idx = self.compile_key_unsilenced(idx_expr, true)?;
                        // (snapshotted while unsilenced)

                        // Check offsetExists (the outer dimensions are
                        // FETCH_DIM_IS fetches)
                        let isset_tmp = self.op_array.alloc_temp();
                        self.op_array.emit(Op {
                            opcode: if is_last {
                                OpCode::ArrayIsset
                            } else {
                                OpCode::ArrayIssetFetch
                            },
                            op1: current,
                            op2: idx,
                            result: OperandType::Tmp(isset_tmp),
                            line: expr.span.line,
                        });
                        let jmp_pos = self.op_array.ops.len();
                        jmp_to_true.push(jmp_pos);
                        self.op_array.emit(Op {
                            opcode: OpCode::JmpZ,
                            op1: OperandType::Tmp(isset_tmp),
                            op2: OperandType::JmpTarget(0), // patched later
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });

                        // Get the value
                        let get_tmp = self.op_array.alloc_temp();
                        self.op_array.emit(Op {
                            opcode: OpCode::ArrayGet,
                            op1: current,
                            op2: idx,
                            result: OperandType::Tmp(get_tmp),
                            line: expr.span.line,
                        });
                        current = OperandType::Tmp(get_tmp);
                    }

                    self.op_array.emit(Op {
                        opcode: OpCode::ErrorRestore,
                        op1: OperandType::Unused,
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });

                    // Value exists: check if it's empty (BooleanNot)
                    let not_tmp = self.op_array.alloc_temp();
                    let quiet = self.quiet_operand_flag();
                    self.op_array.emit(Op {
                        opcode: OpCode::BooleanNot,
                        op1: current,
                        // empty(): reads quietly (op2 set).
                        op2: quiet,
                        result: OperandType::Tmp(not_tmp),
                        line: expr.span.line,
                    });
                    self.op_array.emit(Op {
                        opcode: OpCode::Assign,
                        op1: OperandType::Tmp(result_tmp),
                        op2: OperandType::Tmp(not_tmp),
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });
                    let jmp_end_pos = self.op_array.ops.len();
                    self.op_array.emit(Op {
                        opcode: OpCode::Jmp,
                        op1: OperandType::JmpTarget(0),
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });

                    // True label (key doesn't exist -> empty is true)
                    let true_target = self.op_array.ops.len() as u32;
                    let true_lit = self.op_array.add_literal(Value::True);
                    self.op_array.emit(Op {
                        opcode: OpCode::Assign,
                        op1: OperandType::Tmp(result_tmp),
                        op2: OperandType::Const(true_lit),
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });
                    self.op_array.emit(Op {
                        opcode: OpCode::ErrorRestore,
                        op1: OperandType::Unused,
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });

                    let end_target = self.op_array.ops.len() as u32;
                    for jmp_pos in jmp_to_true {
                        self.op_array.ops[jmp_pos].op2 = OperandType::JmpTarget(true_target);
                    }
                    self.op_array.ops[jmp_end_pos].op1 = OperandType::JmpTarget(end_target);

                    return Ok(OperandType::Tmp(result_tmp));
                }

                if matches!(
                    &inner.kind,
                    ExprKind::PropertyAccess {
                        nullsafe: false,
                        ..
                    }
                ) {
                    // empty($o->p): __isset first, then __get (FETCH_OBJ_IS).
                    let line = expr.span.line;
                    let mut patches: Vec<u32> = Vec::new();
                    let val = self.compile_isset_prop_chain(inner, line, &mut patches)?;
                    self.op_array.emit(Op {
                        opcode: OpCode::ErrorRestore,
                        op1: OperandType::Unused,
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line,
                    });
                    let tmp = self.op_array.alloc_temp();
                    let quiet = self.quiet_operand_flag();
                    self.op_array.emit(Op {
                        opcode: OpCode::BooleanNot,
                        op1: val,
                        // empty(): reads quietly (op2 set).
                        op2: quiet,
                        result: OperandType::Tmp(tmp),
                        line,
                    });
                    let jmp_end = self.op_array.emit(Op {
                        opcode: OpCode::Jmp,
                        op1: OperandType::JmpTarget(0),
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line,
                    });
                    let fail_label = self.op_array.current_offset();
                    for p in &patches {
                        self.op_array.ops[*p as usize].op2 = OperandType::JmpTarget(fail_label);
                    }
                    self.op_array.emit(Op {
                        opcode: OpCode::ErrorRestore,
                        op1: OperandType::Unused,
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line,
                    });
                    let true_lit = self.op_array.add_literal(Value::True);
                    self.op_array.emit(Op {
                        opcode: OpCode::Assign,
                        op1: OperandType::Tmp(tmp),
                        op2: OperandType::Const(true_lit),
                        result: OperandType::Unused,
                        line,
                    });
                    let end = self.op_array.current_offset();
                    self.op_array.patch_jump(jmp_end, end);
                    return Ok(OperandType::Tmp(tmp));
                }
                if Self::is_static_prop_expr(inner) {
                    // empty(C::$p): an undeclared / inaccessible property is empty.
                    let (val_tmp, jmp_unset) = self.compile_static_prop_quiet(inner)?;
                    self.op_array.emit(Op {
                        opcode: OpCode::ErrorRestore,
                        op1: OperandType::Unused,
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });
                    let result_tmp = self.op_array.alloc_temp();
                    let quiet = self.quiet_operand_flag();
                    self.op_array.emit(Op {
                        opcode: OpCode::BooleanNot,
                        op1: OperandType::Tmp(val_tmp),
                        // empty(): reads quietly (op2 set).
                        op2: quiet,
                        result: OperandType::Tmp(result_tmp),
                        line: expr.span.line,
                    });
                    let jmp_end = self.op_array.emit(Op {
                        opcode: OpCode::Jmp,
                        op1: OperandType::JmpTarget(0),
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });
                    let true_target = self.op_array.current_offset();
                    self.op_array.ops[jmp_unset as usize].op2 = OperandType::JmpTarget(true_target);
                    let true_lit = self.op_array.add_literal(Value::True);
                    self.op_array.emit(Op {
                        opcode: OpCode::Assign,
                        op1: OperandType::Tmp(result_tmp),
                        op2: OperandType::Const(true_lit),
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });
                    self.op_array.emit(Op {
                        opcode: OpCode::ErrorRestore,
                        op1: OperandType::Unused,
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });
                    let end = self.op_array.current_offset();
                    self.op_array.patch_jump(jmp_end, end);
                    return Ok(OperandType::Tmp(result_tmp));
                }

                let val = self.compile_isset_operand(inner)?;
                self.op_array.emit(Op {
                    opcode: OpCode::ErrorRestore,
                    op1: OperandType::Unused,
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line: expr.span.line,
                });
                let tmp = self.op_array.alloc_temp();
                let quiet = self.quiet_operand_flag();
                self.op_array.emit(Op {
                    opcode: OpCode::BooleanNot,
                    op1: val,
                    // empty(): reads quietly (op2 set).
                    op2: quiet,
                    result: OperandType::Tmp(tmp),
                    line: expr.span.line,
                });
                Ok(OperandType::Tmp(tmp))
            }

            ExprKind::Closure {
                params,
                body,
                use_vars,
                is_static,
                return_type: closure_return_type,
                attributes: closure_attributes,
                end_line: closure_end_line,
                doc_comment: closure_doc_comment,
                returns_by_ref: closure_returns_by_ref,
                ..
            } => {
                check_duplicate_params(params, expr.span.line)?;
                // Compile closure body as a child function
                let _closure_id = self.op_array.child_functions.len();
                let global_id = next_closure_id();
                let closure_name = format!("__closure_{}", global_id).into_bytes();
                // Compute the canonical PHP closure display name from current scope.
                let display_name = self.closure_display_name(expr.span.line);

                // Check if closure body contains yield
                let is_generator = stmts_contain_yield(body);

                let mut closure_compiler = Compiler::new();
                // A closure can be rebound to another scope: self::/parent::
                // constants resolve at run time.
                closure_compiler.keep_relative_class_names = true;
                closure_compiler.op_array.name = closure_name.clone();
                closure_compiler.op_array.display_name = display_name;
                closure_compiler.op_array.is_generator = is_generator;
                closure_compiler.op_array.returns_by_ref = *closure_returns_by_ref;
                closure_compiler.op_array.is_static_closure = *is_static;
                closure_compiler.op_array.decl_line = expr.span.line;
                closure_compiler.op_array.returns_by_ref = *closure_returns_by_ref;
                closure_compiler.op_array.end_line = if *closure_end_line > 0 {
                    *closure_end_line
                } else {
                    expr.span.line
                };
                closure_compiler.op_array.strict_types = self.op_array.strict_types;
                closure_compiler.op_array.attributes =
                    self.compile_closure_attributes(closure_attributes);
                closure_compiler.op_array.doc_comment = closure_doc_comment.clone();
                // Propagate the closure's declared return type so ReflectionFunction
                // observes it via `hasReturnType`/`getReturnType`.
                if let Some(hint) = closure_return_type {
                    closure_compiler.op_array.return_type = Some(type_hint_to_param_type_with_ns(
                        hint,
                        &self.current_namespace,
                        &self.use_map,
                    ));
                }
                closure_compiler.op_array.filename = self.source_file.clone();
                closure_compiler.source_file = self.source_file.clone();
                closure_compiler.current_class = self.current_class.clone();
                closure_compiler.is_in_trait = self.is_in_trait;
                closure_compiler.current_parent_class = self.current_parent_class.clone();
                closure_compiler.anon_class_name_map = self.anon_class_name_map.clone();
                // Inherit scope_class from the enclosing function for visibility checks
                closure_compiler.op_array.scope_class =
                    self.op_array.scope_class.clone().or_else(|| {
                        self.current_class
                            .as_ref()
                            .map(|c| c.iter().map(|b| b.to_ascii_lowercase()).collect())
                    });

                // If inside a class method and not static, automatically capture $this
                let has_this = !is_static
                    && self.current_class.is_some()
                    && self.op_array.cv_names.contains(&b"this".to_vec());
                if has_this {
                    closure_compiler.op_array.get_or_create_cv(b"this");
                    closure_compiler
                        .op_array
                        .closure_capture_names
                        .push(b"this".to_vec());
                }
                for use_var in use_vars {
                    closure_compiler
                        .op_array
                        .closure_capture_names
                        .push(use_var.variable.clone());
                }
                closure_compiler.op_array.closure_params =
                    params.iter().map(|p| (p.name.clone(), p.by_ref)).collect();

                // Set up use vars as the first CVs (before params)
                for (ui, use_var) in use_vars.iter().enumerate() {
                    if use_var.variable == b"this" {
                        return Err(CompileError {
                            message: "Cannot use $this as lexical variable".into(),
                            line: expr.span.line,
                        });
                    }
                    if matches!(
                        use_var.variable.as_slice(),
                        b"GLOBALS"
                            | b"_SERVER"
                            | b"_GET"
                            | b"_POST"
                            | b"_COOKIE"
                            | b"_FILES"
                            | b"_ENV"
                            | b"_REQUEST"
                            | b"_SESSION"
                    ) {
                        return Err(CompileError {
                            message: "Cannot use auto-global as lexical variable".into(),
                            line: expr.span.line,
                        });
                    }
                    if params.iter().any(|p| p.name == use_var.variable) {
                        return Err(CompileError {
                            message: format!(
                                "Cannot use lexical variable ${} as a parameter name",
                                String::from_utf8_lossy(&use_var.variable)
                            ),
                            line: expr.span.line,
                        });
                    }
                    if use_vars[..ui]
                        .iter()
                        .any(|u| u.variable == use_var.variable)
                    {
                        return Err(CompileError {
                            message: format!(
                                "Cannot use variable ${} twice",
                                String::from_utf8_lossy(&use_var.variable)
                            ),
                            line: expr.span.line,
                        });
                    }
                    closure_compiler
                        .op_array
                        .get_or_create_cv(&use_var.variable);
                }
                // Count required params and set param_count
                closure_compiler.op_array.param_count = params.len() as u32
                    + use_vars.len() as u32
                    + if !*is_static && self.current_class.is_some() {
                        1
                    } else {
                        0
                    };
                closure_compiler.op_array.required_param_count = {
                    let mut last_req: i64 = -1;
                    for (i, p) in params.iter().enumerate() {
                        if !p.variadic && p.default.is_none() {
                            last_req = i as i64;
                        }
                    }
                    (last_req + 1) as u32
                };
                // Compile parameter attributes
                closure_compiler.op_array.param_attributes = params
                    .iter()
                    .map(|p| self.compile_closure_attributes(&p.attributes))
                    .collect();
                // Record by-ref params for closures (with offset for $this and use vars)
                {
                    let mut by_ref = Vec::new();
                    let mut has_default = Vec::new();
                    if has_this {
                        by_ref.push(false);
                        has_default.push(false);
                    } // $this
                    for uv in use_vars {
                        by_ref.push(uv.by_ref);
                        has_default.push(false);
                    } // use vars
                    for p in params.iter() {
                        by_ref.push(p.by_ref);
                        has_default.push(p.default.is_some());
                    } // params
                    closure_compiler.op_array.by_ref_params = by_ref;
                    closure_compiler.op_array.param_has_default = has_default;
                }

                // Validate parameter types
                for param in params.iter() {
                    if let Some(hint) = &param.type_hint {
                        if check_static_param_type(hint) {
                            return Err(CompileError {
                                message: "Cannot use the static modifier on a parameter"
                                    .to_string(),
                                line: expr.span.line,
                            });
                        }
                    }
                }

                // Set up parameter CVs
                for param in params {
                    let cv = closure_compiler.op_array.get_or_create_cv(&param.name);

                    // Handle variadic parameter
                    if param.variadic {
                        closure_compiler.op_array.variadic_param = Some(cv);
                    }

                    // Store parameter type info
                    let type_info = param.type_hint.as_ref().map(|hint| {
                        let mut pt = type_hint_to_param_type_with_ns(
                            hint,
                            &self.current_namespace,
                            &self.use_map,
                        );
                        let mut is_implicitly_nullable = false;
                        if let Some(default_expr) = &param.default {
                            if matches!(default_expr.kind, ExprKind::Null)
                                && !is_type_nullable_or_mixed(&pt)
                            {
                                pt = ParamType::Nullable(Box::new(pt));
                                is_implicitly_nullable = true;
                            }
                        }
                        ParamTypeInfo {
                            param_type: pt,
                            param_name: param.name.clone(),
                            implicitly_nullable: is_implicitly_nullable,
                        }
                    });
                    while closure_compiler.op_array.param_types.len() <= cv as usize {
                        closure_compiler.op_array.param_types.push(None);
                    }
                    closure_compiler.op_array.param_types[cv as usize] = type_info;

                    // Compile default value
                    if let Some(default_expr) = &param.default {
                        closure_compiler
                            .op_array
                            .set_param_default_repr(cv, self.default_value_repr(default_expr));
                        let undef_idx = closure_compiler.op_array.add_literal(Value::Undef);
                        let check_tmp = closure_compiler.op_array.alloc_temp();
                        closure_compiler.op_array.emit(Op {
                            opcode: OpCode::Identical,
                            op1: OperandType::Cv(cv),
                            op2: OperandType::Const(undef_idx),
                            result: OperandType::Tmp(check_tmp),
                            line: 0,
                        });
                        let jmp_skip = closure_compiler.op_array.emit(Op {
                            opcode: OpCode::JmpZ,
                            op1: OperandType::Tmp(check_tmp),
                            op2: OperandType::JmpTarget(0),
                            result: OperandType::Unused,
                            line: 0,
                        });
                        let default_val =
                            closure_compiler.compile_const_expr_value(default_expr)?;
                        if !matches!(default_expr.kind, ExprKind::Null) {
                            let pcv =
                                closure_compiler.op_array.get_or_create_cv(&param.name) as usize;
                            if let Some(Some(pti)) =
                                closure_compiler.op_array.param_types.get(pcv).cloned()
                            {
                                match Self::check_literal_default(&pti.param_type, default_expr) {
                                    Err((tn, _)) => {
                                        return Err(CompileError {
                                            message: format!(
                                                "Cannot use {} as default value for parameter ${} of type {}",
                                                tn,
                                                String::from_utf8_lossy(&param.name),
                                                crate::vm::variance::type_to_string(
                                                    &crate::vm::variance::TypeView::from_param_type(
                                                        &pti.param_type
                                                    ),
                                                    None
                                                )
                                            ),
                                            line: default_expr.span.line,
                                        });
                                    }
                                    Ok(Some(widened)) => {
                                        if let OperandType::Const(li) = default_val {
                                            closure_compiler.op_array.literals[li as usize] =
                                                widened;
                                        }
                                    }
                                    Ok(None) => {}
                                }
                            }
                        }
                        closure_compiler.op_array.emit(Op {
                            opcode: OpCode::Assign,
                            op1: OperandType::Cv(cv),
                            op2: default_val,
                            result: OperandType::Unused,
                            line: 0,
                        });
                        Self::emit_recv_default_check(
                            &mut closure_compiler.op_array,
                            cv,
                            default_expr,
                        );
                        let after = closure_compiler.op_array.current_offset();
                        closure_compiler.op_array.patch_jump(jmp_skip, after);
                    }
                }

                for s in body {
                    closure_compiler.compile_stmt(s)?;
                }
                closure_compiler.check_pending_gotos()?;

                let implicit_line = closure_compiler.op_array.end_line;
                closure_compiler.emit_by_ref_return_notice(None, implicit_line);
                let null_idx = closure_compiler.op_array.add_literal(Value::Null);
                closure_compiler.op_array.emit(Op {
                    opcode: OpCode::Return,
                    op1: OperandType::Const(null_idx),
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line: 0,
                });

                self.op_array
                    .child_functions
                    .push(closure_compiler.op_array);

                // Emit DeclareFunction for the closure
                let name_idx = self
                    .op_array
                    .add_literal(Value::String(PhpString::from_vec(closure_name.clone())));
                let func_idx = self.op_array.add_literal(Value::Long(
                    (self.op_array.child_functions.len() - 1) as i64,
                ));
                self.op_array.emit(Op {
                    opcode: OpCode::DeclareFunction,
                    op1: OperandType::Const(name_idx),
                    op2: OperandType::Const(func_idx),
                    result: OperandType::Unused,
                    line: expr.span.line,
                });

                // If there are use vars (or $this), create an array [closure_name, use_val_1, ...]
                let needs_capture = !use_vars.is_empty() || has_this;
                if needs_capture {
                    let arr_tmp = self.op_array.alloc_temp();
                    self.op_array.emit(Op {
                        opcode: OpCode::ArrayNew,
                        op1: OperandType::Unused,
                        op2: OperandType::Unused,
                        result: OperandType::Tmp(arr_tmp),
                        line: expr.span.line,
                    });
                    // First element: closure name
                    let name_val = self
                        .op_array
                        .add_literal(Value::String(PhpString::from_vec(closure_name)));
                    self.op_array.emit(Op {
                        opcode: OpCode::ArrayAppend,
                        op1: OperandType::Tmp(arr_tmp),
                        op2: OperandType::Const(name_val),
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });
                    // Capture $this if in class context
                    if has_this {
                        let this_cv = self.op_array.get_or_create_cv(b"this");
                        self.op_array.emit(Op {
                            opcode: OpCode::ArrayAppend,
                            op1: OperandType::Tmp(arr_tmp),
                            op2: OperandType::Cv(this_cv),
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                    }
                    // Subsequent elements: captured use var values
                    for use_var in use_vars {
                        let cv = self.op_array.get_or_create_cv(&use_var.variable);
                        if use_var.by_ref {
                            // By-reference capture: make the CV a reference first,
                            // then append the raw Reference value (not dereffed)
                            self.op_array.emit(Op {
                                opcode: OpCode::MakeRef,
                                op1: OperandType::Cv(cv),
                                op2: OperandType::Unused,
                                result: OperandType::Unused,
                                line: expr.span.line,
                            });
                            // Use ArrayAppendRef to preserve the Reference wrapper
                            self.op_array.emit(Op {
                                opcode: OpCode::ArrayAppendRef,
                                op1: OperandType::Tmp(arr_tmp),
                                op2: OperandType::Cv(cv),
                                result: OperandType::Unused,
                                line: expr.span.line,
                            });
                        } else {
                            self.op_array.emit(Op {
                                opcode: OpCode::ArrayAppend,
                                op1: OperandType::Tmp(arr_tmp),
                                op2: OperandType::Cv(cv),
                                result: OperandType::Unused,
                                line: expr.span.line,
                            });
                        }
                    }
                    Ok(self.wrap_closure_operand(OperandType::Tmp(arr_tmp)))
                } else {
                    // No use vars - just return the closure name
                    let name_val_idx = self
                        .op_array
                        .add_literal(Value::String(PhpString::from_vec(closure_name)));
                    Ok(self.wrap_closure_operand(OperandType::Const(name_val_idx)))
                }
            }

            ExprKind::ArrowFunction {
                params,
                body,
                attributes,
                end_line: arrow_end_line,
                doc_comment: arrow_doc_comment,
                return_type: arrow_return_type,
                returns_by_ref: arrow_returns_by_ref,
                is_static: arrow_is_static,
                ..
            } => {
                check_duplicate_params(params, expr.span.line)?;
                // Arrow function: fn($x) => $x * 2
                // Arrow functions implicitly capture outer variables by value

                // Collect all variables referenced in the body
                let mut body_vars = Vec::new();
                collect_expr_variables(body, &mut body_vars);

                // Remove parameters from the captured list
                let param_names: Vec<Vec<u8>> = params.iter().map(|p| p.name.clone()).collect();
                // Like closures, non-static arrow functions in a method bind $this
                // (captured first); static ones never see it.
                let arrow_has_this = !*arrow_is_static
                    && self.current_class.is_some()
                    && self.op_array.cv_names.contains(&b"this".to_vec());
                let mut use_vars: Vec<Vec<u8>> = body_vars
                    .into_iter()
                    .filter(|v| !param_names.contains(v) && v.as_slice() != b"this")
                    .collect();
                if arrow_has_this {
                    use_vars.insert(0, b"this".to_vec());
                }

                let _closure_id = self.op_array.child_functions.len();
                let global_id = next_closure_id();
                let closure_name = format!("__arrow_{}", global_id).into_bytes();
                // Arrow functions share the canonical `{closure:...}` display name format.
                let display_name = self.closure_display_name(expr.span.line);

                let mut closure_compiler = Compiler::new();
                closure_compiler.keep_relative_class_names = true;
                closure_compiler.op_array.name = closure_name.clone();
                closure_compiler.op_array.display_name = display_name;
                closure_compiler.op_array.filename = self.source_file.clone();
                closure_compiler.op_array.decl_line = expr.span.line;
                closure_compiler.op_array.returns_by_ref = *arrow_returns_by_ref;
                closure_compiler.op_array.end_line = if *arrow_end_line > 0 {
                    *arrow_end_line
                } else {
                    expr.span.line
                };
                closure_compiler.op_array.strict_types = self.op_array.strict_types;
                closure_compiler.op_array.attributes = self.compile_closure_attributes(attributes);
                closure_compiler.op_array.doc_comment = arrow_doc_comment.clone();
                closure_compiler.op_array.param_attributes = params
                    .iter()
                    .map(|p| self.compile_closure_attributes(&p.attributes))
                    .collect();
                // Propagate arrow function's declared return type.
                if let Some(hint) = arrow_return_type {
                    closure_compiler.op_array.return_type = Some(type_hint_to_param_type_with_ns(
                        hint,
                        &self.current_namespace,
                        &self.use_map,
                    ));
                }
                closure_compiler.source_file = self.source_file.clone();
                closure_compiler.current_class = self.current_class.clone();
                closure_compiler.is_in_trait = self.is_in_trait;
                closure_compiler.current_parent_class = self.current_parent_class.clone();
                closure_compiler.anon_class_name_map = self.anon_class_name_map.clone();
                // Inherit scope_class from the enclosing function for visibility checks
                closure_compiler.op_array.scope_class =
                    self.op_array.scope_class.clone().or_else(|| {
                        self.current_class
                            .as_ref()
                            .map(|c| c.iter().map(|b| b.to_ascii_lowercase()).collect())
                    });

                // Validate parameter types
                for param in params.iter() {
                    if let Some(hint) = &param.type_hint {
                        if check_static_param_type(hint) {
                            return Err(CompileError {
                                message: "Cannot use the static modifier on a parameter"
                                    .to_string(),
                                line: expr.span.line,
                            });
                        }
                    }
                }

                // Set up use vars as the first CVs (before params)
                for uv in &use_vars {
                    closure_compiler.op_array.get_or_create_cv(uv);
                }
                closure_compiler.op_array.closure_capture_names = use_vars.clone();
                closure_compiler.op_array.is_static_closure = *arrow_is_static;
                closure_compiler.op_array.is_generator = expr_contains_yield(body);
                closure_compiler.op_array.closure_params =
                    params.iter().map(|p| (p.name.clone(), p.by_ref)).collect();
                closure_compiler.op_array.param_count = (params.len() + use_vars.len()) as u32;
                closure_compiler.op_array.required_param_count = {
                    let mut last_req: i64 = -1;
                    for (i, p) in params.iter().enumerate() {
                        if !p.variadic && p.default.is_none() {
                            last_req = i as i64;
                        }
                    }
                    (last_req + 1) as u32
                };
                {
                    let mut by_ref = Vec::new();
                    let mut has_default = Vec::new();
                    for _ in &use_vars {
                        by_ref.push(false);
                        has_default.push(false);
                    }
                    for p in params.iter() {
                        by_ref.push(p.by_ref);
                        has_default.push(p.default.is_some());
                    }
                    closure_compiler.op_array.by_ref_params = by_ref;
                    closure_compiler.op_array.param_has_default = has_default;
                }
                // Set up parameter CVs
                for param in params {
                    let cv = closure_compiler.op_array.get_or_create_cv(&param.name);
                    if param.variadic {
                        closure_compiler.op_array.variadic_param = Some(cv);
                    }

                    // Store parameter type info
                    let type_info = param.type_hint.as_ref().map(|hint| {
                        let mut pt = type_hint_to_param_type_with_ns(
                            hint,
                            &self.current_namespace,
                            &self.use_map,
                        );
                        let mut is_implicitly_nullable = false;
                        if let Some(default_expr) = &param.default {
                            if matches!(default_expr.kind, ExprKind::Null)
                                && !is_type_nullable_or_mixed(&pt)
                            {
                                pt = ParamType::Nullable(Box::new(pt));
                                is_implicitly_nullable = true;
                            }
                        }
                        ParamTypeInfo {
                            param_type: pt,
                            param_name: param.name.clone(),
                            implicitly_nullable: is_implicitly_nullable,
                        }
                    });
                    while closure_compiler.op_array.param_types.len() <= cv as usize {
                        closure_compiler.op_array.param_types.push(None);
                    }
                    closure_compiler.op_array.param_types[cv as usize] = type_info;

                    // Compile default value
                    if let Some(default_expr) = &param.default {
                        let undef_idx = closure_compiler.op_array.add_literal(Value::Undef);
                        let check_tmp = closure_compiler.op_array.alloc_temp();
                        closure_compiler.op_array.emit(Op {
                            opcode: OpCode::Identical,
                            op1: OperandType::Cv(cv),
                            op2: OperandType::Const(undef_idx),
                            result: OperandType::Tmp(check_tmp),
                            line: 0,
                        });
                        let jmp_skip = closure_compiler.op_array.emit(Op {
                            opcode: OpCode::JmpZ,
                            op1: OperandType::Tmp(check_tmp),
                            op2: OperandType::JmpTarget(0),
                            result: OperandType::Unused,
                            line: 0,
                        });
                        let default_val =
                            closure_compiler.compile_const_expr_value(default_expr)?;
                        if !matches!(default_expr.kind, ExprKind::Null) {
                            let pcv =
                                closure_compiler.op_array.get_or_create_cv(&param.name) as usize;
                            if let Some(Some(pti)) =
                                closure_compiler.op_array.param_types.get(pcv).cloned()
                            {
                                match Self::check_literal_default(&pti.param_type, default_expr) {
                                    Err((tn, _)) => {
                                        return Err(CompileError {
                                            message: format!(
                                                "Cannot use {} as default value for parameter ${} of type {}",
                                                tn,
                                                String::from_utf8_lossy(&param.name),
                                                crate::vm::variance::type_to_string(
                                                    &crate::vm::variance::TypeView::from_param_type(
                                                        &pti.param_type
                                                    ),
                                                    None
                                                )
                                            ),
                                            line: default_expr.span.line,
                                        });
                                    }
                                    Ok(Some(widened)) => {
                                        if let OperandType::Const(li) = default_val {
                                            closure_compiler.op_array.literals[li as usize] =
                                                widened;
                                        }
                                    }
                                    Ok(None) => {}
                                }
                            }
                        }
                        closure_compiler.op_array.emit(Op {
                            opcode: OpCode::Assign,
                            op1: OperandType::Cv(cv),
                            op2: default_val,
                            result: OperandType::Unused,
                            line: 0,
                        });
                        Self::emit_recv_default_check(
                            &mut closure_compiler.op_array,
                            cv,
                            default_expr,
                        );
                        let after = closure_compiler.op_array.current_offset();
                        closure_compiler.op_array.patch_jump(jmp_skip, after);
                    }
                }

                closure_compiler.emit_by_ref_return_notice(Some(body), expr.span.line);
                let body_val = closure_compiler.compile_expr(body)?;
                closure_compiler.op_array.emit(Op {
                    opcode: OpCode::Return,
                    op1: body_val,
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line: expr.span.line,
                });

                self.op_array
                    .child_functions
                    .push(closure_compiler.op_array);

                let name_idx = self
                    .op_array
                    .add_literal(Value::String(PhpString::from_vec(closure_name.clone())));
                let func_idx = self.op_array.add_literal(Value::Long(
                    (self.op_array.child_functions.len() - 1) as i64,
                ));
                self.op_array.emit(Op {
                    opcode: OpCode::DeclareFunction,
                    op1: OperandType::Const(name_idx),
                    op2: OperandType::Const(func_idx),
                    result: OperandType::Unused,
                    line: expr.span.line,
                });

                // If there are use vars, create array [closure_name, use_val_1, ...]
                if !use_vars.is_empty() {
                    let arr_tmp = self.op_array.alloc_temp();
                    self.op_array.emit(Op {
                        opcode: OpCode::ArrayNew,
                        op1: OperandType::Unused,
                        op2: OperandType::Unused,
                        result: OperandType::Tmp(arr_tmp),
                        line: expr.span.line,
                    });
                    let name_val = self
                        .op_array
                        .add_literal(Value::String(PhpString::from_vec(closure_name)));
                    self.op_array.emit(Op {
                        opcode: OpCode::ArrayAppend,
                        op1: OperandType::Tmp(arr_tmp),
                        op2: OperandType::Const(name_val),
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });
                    for uv in &use_vars {
                        let cv = self.op_array.get_or_create_cv(uv);
                        if uv.as_slice() == b"this" {
                            self.op_array.emit(Op {
                                opcode: OpCode::ArrayAppend,
                                op1: OperandType::Tmp(arr_tmp),
                                op2: OperandType::Cv(cv),
                                result: OperandType::Unused,
                                line: expr.span.line,
                            });
                            continue;
                        }
                        // Implicit binds of undefined variables are skipped
                        // silently (the slot stays undefined in the arrow fn).
                        let undef_idx = self.op_array.add_literal(Value::Undef);
                        let chk = self.op_array.alloc_temp();
                        self.op_array.emit(Op {
                            opcode: OpCode::Identical,
                            op1: OperandType::Cv(cv),
                            op2: OperandType::Const(undef_idx),
                            result: OperandType::Tmp(chk),
                            line: expr.span.line,
                        });
                        let jmp_undef = self.op_array.emit(Op {
                            opcode: OpCode::JmpNz,
                            op1: OperandType::Tmp(chk),
                            op2: OperandType::JmpTarget(0),
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                        self.op_array.emit(Op {
                            opcode: OpCode::ArrayAppend,
                            op1: OperandType::Tmp(arr_tmp),
                            op2: OperandType::Cv(cv),
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                        let jmp_end = self.op_array.emit(Op {
                            opcode: OpCode::Jmp,
                            op1: OperandType::JmpTarget(0),
                            op2: OperandType::Unused,
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                        let l_undef = self.op_array.current_offset();
                        self.op_array.patch_jump(jmp_undef, l_undef);
                        self.op_array.emit(Op {
                            opcode: OpCode::ArrayAppend,
                            op1: OperandType::Tmp(arr_tmp),
                            op2: OperandType::Const(undef_idx),
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                        let l_end = self.op_array.current_offset();
                        self.op_array.patch_jump(jmp_end, l_end);
                    }
                    Ok(self.wrap_closure_operand(OperandType::Tmp(arr_tmp)))
                } else {
                    let name_val_idx = self
                        .op_array
                        .add_literal(Value::String(PhpString::from_vec(closure_name)));
                    Ok(self.wrap_closure_operand(OperandType::Const(name_val_idx)))
                }
            }

            ExprKind::Yield(value, key) => {
                // The key is evaluated before the value (zend_compile_yield).
                let key_operand = if let Some(key_expr) = key {
                    self.compile_expr(key_expr)?
                } else {
                    OperandType::Unused
                };
                // For by-ref generators (function &gen()), yielding a non-reference
                // expression (constant, operator result, by-value function call)
                // emits a runtime Notice. We detect at compile time:
                //   - literals and operator results: notice
                //   - variables / array access / property access: no notice
                //   - function calls: notice unless the static name resolves to a
                //     function declared as returns_by_ref
                if self.op_array.returns_by_ref {
                    if let Some(val_expr) = value {
                        if expr_is_in_nullsafe_chain(val_expr) {
                            return Err(CompileError {
                                message: "Cannot take reference of a nullsafe chain".into(),
                                line: val_expr.span.line,
                            });
                        }
                        let mut emit_notice = false;
                        match &val_expr.kind {
                            ExprKind::Variable(_)
                            | ExprKind::DynamicVariable(_)
                            | ExprKind::PropertyAccess { .. }
                            | ExprKind::StaticPropertyAccess { .. }
                            | ExprKind::DynamicStaticPropertyAccess { .. }
                            | ExprKind::ArrayAccess { .. } => {}
                            // A call: the notice depends on whether the callee
                            // returned a reference (below, once it ran).
                            ExprKind::FunctionCall { .. }
                            | ExprKind::MethodCall { .. }
                            | ExprKind::StaticMethodCall { .. } => {}
                            _ => {
                                emit_notice = true;
                            }
                        }
                        if emit_notice {
                            let msg_str = "Only variable references should be yielded by reference";
                            let msg_idx = self.op_array.add_literal(Value::String(
                                crate::string::PhpString::from_bytes(msg_str.as_bytes()),
                            ));
                            self.op_array.emit(Op {
                                opcode: OpCode::EmitNotice,
                                op1: OperandType::Const(msg_idx),
                                op2: OperandType::Unused,
                                result: OperandType::Unused,
                                line: expr.span.line,
                            });
                        }
                    }
                }
                // Compile the yielded value (if any); a by-ref generator yields
                // the variable / element / property itself.
                let val_operand = if let Some(val_expr) = value {
                    if self.op_array.returns_by_ref
                        && matches!(
                            val_expr.kind,
                            ExprKind::Variable(_)
                                | ExprKind::ArrayAccess { index: Some(_), .. }
                                | ExprKind::PropertyAccess {
                                    nullsafe: false,
                                    ..
                                }
                        )
                    {
                        self.compile_ref_fetch(val_expr)?
                    } else if self.op_array.returns_by_ref
                        && matches!(
                            val_expr.kind,
                            ExprKind::FunctionCall { .. }
                                | ExprKind::MethodCall { .. }
                                | ExprKind::StaticMethodCall { .. }
                        )
                    {
                        self.compile_yield_ref_call(val_expr, expr.span.line)?
                    } else {
                        self.compile_expr(val_expr)?
                    }
                } else {
                    OperandType::Unused
                };

                // The result of a yield expression is the value sent via send()
                let result_tmp = self.op_array.alloc_temp();
                self.op_array.emit(Op {
                    opcode: OpCode::Yield,
                    op1: val_operand,
                    op2: key_operand,
                    result: OperandType::Tmp(result_tmp),
                    line: expr.span.line,
                });
                Ok(OperandType::Tmp(result_tmp))
            }

            ExprKind::YieldFrom(inner) => {
                if self.op_array.returns_by_ref {
                    return Err(CompileError {
                        message: "Cannot use \"yield from\" inside a by-reference generator".into(),
                        line: expr.span.line,
                    });
                }
                let val = self.compile_expr(inner)?;
                let tmp = self.op_array.alloc_temp();
                self.op_array.emit(Op {
                    opcode: OpCode::YieldFrom,
                    op1: val,
                    op2: OperandType::Unused,
                    result: OperandType::Tmp(tmp),
                    line: expr.span.line,
                });
                Ok(OperandType::Tmp(tmp))
            }

            ExprKind::Clone(inner) => {
                let val = self.compile_expr(inner)?;
                let tmp = self.op_array.alloc_temp();
                self.op_array.emit(Op {
                    opcode: OpCode::CloneObj,
                    op1: val,
                    op2: OperandType::Unused,
                    result: OperandType::Tmp(tmp),
                    line: expr.span.line,
                });
                Ok(OperandType::Tmp(tmp))
            }

            ExprKind::Spread(inner) => self.compile_expr(inner),

            ExprKind::ThrowExpr(inner) => {
                let val = self.compile_expr(inner)?;
                self.op_array.emit(Op {
                    opcode: OpCode::Throw,
                    op1: val,
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line: expr.span.line,
                });
                // throw never returns, but we need a result for expression context
                let null_idx = self.op_array.add_literal(Value::Null);
                Ok(OperandType::Const(null_idx))
            }

            ExprKind::ClassConstAccess { class, constant } => {
                // Handle ClassName::class, ClassName::CONST, self::CONST
                let class_name = match &class.kind {
                    ExprKind::Identifier(name) => {
                        self.check_class_ref_scope(name, class.span.line)?;
                        self.resolve_class_name(name)
                    }
                    _ => {
                        if is_illegal_class_literal(class) {
                            let message = if constant == b"class"
                                && matches!(class.kind, ExprKind::Array(_))
                            {
                                "Cannot use \"::class\" on value of type array".into()
                            } else {
                                "Illegal class name".into()
                            };
                            return Err(CompileError {
                                message,
                                line: class.span.line,
                            });
                        }
                        // $expr::class - emit GetClassName opcode
                        if constant == b"class" {
                            // A constant-folded operand (zend_compile_class_name).
                            if let Some(v) = Self::eval_const_expr(class) {
                                return Err(CompileError {
                                    message: format!(
                                        "Cannot use \"::class\" on {}",
                                        crate::vm::Vm::value_type_name(&v)
                                    ),
                                    line: class.span.line,
                                });
                            }
                            let obj_operand = self.compile_expr(class)?;
                            let tmp = self.op_array.alloc_temp();
                            self.op_array.emit(Op {
                                opcode: OpCode::GetClassName,
                                op1: obj_operand,
                                op2: OperandType::Unused,
                                result: OperandType::Tmp(tmp),
                                line: expr.span.line,
                            });
                            return Ok(OperandType::Tmp(tmp));
                        }
                        // $obj::CONST / $name::CONST - the operand is an object (its
                        // class) or a class-name string; StaticPropGet takes either.
                        let obj_operand = self.compile_expr(class)?;
                        // Look up the constant using StaticPropGet
                        let const_name_idx = self
                            .op_array
                            .add_literal(Value::String(PhpString::from_vec(constant.clone())));
                        let tmp = self.op_array.alloc_temp();
                        self.op_array.emit(Op {
                            opcode: OpCode::StaticPropGet,
                            op1: obj_operand,
                            op2: OperandType::Const(const_name_idx),
                            result: OperandType::Tmp(tmp),
                            line: expr.span.line,
                        });
                        return Ok(OperandType::Tmp(tmp));
                    }
                };

                // ClassName::class returns the class name as a string
                if constant == b"class" {
                    return self.compile_class_name_const(
                        &class_name,
                        class.span.line,
                        expr.span.line,
                    );
                }

                // Try to find the constant at compile time in already-compiled classes
                let is_self_const = class_name.eq_ignore_ascii_case(b"self");
                let resolved_class = if self.keep_relative_class_names
                    && (is_self_const || class_name.eq_ignore_ascii_case(b"parent"))
                {
                    class_name.to_ascii_lowercase()
                } else if is_self_const {
                    self.current_class.clone().unwrap_or(class_name.clone())
                } else if class_name.eq_ignore_ascii_case(b"static") {
                    // Late static binding: resolve at runtime
                    b"static".to_vec()
                } else if class_name.eq_ignore_ascii_case(b"parent") {
                    self.current_parent_class
                        .clone()
                        .unwrap_or(class_name.clone())
                } else {
                    class_name.clone()
                };

                // Use runtime lookup via StaticPropGet (class constants are stored similarly)
                let class_idx = self
                    .op_array
                    .add_literal(Value::String(PhpString::from_vec(resolved_class)));
                // Track self:: references for trait patching
                if is_self_const && self.is_in_trait {
                    self.op_array.class_const_literals.push(class_idx);
                }
                let const_name_idx = self
                    .op_array
                    .add_literal(Value::String(PhpString::from_vec(constant.clone())));
                let tmp = self.op_array.alloc_temp();
                // Reuse StaticPropGet for class constants (VM will check both)
                self.op_array.emit(Op {
                    opcode: OpCode::StaticPropGet,
                    op1: OperandType::Const(class_idx),
                    op2: OperandType::Const(const_name_idx),
                    result: OperandType::Tmp(tmp),
                    line: expr.span.line,
                });
                Ok(OperandType::Tmp(tmp))
            }

            ExprKind::DynamicClassConstAccess { class, constant } => {
                // Dynamic class constant fetch: Foo::{$expr} or $var::{$expr}
                let class_op = match &class.kind {
                    ExprKind::Identifier(name) => {
                        let resolved = self.resolve_class_name(name);
                        let resolved = if resolved.eq_ignore_ascii_case(b"self") {
                            self.current_class.clone().unwrap_or(resolved)
                        } else if resolved.eq_ignore_ascii_case(b"parent") {
                            self.current_parent_class.clone().unwrap_or(resolved)
                        } else if resolved.eq_ignore_ascii_case(b"static") {
                            b"static".to_vec()
                        } else {
                            resolved
                        };
                        let class_idx = self
                            .op_array
                            .add_literal(Value::String(PhpString::from_vec(resolved)));
                        OperandType::Const(class_idx)
                    }
                    _ => {
                        // Dynamic class expression: $foo::{$bar}
                        // Compile the class expression - its result is a string with the class name
                        self.compile_expr(class)?
                    }
                };

                let const_expr = self.compile_expr(constant)?;
                let tmp = self.op_array.alloc_temp();
                self.op_array.emit(Op {
                    opcode: OpCode::StaticPropGet,
                    op1: class_op,
                    op2: const_expr,
                    result: OperandType::Tmp(tmp),
                    line: expr.span.line,
                });
                Ok(OperandType::Tmp(tmp))
            }

            ExprKind::StaticMethodCall {
                class,
                method,
                args,
                method_line,
            } => {
                self.check_parent_hook_call(class, method, false, expr.span.line)?;
                let discard_flag = if std::mem::take(&mut self.is_discarding_result) {
                    OperandType::Const(self.op_array.add_literal(Value::True))
                } else {
                    OperandType::Unused
                };
                // Check if the class expression is in a nullsafe chain
                let chain_nullsafe = expr_is_in_nullsafe_chain(class);
                let tmp = self.op_array.alloc_temp();

                // Handle ClassName::method() and parent::method()
                let class_name = match &class.kind {
                    ExprKind::Identifier(name) => {
                        self.check_class_ref_scope(name, class.span.line)?;
                        Some(self.resolve_class_name(name))
                    }
                    _ => None, // Dynamic class expression - resolve at runtime
                };

                // For nullsafe chains with dynamic class, we need to pre-compile the class
                // and check for null before setting up the call
                let jmp_null = if chain_nullsafe && class_name.is_none() {
                    let class_operand = self.compile_expr(class)?;
                    let null_idx = self.op_array.add_literal(Value::Null);
                    let is_null_tmp = self.op_array.alloc_temp();
                    self.op_array.emit(Op {
                        opcode: OpCode::Identical,
                        op1: class_operand,
                        op2: OperandType::Const(null_idx),
                        result: OperandType::Tmp(is_null_tmp),
                        line: expr.span.line,
                    });
                    let jmp = self.op_array.emit(Op {
                        opcode: OpCode::JmpNz,
                        op1: OperandType::Tmp(is_null_tmp),
                        op2: OperandType::JmpTarget(0),
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });

                    // Emit the call setup with pre-compiled class operand
                    let method_idx = self
                        .op_array
                        .add_literal(Value::String(PhpString::from_vec(method.to_vec())));
                    let arg_count = self.op_array.add_literal(Value::Long(args.len() as i64));
                    self.op_array.emit(Op {
                        opcode: OpCode::InitDynamicStaticCall,
                        op1: class_operand,
                        op2: OperandType::Const(method_idx),
                        result: OperandType::Const(arg_count),
                        line: expr.span.line,
                    });

                    self.compile_send_args(args, expr.span.line)?;

                    self.op_array.emit(Op {
                        opcode: OpCode::DoFCall,
                        op1: discard_flag,
                        op2: OperandType::Unused,
                        result: OperandType::Tmp(tmp),
                        line: if *method_line > 0 { *method_line } else { expr.span.line },
                    });

                    Some(jmp)
                } else {
                    // mysqli::poll() takes its arrays by reference
                    let static_bridge: Option<&[u8]> = match &class_name {
                        Some(c)
                            if c.eq_ignore_ascii_case(b"mysqli")
                                && method.eq_ignore_ascii_case(b"poll") =>
                        {
                            Some(b"mysqli_poll")
                        }
                        _ => None,
                    };
                    // ext/intl static methods implemented by a procedural
                    // function (`@alias`): its stub declares the by-reference
                    // parameters (IntlTimeZone::getCanonicalID(), ...).
                    let intl_alias: Option<Vec<u8>> = match &class_name {
                        Some(c) if static_bridge.is_none() => crate::stubs::find_method(c, method)
                            .filter(|(sc, m)| sc.ext == "intl" && m.is_static())
                            .and_then(|(sc, m)| {
                                crate::stub_sigs::ALIASES
                                    .iter()
                                    .find(|(k, _)| {
                                        k.split_once("::").is_some_and(|(kc, km)| {
                                            kc.eq_ignore_ascii_case(sc.name)
                                                && km.eq_ignore_ascii_case(m.name)
                                        })
                                    })
                                    .map(|(_, f)| f.as_bytes().to_ascii_lowercase())
                            }),
                        _ => None,
                    };
                    let static_bridge = static_bridge.or(intl_alias.as_deref());
                    if let Some(class_name) = class_name {
                        // Static class name known at compile time
                        // Keep parent:: and self:: as markers for late static binding forwarding.
                        // The VM will resolve them at runtime while preserving the called class.
                        // static:: is also kept as-is (already handled).
                        // Only explicit class names are resolved here.
                        let resolved_class = if class_name.eq_ignore_ascii_case(b"self") {
                            if self.is_in_trait {
                                // In traits, self:: must be resolved to the trait name now
                                // (trait patching will replace it later with the using class)
                                self.current_class.clone().unwrap_or(class_name.clone())
                            } else {
                                // Keep "self" as marker for LSB forwarding
                                b"self".to_vec()
                            }
                        } else if class_name.eq_ignore_ascii_case(b"static") {
                            b"static".to_vec()
                        } else if class_name.eq_ignore_ascii_case(b"parent") {
                            if self.is_in_trait {
                                // In traits, parent:: must be resolved to the parent name now
                                self.current_parent_class
                                    .clone()
                                    .unwrap_or(class_name.clone())
                            } else {
                                // Keep "parent" as marker for LSB forwarding
                                b"parent".to_vec()
                            }
                        } else {
                            class_name.clone()
                        };

                        let mut func_name = resolved_class;
                        func_name.extend_from_slice(b"::");
                        func_name.extend_from_slice(method);
                        let name_idx = self
                            .op_array
                            .add_literal(Value::String(PhpString::from_vec(func_name)));
                        if self.is_in_trait && class_name.eq_ignore_ascii_case(b"self") {
                            // "Trait::method" is re-targeted to the using class on import.
                            self.op_array.class_const_literals.push(name_idx);
                        }
                        let arg_count = self.op_array.add_literal(Value::Long(args.len() as i64));
                        self.op_array.emit(Op {
                            opcode: OpCode::InitFCall,
                            op1: OperandType::Const(name_idx),
                            op2: OperandType::Const(arg_count),
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                    } else {
                        // Dynamic class expression: $obj::method() or expr::method()
                        let class_operand = self.compile_expr(class)?;
                        let method_idx = self
                            .op_array
                            .add_literal(Value::String(PhpString::from_vec(method.to_vec())));
                        let arg_count = self.op_array.add_literal(Value::Long(args.len() as i64));
                        self.op_array.emit(Op {
                            opcode: OpCode::InitDynamicStaticCall,
                            op1: class_operand,
                            op2: OperandType::Const(method_idx),
                            result: OperandType::Const(arg_count),
                            line: expr.span.line,
                        });
                    }

                    self.compile_send_args_with_name(args, expr.span.line, static_bridge)?;

                    self.op_array.emit(Op {
                        opcode: OpCode::DoFCall,
                        op1: discard_flag,
                        op2: OperandType::Unused,
                        result: OperandType::Tmp(tmp),
                        line: if *method_line > 0 { *method_line } else { expr.span.line },
                    });

                    None
                };

                if let Some(jmp) = jmp_null {
                    let skip_null = self.op_array.emit(Op {
                        opcode: OpCode::Jmp,
                        op1: OperandType::JmpTarget(0),
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });
                    let null_assign_pos = self.op_array.current_offset();
                    self.op_array.patch_jump(jmp, null_assign_pos);
                    let null_idx = self.op_array.add_literal(Value::Null);
                    self.op_array.emit(Op {
                        opcode: OpCode::Assign,
                        op1: OperandType::Tmp(tmp),
                        op2: OperandType::Const(null_idx),
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });
                    let end = self.op_array.current_offset();
                    self.op_array.patch_jump(skip_null, end);
                }

                Ok(OperandType::Tmp(tmp))
            }

            ExprKind::DynamicStaticMethodCall {
                class,
                method,
                args,
            } => {
                if matches!(
                    method.kind,
                    ExprKind::Int(_)
                        | ExprKind::Float(_)
                        | ExprKind::True
                        | ExprKind::False
                        | ExprKind::Null
                ) {
                    return Err(CompileError {
                        message: "Method name must be a string".into(),
                        line: expr.span.line,
                    });
                }
                // Dynamic static method call: Foo::$method()
                let class_operand = match &class.kind {
                    ExprKind::Identifier(name) => {
                        let resolved = self.resolve_class_name(name);
                        let resolved = if resolved.eq_ignore_ascii_case(b"self") {
                            self.current_class.clone().unwrap_or(resolved)
                        } else if resolved.eq_ignore_ascii_case(b"parent") {
                            self.current_parent_class.clone().unwrap_or(resolved)
                        } else {
                            resolved
                        };
                        let idx = self
                            .op_array
                            .add_literal(Value::String(PhpString::from_vec(resolved)));
                        OperandType::Const(idx)
                    }
                    _ => self.compile_expr(class)?,
                };
                let method_operand = self.compile_expr(method)?;
                let arg_count = self.op_array.add_literal(Value::Long(args.len() as i64));
                self.op_array.emit(Op {
                    opcode: OpCode::InitDynamicStaticCall,
                    op1: class_operand,
                    op2: method_operand,
                    result: OperandType::Const(arg_count),
                    line: expr.span.line,
                });

                self.compile_send_args(args, expr.span.line)?;

                let tmp = self.op_array.alloc_temp();
                self.op_array.emit(Op {
                    opcode: OpCode::DoFCall,
                    op1: OperandType::Unused,
                    op2: OperandType::Unused,
                    result: OperandType::Tmp(tmp),
                    line: expr.span.line,
                });

                Ok(OperandType::Tmp(tmp))
            }

            ExprKind::StaticPropertyAccess { class, property } => {
                if is_illegal_class_literal(class) {
                    return Err(CompileError {
                        message: "Illegal class name".into(),
                        line: class.span.line,
                    });
                }
                // Check if the class expression is in a nullsafe chain
                let chain_nullsafe = expr_is_in_nullsafe_chain(class);
                let (class_operand, prop_str) = match &class.kind {
                    ExprKind::Identifier(name) => {
                        let resolved = self.resolve_class_name(name);
                        // Resolve self/parent, keep static as literal for LSB
                        let is_self = resolved.eq_ignore_ascii_case(b"self");
                        let class_name = if is_self {
                            self.current_class.clone().unwrap_or(resolved)
                        } else if resolved.eq_ignore_ascii_case(b"static") {
                            // Late static binding: resolve at runtime
                            b"static".to_vec()
                        } else if resolved.eq_ignore_ascii_case(b"parent") {
                            self.current_parent_class.clone().unwrap_or(resolved)
                        } else {
                            resolved
                        };
                        let idx = self
                            .op_array
                            .add_literal(Value::String(PhpString::from_vec(class_name)));
                        // Track self:: references for trait patching (like __CLASS__)
                        if is_self && self.is_in_trait {
                            self.op_array.class_const_literals.push(idx);
                        }
                        (OperandType::Const(idx), property.clone())
                    }
                    _ => {
                        // Dynamic class expression (e.g. $obj::$prop) - compile and pass as operand
                        let class_op = self.compile_expr(class)?;
                        (class_op, property.clone())
                    }
                };
                let prop_idx = self
                    .op_array
                    .add_literal(Value::String(PhpString::from_vec(prop_str)));
                let tmp = self.op_array.alloc_temp();

                // Nullsafe chain: if class expression could be null, short-circuit
                let jmp_null = if chain_nullsafe {
                    let null_idx = self.op_array.add_literal(Value::Null);
                    let is_null_tmp = self.op_array.alloc_temp();
                    self.op_array.emit(Op {
                        opcode: OpCode::Identical,
                        op1: class_operand,
                        op2: OperandType::Const(null_idx),
                        result: OperandType::Tmp(is_null_tmp),
                        line: expr.span.line,
                    });
                    let jmp = self.op_array.emit(Op {
                        opcode: OpCode::JmpNz,
                        op1: OperandType::Tmp(is_null_tmp),
                        op2: OperandType::JmpTarget(0),
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });
                    Some(jmp)
                } else {
                    None
                };

                self.op_array.emit(Op {
                    opcode: OpCode::StaticPropFetch,
                    op1: class_operand,
                    op2: OperandType::Const(prop_idx),
                    result: OperandType::Tmp(tmp),
                    line: expr.span.line,
                });

                if let Some(jmp) = jmp_null {
                    let skip_null = self.op_array.emit(Op {
                        opcode: OpCode::Jmp,
                        op1: OperandType::JmpTarget(0),
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });
                    let null_assign_pos = self.op_array.current_offset();
                    self.op_array.patch_jump(jmp, null_assign_pos);
                    let null_idx = self.op_array.add_literal(Value::Null);
                    self.op_array.emit(Op {
                        opcode: OpCode::Assign,
                        op1: OperandType::Tmp(tmp),
                        op2: OperandType::Const(null_idx),
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });
                    let end = self.op_array.current_offset();
                    self.op_array.patch_jump(skip_null, end);
                }

                Ok(OperandType::Tmp(tmp))
            }

            ExprKind::DynamicStaticPropertyAccess { class, property } => {
                // Test::$$bar - compile class and property expression, then StaticPropFetch
                let class_operand = match &class.kind {
                    ExprKind::Identifier(name) => {
                        let resolved = self.resolve_class_name(name);
                        let is_self = resolved.eq_ignore_ascii_case(b"self");
                        let class_name = if is_self {
                            self.current_class.clone().unwrap_or(resolved)
                        } else if resolved.eq_ignore_ascii_case(b"static") {
                            b"static".to_vec()
                        } else if resolved.eq_ignore_ascii_case(b"parent") {
                            self.current_parent_class.clone().unwrap_or(resolved)
                        } else {
                            resolved
                        };
                        let idx = self
                            .op_array
                            .add_literal(Value::String(PhpString::from_vec(class_name)));
                        if is_self && self.is_in_trait {
                            self.op_array.class_const_literals.push(idx);
                        }
                        OperandType::Const(idx)
                    }
                    _ => self.compile_expr(class)?,
                };
                // Compile the property expression (e.g., $bar which holds the property name)
                let prop_op = self.compile_expr(property)?;
                let tmp = self.op_array.alloc_temp();
                self.op_array.emit(Op {
                    opcode: OpCode::StaticPropFetch,
                    op1: class_operand,
                    op2: prop_op,
                    result: OperandType::Tmp(tmp),
                    line: expr.span.line,
                });
                Ok(OperandType::Tmp(tmp))
            }

            ExprKind::PropertyAccess {
                object,
                property,
                nullsafe,
            } => {
                self.chain_base = true;
                let obj = self.compile_expr(object)?;
                // Nullsafe: a null object short-circuits the chain (before
                // the property name is evaluated)
                let jmp_null = if *nullsafe {
                    self.emit_nullsafe_check(obj, expr.span.line)
                } else {
                    None
                };
                let prop_operand = self.compile_prop_name(property)?;

                let tmp = self.op_array.alloc_temp();

                if self.in_const_expr {
                    // (result: the property name, converted to string first)
                    self.op_array.emit(Op {
                        opcode: OpCode::ConstExprPropCheck,
                        op1: obj,
                        op2: OperandType::Unused,
                        result: prop_operand,
                        line: expr.span.line,
                    });
                }
                self.op_array.emit(Op {
                    opcode: OpCode::PropertyGet,
                    op1: obj,
                    op2: prop_operand,
                    result: OperandType::Tmp(tmp),
                    line: expr.span.line,
                });

                if let Some(jmp) = jmp_null {
                    // Jump past the assign-null
                    let skip_null = self.op_array.emit(Op {
                        opcode: OpCode::Jmp,
                        op1: OperandType::JmpTarget(0),
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });
                    // Nullsafe short-circuit: assign null to result
                    let null_assign_pos = self.op_array.current_offset();
                    self.op_array.patch_jump(jmp, null_assign_pos);
                    let null_idx = self.op_array.add_literal(Value::Null);
                    self.op_array.emit(Op {
                        opcode: OpCode::Assign,
                        op1: OperandType::Tmp(tmp),
                        op2: OperandType::Const(null_idx),
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });
                    let end = self.op_array.current_offset();
                    self.op_array.patch_jump(skip_null, end);
                }

                Ok(OperandType::Tmp(tmp))
            }

            ExprKind::MethodCall {
                object,
                method,
                args,
                nullsafe,
                ..
            } => {
                // Check if this is in a nullsafe chain (e.g., $obj?->foo()->bar()
                // where ->bar() should also short-circuit)
                if matches!(
                    method.kind,
                    ExprKind::Int(_)
                        | ExprKind::Float(_)
                        | ExprKind::True
                        | ExprKind::False
                        | ExprKind::Null
                ) {
                    return Err(CompileError {
                        message: "Method name must be a string".into(),
                        line: expr.span.line,
                    });
                }
                let discard_flag = if std::mem::take(&mut self.is_discarding_result) {
                    OperandType::Const(self.op_array.add_literal(Value::True))
                } else {
                    OperandType::Unused
                };
                let obj_tmp_start = self.op_array.temp_count;
                self.chain_base = true;
                let obj = self.compile_expr(object)?;
                let tmp = self.op_array.alloc_temp();

                // Nullsafe: a null object short-circuits the chain
                let jmp_null = if *nullsafe {
                    self.emit_nullsafe_check(obj, expr.span.line)
                } else {
                    None
                };

                let (method_operand, method_name_for_ref): (OperandType, Option<Vec<u8>>) =
                    match &method.kind {
                        ExprKind::Identifier(name) => {
                            let name_idx = self
                                .op_array
                                .add_literal(Value::String(PhpString::from_vec(name.clone())));
                            (OperandType::Const(name_idx), Some(name.clone()))
                        }
                        _ => {
                            // Dynamic method name (e.g., $this->$method())
                            (self.compile_expr(method)?, None)
                        }
                    };

                self.op_array.emit(Op {
                    opcode: OpCode::InitMethodCall,
                    op1: obj,
                    op2: method_operand,
                    result: OperandType::Unused,
                    line: expr.span.line,
                });

                // Pass method name through so by-ref args of known builtin methods
                // (e.g. mysqli_stmt::bind_param) emit SendRef.
                let bridge_name: Option<Vec<u8>> = method_name_for_ref
                    .as_ref()
                    .and_then(|m| Self::builtin_method_to_bridge_func(m));
                self.compile_send_args_with_name(args, expr.span.line, bridge_name.as_deref())?;

                // The call is on the method name's line (GH-8810).
                let call_line = if method.span.line > 0 {
                    method.span.line
                } else {
                    expr.span.line
                };
                self.op_array.emit(Op {
                    opcode: OpCode::DoFCall,
                    op1: discard_flag,
                    op2: OperandType::Unused,
                    result: OperandType::Tmp(tmp),
                    line: call_line,
                });

                if let Some(jmp) = jmp_null {
                    // Jump past the assign-null that follows
                    let skip_null = self.op_array.emit(Op {
                        opcode: OpCode::Jmp,
                        op1: OperandType::JmpTarget(0),
                        op2: OperandType::Unused,
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });
                    // Nullsafe short-circuit: assign null to result
                    let null_assign_pos = self.op_array.current_offset();
                    self.op_array.patch_jump(jmp, null_assign_pos);
                    let null_idx = self.op_array.add_literal(Value::Null);
                    self.op_array.emit(Op {
                        opcode: OpCode::Assign,
                        op1: OperandType::Tmp(tmp),
                        op2: OperandType::Const(null_idx),
                        result: OperandType::Unused,
                        line: expr.span.line,
                    });
                    let end = self.op_array.current_offset();
                    self.op_array.patch_jump(skip_null, end);
                }
                if matches!(obj, OperandType::Tmp(_)) {
                    self.emit_free_call_tmps(obj_tmp_start, tmp, expr.span.line);
                }

                Ok(OperandType::Tmp(tmp))
            }

            ExprKind::DynamicVariable(inner) => {
                // $$var - dynamic variable access
                let name_op = self.compile_expr(inner)?;
                let tmp = self.op_array.alloc_temp();
                self.op_array.emit(Op {
                    opcode: OpCode::VarVarGet,
                    op1: name_op,
                    op2: OperandType::Unused,
                    result: OperandType::Tmp(tmp),
                    line: expr.span.line,
                });
                Ok(OperandType::Tmp(tmp))
            }

            ExprKind::AssignRef { target, value } if matches!(&value.kind, ExprKind::DynamicVariable(i) if Self::static_dynvar_name(i).is_none()) => {
                self.compile_assign_ref_dynvar_value(expr, target, value)
            }

            ExprKind::AssignRef { target, value } if matches!(&target.kind, ExprKind::DynamicVariable(i) if Self::static_dynvar_name(i).is_none()) => {
                self.compile_assign_ref_dynvar_target(expr, target, value)
            }

            ExprKind::AssignRef { target, value } => {
                let result_discarded = std::mem::take(&mut self.assign_result_discarded);
                // Check for nullsafe chain in reference context
                if expr_is_in_nullsafe_chain(target) {
                    return Err(CompileError {
                        message: "Can't use nullsafe operator in write context".into(),
                        line: expr.span.line,
                    });
                }
                if expr_is_in_nullsafe_chain(value) {
                    return Err(CompileError {
                        message: "Cannot take reference of a nullsafe chain".into(),
                        line: expr.span.line,
                    });
                }
                // Check for $this = &$value
                if let ExprKind::Variable(target_name) = &target.kind {
                    if target_name == b"this" && self.current_class.is_some() {
                        return Err(CompileError {
                            message: "Cannot re-assign $this".into(),
                            line: expr.span.line,
                        });
                    }
                }
                // $GLOBALS can only be modified using $GLOBALS[$name] = $value syntax
                if matches!(&target.kind, ExprKind::Variable(name) if name == b"GLOBALS") {
                    return Err(CompileError {
                        message: "$GLOBALS can only be modified using the $GLOBALS[$name] = $value syntax".to_string(),
                        line: expr.span.line,
                    });
                }
                if matches!(&value.kind, ExprKind::Variable(n) if n == b"GLOBALS") {
                    return Err(CompileError {
                        message: "Cannot acquire reference to $GLOBALS".into(),
                        line: expr.span.line,
                    });
                }
                // $target = &$value  — both CVs share the same reference
                match (&target.kind, &value.kind) {
                    (ExprKind::Variable(target_name), ExprKind::Variable(value_name)) => {
                        let target_cv = self.op_array.get_or_create_cv(target_name);
                        let value_cv = self.op_array.get_or_create_cv(value_name);
                        self.op_array.emit(Op {
                            opcode: OpCode::AssignRef,
                            op1: OperandType::Cv(target_cv),
                            op2: OperandType::Cv(value_cv),
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                        Ok(OperandType::Cv(target_cv))
                    }
                    (
                        ExprKind::Variable(target_name),
                        ExprKind::ArrayAccess {
                            array: value_arr,
                            index: value_idx,
                        },
                    ) => {
                        // $var = &$arr[key] — get/create reference in array, assign to variable
                        let ref_tmp =
                            self.compile_dim_ref(value_arr, value_idx.as_deref(), expr.span.line)?;
                        let target_cv = self.op_array.get_or_create_cv(target_name);
                        // Bind the CV to the reference (rebinding, not writing
                        // through a reference the CV may already hold)
                        self.op_array.emit(Op {
                            opcode: OpCode::AssignRef,
                            op1: OperandType::Cv(target_cv),
                            op2: OperandType::Tmp(ref_tmp),
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                        Ok(OperandType::Cv(target_cv))
                    }
                    (
                        ExprKind::Variable(target_name),
                        ExprKind::PropertyAccess {
                            object,
                            property,
                            nullsafe: false,
                        },
                    ) => {
                        // $var = &$obj->prop — bind the variable to the property slot
                        // (rebinding, not writing through a reference the CV
                        // may already hold)
                        let ref_tmp =
                            self.compile_property_ref(object, property, expr.span.line)?;
                        let target_cv = self.op_array.get_or_create_cv(target_name);
                        self.op_array.emit(Op {
                            opcode: OpCode::AssignRef,
                            op1: OperandType::Cv(target_cv),
                            op2: OperandType::Tmp(ref_tmp),
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                        Ok(OperandType::Cv(target_cv))
                    }
                    (
                        ExprKind::ArrayAccess { array, index },
                        ExprKind::PropertyAccess {
                            object,
                            property,
                            nullsafe: false,
                        },
                    ) => self.compile_dim_assign_prop_ref(
                        array,
                        index.as_deref(),
                        object,
                        property,
                        result_discarded,
                        expr.span.line,
                    ),
                    (
                        ExprKind::PropertyAccess {
                            object,
                            property,
                            nullsafe: false,
                        },
                        _,
                    ) => {
                        // $obj->prop = &<expr>
                        let value_op = match &value.kind {
                            ExprKind::Variable(value_name) => {
                                let value_cv = self.op_array.get_or_create_cv(value_name);
                                self.op_array.emit(Op {
                                    opcode: OpCode::MakeRef,
                                    op1: OperandType::Cv(value_cv),
                                    op2: OperandType::Unused,
                                    result: OperandType::Unused,
                                    line: expr.span.line,
                                });
                                OperandType::Cv(value_cv)
                            }
                            ExprKind::ArrayAccess {
                                array: value_arr,
                                index: value_idx,
                            } => OperandType::Tmp(self.compile_dim_ref(
                                value_arr,
                                value_idx.as_deref(),
                                expr.span.line,
                            )?),
                            ExprKind::PropertyAccess {
                                object: vo,
                                property: vp,
                                nullsafe: false,
                            } => OperandType::Tmp(self.compile_property_ref(
                                vo,
                                vp,
                                expr.span.line,
                            )?),
                            ExprKind::StaticPropertyAccess { .. }
                            | ExprKind::DynamicStaticPropertyAccess { .. } => OperandType::Tmp(
                                self.emit_static_prop_fetch(OpCode::StaticPropGetRef, value)?,
                            ),
                            _ => self.compile_expr(value)?,
                        };
                        let obj = self.compile_obj_write_base(object)?;
                        let name = self.compile_property_name(property)?;
                        self.op_array.emit(Op {
                            opcode: OpCode::PropertySetRef,
                            op1: obj,
                            op2: value_op,
                            result: name,
                            line: expr.span.line,
                        });
                        // (ZEND_ASSIGN_OBJ_REF raises it once the property
                        // slot was fetched)
                        if !matches!(
                            value.kind,
                            ExprKind::Variable(_)
                                | ExprKind::ArrayAccess { .. }
                                | ExprKind::PropertyAccess {
                                    nullsafe: false,
                                    ..
                                }
                                | ExprKind::StaticPropertyAccess { .. }
                                | ExprKind::DynamicStaticPropertyAccess { .. }
                        ) {
                            self.emit_assign_ref_call_notice(value, expr.span.line);
                        }
                        Ok(value_op)
                    }
                    (
                        ExprKind::Variable(target_name),
                        ExprKind::StaticPropertyAccess { .. }
                        | ExprKind::DynamicStaticPropertyAccess { .. },
                    ) => {
                        // $var = &C::$p — bind the variable to the static slot
                        let ref_tmp =
                            self.emit_static_prop_fetch(OpCode::StaticPropGetRef, value)?;
                        let target_cv = self.op_array.get_or_create_cv(target_name);
                        self.op_array.emit(Op {
                            opcode: OpCode::AssignRef,
                            op1: OperandType::Cv(target_cv),
                            op2: OperandType::Tmp(ref_tmp),
                            result: OperandType::Unused,
                            line: expr.span.line,
                        });
                        Ok(OperandType::Cv(target_cv))
                    }
                    (
                        ExprKind::ArrayAccess {
                            array,
                            index: Some(index),
                        },
                        ExprKind::StaticPropertyAccess { .. }
                        | ExprKind::DynamicStaticPropertyAccess { .. },
                    ) => {
                        // $arr[k] = &C::$p
                        let ref_tmp =
                            self.emit_static_prop_fetch(OpCode::StaticPropGetRef, value)?;
                        let arr = self.compile_dim_write_base(array)?;
                        let idx = self.compile_expr(index)?;
                        self.op_array.emit(Op {
                            opcode: OpCode::ArraySetRef,
                            op1: arr,
                            op2: OperandType::Tmp(ref_tmp),
                            result: idx,
                            line: expr.span.line,
                        });
                        Ok(arr)
                    }
                    (ExprKind::Variable(target_name), _) => {
                        // $target = &<expr> — evaluate expr, assign to target, then make both reference
                        let is_call = Self::is_call_expr(value);
                        let val = self.compile_expr(value)?;
                        self.emit_assign_ref_call_notice(value, expr.span.line);
                        let target_cv = self.op_array.get_or_create_cv(target_name);
                        if is_call && matches!(val, OperandType::Tmp(_)) {
                            // Bind to the returned reference (or assign the value).
                            self.mark_ref_call(&val);
                            let result = if result_discarded {
                                OperandType::Unused
                            } else {
                                OperandType::Tmp(self.op_array.alloc_temp())
                            };
                            self.op_array.emit(Op {
                                opcode: OpCode::AssignRef,
                                op1: OperandType::Cv(target_cv),
                                op2: val,
                                result,
                                line: expr.span.line,
                            });
                            return Ok(if result_discarded {
                                OperandType::Cv(target_cv)
                            } else {
                                result
                            });
                        }
                        let result = if result_discarded {
                            OperandType::Unused
                        } else {
                            OperandType::Tmp(self.op_array.alloc_temp())
                        };
                        self.op_array.emit(Op {
                            opcode: OpCode::Assign,
                            op1: OperandType::Cv(target_cv),
                            op2: val,
                            result,
                            line: expr.span.line,
                        });
                        Ok(if result_discarded {
                            OperandType::Cv(target_cv)
                        } else {
                            result
                        })
                    }
                    (ExprKind::ArrayAccess { array, index }, ExprKind::Variable(value_name)) => {
                        // $arr[key] = &$var — store reference into array element
                        let arr = self.compile_dim_write_base(array)?;
                        let value_cv = self.op_array.get_or_create_cv(value_name);
                        if let Some(idx_expr) = index {
                            let idx = self.compile_expr(idx_expr)?;
                            self.op_array.emit(Op {
                                opcode: OpCode::ArraySetRef,
                                op1: arr,
                                op2: OperandType::Cv(value_cv),
                                result: idx,
                                line: expr.span.line,
                            });
                        } else {
                            // $arr[] = &$var — append reference
                            self.op_array.emit(Op {
                                opcode: OpCode::MakeRef,
                                op1: OperandType::Cv(value_cv),
                                op2: OperandType::Unused,
                                result: OperandType::Unused,
                                line: expr.span.line,
                            });
                            self.op_array.emit(Op {
                                opcode: OpCode::ArrayAppendRef,
                                op1: arr,
                                op2: OperandType::Cv(value_cv),
                                result: OperandType::Unused,
                                line: expr.span.line,
                            });
                        }
                        Ok(self.ref_assign_result(
                            OperandType::Cv(value_cv),
                            result_discarded,
                            expr.span.line,
                        ))
                    }
                    (
                        ExprKind::ArrayAccess {
                            array: target_arr,
                            index: target_idx,
                        },
                        ExprKind::ArrayAccess {
                            array: value_arr,
                            index: value_idx,
                        },
                    ) => {
                        // $arr1[k1] = &$arr2[k2] — get/create reference in source, store in target
                        let ref_tmp =
                            self.compile_dim_ref(value_arr, value_idx.as_deref(), expr.span.line)?;
                        let dst_arr = self.compile_dim_write_base(target_arr)?;
                        if let Some(dst_idx_expr) = target_idx {
                            let dst_idx = self.compile_expr(dst_idx_expr)?;
                            self.op_array.emit(Op {
                                opcode: OpCode::ArraySetRef,
                                op1: dst_arr,
                                op2: OperandType::Tmp(ref_tmp),
                                result: dst_idx,
                                line: expr.span.line,
                            });
                        } else {
                            self.op_array.emit(Op {
                                opcode: OpCode::ArrayAppendRef,
                                op1: dst_arr,
                                op2: OperandType::Tmp(ref_tmp),
                                result: OperandType::Unused,
                                line: expr.span.line,
                            });
                        }
                        Ok(self.ref_assign_result(
                            OperandType::Tmp(ref_tmp),
                            result_discarded,
                            expr.span.line,
                        ))
                    }
                    (ExprKind::ArrayAccess { array, index }, _) => {
                        // $arr[key] = &<expr> — evaluate expr and store reference
                        let arr = self.compile_dim_write_base(array)?;
                        let val = self.compile_expr(value)?;
                        if let Some(idx_expr) = index {
                            let idx = self.compile_expr(idx_expr)?;
                            self.op_array.emit(Op {
                                opcode: OpCode::ArraySetRef,
                                op1: arr,
                                op2: val,
                                result: idx,
                                line: expr.span.line,
                            });
                        } else {
                            self.op_array.emit(Op {
                                opcode: OpCode::ArrayAppendRef,
                                op1: arr,
                                op2: val,
                                result: OperandType::Unused,
                                line: expr.span.line,
                            });
                        }
                        // (after the dimension fetch, which may throw)
                        self.emit_assign_ref_call_notice(value, expr.span.line);
                        Ok(self.ref_assign_result(val, result_discarded, expr.span.line))
                    }
                    (
                        ExprKind::StaticPropertyAccess { .. }
                        | ExprKind::DynamicStaticPropertyAccess { .. },
                        _,
                    ) => {
                        // C::$p = &<expr>
                        let value_op = match &value.kind {
                            ExprKind::Variable(value_name) => {
                                let value_cv = self.op_array.get_or_create_cv(value_name);
                                self.op_array.emit(Op {
                                    opcode: OpCode::MakeRef,
                                    op1: OperandType::Cv(value_cv),
                                    op2: OperandType::Unused,
                                    result: OperandType::Unused,
                                    line: expr.span.line,
                                });
                                OperandType::Cv(value_cv)
                            }
                            ExprKind::ArrayAccess {
                                array: value_arr,
                                index: Some(value_idx),
                            } => {
                                let src_arr = self.compile_dim_write_base(value_arr)?;
                                let src_idx = self.compile_expr(value_idx)?;
                                let ref_tmp = self.op_array.alloc_temp();
                                self.op_array.emit(Op {
                                    opcode: OpCode::ArrayGetRef,
                                    op1: src_arr,
                                    op2: src_idx,
                                    result: OperandType::Tmp(ref_tmp),
                                    line: expr.span.line,
                                });
                                OperandType::Tmp(ref_tmp)
                            }
                            ExprKind::PropertyAccess {
                                object: vo,
                                property: vp,
                                nullsafe: false,
                            } => OperandType::Tmp(self.compile_property_ref(
                                vo,
                                vp,
                                expr.span.line,
                            )?),
                            ExprKind::StaticPropertyAccess { .. }
                            | ExprKind::DynamicStaticPropertyAccess { .. } => OperandType::Tmp(
                                self.emit_static_prop_fetch(OpCode::StaticPropGetRef, value)?,
                            ),
                            _ => {
                                let v = self.compile_expr(value)?;
                                self.emit_assign_ref_call_notice(value, expr.span.line);
                                v
                            }
                        };
                        let (class_op, name_op) = self.compile_static_prop_operands(target)?;
                        self.op_array.emit(Op {
                            opcode: OpCode::StaticPropSetRef,
                            op1: class_op,
                            op2: value_op,
                            result: name_op,
                            line: expr.span.line,
                        });
                        Ok(self.ref_assign_result(value_op, result_discarded, expr.span.line))
                    }
                    _ => {
                        let idx = self.op_array.add_literal(Value::Null);
                        Ok(OperandType::Const(idx))
                    }
                }
            }

            ExprKind::FirstClassCallable(target) => {
                if let CallableTarget::StaticMethod { class, method } = target {
                    self.check_parent_hook_call(class, method, true, expr.span.line)?;
                }
                self.compile_first_class_callable(target, expr.span.line)
            }

            ExprKind::ConstantAccess(parts) if parts.len() == 1 => {
                // Parenthesized constant name (`(NAME)(...)`): same lookup
                // (with namespace resolution) as a bare identifier.
                let e = Expr {
                    kind: ExprKind::Identifier(parts[0].clone()),
                    span: expr.span,
                };
                self.compile_expr(&e)
            }

            ExprKind::ConstantAccess(parts) => {
                // Qualified constant - build fully-qualified name and emit ConstLookup
                let mut full_name = Vec::new();
                for (i, part) in parts.iter().enumerate() {
                    if i > 0 {
                        full_name.push(b'\\');
                    }
                    full_name.extend_from_slice(part);
                }
                // Check if it's a known compile-time constant first
                let lower: Vec<u8> = full_name.iter().map(|b| b.to_ascii_lowercase()).collect();
                // Try to resolve as a known constant (using the Identifier path)
                let known = match lower.as_slice() {
                    b"true" => Some(Value::True),
                    b"false" => Some(Value::False),
                    b"null" => Some(Value::Null),
                    _ => None,
                };
                if let Some(val) = known {
                    let idx = self.op_array.add_literal(val);
                    Ok(OperandType::Const(idx))
                } else {
                    let name_idx = self
                        .op_array
                        .add_literal(Value::String(PhpString::from_vec(full_name)));
                    let tmp = self.op_array.alloc_temp();
                    self.op_array.emit(Op {
                        opcode: OpCode::ConstLookup,
                        op1: OperandType::Const(name_idx),
                        op2: OperandType::Unused,
                        result: OperandType::Tmp(tmp),
                        line: expr.span.line,
                    });
                    Ok(OperandType::Tmp(tmp))
                }
            }
        }
    }

    /// Wrap the internal callable produced for a closure expression into a
    /// `Closure` object (emits MakeClosure).
    fn wrap_closure_operand(&mut self, inner: OperandType) -> OperandType {
        let line = self.op_array.ops.last().map(|o| o.line).unwrap_or(0);
        let tmp = self.op_array.alloc_temp();
        self.op_array.emit(Op {
            opcode: OpCode::MakeClosure,
            op1: inner,
            op2: OperandType::Unused,
            result: OperandType::Tmp(tmp),
            line,
        });
        OperandType::Tmp(tmp)
    }

    /// Compile first-class callable syntax: strlen(...), $obj->method(...), Foo::method(...)
    /// Creates a synthetic closure that wraps the call and forwards arguments via ...$args.
    /// `$arr[k] = &$obj->prop` / `$arr[] = &$obj->prop`: the property
    /// becomes a reference (MAKE_REF) before the dimension is fetched for
    /// writing, so `$o->x[] = &$o->x` nests the reference in itself.
    #[inline(never)]
    fn compile_dim_assign_prop_ref(
        &mut self,
        array: &Expr,
        index: Option<&Expr>,
        object: &Expr,
        property: &Expr,
        result_discarded: bool,
        line: u32,
    ) -> CompileResult<OperandType> {
        let ref_tmp = self.compile_property_ref(object, property, line)?;
        let arr = self.compile_dim_write_base(array)?;
        if let Some(index) = index {
            let idx = self.compile_expr(index)?;
            self.op_array.emit(Op {
                opcode: OpCode::ArraySetRef,
                op1: arr,
                op2: OperandType::Tmp(ref_tmp),
                result: idx,
                line,
            });
        } else {
            self.op_array.emit(Op {
                opcode: OpCode::ArrayAppendRef,
                op1: arr,
                op2: OperandType::Tmp(ref_tmp),
                result: OperandType::Unused,
                line,
            });
        }
        Ok(self.ref_assign_result(OperandType::Tmp(ref_tmp), result_discarded, line))
    }

    fn compile_first_class_callable(
        &mut self,
        target: &CallableTarget,
        line: u32,
    ) -> CompileResult<OperandType> {
        // Check for nullsafe operator which cannot be combined with closure creation
        let in_nullsafe_chain = match target {
            CallableTarget::Method { nullsafe: true, .. } => true,
            CallableTarget::Method { object, .. } => expr_is_in_nullsafe_chain(object),
            CallableTarget::StaticMethod { class, .. } => expr_is_in_nullsafe_chain(class),
            CallableTarget::Function(f) => expr_is_in_nullsafe_chain(f),
        };
        if in_nullsafe_chain {
            return Err(CompileError {
                message: "Cannot combine nullsafe operator with Closure creation".into(),
                line,
            });
        }

        // Target descriptor resolved at runtime by MakeFcc (see Vm::make_fcc).
        let fcc_desc: Option<Vec<u8>> = match target {
            CallableTarget::Function(name_expr) => match &name_expr.kind {
                ExprKind::Identifier(n) => {
                    // Only unqualified names fall back to the global function.
                    let mut d = if n.contains(&b'\\') {
                        b"F:".to_vec()
                    } else {
                        b"f:".to_vec()
                    };
                    d.extend_from_slice(&self.resolve_function_name(n));
                    Some(d)
                }
                _ => Some(b"d:".to_vec()),
            },
            CallableTarget::Method { method, .. } => match &method.kind {
                ExprKind::Identifier(m) => {
                    let mut d = b"m:".to_vec();
                    d.extend_from_slice(m);
                    Some(d)
                }
                _ => None,
            },
            CallableTarget::StaticMethod { class, method } => match &class.kind {
                ExprKind::Identifier(cn) => {
                    let class_n = self.resolve_class_name(cn);
                    let resolved = if class_n.eq_ignore_ascii_case(b"self") {
                        self.current_class.clone().unwrap_or(class_n.clone())
                    } else if class_n.eq_ignore_ascii_case(b"static") {
                        b"static".to_vec()
                    } else if class_n.eq_ignore_ascii_case(b"parent") {
                        match &self.current_parent_class {
                            Some(p) => {
                                let mut v = b"parent:".to_vec();
                                v.extend_from_slice(p);
                                v
                            }
                            None => class_n.clone(),
                        }
                    } else {
                        class_n.clone()
                    };
                    let mut d = if self.in_const_expr {
                        b"S:".to_vec()
                    } else {
                        b"s:".to_vec()
                    };
                    d.extend_from_slice(&resolved);
                    d.extend_from_slice(b"::");
                    d.extend_from_slice(method);
                    Some(d)
                }
                _ => None,
            },
        };

        let _closure_id = self.op_array.child_functions.len();
        let global_id = next_closure_id();
        let closure_name = format!("__closure_fcc_{}", global_id).into_bytes();

        let mut cc = Compiler::new();
        cc.op_array.name = closure_name.clone();
        cc.op_array.strict_types = self.op_array.strict_types;
        cc.op_array.filename = self.source_file.clone();
        cc.current_class = self.current_class.clone();
        cc.current_parent_class = self.current_parent_class.clone();
        cc.op_array.scope_class = self.op_array.scope_class.clone().or_else(|| {
            self.current_class
                .as_ref()
                .map(|c| c.iter().map(|b| b.to_ascii_lowercase()).collect())
        });
        cc.anon_class_name_map = self.anon_class_name_map.clone();

        // Determine what needs to be captured.
        // - Function with Identifier: no capture needed (resolved at compile time)
        // - Function with dynamic expr (Variable, etc.): capture the callable value
        // - Method call: capture the object
        // - Static method: no capture needed (resolved at compile time)
        let needs_capture = match target {
            CallableTarget::Function(name_expr) => {
                !matches!(name_expr.kind, ExprKind::Identifier(_))
            }
            CallableTarget::Method { .. } => true,
            CallableTarget::StaticMethod { .. } => false,
        };

        if needs_capture {
            // Reserve cv0 for the captured value (object or callable)
            cc.op_array.get_or_create_cv(b"__fcc_captured");
        }

        // Set up variadic ...$args parameter
        let args_cv = cc.op_array.get_or_create_cv(b"args");
        cc.op_array.param_count = 1;
        cc.op_array.required_param_count = 0;
        cc.op_array.variadic_param = Some(args_cv);

        // Now emit the call inside the closure body
        match target {
            CallableTarget::Function(name_expr) => {
                let call_op = if let ExprKind::Identifier(n) = &name_expr.kind {
                    // Static function name - resolve at compile time
                    let resolved_name = self.resolve_function_name(n);
                    cc.op_array.fcc_target_name = Some(resolved_name.clone());
                    let name_idx = cc
                        .op_array
                        .add_literal(Value::String(PhpString::from_vec(resolved_name)));
                    OperandType::Const(name_idx)
                } else {
                    // Dynamic callable - use captured value from cv0
                    OperandType::Cv(0) // __fcc_captured
                };
                let arg_count_idx = cc.op_array.add_literal(Value::Long(0));
                cc.op_array.emit(Op {
                    opcode: OpCode::InitFCall,
                    op1: call_op,
                    op2: OperandType::Const(arg_count_idx),
                    result: OperandType::Unused,
                    line,
                });
                cc.op_array.emit(Op {
                    opcode: OpCode::SendUnpack,
                    op1: OperandType::Cv(args_cv),
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line,
                });
                let result_tmp = cc.op_array.alloc_temp();
                cc.op_array.emit(Op {
                    opcode: OpCode::DoFCall,
                    op1: OperandType::Unused,
                    op2: OperandType::Unused,
                    result: OperandType::Tmp(result_tmp),
                    line,
                });
                cc.op_array.emit(Op {
                    opcode: OpCode::Return,
                    op1: OperandType::Tmp(result_tmp),
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line,
                });
            }
            CallableTarget::Method { method, .. } => {
                // Object is captured in cv0 (__fcc_captured)
                let obj_cv = 0u32;
                let method_name = match &method.kind {
                    ExprKind::Identifier(name) => name.clone(),
                    _ => b"__invoke".to_vec(),
                };
                // For method FCCs, we don't know the class name at compile time
                // since it depends on the object type at runtime
                let method_idx = cc
                    .op_array
                    .add_literal(Value::String(PhpString::from_vec(method_name)));
                cc.op_array.emit(Op {
                    opcode: OpCode::InitMethodCall,
                    op1: OperandType::Cv(obj_cv),
                    op2: OperandType::Const(method_idx),
                    result: OperandType::Unused,
                    line,
                });
                cc.op_array.emit(Op {
                    opcode: OpCode::SendUnpack,
                    op1: OperandType::Cv(args_cv),
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line,
                });
                let result_tmp = cc.op_array.alloc_temp();
                cc.op_array.emit(Op {
                    opcode: OpCode::DoFCall,
                    op1: OperandType::Unused,
                    op2: OperandType::Unused,
                    result: OperandType::Tmp(result_tmp),
                    line,
                });
                cc.op_array.emit(Op {
                    opcode: OpCode::Return,
                    op1: OperandType::Tmp(result_tmp),
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line,
                });
            }
            CallableTarget::StaticMethod { class, method } => {
                let class_name = match &class.kind {
                    ExprKind::Identifier(name) => self.resolve_class_name(name),
                    _ => {
                        return Err(CompileError {
                            message: "unsupported static method callable target".into(),
                            line,
                        });
                    }
                };
                let resolved_class = if class_name.eq_ignore_ascii_case(b"self") {
                    self.current_class.clone().unwrap_or(class_name.clone())
                } else if class_name.eq_ignore_ascii_case(b"static") {
                    b"static".to_vec()
                } else if class_name.eq_ignore_ascii_case(b"parent") {
                    self.current_parent_class
                        .clone()
                        .unwrap_or(class_name.clone())
                } else {
                    class_name.clone()
                };
                let mut func_name = resolved_class;
                func_name.extend_from_slice(b"::");
                func_name.extend_from_slice(method);
                cc.op_array.fcc_target_name = Some(func_name.clone());
                let name_idx = cc
                    .op_array
                    .add_literal(Value::String(PhpString::from_vec(func_name)));
                let arg_count_idx = cc.op_array.add_literal(Value::Long(0));
                cc.op_array.emit(Op {
                    opcode: OpCode::InitFCall,
                    op1: OperandType::Const(name_idx),
                    op2: OperandType::Const(arg_count_idx),
                    result: OperandType::Unused,
                    line,
                });
                cc.op_array.emit(Op {
                    opcode: OpCode::SendUnpack,
                    op1: OperandType::Cv(args_cv),
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line,
                });
                let result_tmp = cc.op_array.alloc_temp();
                cc.op_array.emit(Op {
                    opcode: OpCode::DoFCall,
                    op1: OperandType::Unused,
                    op2: OperandType::Unused,
                    result: OperandType::Tmp(result_tmp),
                    line,
                });
                cc.op_array.emit(Op {
                    opcode: OpCode::Return,
                    op1: OperandType::Tmp(result_tmp),
                    op2: OperandType::Unused,
                    result: OperandType::Unused,
                    line,
                });
            }
        }

        self.op_array.child_functions.push(cc.op_array);

        // Emit DeclareFunction for the closure
        let name_idx = self
            .op_array
            .add_literal(Value::String(PhpString::from_vec(closure_name.clone())));
        let func_idx = self.op_array.add_literal(Value::Long(
            (self.op_array.child_functions.len() - 1) as i64,
        ));
        self.op_array.emit(Op {
            opcode: OpCode::DeclareFunction,
            op1: OperandType::Const(name_idx),
            op2: OperandType::Const(func_idx),
            result: OperandType::Unused,
            line,
        });

        if needs_capture {
            // Compile the captured value in the outer scope
            let captured_op = match target {
                CallableTarget::Method { object, .. } => self.compile_expr(object)?,
                CallableTarget::Function(name_expr) => self.compile_expr(name_expr)?,
                _ => unreachable!(),
            };

            let arr_tmp = self.op_array.alloc_temp();
            self.op_array.emit(Op {
                opcode: OpCode::ArrayNew,
                op1: OperandType::Unused,
                op2: OperandType::Unused,
                result: OperandType::Tmp(arr_tmp),
                line,
            });
            let name_val = self
                .op_array
                .add_literal(Value::String(PhpString::from_vec(closure_name)));
            self.op_array.emit(Op {
                opcode: OpCode::ArrayAppend,
                op1: OperandType::Tmp(arr_tmp),
                op2: OperandType::Const(name_val),
                result: OperandType::Unused,
                line,
            });
            self.op_array.emit(Op {
                opcode: OpCode::ArrayAppend,
                op1: OperandType::Tmp(arr_tmp),
                op2: captured_op,
                result: OperandType::Unused,
                line,
            });
            // `$obj->{expr}(...)`: the method name is evaluated (after the
            // object) and resolved at run time ("M:" + name).
            if let CallableTarget::Method { method, .. } = target {
                if !matches!(method.kind, ExprKind::Identifier(_)) {
                    let name = self.compile_expr(method)?;
                    let pre = self
                        .op_array
                        .add_literal(Value::String(PhpString::from_bytes(b"M:")));
                    let desc = self.op_array.alloc_temp();
                    self.op_array.emit(Op {
                        opcode: OpCode::Concat,
                        op1: OperandType::Const(pre),
                        op2: name,
                        result: OperandType::Tmp(desc),
                        line,
                    });
                    let tmp = self.op_array.alloc_temp();
                    self.op_array.emit(Op {
                        opcode: OpCode::MakeFcc,
                        op1: OperandType::Tmp(arr_tmp),
                        op2: OperandType::Tmp(desc),
                        result: OperandType::Tmp(tmp),
                        line,
                    });
                    return Ok(OperandType::Tmp(tmp));
                }
            }
            Ok(self.emit_make_fcc(OperandType::Tmp(arr_tmp), fcc_desc, line))
        } else {
            // No captures - just return the closure name
            let name_val_idx = self
                .op_array
                .add_literal(Value::String(PhpString::from_vec(closure_name)));
            Ok(self.emit_make_fcc(OperandType::Const(name_val_idx), fcc_desc, line))
        }
    }

    fn emit_make_fcc(
        &mut self,
        wrapper: OperandType,
        desc: Option<Vec<u8>>,
        line: u32,
    ) -> OperandType {
        let desc = match desc {
            Some(d) => d,
            None => return self.wrap_closure_operand(wrapper),
        };
        let desc_idx = self
            .op_array
            .add_literal(Value::String(PhpString::from_vec(desc)));
        let tmp = self.op_array.alloc_temp();
        self.op_array.emit(Op {
            opcode: OpCode::MakeFcc,
            op1: wrapper,
            op2: OperandType::Const(desc_idx),
            result: OperandType::Tmp(tmp),
            line,
        });
        OperandType::Tmp(tmp)
    }

    /// Evaluate a constant expression at compile time (for property defaults, etc.)
    /// Check if an expression (foreach value/key target) contains $this assignment
    fn check_foreach_this_assign(&self, expr: &Expr, _line: u32) -> CompileResult<bool> {
        match &expr.kind {
            ExprKind::Variable(name) if name == b"this" => Ok(true),
            ExprKind::Array(elems) => {
                for elem in elems {
                    if self.check_foreach_this_assign(&elem.value, _line)? {
                        return Ok(true);
                    }
                }
                Ok(false)
            }
            ExprKind::FunctionCall { name, args } if matches!(&name.kind, ExprKind::Identifier(n) if n.eq_ignore_ascii_case(b"list")) =>
            {
                for arg in args {
                    if self.check_foreach_this_assign(&arg.value, _line)? {
                        return Ok(true);
                    }
                }
                Ok(false)
            }
            _ => Ok(false),
        }
    }

    /// zend_compile_const_expr(): the compile error a constant expression
    /// (initializer, attribute argument, constant value) raises, if any.
    /// `allow_dynamic` is false for class constants and property defaults,
    /// which reject `new` and object casts.
    pub(crate) fn const_expr_error(expr: &Expr, allow_dynamic: bool) -> Option<String> {
        use goro_parser::ast::ExprKind as E;
        const INVALID: &str = "Constant expression contains invalid operations";
        let rec = |e: &Expr| Self::const_expr_error(e, allow_dynamic);
        let is_name = |e: &Expr| matches!(e.kind, E::Identifier(_));
        let name_of = |e: &Expr| match &e.kind {
            E::Identifier(n) => Some(n.clone()),
            _ => None,
        };
        // zend_compile_const_expr_class_reference()
        let class_reference = |class: &Expr| -> Option<String> {
            match name_of(class) {
                Some(n) if n.starts_with(b"__anonymous_class_") => {
                    Some("Cannot use anonymous class in constant expression".into())
                }
                Some(n) if n.eq_ignore_ascii_case(b"static") => {
                    Some("\"static\" is not allowed in compile-time constants".into())
                }
                Some(_) => None,
                None => Some("Cannot use dynamic class name in constant expression".into()),
            }
        };
        match &expr.kind {
            E::Int(_)
            | E::Float(_)
            | E::String(_)
            | E::True
            | E::False
            | E::Null
            | E::ConstantAccess(_)
            | E::Identifier(_) => None,
            // A heredoc without interpolation is a plain string.
            E::InterpolatedString(parts) => {
                if parts
                    .iter()
                    .all(|p| matches!(p, goro_parser::ast::StringPart::Literal(_)))
                {
                    None
                } else {
                    Some(INVALID.into())
                }
            }
            E::BinaryOp { left, right, .. } => rec(left).or_else(|| rec(right)),
            E::UnaryOp { operand, op, .. } => {
                use goro_parser::ast::UnaryOp as U;
                if matches!(
                    op,
                    U::PreIncrement | U::PreDecrement | U::PostIncrement | U::PostDecrement
                ) {
                    return Some(INVALID.into());
                }
                rec(operand)
            }
            E::Cast(ct, inner) => {
                if *ct == goro_parser::ast::CastType::Unset {
                    return Some("The (unset) cast is no longer supported".into());
                }
                if *ct == goro_parser::ast::CastType::Object && !allow_dynamic {
                    return Some("Object casts are not supported in this context".into());
                }
                rec(inner)
            }
            E::Ternary {
                condition,
                if_true,
                if_false,
            } => rec(condition)
                .or_else(|| if_true.as_deref().and_then(rec))
                .or_else(|| rec(if_false)),
            E::NullCoalesce { left, right } => rec(left).or_else(|| rec(right)),
            E::ArrayAccess { index: None, .. } => Some("Cannot use [] for reading".into()),
            E::ArrayAccess { array, index } => {
                rec(array).or_else(|| index.as_deref().and_then(rec))
            }
            E::Array(elements) => elements
                .iter()
                .find_map(|e| e.key.as_ref().and_then(rec).or_else(|| rec(&e.value))),
            E::PropertyAccess {
                object, property, ..
            } => rec(object).or_else(|| {
                if is_name(property) {
                    None
                } else {
                    rec(property)
                }
            }),
            E::ClassConstAccess { class, constant } => {
                if constant.eq_ignore_ascii_case(b"class") {
                    // zend_compile_const_expr_class_name()
                    match name_of(class) {
                        Some(n) if n.eq_ignore_ascii_case(b"static") => Some(
                            "static::class cannot be used for compile-time class name resolution"
                                .into(),
                        ),
                        Some(_) => None,
                        None => Some(
                            "(expression)::class cannot be used in constant expressions".into(),
                        ),
                    }
                } else {
                    // zend_compile_const_expr_class_const()
                    match name_of(class) {
                        Some(n) if n.eq_ignore_ascii_case(b"static") => {
                            Some("\"static::\" is not allowed in compile-time constants".into())
                        }
                        Some(_) => None,
                        None => Some(
                            "Dynamic class names are not allowed in compile-time class constant references"
                                .into(),
                        ),
                    }
                }
            }
            E::DynamicClassConstAccess { class, constant } => {
                if !is_name(class) {
                    return Some(
                        "Dynamic class names are not allowed in compile-time class constant references"
                            .into(),
                    );
                }
                if name_of(class).is_some_and(|n| n.eq_ignore_ascii_case(b"static")) {
                    return Some("\"static::\" is not allowed in compile-time constants".into());
                }
                rec(constant)
            }
            E::New { class, args } => {
                if !allow_dynamic {
                    return Some("New expressions are not supported in this context".into());
                }
                if let Some(e) = class_reference(class) {
                    return Some(e);
                }
                let mut named = false;
                for a in args {
                    if a.unpack {
                        return Some(
                            "Argument unpacking in constant expressions is not supported".into(),
                        );
                    }
                    if a.name.is_some() {
                        named = true;
                    } else if named {
                        return Some("Cannot use positional argument after named argument".into());
                    }
                }
                args.iter().find_map(|a| rec(&a.value))
            }
            E::Closure {
                is_static,
                use_vars,
                ..
            } => {
                if !*is_static {
                    Some("Closures in constant expressions must be static".into())
                } else if !use_vars.is_empty() {
                    Some("Cannot use(...) variables in constant expression".into())
                } else {
                    None
                }
            }
            E::FirstClassCallable(target) => match target {
                goro_parser::ast::CallableTarget::Function(name) => match &name.kind {
                    E::Identifier(_) | E::String(_) => None,
                    E::Int(_) | E::Float(_) | E::True | E::False | E::Null | E::Array(_) => {
                        Some("Illegal function name".into())
                    }
                    _ => Some("Cannot use dynamic function name in constant expression".into()),
                },
                goro_parser::ast::CallableTarget::StaticMethod { class, .. } => {
                    class_reference(class)
                }
                goro_parser::ast::CallableTarget::Method { .. } => Some(INVALID.into()),
            },
            _ => Some(INVALID.into()),
        }
    }

    /// Redundancy checks of zend_compile_typename that need resolved class
    /// names (use imports): duplicate intersection members, DNF members made
    /// redundant by another member, unresolvable self/parent in intersections.
    /// zend_compile_single_typename(): an unqualified `integer`, `double`,
    /// `boolean` or `resource` (not imported) is a class name, with a warning.
    fn warn_confusable_types(&self, hint: &TypeHint, line: u32) {
        match hint {
            TypeHint::Simple(name) => {
                let correct = match name.as_slice() {
                    b"integer" => Some("int"),
                    b"double" => Some("float"),
                    b"boolean" => Some("bool"),
                    b"resource" => None,
                    _ => return,
                };
                if self.use_map.contains_key(&name.to_ascii_lowercase()) {
                    return;
                }
                let resolved =
                    type_hint_to_param_type_with_ns(hint, &self.current_namespace, &self.use_map);
                let ParamType::Simple(class_name) = resolved else {
                    return;
                };
                let extra = if self.current_namespace.is_empty() {
                    ""
                } else {
                    " or import the class with \"use\""
                };
                let name = String::from_utf8_lossy(name);
                let class_name = String::from_utf8_lossy(&class_name);
                let msg = match correct {
                    Some(c) => format!(
                        "\"{}\" will be interpreted as a class name. Did you mean \"{}\"? Write \"\\{}\"{} to suppress this warning",
                        name, c, class_name, extra
                    ),
                    None => format!(
                        "\"{}\" is not a supported builtin type and will be interpreted as a class name. Write \"\\{}\"{} to suppress this warning",
                        name, class_name, extra
                    ),
                };
                push_compile_warning(msg, line);
            }
            TypeHint::Nullable(inner) => self.warn_confusable_types(inner, line),
            TypeHint::Union(parts) | TypeHint::Intersection(parts) => {
                for p in parts {
                    self.warn_confusable_types(p, line);
                }
            }
        }
    }

    fn type_redundancy_error(&self, hint: &TypeHint, line: u32) -> Option<String> {
        self.warn_confusable_types(hint, line);
        fn relative_in_intersection(h: &TypeHint, in_trait: bool) -> Option<String> {
            match h {
                TypeHint::Intersection(parts) => {
                    for p in parts {
                        if let TypeHint::Simple(n) = p {
                            if in_trait
                                && (n.eq_ignore_ascii_case(b"self")
                                    || n.eq_ignore_ascii_case(b"parent"))
                            {
                                return Some(format!(
                                    "Type {} cannot be part of an intersection type",
                                    String::from_utf8_lossy(n)
                                ));
                            }
                        }
                    }
                    None
                }
                TypeHint::Union(parts) => parts
                    .iter()
                    .find_map(|p| relative_in_intersection(p, in_trait)),
                TypeHint::Nullable(inner) => relative_in_intersection(inner, in_trait),
                _ => None,
            }
        }
        if let Some(e) = relative_in_intersection(hint, self.is_in_trait) {
            return Some(e);
        }
        let pt = type_hint_to_param_type_with_ns(hint, &self.current_namespace, &self.use_map);
        fn names(parts: &[ParamType]) -> Vec<Vec<u8>> {
            parts
                .iter()
                .filter_map(|p| {
                    if let ParamType::Simple(n) = p {
                        Some(n.clone())
                    } else {
                        None
                    }
                })
                .collect()
        }
        fn is_builtin(n: &[u8]) -> bool {
            matches!(
                n,
                b"int"
                    | b"integer"
                    | b"float"
                    | b"double"
                    | b"string"
                    | b"bool"
                    | b"boolean"
                    | b"array"
                    | b"object"
                    | b"callable"
                    | b"iterable"
                    | b"mixed"
                    | b"null"
                    | b"void"
                    | b"false"
                    | b"true"
                    | b"never"
                    | b"static"
                    | b"self"
                    | b"parent"
            )
        }
        fn join(ns: &[Vec<u8>]) -> String {
            ns.iter()
                .map(|n| String::from_utf8_lossy(n).to_string())
                .collect::<Vec<_>>()
                .join("&")
        }
        fn contains_ci(list: &[Vec<u8>], n: &[u8]) -> bool {
            list.iter().any(|x| x.eq_ignore_ascii_case(n))
        }
        match &pt {
            ParamType::Intersection(parts) => {
                let ns = names(parts);
                for i in 1..ns.len() {
                    if contains_ci(&ns[..i], &ns[i]) {
                        return Some(format!(
                            "Duplicate type {} is redundant",
                            String::from_utf8_lossy(&ns[i])
                        ));
                    }
                }
                None
            }
            ParamType::Union(parts) => {
                enum M {
                    C(Vec<u8>),
                    I(Vec<Vec<u8>>),
                }
                let mut list: Vec<M> = Vec::new();
                for p in parts {
                    match p {
                        ParamType::Intersection(ip) => {
                            let new = names(ip);
                            for i in 1..new.len() {
                                if contains_ci(&new[..i], &new[i]) {
                                    return Some(format!(
                                        "Duplicate type {} is redundant",
                                        String::from_utf8_lossy(&new[i])
                                    ));
                                }
                            }
                            for prev in &list {
                                match prev {
                                    M::I(old) => {
                                        let (smaller, larger) = if old.len() < new.len() {
                                            (old, &new)
                                        } else {
                                            (&new, old)
                                        };
                                        let sum = smaller
                                            .iter()
                                            .filter(|n| contains_ci(larger, n))
                                            .count();
                                        if sum == smaller.len() {
                                            // left = new, right = old (zend_are_intersection_types_redundant(single, prev))
                                            let flipped = old.len() < new.len();
                                            let (sm_s, lg_s) = if flipped {
                                                (join(old), join(&new))
                                            } else {
                                                (join(&new), join(old))
                                            };
                                            if smaller.len() == larger.len() {
                                                return Some(format!(
                                                    "Type {} is redundant with type {}",
                                                    sm_s, lg_s
                                                ));
                                            }
                                            return Some(format!(
                                                "Type {} is redundant as it is more restrictive than type {}",
                                                lg_s, sm_s
                                            ));
                                        }
                                    }
                                    M::C(c) => {
                                        if contains_ci(&new, c) {
                                            return Some(format!(
                                                "Type {} is redundant as it is more restrictive than type {}",
                                                join(&new),
                                                String::from_utf8_lossy(c)
                                            ));
                                        }
                                    }
                                }
                            }
                            list.push(M::I(new));
                        }
                        ParamType::Simple(n) if !is_builtin(n) => {
                            for prev in &list {
                                match prev {
                                    M::I(old) => {
                                        if contains_ci(old, n) {
                                            return Some(format!(
                                                "Type {} is redundant as it is more restrictive than type {}",
                                                join(old),
                                                String::from_utf8_lossy(n)
                                            ));
                                        }
                                    }
                                    M::C(c) => {
                                        if c.eq_ignore_ascii_case(n) {
                                            return Some(format!(
                                                "Duplicate type {} is redundant",
                                                String::from_utf8_lossy(n)
                                            ));
                                        }
                                    }
                                }
                            }
                            list.push(M::C(n.clone()));
                        }
                        _ => {}
                    }
                }
                None
            }
            _ => None,
        }
    }

    /// zend_is_valid_default_value for a compile-time literal default value.
    /// Ok(None): valid or not a literal; Ok(Some(v)): valid once widened to
    /// float (use `v`); Err((type name, value name)) when invalid.
    /// RECV_INIT: a parameter default that is not a compile-time constant
    /// (e.g. a constant reference) is type-checked when it is used.
    fn emit_recv_default_check(op_array: &mut OpArray, cv: u32, default_expr: &Expr) {
        if Self::eval_const_expr(default_expr).is_some()
            || !matches!(op_array.param_types.get(cv as usize), Some(Some(_)))
        {
            return;
        }
        op_array.emit(Op {
            opcode: OpCode::RecvDefaultCheck,
            op1: OperandType::Cv(cv),
            op2: OperandType::Unused,
            result: OperandType::Unused,
            line: default_expr.span.line,
        });
    }

    fn check_literal_default(
        pt: &ParamType,
        e: &Expr,
    ) -> Result<Option<Value>, (&'static str, &'static str)> {
        use crate::vm::variance::{
            T_ANY, T_ARRAY, T_DOUBLE, T_FALSE, T_LONG, T_NULL, T_STRING, T_TRUE, TypeView,
        };
        let v = match Self::eval_const_expr(e) {
            Some(v) => v,
            None => return Ok(None),
        };
        let tv = TypeView::from_param_type(pt);
        if tv.mask & T_ANY == T_ANY {
            return Ok(None);
        }
        let (bit, tn, vn) = match &v {
            Value::Null => (T_NULL, "null", "null"),
            Value::False => (T_FALSE, "bool", "false"),
            Value::True => (T_TRUE, "bool", "true"),
            Value::Long(_) => (T_LONG, "int", "int"),
            Value::Double(_) => (T_DOUBLE, "float", "float"),
            Value::String(_) => (T_STRING, "string", "string"),
            Value::Array(_) => (T_ARRAY, "array", "array"),
            _ => return Ok(None),
        };
        if tv.mask & bit != 0 {
            return Ok(None);
        }
        if let Value::Long(n) = v {
            if tv.mask & T_DOUBLE != 0 {
                return Ok(Some(Value::Double(n as f64)));
            }
        }
        Err((tn, vn))
    }

    /// Builtins whose first parameter is `array &$array` (goro passes the
    /// array by shared handle instead of by reference).
    fn is_array_ref_builtin(func_name: Option<&[u8]>) -> bool {
        let Some(fname) = func_name else {
            return false;
        };
        let lower = fname.to_ascii_lowercase();
        let lower = lower.strip_prefix(b"\\").unwrap_or(&lower);
        matches!(
            lower,
            b"next"
                | b"prev"
                | b"reset"
                | b"end"
                | b"array_shift"
                | b"array_pop"
                | b"array_unshift"
                | b"array_push"
                | b"array_splice"
                | b"sort"
                | b"rsort"
                | b"usort"
                | b"uasort"
                | b"uksort"
                | b"asort"
                | b"arsort"
                | b"ksort"
                | b"krsort"
                | b"natsort"
                | b"natcasesort"
                | b"shuffle"
                | b"array_walk"
                | b"array_walk_recursive"
        )
    }

    fn is_superglobal_name(name: &[u8]) -> bool {
        matches!(
            name,
            b"GLOBALS"
                | b"_SERVER"
                | b"_GET"
                | b"_POST"
                | b"_COOKIE"
                | b"_FILES"
                | b"_ENV"
                | b"_REQUEST"
                | b"_SESSION"
        )
    }

    /// Sub-expressions of a `??=` target that are evaluated once: everything
    /// but the variable/dim/property path itself (whose fetch mode differs
    /// between the BP_VAR_IS and the BP_VAR_W pass) and literals.
    fn is_memoizable(expr: &Expr) -> bool {
        !matches!(
            expr.kind,
            ExprKind::Variable(_)
                | ExprKind::DynamicVariable(_)
                | ExprKind::ArrayAccess { .. }
                | ExprKind::PropertyAccess { .. }
                | ExprKind::StaticPropertyAccess { .. }
                | ExprKind::DynamicStaticPropertyAccess { .. }
                | ExprKind::Int(_)
                | ExprKind::Float(_)
                | ExprKind::String(_)
                | ExprKind::True
                | ExprKind::False
                | ExprKind::Null
                | ExprKind::Identifier(_)
        )
    }

    /// zend_compile_memoized_expr()
    fn compile_memoized_expr(&mut self, expr: &Expr) -> CompileResult<OperandType> {
        let key = expr as *const Expr as usize;
        let mode = self.memoize_mode;
        if mode == 2 {
            if let Some(op) = self.memoized_exprs.get(&key) {
                return Ok(*op);
            }
        }
        self.memoize_mode = 0;
        let r = self.compile_expr(expr);
        self.memoize_mode = mode;
        let r = r?;
        if mode == 1 {
            self.memoized_exprs.insert(key, r);
        }
        Ok(r)
    }

    /// `$target ??= $value` (zend_compile_assign_coalesce): the target is
    /// fetched for isset (BP_VAR_IS); only when that yields null is $value
    /// evaluated and the target fetched again for write, reusing the
    /// operands of its sub-expressions instead of evaluating them twice.
    fn compile_assign_coalesce(
        &mut self,
        expr: &Expr,
        target: &Expr,
        value: &Expr,
    ) -> CompileResult<OperandType> {
        let line = expr.span.line;
        let saved_mode = self.memoize_mode;
        let saved_exprs = std::mem::take(&mut self.memoized_exprs);
        let saved_root = self.memoize_root;
        // The target subtree is moved (not cloned) from the isset pass into
        // the assignment, so the memo keys (node addresses) stay valid.
        let is_expr = Expr {
            kind: ExprKind::NullCoalesce {
                left: Box::new(target.clone()),
                right: Box::new(Expr {
                    kind: ExprKind::Null,
                    span: expr.span,
                }),
            },
            span: expr.span,
        };
        self.memoize_mode = 1;
        self.memoize_root = &is_expr as *const Expr as usize;
        let is_val = self.compile_expr(&is_expr);
        self.memoize_mode = 0;
        let result = (|| -> CompileResult<OperandType> {
            let is_val = is_val?;
            let result_tmp = self.op_array.alloc_temp();
            self.op_array.emit(Op {
                opcode: OpCode::QmAssign,
                op1: is_val,
                op2: OperandType::Unused,
                result: OperandType::Tmp(result_tmp),
                line,
            });
            let set_tmp = self.op_array.alloc_temp();
            self.op_array.emit(Op {
                opcode: OpCode::IssetCheck,
                op1: OperandType::Tmp(result_tmp),
                op2: OperandType::Unused,
                result: OperandType::Tmp(set_tmp),
                line,
            });
            let jmp_end = self.op_array.emit(Op {
                opcode: OpCode::JmpNz,
                op1: OperandType::Tmp(set_tmp),
                op2: OperandType::JmpTarget(0),
                result: OperandType::Unused,
                line,
            });
            let ExprKind::NullCoalesce { left, .. } = is_expr.kind else {
                unreachable!()
            };
            let assign = Expr {
                kind: ExprKind::Assign {
                    target: left,
                    value: Box::new(value.clone()),
                },
                span: expr.span,
            };
            self.memoize_mode = 2;
            self.memoize_root = &assign as *const Expr as usize;
            let assigned = self.compile_expr(&assign);
            self.memoize_mode = 0;
            let assigned = assigned?;
            self.op_array.emit(Op {
                opcode: OpCode::QmAssign,
                op1: assigned,
                op2: OperandType::Unused,
                result: OperandType::Tmp(result_tmp),
                line,
            });
            let end = self.op_array.current_offset();
            self.op_array.patch_jump(jmp_end, end);
            // Free the memoized temporaries (their destructors run here).
            let mut memo_tmps: Vec<u32> = self
                .memoized_exprs
                .values()
                .filter_map(|o| match o {
                    OperandType::Tmp(t) => Some(*t),
                    _ => None,
                })
                .collect();
            memo_tmps.sort_unstable();
            memo_tmps.dedup();
            for t in memo_tmps {
                self.op_array.emit(Op {
                    opcode: OpCode::FreeTmps,
                    op1: OperandType::Tmp(t),
                    op2: OperandType::Tmp(t + 1),
                    result: OperandType::Unused,
                    line,
                });
            }
            Ok(OperandType::Tmp(result_tmp))
        })();
        self.memoize_mode = saved_mode;
        self.memoized_exprs = saved_exprs;
        self.memoize_root = saved_root;
        result
    }

    fn eval_const_expr(expr: &Expr) -> Option<Value> {
        match &expr.kind {
            ExprKind::Int(n) => Some(Value::Long(*n)),
            ExprKind::Float(f) => Some(Value::Double(*f)),
            ExprKind::String(s) => Some(Value::String(PhpString::from_vec(s.clone()))),
            ExprKind::True => Some(Value::True),
            ExprKind::False => Some(Value::False),
            ExprKind::Null => Some(Value::Null),
            ExprKind::Array(elements) => {
                let mut arr = crate::array::PhpArray::new();
                for elem in elements {
                    let val = Self::eval_const_expr(&elem.value)?;
                    if elem.unpack {
                        // Spread operator in constant expression: only arrays allowed
                        if let Value::Array(src_arr) = val {
                            let src_borrow = src_arr.borrow();
                            for (k, v) in src_borrow.iter() {
                                arr.set(k.clone(), v.clone());
                            }
                        } else {
                            // Non-array in constant expression spread: return None
                            // (will be handled at runtime with proper error)
                            return None;
                        }
                    } else if let Some(key_expr) = &elem.key {
                        let k = Self::eval_const_expr(key_expr)?;
                        let key = match k {
                            Value::Long(n) => crate::array::ArrayKey::Int(n),
                            Value::String(s) => crate::array::ArrayKey::String(s),
                            _ => return None,
                        };
                        arr.set(key, val);
                    } else {
                        arr.push(val);
                    }
                }
                Some(Value::Array(std::rc::Rc::new(std::cell::RefCell::new(arr))))
            }
            ExprKind::UnaryOp {
                op: UnaryOp::Negate,
                operand,
                ..
            } => match Self::eval_const_expr(operand)? {
                Value::Long(n) => Some(Value::Long(-n)),
                Value::Double(f) => Some(Value::Double(-f)),
                _ => None,
            },
            ExprKind::UnaryOp {
                op: UnaryOp::BitwiseNot,
                operand,
                ..
            } => match Self::eval_const_expr(operand)? {
                Value::Long(n) => Some(Value::Long(!n)),
                _ => None,
            },
            ExprKind::BinaryOp {
                left, op, right, ..
            } => {
                let l = Self::eval_const_expr(left)?;
                let r = Self::eval_const_expr(right)?;
                match (l, op, r) {
                    (Value::Long(a), BinaryOp::ShiftLeft, Value::Long(b)) => {
                        Some(Value::Long(a << b))
                    }
                    (Value::Long(a), BinaryOp::ShiftRight, Value::Long(b)) => {
                        Some(Value::Long(a >> b))
                    }
                    (Value::Long(a), BinaryOp::BitwiseAnd, Value::Long(b)) => {
                        Some(Value::Long(a & b))
                    }
                    (Value::Long(a), BinaryOp::BitwiseOr, Value::Long(b)) => {
                        Some(Value::Long(a | b))
                    }
                    (Value::Long(a), BinaryOp::BitwiseXor, Value::Long(b)) => {
                        Some(Value::Long(a ^ b))
                    }
                    (Value::Long(a), BinaryOp::Add, Value::Long(b)) => {
                        Some(Value::Long(a.wrapping_add(b)))
                    }
                    (Value::Long(a), BinaryOp::Sub, Value::Long(b)) => {
                        Some(Value::Long(a.wrapping_sub(b)))
                    }
                    (Value::Long(a), BinaryOp::Mul, Value::Long(b)) => {
                        Some(Value::Long(a.wrapping_mul(b)))
                    }
                    (Value::Long(a), BinaryOp::Div, Value::Long(b)) if b != 0 => {
                        if a % b == 0 {
                            Some(Value::Long(a / b))
                        } else {
                            Some(Value::Double(a as f64 / b as f64))
                        }
                    }
                    (Value::Long(a), BinaryOp::Mod, Value::Long(b)) if b != 0 => {
                        Some(Value::Long(a % b))
                    }
                    (Value::Long(a), BinaryOp::Pow, Value::Long(b)) if b >= 0 => {
                        Some(Value::Long(a.wrapping_pow(b as u32)))
                    }
                    (Value::Double(a), BinaryOp::Add, Value::Double(b)) => {
                        Some(Value::Double(a + b))
                    }
                    (Value::Double(a), BinaryOp::Sub, Value::Double(b)) => {
                        Some(Value::Double(a - b))
                    }
                    (Value::Double(a), BinaryOp::Mul, Value::Double(b)) => {
                        Some(Value::Double(a * b))
                    }
                    (Value::Double(a), BinaryOp::Div, Value::Double(b)) if b != 0.0 => {
                        Some(Value::Double(a / b))
                    }
                    (Value::Long(a), BinaryOp::Add, Value::Double(b)) => {
                        Some(Value::Double(a as f64 + b))
                    }
                    (Value::Double(a), BinaryOp::Add, Value::Long(b)) => {
                        Some(Value::Double(a + b as f64))
                    }
                    (Value::String(a), BinaryOp::Concat, Value::String(b)) => {
                        let mut result = a.as_bytes().to_vec();
                        result.extend_from_slice(b.as_bytes());
                        Some(Value::String(PhpString::from_vec(result)))
                    }
                    // String concatenation with non-string right side
                    (Value::String(a), BinaryOp::Concat, rv) => {
                        let mut result = a.as_bytes().to_vec();
                        result.extend_from_slice(rv.to_php_string().as_bytes());
                        Some(Value::String(PhpString::from_vec(result)))
                    }
                    // Boolean/logical operators - always return bool
                    (l, BinaryOp::BooleanAnd, r) | (l, BinaryOp::LogicalAnd, r) => {
                        Some(if l.is_truthy() && r.is_truthy() {
                            Value::True
                        } else {
                            Value::False
                        })
                    }
                    (l, BinaryOp::BooleanOr, r) | (l, BinaryOp::LogicalOr, r) => {
                        Some(if l.is_truthy() || r.is_truthy() {
                            Value::True
                        } else {
                            Value::False
                        })
                    }
                    (l, BinaryOp::LogicalXor, r) => Some(if l.is_truthy() ^ r.is_truthy() {
                        Value::True
                    } else {
                        Value::False
                    }),
                    // Comparison operators
                    (Value::Long(a), BinaryOp::Less, Value::Long(b)) => {
                        Some(if a < b { Value::True } else { Value::False })
                    }
                    (Value::Long(a), BinaryOp::Greater, Value::Long(b)) => {
                        Some(if a > b { Value::True } else { Value::False })
                    }
                    (Value::Long(a), BinaryOp::LessEqual, Value::Long(b)) => {
                        Some(if a <= b { Value::True } else { Value::False })
                    }
                    (Value::Long(a), BinaryOp::GreaterEqual, Value::Long(b)) => {
                        Some(if a >= b { Value::True } else { Value::False })
                    }
                    (Value::Long(a), BinaryOp::Equal, Value::Long(b)) => {
                        Some(if a == b { Value::True } else { Value::False })
                    }
                    (Value::Long(a), BinaryOp::Identical, Value::Long(b)) => {
                        Some(if a == b { Value::True } else { Value::False })
                    }
                    (Value::Long(a), BinaryOp::NotEqual, Value::Long(b)) => {
                        Some(if a != b { Value::True } else { Value::False })
                    }
                    (Value::Long(a), BinaryOp::NotIdentical, Value::Long(b)) => {
                        Some(if a != b { Value::True } else { Value::False })
                    }
                    // Equal/NotEqual with string comparison (loose)
                    (Value::String(a), BinaryOp::Equal, Value::String(b)) => {
                        Some(if a.as_bytes() == b.as_bytes() {
                            Value::True
                        } else {
                            Value::False
                        })
                    }
                    (Value::String(a), BinaryOp::NotEqual, Value::String(b)) => {
                        Some(if a.as_bytes() != b.as_bytes() {
                            Value::True
                        } else {
                            Value::False
                        })
                    }
                    (Value::Long(a), BinaryOp::Equal, Value::String(b))
                    | (Value::String(b), BinaryOp::Equal, Value::Long(a)) => {
                        let s = std::str::from_utf8(b.as_bytes()).unwrap_or("");
                        Some(if s.parse::<i64>().ok() == Some(a) {
                            Value::True
                        } else {
                            Value::False
                        })
                    }
                    (Value::Long(a), BinaryOp::NotEqual, Value::String(b))
                    | (Value::String(b), BinaryOp::NotEqual, Value::Long(a)) => {
                        let s = std::str::from_utf8(b.as_bytes()).unwrap_or("");
                        Some(if s.parse::<i64>().ok() != Some(a) {
                            Value::True
                        } else {
                            Value::False
                        })
                    }
                    _ => None,
                }
            }
            // Ternary operator
            ExprKind::Ternary {
                condition,
                if_true,
                if_false,
            } => {
                let cond = Self::eval_const_expr(condition)?;
                if cond.is_truthy() {
                    if let Some(true_expr) = if_true {
                        Self::eval_const_expr(true_expr)
                    } else {
                        // Short ternary: $a ?: $b - return the condition value itself
                        Some(cond)
                    }
                } else {
                    Self::eval_const_expr(if_false)
                }
            }
            // UnaryOp::BooleanNot (!)
            ExprKind::UnaryOp {
                op: UnaryOp::BooleanNot,
                operand,
                ..
            } => {
                let val = Self::eval_const_expr(operand)?;
                Some(if val.is_truthy() {
                    Value::False
                } else {
                    Value::True
                })
            }
            // UnaryOp::Plus (+)
            ExprKind::UnaryOp {
                op: UnaryOp::Plus,
                operand,
                ..
            } => Self::eval_const_expr(operand),
            // Handle Identifier constants (TRUE, FALSE, NULL, PHP_INT_MAX, etc.)
            ExprKind::Identifier(name) => {
                let lower: Vec<u8> = name.iter().map(|b| b.to_ascii_lowercase()).collect();
                match lower.as_slice() {
                    b"true" => Some(Value::True),
                    b"false" => Some(Value::False),
                    b"null" => Some(Value::Null),
                    b"php_eol" => Some(Value::String(PhpString::from_bytes(b"\n"))),
                    b"php_int_max" => Some(Value::Long(i64::MAX)),
                    b"php_int_min" => Some(Value::Long(i64::MIN)),
                    b"php_int_size" => Some(Value::Long(8)),
                    b"php_major_version" => Some(Value::Long(8)),
                    b"php_minor_version" => Some(Value::Long(5)),
                    b"php_float_dig" => Some(Value::Long(15)),
                    b"php_float_epsilon" => Some(Value::Double(f64::EPSILON)),
                    b"php_float_max" => Some(Value::Double(f64::MAX)),
                    b"php_float_min" => Some(Value::Double(f64::MIN_POSITIVE)),
                    b"php_float_inf" => Some(Value::Double(f64::INFINITY)),
                    b"php_float_nan" => Some(Value::Double(f64::NAN)),
                    b"php_maxpathlen" => Some(Value::Long(4096)),
                    b"php_prefix" => Some(Value::String(PhpString::from_bytes(b"/usr"))),
                    b"php_os" => Some(Value::String(PhpString::from_bytes(b"Linux"))),
                    b"php_os_family" => Some(Value::String(PhpString::from_bytes(b"Linux"))),
                    b"php_sapi" => Some(Value::String(PhpString::from_bytes(b"cli"))),
                    b"php_version" => Some(Value::String(PhpString::from_bytes(b"8.5.0-goro"))),
                    b"php_version_id" => Some(Value::Long(80500)),
                    b"php_release_version" => Some(Value::Long(0)),
                    b"php_extra_version" => Some(Value::String(PhpString::from_bytes(b"-goro"))),
                    b"php_debug" => Some(Value::Long(0)),
                    b"php_zts" => Some(Value::Long(0)),
                    b"php_binary" => Some(Value::String(PhpString::from_bytes(b"/usr/bin/php"))),
                    b"php_bindir" => Some(Value::String(PhpString::from_bytes(b"/usr/bin"))),
                    b"php_libdir" => Some(Value::String(PhpString::from_bytes(b"/usr/lib"))),
                    b"php_datadir" => Some(Value::String(PhpString::from_bytes(b"/usr/share"))),
                    b"php_sysconfdir" => Some(Value::String(PhpString::from_bytes(b"/etc"))),
                    b"php_localstatedir" => Some(Value::String(PhpString::from_bytes(b"/var"))),
                    b"php_config_file_path" => Some(Value::String(PhpString::from_bytes(b"/etc"))),
                    b"php_config_file_scan_dir" => Some(Value::String(PhpString::from_bytes(b""))),
                    b"php_extension_dir" => Some(Value::String(PhpString::from_bytes(b"."))),
                    b"directory_separator" | b"dirsep" => {
                        Some(Value::String(PhpString::from_bytes(b"/")))
                    }
                    b"path_separator" => Some(Value::String(PhpString::from_bytes(b":"))),
                    b"stdin" | b"stdout" | b"stderr" => None, // resources can't be const
                    b"nan" => Some(Value::Double(f64::NAN)),
                    b"inf" => Some(Value::Double(f64::INFINITY)),
                    _ => None,
                }
            }
            // Array access on constant arrays: [1,2,3][0] or CONST_ARRAY[key]
            ExprKind::ArrayAccess { array, index } => {
                let arr_val = Self::eval_const_expr(array)?;
                if let Value::Array(arr_rc) = arr_val {
                    let arr = arr_rc.borrow();
                    if let Some(idx_expr) = index {
                        let key_val = Self::eval_const_expr(idx_expr)?;
                        let key = match key_val {
                            Value::Long(n) => crate::array::ArrayKey::Int(n),
                            Value::String(s) => crate::array::ArrayKey::String(s),
                            _ => return None,
                        };
                        Some(arr.get(&key).cloned().unwrap_or(Value::Null))
                    } else {
                        None // append access [] not valid in const expr
                    }
                } else {
                    Some(Value::Null) // accessing array offset on non-array
                }
            }
            // Cast expressions in constant contexts
            ExprKind::Cast(cast_type, operand) => {
                let val = Self::eval_const_expr(operand)?;
                match cast_type {
                    CastType::Int => Some(Value::Long(val.to_long())),
                    CastType::Float => Some(Value::Double(val.to_double())),
                    CastType::String => Some(Value::String(val.to_php_string())),
                    CastType::Bool => Some(if val.is_truthy() {
                        Value::True
                    } else {
                        Value::False
                    }),
                    CastType::Array => match val {
                        Value::Array(_) => Some(val),
                        Value::Null => Some(Value::Array(std::rc::Rc::new(
                            std::cell::RefCell::new(crate::array::PhpArray::new()),
                        ))),
                        other => {
                            let mut arr = crate::array::PhpArray::new();
                            arr.push(other);
                            Some(Value::Array(std::rc::Rc::new(std::cell::RefCell::new(arr))))
                        }
                    },
                    _ => None,
                }
            }
            // FunctionCall in const expr (limited support for common functions)
            ExprKind::FunctionCall { name, args } => {
                if let ExprKind::Identifier(func_name) = &name.kind {
                    let lower: Vec<u8> = func_name.iter().map(|b| b.to_ascii_lowercase()).collect();
                    match lower.as_slice() {
                        b"strlen" if args.len() == 1 => {
                            let val = Self::eval_const_expr(&args[0].value)?;
                            if let Value::String(s) = val {
                                Some(Value::Long(s.len() as i64))
                            } else {
                                None
                            }
                        }
                        _ => None,
                    }
                } else {
                    None
                }
            }
            _ => None,
        }
    }

    /// Try to resolve an expression as a class constant reference.
    /// This handles `self::CONST`, `ClassName::CONST` etc. during class compilation.
    fn eval_class_const_expr(
        expr: &Expr,
        class: &ClassEntry,
        qualified_name: &[u8],
        extends: Option<&[u8]>,
        compiler: &Compiler,
    ) -> Option<Value> {
        match &expr.kind {
            ExprKind::ClassConstAccess {
                class: class_expr,
                constant,
            } => {
                let target_class = match &class_expr.kind {
                    ExprKind::Identifier(name) => {
                        let resolved = compiler.resolve_class_name(name);
                        let lower: Vec<u8> =
                            resolved.iter().map(|b| b.to_ascii_lowercase()).collect();
                        if lower == b"self" || lower == b"static" {
                            qualified_name.to_vec()
                        } else if lower == b"parent" {
                            // No parent: not evaluable here (the caller
                            // reports the error).
                            extends.map(|p| compiler.resolve_class_name(p))?
                        } else {
                            resolved
                        }
                    }
                    _ => return None,
                };

                // ClassName::class returns the fully qualified class name as a string
                if constant == b"class" {
                    return Some(Value::String(PhpString::from_vec(target_class)));
                }

                // Check if this references the same class
                let target_lower: Vec<u8> = target_class
                    .iter()
                    .map(|b| b.to_ascii_lowercase())
                    .collect();
                let self_lower: Vec<u8> = qualified_name
                    .iter()
                    .map(|b| b.to_ascii_lowercase())
                    .collect();
                if target_lower == self_lower {
                    // Look up the constant in the class being compiled
                    if let Some(val) = class.constants.get(constant) {
                        // Make sure the value isn't a deferred marker
                        if let Value::String(s) = val {
                            if s.as_bytes().starts_with(b"__deferred_const__::") {
                                return None;
                            }
                        }
                        return Some(val.clone());
                    }
                }
                None
            }
            ExprKind::DynamicClassConstAccess {
                class: class_expr,
                constant: const_expr,
            } => {
                // Dynamic class constant access in constant expression context: self::{'BAR'}
                // Only evaluatable if the class is self/static and the key is a string literal
                let target_class = match &class_expr.kind {
                    ExprKind::Identifier(name) => {
                        let resolved = compiler.resolve_class_name(name);
                        let lower: Vec<u8> =
                            resolved.iter().map(|b| b.to_ascii_lowercase()).collect();
                        if lower == b"self" || lower == b"static" {
                            qualified_name.to_vec()
                        } else if lower == b"parent" {
                            // No parent: not evaluable here (the caller
                            // reports the error).
                            extends.map(|p| compiler.resolve_class_name(p))?
                        } else {
                            resolved
                        }
                    }
                    _ => return None,
                };
                // Evaluate the constant name expression
                let const_name_val = Self::eval_const_expr(const_expr).or_else(|| {
                    Self::eval_class_const_expr(
                        const_expr,
                        class,
                        qualified_name,
                        extends,
                        compiler,
                    )
                })?;
                let const_name_str = match const_name_val {
                    Value::String(s) => s.as_bytes().to_vec(),
                    _ => return None,
                };
                // Check if this references the same class
                let target_lower: Vec<u8> = target_class
                    .iter()
                    .map(|b| b.to_ascii_lowercase())
                    .collect();
                let self_lower: Vec<u8> = qualified_name
                    .iter()
                    .map(|b| b.to_ascii_lowercase())
                    .collect();
                if target_lower == self_lower {
                    if let Some(val) = class.constants.get(&const_name_str) {
                        if let Value::String(s) = val {
                            if s.as_bytes().starts_with(b"__deferred_const__::") {
                                return None;
                            }
                        }
                        return Some(val.clone());
                    }
                }
                None
            }
            _ => None,
        }
    }

    /// Compile a class-constant value expression into either a concrete Value
    /// or a deferred marker string that the runtime resolves at access time.
    /// Returns None when the expression has no constant-evaluable form (e.g.,
    /// references a function call or `new Foo()`); callers should fall back
    /// to other paths or store Value::Null.
    ///
    /// Handles recursion through nested BinaryOps, so expressions like
    ///   self::class . '-' . SUFFIX
    /// where SUFFIX is a runtime-defined global constant produce a chained
    /// `__deferred_binop__::` marker rather than collapsing to Null.
    fn eval_or_defer_in_class_const(
        &self,
        expr: &Expr,
        class: &ClassEntry,
        qualified_name: &[u8],
        extends: Option<&[u8]>,
    ) -> Option<Value> {
        // Fast path: literal constants.
        if let Some(v) = Self::eval_const_expr(expr) {
            return Some(v);
        }
        // Class-context constants (self::FOO, OtherClass::BAR, ::class).
        if let Some(v) = Self::eval_class_const_expr(expr, class, qualified_name, extends, self) {
            return Some(v);
        }
        match &expr.kind {
            ExprKind::ClassConstAccess {
                class: class_expr,
                constant,
            } => {
                // Unresolved: emit a deferred marker.
                let class_name = match &class_expr.kind {
                    ExprKind::Identifier(name) => {
                        let resolved = self.resolve_class_name(name);
                        if resolved.eq_ignore_ascii_case(b"self") {
                            qualified_name.to_vec()
                        } else if resolved.eq_ignore_ascii_case(b"parent") {
                            extends
                                .map(|p| self.resolve_class_name(p))
                                .unwrap_or(resolved)
                        } else {
                            resolved
                        }
                    }
                    _ => qualified_name.to_vec(),
                };
                let mut marker = b"__deferred_const__::".to_vec();
                marker.extend_from_slice(&class_name);
                marker.push(b':');
                marker.push(b':');
                marker.extend_from_slice(constant);
                Some(Value::String(crate::string::PhpString::from_vec(marker)))
            }
            ExprKind::ConstantAccess(parts) => {
                // Try magic constants first.
                let name_lower: Vec<u8> = parts.iter().flat_map(|p| p.iter()).copied().collect();
                let name_lower_lc: Vec<u8> =
                    name_lower.iter().map(|c| c.to_ascii_lowercase()).collect();
                let magic_val =
                    self.resolve_class_const_magic(&name_lower_lc, qualified_name, expr.span.line);
                if !matches!(magic_val, Value::Null) {
                    return Some(magic_val);
                }
                let mut full_name = Vec::new();
                for (i, part) in parts.iter().enumerate() {
                    if i > 0 {
                        full_name.push(b'\\');
                    }
                    full_name.extend_from_slice(part);
                }
                let mut marker = b"__deferred_global_const__::".to_vec();
                marker.extend_from_slice(&full_name);
                Some(Value::String(crate::string::PhpString::from_vec(marker)))
            }
            ExprKind::Identifier(name) => {
                let name_lower_lc: Vec<u8> = name.iter().map(|c| c.to_ascii_lowercase()).collect();
                let magic_val =
                    self.resolve_class_const_magic(&name_lower_lc, qualified_name, expr.span.line);
                if !matches!(magic_val, Value::Null) {
                    return Some(magic_val);
                }
                let resolved_name = if self.current_namespace.is_empty() {
                    name.clone()
                } else {
                    let mut fqn = self.current_namespace.clone();
                    fqn.push(b'\\');
                    fqn.extend_from_slice(name);
                    fqn
                };
                let mut marker = b"__deferred_global_const__::".to_vec();
                marker.extend_from_slice(&resolved_name);
                Some(Value::String(crate::string::PhpString::from_vec(marker)))
            }
            ExprKind::BinaryOp {
                op, left, right, ..
            } => {
                let lv = self.eval_or_defer_in_class_const(left, class, qualified_name, extends)?;
                let rv =
                    self.eval_or_defer_in_class_const(right, class, qualified_name, extends)?;
                let is_deferred = |v: &Value| {
                    matches!(v, Value::String(s)
                    if s.as_bytes().starts_with(b"__deferred_const__::")
                    || s.as_bytes().starts_with(b"__deferred_global_const__::")
                    || s.as_bytes().starts_with(b"__deferred_binop__::"))
                };
                if is_deferred(&lv) || is_deferred(&rv) {
                    let op_code: u8 = match op {
                        BinaryOp::Concat => 1,
                        BinaryOp::Add => 2,
                        BinaryOp::Sub => 3,
                        BinaryOp::Mul => 4,
                        BinaryOp::BitwiseOr => 5,
                        BinaryOp::BitwiseAnd => 6,
                        BinaryOp::ShiftLeft => 7,
                        BinaryOp::ShiftRight => 8,
                        _ => 0,
                    };
                    let l_str = lv.to_php_string();
                    let r_str = rv.to_php_string();
                    let mut marker = b"__deferred_binop__::".to_vec();
                    marker.push(op_code);
                    marker.push(b':');
                    marker.extend_from_slice(l_str.as_bytes());
                    marker.push(0);
                    marker.extend_from_slice(r_str.as_bytes());
                    Some(Value::String(crate::string::PhpString::from_vec(marker)))
                } else {
                    // Only what cannot warn or throw is folded here; the
                    // rest is evaluated (in a thunk) when the constant is.
                    let num = |v: &Value| matches!(v, Value::Long(_) | Value::Double(_));
                    let ints = matches!((&lv, &rv), (Value::Long(_), Value::Long(_)));
                    match op {
                        BinaryOp::Add if num(&lv) && num(&rv) => Some(lv.add(&rv)),
                        BinaryOp::Sub if num(&lv) && num(&rv) => Some(lv.sub(&rv)),
                        BinaryOp::Mul if num(&lv) && num(&rv) => Some(lv.mul(&rv)),
                        BinaryOp::Concat
                            if !matches!(lv, Value::Array(_)) && !matches!(rv, Value::Array(_)) =>
                        {
                            let mut result = lv.to_php_string().as_bytes().to_vec();
                            result.extend_from_slice(rv.to_php_string().as_bytes());
                            Some(Value::String(crate::string::PhpString::from_vec(result)))
                        }
                        BinaryOp::BitwiseOr if ints => {
                            Some(Value::Long(lv.to_long() | rv.to_long()))
                        }
                        BinaryOp::BitwiseAnd if ints => {
                            Some(Value::Long(lv.to_long() & rv.to_long()))
                        }
                        BinaryOp::ShiftLeft if ints && (0..64).contains(&rv.to_long()) => {
                            Some(Value::Long(lv.to_long() << rv.to_long()))
                        }
                        BinaryOp::ShiftRight if ints && (0..64).contains(&rv.to_long()) => {
                            Some(Value::Long(lv.to_long() >> rv.to_long()))
                        }
                        _ => None,
                    }
                }
            }
            _ => None,
        }
    }

    /// Walk a constant value expression and collect all class constant
    /// references as (class_name_lower, constant_name) pairs. The class name
    /// uses the resolved fully-qualified form, lowercased, so it can be used
    /// as a lookup key into `self.classes`. `self`/`parent`/`static` are
    /// resolved to the actual class. Used to track which constants a class
    /// constant depends on, so #[\Deprecated] banners for those can be
    /// re-emitted at access time.
    fn collect_class_const_refs(
        expr: &Expr,
        qualified_name: &[u8],
        extends: Option<&[u8]>,
        compiler: &Compiler,
        out: &mut Vec<(Vec<u8>, Vec<u8>)>,
    ) {
        match &expr.kind {
            ExprKind::ClassConstAccess {
                class: class_expr,
                constant,
            } => {
                if constant == b"class" {
                    return;
                }
                let class_resolved: Option<Vec<u8>> = match &class_expr.kind {
                    ExprKind::Identifier(name) => {
                        let resolved = compiler.resolve_class_name(name);
                        let lower: Vec<u8> =
                            resolved.iter().map(|b| b.to_ascii_lowercase()).collect();
                        if lower == b"self" || lower == b"static" {
                            Some(qualified_name.to_vec())
                        } else if lower == b"parent" {
                            extends.map(|p| compiler.resolve_class_name(p))
                        } else {
                            Some(resolved)
                        }
                    }
                    _ => None,
                };
                if let Some(cls) = class_resolved {
                    let cls_lower: Vec<u8> = cls.iter().map(|b| b.to_ascii_lowercase()).collect();
                    out.push((cls_lower, constant.clone()));
                }
            }
            ExprKind::BinaryOp { left, right, .. } => {
                Self::collect_class_const_refs(left, qualified_name, extends, compiler, out);
                Self::collect_class_const_refs(right, qualified_name, extends, compiler, out);
            }
            ExprKind::UnaryOp { operand, .. } => {
                Self::collect_class_const_refs(operand, qualified_name, extends, compiler, out);
            }
            ExprKind::Ternary {
                condition,
                if_true,
                if_false,
            } => {
                Self::collect_class_const_refs(condition, qualified_name, extends, compiler, out);
                if let Some(t) = if_true {
                    Self::collect_class_const_refs(t, qualified_name, extends, compiler, out);
                }
                Self::collect_class_const_refs(if_false, qualified_name, extends, compiler, out);
            }
            ExprKind::NullCoalesce { left, right } => {
                Self::collect_class_const_refs(left, qualified_name, extends, compiler, out);
                Self::collect_class_const_refs(right, qualified_name, extends, compiler, out);
            }
            ExprKind::Array(elements) => {
                for elem in elements {
                    if let Some(k) = &elem.key {
                        Self::collect_class_const_refs(k, qualified_name, extends, compiler, out);
                    }
                    Self::collect_class_const_refs(
                        &elem.value,
                        qualified_name,
                        extends,
                        compiler,
                        out,
                    );
                }
            }
            ExprKind::Cast(_, inner) => {
                Self::collect_class_const_refs(inner, qualified_name, extends, compiler, out);
            }
            _ => {}
        }
    }
}

/// Map a compound-assignment binary operator (`+=`, `.=`, ...) to the plain
/// binary opcode used to compute the new value.
fn compound_binary_opcode(op: &BinaryOp) -> OpCode {
    match op {
        BinaryOp::Add => OpCode::Add,
        BinaryOp::Sub => OpCode::Sub,
        BinaryOp::Mul => OpCode::Mul,
        BinaryOp::Div => OpCode::Div,
        BinaryOp::Mod => OpCode::Mod,
        BinaryOp::Pow => OpCode::Pow,
        BinaryOp::Concat => OpCode::Concat,
        BinaryOp::BitwiseAnd => OpCode::BitwiseAnd,
        BinaryOp::BitwiseOr => OpCode::BitwiseOr,
        BinaryOp::BitwiseXor => OpCode::BitwiseXor,
        BinaryOp::ShiftLeft => OpCode::ShiftLeft,
        BinaryOp::ShiftRight => OpCode::ShiftRight,
        _ => OpCode::Add,
    }
}

/// Convert an AST TypeHint into a runtime ParamType with namespace resolution.
/// zend_assert_valid_class_name(.., "a type name"): a qualified class name
/// whose last segment is a reserved type name (e.g. `bar\int`).
fn reserved_type_name_error(pt: &ParamType) -> Option<String> {
    match pt {
        ParamType::Simple(name) => {
            let pos = name.iter().rposition(|&b| b == b'\\')?;
            let uq = name[pos + 1..].to_ascii_lowercase();
            matches!(
                uq.as_slice(),
                b"bool"
                    | b"false"
                    | b"float"
                    | b"int"
                    | b"null"
                    | b"parent"
                    | b"self"
                    | b"static"
                    | b"string"
                    | b"true"
                    | b"void"
                    | b"never"
                    | b"iterable"
                    | b"object"
                    | b"mixed"
                    | b"array"
                    | b"callable"
            )
            .then(|| {
                format!(
                    "Cannot use \"{}\" as a type name as it is reserved",
                    String::from_utf8_lossy(name)
                )
            })
        }
        ParamType::Nullable(inner) => reserved_type_name_error(inner),
        ParamType::Union(ts) | ParamType::Intersection(ts) => {
            ts.iter().find_map(reserved_type_name_error)
        }
    }
}

fn type_hint_to_param_type_with_ns(
    hint: &TypeHint,
    namespace: &[u8],
    use_map: &HashMap<Vec<u8>, Vec<u8>>,
) -> ParamType {
    match hint {
        TypeHint::Simple(name) => {
            let lower: Vec<u8> = name.iter().map(|b| b.to_ascii_lowercase()).collect();
            // Check if it's a built-in type; if so, store lowercase.
            // (`integer`, `double`, `boolean` are class names, not aliases.)
            match lower.as_slice() {
                b"int" | b"float" | b"string" | b"bool" | b"array" | b"object" | b"callable"
                | b"iterable" | b"mixed" | b"null" | b"void" | b"self" | b"parent" | b"static"
                | b"false" | b"true" | b"never" => ParamType::Simple(lower),
                _ => {
                    // Class name: resolve through namespace
                    // Check for fully qualified (starts with \)
                    if name.starts_with(b"\\") {
                        return ParamType::Simple(name[1..].to_vec());
                    }
                    // namespace\Foo is relative to the current namespace.
                    if lower.starts_with(b"namespace\\") {
                        let rest = &name[b"namespace\\".len()..];
                        if namespace.is_empty() {
                            return ParamType::Simple(rest.to_vec());
                        }
                        let mut result = namespace.to_vec();
                        result.push(b'\\');
                        result.extend_from_slice(rest);
                        return ParamType::Simple(result);
                    }
                    // Check use map
                    if let Some(pos) = name.iter().position(|&b| b == b'\\') {
                        let first_part = &name[..pos];
                        let first_lower: Vec<u8> =
                            first_part.iter().map(|b| b.to_ascii_lowercase()).collect();
                        if let Some(resolved) = use_map.get(&first_lower) {
                            let mut result = resolved.clone();
                            result.extend_from_slice(&name[pos..]);
                            return ParamType::Simple(result);
                        }
                        // Qualified but no use match: prefix with namespace
                        if namespace.is_empty() {
                            ParamType::Simple(name.clone())
                        } else {
                            let mut result = namespace.to_vec();
                            result.push(b'\\');
                            result.extend_from_slice(name);
                            ParamType::Simple(result)
                        }
                    } else {
                        // Unqualified: check use map
                        let name_lower: Vec<u8> =
                            name.iter().map(|b| b.to_ascii_lowercase()).collect();
                        if let Some(resolved) = use_map.get(&name_lower) {
                            return ParamType::Simple(resolved.clone());
                        }
                        // Prefix with namespace
                        if namespace.is_empty() {
                            ParamType::Simple(name.clone())
                        } else {
                            let mut result = namespace.to_vec();
                            result.push(b'\\');
                            result.extend_from_slice(name);
                            ParamType::Simple(result)
                        }
                    }
                }
            }
        }
        TypeHint::Nullable(inner) => ParamType::Nullable(Box::new(
            type_hint_to_param_type_with_ns(inner, namespace, use_map),
        )),
        TypeHint::Union(types) => ParamType::Union(
            types
                .iter()
                .map(|t| type_hint_to_param_type_with_ns(t, namespace, use_map))
                .collect(),
        ),
        TypeHint::Intersection(types) => ParamType::Intersection(
            types
                .iter()
                .map(|t| type_hint_to_param_type_with_ns(t, namespace, use_map))
                .collect(),
        ),
    }
}

/// Check if a ParamType is already nullable or mixed (which implicitly allows null)
fn is_type_nullable_or_mixed(pt: &ParamType) -> bool {
    match pt {
        ParamType::Nullable(_) => true,
        ParamType::Simple(name) => {
            let lower: Vec<u8> = name.iter().map(|b| b.to_ascii_lowercase()).collect();
            lower == b"mixed" || lower == b"null"
        }
        ParamType::Union(types) => types.iter().any(|t| {
            matches!(t, ParamType::Simple(n) if {
                let lower: Vec<u8> = n.iter().map(|b| b.to_ascii_lowercase()).collect();
                lower == b"null" || lower == b"mixed"
            })
        }),
        ParamType::Intersection(_) => false,
    }
}

/// Format a TypeHint as a display string for error messages
fn type_hint_display(hint: &TypeHint) -> String {
    match hint {
        TypeHint::Simple(name) => String::from_utf8_lossy(name).to_string(),
        TypeHint::Nullable(inner) => format!("?{}", type_hint_display(inner)),
        TypeHint::Union(types) => types
            .iter()
            .map(type_hint_display)
            .collect::<Vec<_>>()
            .join("|"),
        TypeHint::Intersection(types) => types
            .iter()
            .map(type_hint_display)
            .collect::<Vec<_>>()
            .join("&"),
    }
}

/// Check if a name is a reserved type name that cannot be used as a class/interface/trait name
pub fn is_reserved_class_name(name: &[u8]) -> bool {
    let lower: Vec<u8> = name.iter().map(|b| b.to_ascii_lowercase()).collect();
    matches!(
        lower.as_slice(),
        b"int"
            | b"float"
            | b"string"
            | b"bool"
            | b"array"
            | b"object"
            | b"callable"
            | b"iterable"
            | b"mixed"
            | b"null"
            | b"void"
            | b"self"
            | b"parent"
            | b"static"
            | b"false"
            | b"true"
            | b"never"
    )
}

/// Validate a type hint for redundancy, standalone constraints, and other compile-time rules.
/// Returns an error message string if invalid, or None if valid.
/// `class_name` is the current class name for self resolution, or None if not in a class.
/// `parent_class_name` is the parent class name for parent resolution, or None if no parent.
fn validate_type_hint(hint: &TypeHint, class_name: Option<&[u8]>) -> Option<String> {
    validate_type_hint_full(hint, class_name, None)
}

/// zend_compile_single_typename() / zend_resolve_class_name() on a fully
/// qualified (`\\int`) or namespace-relative (`namespace\\self`) name.
fn qualified_type_name_error(hint: &TypeHint) -> Option<String> {
    match hint {
        TypeHint::Simple(n) => {
            let (rest, prefix): (&[u8], &str) = if let Some(r) = n.strip_prefix(b"\\") {
                (r, "\\")
            } else if n.len() > 10 && n[..10].eq_ignore_ascii_case(b"namespace\\") {
                (&n[10..], "namespace\\")
            } else {
                return None;
            };
            if rest.contains(&b'\\') {
                return None;
            }
            let lower = rest.to_ascii_lowercase();
            match lower.as_slice() {
                b"null" | b"true" | b"false" | b"int" | b"float" | b"string" | b"bool"
                | b"void" | b"never" | b"iterable" | b"object" | b"mixed" => Some(format!(
                    "Type declaration '{}' must be unqualified",
                    String::from_utf8_lossy(&lower)
                )),
                b"self" | b"parent" | b"static" => Some(format!(
                    "'{}{}' is an invalid class name",
                    prefix,
                    String::from_utf8_lossy(rest)
                )),
                _ => None,
            }
        }
        TypeHint::Nullable(inner) => qualified_type_name_error(inner),
        TypeHint::Union(ts) | TypeHint::Intersection(ts) => {
            ts.iter().find_map(qualified_type_name_error)
        }
    }
}

fn validate_type_hint_full(
    hint: &TypeHint,
    class_name: Option<&[u8]>,
    parent_class_name: Option<&[u8]>,
) -> Option<String> {
    if let Some(e) = qualified_type_name_error(hint) {
        return Some(e);
    }
    match hint {
        TypeHint::Nullable(inner) => {
            // ?null is invalid
            if let TypeHint::Simple(n) = inner.as_ref() {
                let lower: Vec<u8> = n.iter().map(|b| b.to_ascii_lowercase()).collect();
                if lower == b"null" {
                    return Some("null cannot be marked as nullable".to_string());
                }
                // ?mixed is invalid - "mixed already includes null"
                if lower == b"mixed" {
                    return Some(
                        "Type mixed cannot be marked as nullable since mixed already includes null"
                            .to_string(),
                    );
                }
                // ?void is invalid
                if lower == b"void" {
                    return Some("Void can only be used as a standalone type".to_string());
                }
                // ?never is invalid
                if lower == b"never" {
                    return Some("never can only be used as a standalone type".to_string());
                }
            }
            None
        }
        TypeHint::Union(types) => {
            // Collect all types (expanding iterable to Traversable|array) for duplicate checking
            let mut seen_types: Vec<Vec<u8>> = Vec::new();
            let mut has_object = false;
            let mut has_class_type = false;
            let mut has_bool = false;
            let mut has_false = false;
            let mut has_true = false;
            let mut has_void = false;
            let mut has_mixed = false;
            let mut has_never = false;
            let mut class_type_names: Vec<Vec<u8>> = Vec::new();

            for t in types {
                match t {
                    TypeHint::Simple(n) => {
                        let lower: Vec<u8> = n.iter().map(|b| b.to_ascii_lowercase()).collect();

                        // Resolve self/parent to actual class name for duplicate checking
                        let resolved = match lower.as_slice() {
                            b"self" => class_name.map(|cn| cn.to_vec()),
                            b"parent" => parent_class_name.map(|pn| pn.to_vec()),
                            _ => None,
                        };

                        // Normalize type name for duplicate checking
                        let canonical = match lower.as_slice() {
                            b"integer" => b"int".to_vec(),
                            b"double" => b"float".to_vec(),
                            b"boolean" => b"bool".to_vec(),
                            _ => {
                                if let Some(ref r) = resolved {
                                    r.iter().map(|b| b.to_ascii_lowercase()).collect()
                                } else {
                                    lower.clone()
                                }
                            }
                        };

                        // The display name for error messages: resolved class name or canonical built-in
                        let display_name: String = if let Some(ref r) = resolved {
                            String::from_utf8_lossy(r).to_string()
                        } else if matches!(
                            lower.as_slice(),
                            b"int"
                                | b"integer"
                                | b"float"
                                | b"double"
                                | b"string"
                                | b"bool"
                                | b"boolean"
                                | b"array"
                                | b"object"
                                | b"callable"
                                | b"iterable"
                                | b"mixed"
                                | b"null"
                                | b"void"
                                | b"false"
                                | b"true"
                                | b"never"
                        ) {
                            // For built-in types, display the canonical (lowercase) form
                            String::from_utf8_lossy(&canonical).to_string()
                        } else {
                            // For class types, preserve original case
                            String::from_utf8_lossy(n).to_string()
                        };

                        // Check for standalone types in union
                        match lower.as_slice() {
                            b"void" => has_void = true,
                            b"mixed" => has_mixed = true,
                            b"never" => has_never = true,
                            b"object" => has_object = true,
                            b"bool" | b"boolean" => has_bool = true,
                            b"false" => has_false = true,
                            b"true" => has_true = true,
                            b"iterable" => {
                                // iterable expands to Traversable|array for redundancy checking
                                if seen_types.iter().any(|s| s == b"array") {
                                    return Some("Duplicate type array is redundant".to_string());
                                }
                                if seen_types.iter().any(|s| s == b"traversable") {
                                    return Some(
                                        "Duplicate type Traversable is redundant".to_string(),
                                    );
                                }
                                // Add both expanded types
                                seen_types.push(b"traversable".to_vec());
                                seen_types.push(b"array".to_vec());
                            }
                            b"array" => {
                                // Check if iterable (which includes array) was already seen
                                if seen_types.iter().any(|s| s == b"array") {
                                    return Some("Duplicate type array is redundant".to_string());
                                }
                            }
                            _ => {}
                        }

                        // Check for class type (non-builtin) for object redundancy
                        if !matches!(
                            lower.as_slice(),
                            b"int"
                                | b"integer"
                                | b"float"
                                | b"double"
                                | b"string"
                                | b"bool"
                                | b"boolean"
                                | b"array"
                                | b"object"
                                | b"callable"
                                | b"iterable"
                                | b"mixed"
                                | b"null"
                                | b"void"
                                | b"false"
                                | b"true"
                                | b"never"
                        ) {
                            has_class_type = true;
                            class_type_names.push(display_name.clone().into_bytes());
                        }

                        // Check for duplicate types (skip iterable which was handled above)
                        if lower != b"iterable" {
                            if seen_types.iter().any(|s| s == &canonical) {
                                return Some(format!(
                                    "Duplicate type {} is redundant",
                                    display_name
                                ));
                            }
                            seen_types.push(canonical);
                        }
                    }
                    TypeHint::Intersection(_) => {
                        // DNF type: intersection within union - no duplicate checks needed here
                        // but may contain class types for object redundancy
                        has_class_type = true;
                    }
                    _ => {}
                }
            }

            // mixed can only be standalone (check first, before void/never)
            if has_mixed {
                return Some("Type mixed can only be used as a standalone type".to_string());
            }
            // void can only be standalone
            if has_void {
                return Some("Void can only be used as a standalone type".to_string());
            }
            // never can only be standalone
            if has_never {
                return Some("never can only be used as a standalone type".to_string());
            }
            // bool + false is redundant
            if has_bool && has_false {
                return Some("Duplicate type false is redundant".to_string());
            }
            // bool + true is redundant
            if has_bool && has_true {
                return Some("Duplicate type true is redundant".to_string());
            }
            // true + false should be bool
            if has_true && has_false {
                return Some(
                    "Type contains both true and false, bool must be used instead".to_string(),
                );
            }
            // object + class type is redundant
            if has_object && has_class_type {
                // Render like zend_type_to_string (class names in order, then builtins)
                let pt = type_hint_to_param_type_with_ns(hint, b"", &HashMap::new());
                let mut tv = crate::vm::variance::TypeView::from_param_type(&pt);
                for e in tv.elems.iter_mut() {
                    if let crate::vm::variance::TElem::Name(n) = e {
                        if n.eq_ignore_ascii_case(b"self") {
                            if let Some(cn) = class_name {
                                *n = cn.to_vec();
                            }
                        } else if n.eq_ignore_ascii_case(b"parent") {
                            if let Some(pn) = parent_class_name {
                                *n = pn.to_vec();
                            }
                        }
                    }
                }
                let full_type = crate::vm::variance::type_to_string(&tv, None);
                return Some(format!(
                    "Type {} contains both object and a class type, which is redundant",
                    full_type
                ));
            }

            None
        }
        TypeHint::Simple(n) => {
            // Nothing to validate for a simple standalone type
            let _ = n;
            None
        }
        TypeHint::Intersection(_) => {
            // Intersection type validation is already handled in parser
            None
        }
    }
}

/// zend_compile_typename: `self`/`parent` left unresolved at compile time
/// (inside a trait) cannot be part of an intersection type.
fn relative_type_in_intersection(hint: &TypeHint, in_trait: bool) -> Option<String> {
    if !in_trait {
        return None;
    }
    match hint {
        TypeHint::Intersection(types) => types.iter().find_map(|t| match t {
            TypeHint::Simple(n)
                if n.eq_ignore_ascii_case(b"self") || n.eq_ignore_ascii_case(b"parent") =>
            {
                Some(format!(
                    "Type {} cannot be part of an intersection type",
                    String::from_utf8_lossy(n)
                ))
            }
            _ => None,
        }),
        TypeHint::Union(types) => types
            .iter()
            .find_map(|t| relative_type_in_intersection(t, in_trait)),
        TypeHint::Nullable(inner) => relative_type_in_intersection(inner, in_trait),
        TypeHint::Simple(_) => None,
    }
}

/// Check if a type hint uses self/parent/static outside of a class scope.
/// Returns an error message if invalid.
fn check_relative_type_outside_class(hint: &TypeHint) -> Option<String> {
    match hint {
        TypeHint::Simple(name) => {
            let lower: Vec<u8> = name.iter().map(|b| b.to_ascii_lowercase()).collect();
            match lower.as_slice() {
                b"self" => Some("Cannot use \"self\" when no class scope is active".to_string()),
                b"parent" => {
                    Some("Cannot use \"parent\" when no class scope is active".to_string())
                }
                b"static" => {
                    Some("Cannot use \"static\" when no class scope is active".to_string())
                }
                _ => None,
            }
        }
        TypeHint::Nullable(inner) => check_relative_type_outside_class(inner),
        TypeHint::Union(types) => {
            for t in types {
                if let Some(err) = check_relative_type_outside_class(t) {
                    return Some(err);
                }
            }
            None
        }
        TypeHint::Intersection(types) => {
            for t in types {
                if let Some(err) = check_relative_type_outside_class(t) {
                    return Some(err);
                }
            }
            None
        }
    }
}

/// Check if a type hint contains "static" - which cannot be used as a parameter type.
/// Returns true if the hint contains "static".
fn check_static_param_type(hint: &TypeHint) -> bool {
    match hint {
        TypeHint::Simple(name) => {
            let lower: Vec<u8> = name.iter().map(|b| b.to_ascii_lowercase()).collect();
            lower == b"static"
        }
        TypeHint::Nullable(inner) => check_static_param_type(inner),
        TypeHint::Union(types) | TypeHint::Intersection(types) => {
            types.iter().any(check_static_param_type)
        }
    }
}

/// Check if a type hint uses "parent" in a class with no parent.
/// Returns an error message if invalid.
fn check_parent_type_without_parent(hint: &TypeHint) -> Option<String> {
    match hint {
        TypeHint::Simple(name) => {
            let lower: Vec<u8> = name.iter().map(|b| b.to_ascii_lowercase()).collect();
            if lower == b"parent" {
                Some("Cannot use \"parent\" when current class scope has no parent".to_string())
            } else {
                None
            }
        }
        TypeHint::Nullable(inner) => check_parent_type_without_parent(inner),
        TypeHint::Union(types) => {
            for t in types {
                if let Some(err) = check_parent_type_without_parent(t) {
                    return Some(err);
                }
            }
            None
        }
        TypeHint::Intersection(types) => {
            for t in types {
                if let Some(err) = check_parent_type_without_parent(t) {
                    return Some(err);
                }
            }
            None
        }
    }
}

/// Check if an expression's object chain contains a nullsafe operator.
/// This is used to determine whether chained property/method accesses should
/// automatically short-circuit to null (PHP nullsafe chain semantics).
///
/// For example, in `$obj?->foo()->bar()`, the `->bar()` call is chained from
/// a nullsafe method call `?->foo()`. If `$obj` is null, the entire chain
/// should evaluate to null rather than throwing "call on null".
fn expr_is_in_nullsafe_chain(expr: &Expr) -> bool {
    match &expr.kind {
        ExprKind::MethodCall { nullsafe: true, .. } => true,
        ExprKind::PropertyAccess { nullsafe: true, .. } => true,
        ExprKind::MethodCall {
            object,
            nullsafe: false,
            ..
        } => expr_is_in_nullsafe_chain(object),
        ExprKind::PropertyAccess {
            object,
            nullsafe: false,
            ..
        } => expr_is_in_nullsafe_chain(object),
        ExprKind::ArrayAccess { array, .. } => expr_is_in_nullsafe_chain(array),
        ExprKind::StaticPropertyAccess { class, .. } => expr_is_in_nullsafe_chain(class),
        ExprKind::DynamicStaticPropertyAccess { class, .. } => expr_is_in_nullsafe_chain(class),
        ExprKind::StaticMethodCall { class, .. } => expr_is_in_nullsafe_chain(class),
        ExprKind::DynamicStaticMethodCall { class, .. } => expr_is_in_nullsafe_chain(class),
        _ => false,
    }
}

/// Search top-level statements for `yield` or `yield from`. If found, return
/// the source line where it appears. Function/class bodies are not descended
/// into because yield inside those is allowed.
fn find_top_level_yield(stmts: &[Statement]) -> Option<u32> {
    for stmt in stmts {
        match &stmt.kind {
            // Don't recurse into function/class/closure bodies - yield is legal there.
            StmtKind::FunctionDecl { .. } | StmtKind::ClassDecl { .. } => continue,
            StmtKind::NamespaceDecl { body, .. } => {
                if let Some(body) = body {
                    if let Some(l) = find_top_level_yield(body) {
                        return Some(l);
                    }
                }
            }
            _ => {
                if stmt_contains_yield(stmt) {
                    return Some(stmt.span.line);
                }
            }
        }
    }
    None
}

/// Check if a list of statements contains any yield expressions.
/// This determines whether a function should be compiled as a generator.
fn stmts_contain_yield(stmts: &[Statement]) -> bool {
    for stmt in stmts {
        if stmt_contains_yield(stmt) {
            return true;
        }
    }
    false
}

fn stmt_contains_yield(stmt: &Statement) -> bool {
    match &stmt.kind {
        StmtKind::Expression(expr) => expr_contains_yield(expr),
        StmtKind::Echo(exprs) => exprs.iter().any(expr_contains_yield),
        StmtKind::Return(Some(expr)) => expr_contains_yield(expr),
        StmtKind::If {
            condition,
            body,
            elseif_clauses,
            else_body,
        } => {
            expr_contains_yield(condition)
                || stmts_contain_yield(body)
                || elseif_clauses
                    .iter()
                    .any(|(c, b)| expr_contains_yield(c) || stmts_contain_yield(b))
                || else_body.as_ref().is_some_and(|b| stmts_contain_yield(b))
        }
        StmtKind::While { condition, body } => {
            expr_contains_yield(condition) || stmts_contain_yield(body)
        }
        StmtKind::DoWhile { body, condition } => {
            stmts_contain_yield(body) || expr_contains_yield(condition)
        }
        StmtKind::For {
            init,
            condition,
            update,
            body,
        } => {
            init.iter().any(expr_contains_yield)
                || condition.iter().any(expr_contains_yield)
                || update.iter().any(expr_contains_yield)
                || stmts_contain_yield(body)
        }
        StmtKind::Foreach { expr, body, .. } => {
            expr_contains_yield(expr) || stmts_contain_yield(body)
        }
        StmtKind::Switch { expr, cases } => {
            expr_contains_yield(expr)
                || cases.iter().any(|c| {
                    c.value.as_ref().is_some_and(expr_contains_yield)
                        || stmts_contain_yield(&c.body)
                })
        }
        StmtKind::TryCatch {
            try_body,
            catches,
            finally_body,
            ..
        } => {
            stmts_contain_yield(try_body)
                || catches.iter().any(|c| stmts_contain_yield(&c.body))
                || finally_body
                    .as_ref()
                    .is_some_and(|b| stmts_contain_yield(b))
        }
        StmtKind::Throw(expr) => expr_contains_yield(expr),
        StmtKind::Unset(exprs) => exprs.iter().any(expr_contains_yield),
        // Don't recurse into nested function/class declarations
        StmtKind::FunctionDecl { .. } | StmtKind::ClassDecl { .. } => false,
        _ => false,
    }
}

/// Collect all variable names referenced in an expression (for arrow function capture)
fn collect_expr_variables(expr: &Expr, vars: &mut Vec<Vec<u8>>) {
    match &expr.kind {
        ExprKind::Variable(name) => {
            if !vars.contains(name) && name != b"this" {
                vars.push(name.clone());
            }
        }
        ExprKind::DynamicVariable(inner) => collect_expr_variables(inner, vars),
        ExprKind::BinaryOp { left, right, .. } => {
            collect_expr_variables(left, vars);
            collect_expr_variables(right, vars);
        }
        ExprKind::UnaryOp { operand, .. } => collect_expr_variables(operand, vars),
        ExprKind::Assign { target, value, .. } => {
            collect_expr_variables(target, vars);
            collect_expr_variables(value, vars);
        }
        ExprKind::CompoundAssign { target, value, .. } => {
            collect_expr_variables(target, vars);
            collect_expr_variables(value, vars);
        }
        ExprKind::FunctionCall { name, args } => {
            collect_expr_variables(name, vars);
            for a in args {
                collect_expr_variables(&a.value, vars);
            }
        }
        ExprKind::MethodCall { object, args, .. } => {
            collect_expr_variables(object, vars);
            for a in args {
                collect_expr_variables(&a.value, vars);
            }
        }
        ExprKind::StaticMethodCall { args, .. } => {
            for a in args {
                collect_expr_variables(&a.value, vars);
            }
        }
        ExprKind::Array(elements) => {
            for e in elements {
                if let Some(key) = &e.key {
                    collect_expr_variables(key, vars);
                }
                collect_expr_variables(&e.value, vars);
            }
        }
        ExprKind::ArrayAccess { array, index } => {
            collect_expr_variables(array, vars);
            if let Some(i) = index {
                collect_expr_variables(i, vars);
            }
        }
        ExprKind::Ternary {
            condition,
            if_true,
            if_false,
        } => {
            collect_expr_variables(condition, vars);
            if let Some(t) = if_true {
                collect_expr_variables(t, vars);
            }
            collect_expr_variables(if_false, vars);
        }
        ExprKind::NullCoalesce { left, right } => {
            collect_expr_variables(left, vars);
            collect_expr_variables(right, vars);
        }
        ExprKind::Cast(_, e)
        | ExprKind::Clone(e)
        | ExprKind::Spread(e)
        | ExprKind::Print(e)
        | ExprKind::ThrowExpr(e) => {
            collect_expr_variables(e, vars);
        }
        ExprKind::PropertyAccess { object, .. } => {
            collect_expr_variables(object, vars);
        }
        ExprKind::Instanceof { expr, .. } => collect_expr_variables(expr, vars),
        ExprKind::ArrowFunction { body, .. } => collect_expr_variables(body, vars),
        ExprKind::Closure { use_vars, .. } => {
            // Don't recurse into closures body, but DO collect use vars
            // so that enclosing arrow functions know to capture them
            for uv in use_vars {
                if !vars.contains(&uv.variable) {
                    vars.push(uv.variable.clone());
                }
            }
        }
        ExprKind::Match { subject, arms } => {
            collect_expr_variables(subject, vars);
            for arm in arms {
                if let Some(cond_list) = &arm.conditions {
                    for cond in cond_list {
                        collect_expr_variables(cond, vars);
                    }
                }
                collect_expr_variables(&arm.body, vars);
            }
        }
        _ => {}
    }
}

fn expr_contains_yield(expr: &Expr) -> bool {
    match &expr.kind {
        ExprKind::Yield(_, _) | ExprKind::YieldFrom(_) => true,
        ExprKind::BinaryOp { left, right, .. } => {
            expr_contains_yield(left) || expr_contains_yield(right)
        }
        ExprKind::UnaryOp { operand, .. } => expr_contains_yield(operand),
        ExprKind::Assign { target, value, .. } => {
            expr_contains_yield(target) || expr_contains_yield(value)
        }
        ExprKind::CompoundAssign { target, value, .. } => {
            expr_contains_yield(target) || expr_contains_yield(value)
        }
        ExprKind::FunctionCall { name, args } => {
            expr_contains_yield(name) || args.iter().any(|a| expr_contains_yield(&a.value))
        }
        ExprKind::MethodCall { object, args, .. } => {
            expr_contains_yield(object) || args.iter().any(|a| expr_contains_yield(&a.value))
        }
        ExprKind::Array(elements) => elements.iter().any(|e| {
            e.key.as_ref().is_some_and(expr_contains_yield) || expr_contains_yield(&e.value)
        }),
        ExprKind::ArrayAccess { array, index } => {
            expr_contains_yield(array) || index.as_ref().is_some_and(|i| expr_contains_yield(i))
        }
        ExprKind::Ternary {
            condition,
            if_true,
            if_false,
        } => {
            expr_contains_yield(condition)
                || if_true.as_ref().is_some_and(|t| expr_contains_yield(t))
                || expr_contains_yield(if_false)
        }
        ExprKind::NullCoalesce { left, right } => {
            expr_contains_yield(left) || expr_contains_yield(right)
        }
        ExprKind::Cast(_, e) => expr_contains_yield(e),
        ExprKind::Clone(e) | ExprKind::Spread(e) | ExprKind::Print(e) | ExprKind::ThrowExpr(e) => {
            expr_contains_yield(e)
        }
        ExprKind::PropertyAccess { object, .. } => expr_contains_yield(object),
        ExprKind::Include { path, .. } => expr_contains_yield(path),
        ExprKind::New { class, args } => {
            expr_contains_yield(class) || args.iter().any(|a| expr_contains_yield(&a.value))
        }
        ExprKind::StaticMethodCall { class, args, .. } => {
            expr_contains_yield(class) || args.iter().any(|a| expr_contains_yield(&a.value))
        }
        ExprKind::Match { subject, arms } => {
            expr_contains_yield(subject)
                || arms.iter().any(|arm| {
                    arm.conditions
                        .as_ref()
                        .map(|cs| cs.iter().any(expr_contains_yield))
                        .unwrap_or(false)
                        || expr_contains_yield(&arm.body)
                })
        }
        ExprKind::AssignRef { target, value } => {
            expr_contains_yield(target) || expr_contains_yield(value)
        }
        ExprKind::Instanceof { expr, class } => {
            expr_contains_yield(expr) || expr_contains_yield(class)
        }
        _ => false,
    }
}

/// Check if a list of statements references $this->propname (indicating a backed property)
fn stmts_reference_backing_store(stmts: &[Statement], prop_name: &[u8]) -> bool {
    stmts
        .iter()
        .any(|stmt| stmt_references_backing_store(stmt, prop_name))
}

fn stmt_references_backing_store(stmt: &Statement, prop_name: &[u8]) -> bool {
    match &stmt.kind {
        StmtKind::Expression(e) => expr_references_backing_store(e, prop_name),
        StmtKind::Return(Some(e)) => expr_references_backing_store(e, prop_name),
        StmtKind::Echo(exprs) => exprs
            .iter()
            .any(|e| expr_references_backing_store(e, prop_name)),
        StmtKind::If {
            condition,
            body,
            elseif_clauses,
            else_body,
        } => {
            expr_references_backing_store(condition, prop_name)
                || stmts_reference_backing_store(body, prop_name)
                || elseif_clauses.iter().any(|(c, b)| {
                    expr_references_backing_store(c, prop_name)
                        || stmts_reference_backing_store(b, prop_name)
                })
                || else_body
                    .as_ref()
                    .is_some_and(|b| stmts_reference_backing_store(b, prop_name))
        }
        StmtKind::While { condition, body } | StmtKind::DoWhile { body, condition } => {
            expr_references_backing_store(condition, prop_name)
                || stmts_reference_backing_store(body, prop_name)
        }
        StmtKind::For {
            init,
            condition,
            update,
            body,
        } => {
            init.iter()
                .any(|e| expr_references_backing_store(e, prop_name))
                || condition
                    .iter()
                    .any(|e| expr_references_backing_store(e, prop_name))
                || update
                    .iter()
                    .any(|e| expr_references_backing_store(e, prop_name))
                || stmts_reference_backing_store(body, prop_name)
        }
        StmtKind::Foreach { expr, body, .. } => {
            expr_references_backing_store(expr, prop_name)
                || stmts_reference_backing_store(body, prop_name)
        }
        StmtKind::TryCatch {
            try_body,
            catches,
            finally_body,
        } => {
            stmts_reference_backing_store(try_body, prop_name)
                || catches
                    .iter()
                    .any(|c| stmts_reference_backing_store(&c.body, prop_name))
                || finally_body
                    .as_ref()
                    .is_some_and(|b| stmts_reference_backing_store(b, prop_name))
        }
        StmtKind::Throw(e) => expr_references_backing_store(e, prop_name),
        _ => false,
    }
}

fn expr_references_backing_store(expr: &Expr, prop_name: &[u8]) -> bool {
    match &expr.kind {
        ExprKind::PropertyAccess {
            object, property, ..
        } => {
            // Check if this is $this->propname
            if let ExprKind::Variable(var) = &object.kind {
                if var == b"this" {
                    if let ExprKind::Identifier(name) = &property.kind {
                        if name == prop_name {
                            return true;
                        }
                    }
                }
            }
            expr_references_backing_store(object, prop_name)
                || expr_references_backing_store(property, prop_name)
        }
        ExprKind::Assign { target, value } | ExprKind::AssignRef { target, value } => {
            expr_references_backing_store(target, prop_name)
                || expr_references_backing_store(value, prop_name)
        }
        ExprKind::CompoundAssign { target, value, .. } => {
            expr_references_backing_store(target, prop_name)
                || expr_references_backing_store(value, prop_name)
        }
        ExprKind::BinaryOp { left, right, .. } => {
            expr_references_backing_store(left, prop_name)
                || expr_references_backing_store(right, prop_name)
        }
        ExprKind::UnaryOp { operand, .. } => expr_references_backing_store(operand, prop_name),
        ExprKind::FunctionCall { name, args, .. } => {
            expr_references_backing_store(name, prop_name)
                || args
                    .iter()
                    .any(|a| expr_references_backing_store(&a.value, prop_name))
        }
        ExprKind::MethodCall { object, args, .. } => {
            expr_references_backing_store(object, prop_name)
                || args
                    .iter()
                    .any(|a| expr_references_backing_store(&a.value, prop_name))
        }
        ExprKind::StaticMethodCall { method, args, .. } => {
            // parent::$prop::get() / ::set() is lowered by the parser to
            // StaticMethodCall { method: "__property_get_<prop>" or "__property_set_<prop>" }.
            // Treat this as backing-store access for virtuality determination.
            let is_parent_hook = (method.starts_with(b"__property_get_")
                && &method[b"__property_get_".len()..] == prop_name)
                || (method.starts_with(b"__property_set_")
                    && &method[b"__property_set_".len()..] == prop_name);
            if is_parent_hook {
                return true;
            }
            args.iter()
                .any(|a| expr_references_backing_store(&a.value, prop_name))
        }
        ExprKind::Ternary {
            condition,
            if_true,
            if_false,
        } => {
            expr_references_backing_store(condition, prop_name)
                || if_true
                    .as_ref()
                    .is_some_and(|e| expr_references_backing_store(e, prop_name))
                || expr_references_backing_store(if_false, prop_name)
        }
        ExprKind::NullCoalesce { left, right } => {
            expr_references_backing_store(left, prop_name)
                || expr_references_backing_store(right, prop_name)
        }
        ExprKind::Cast(_, e)
        | ExprKind::Clone(e)
        | ExprKind::Spread(e)
        | ExprKind::Print(e)
        | ExprKind::ThrowExpr(e)
        | ExprKind::YieldFrom(e) => expr_references_backing_store(e, prop_name),
        ExprKind::Yield(k, v) => {
            k.as_ref()
                .is_some_and(|e| expr_references_backing_store(e, prop_name))
                || v.as_ref()
                    .is_some_and(|e| expr_references_backing_store(e, prop_name))
        }
        ExprKind::Array(elements) => elements.iter().any(|el| {
            expr_references_backing_store(&el.value, prop_name)
                || el
                    .key
                    .as_ref()
                    .is_some_and(|k| expr_references_backing_store(k, prop_name))
        }),
        ExprKind::Isset(exprs) => exprs
            .iter()
            .any(|e| expr_references_backing_store(e, prop_name)),
        ExprKind::ArrayAccess { array, index } => {
            expr_references_backing_store(array, prop_name)
                || index
                    .as_ref()
                    .is_some_and(|i| expr_references_backing_store(i, prop_name))
        }
        ExprKind::New { args, .. } => args
            .iter()
            .any(|a| expr_references_backing_store(&a.value, prop_name)),
        ExprKind::Instanceof { expr, .. } => expr_references_backing_store(expr, prop_name),
        ExprKind::Match { subject, arms } => {
            expr_references_backing_store(subject, prop_name)
                || arms.iter().any(|arm| {
                    expr_references_backing_store(&arm.body, prop_name)
                        || arm.conditions.as_ref().is_some_and(|conds| {
                            conds
                                .iter()
                                .any(|c| expr_references_backing_store(c, prop_name))
                        })
                })
        }
        _ => false,
    }
}

/// Convert an expression back to a PHP source string representation.
/// Used by the compiler to inject the source string as assert()'s 2nd argument.
#[allow(clippy::if_same_then_else)] // branches mirror php-src
/// Whether a constant expression of a trait member depends on the class
/// using the trait: `self::class` and `__CLASS__` name that class
/// (ZEND_FETCH_CLASS_SELF / ZEND_AST_CLASS_NAME resolved at runtime).
fn trait_const_expr_uses_scope(expr: &Expr) -> bool {
    use goro_parser::ast::ExprKind as E;
    let rec = trait_const_expr_uses_scope;
    match &expr.kind {
        E::Identifier(n) => n.eq_ignore_ascii_case(b"__CLASS__"),
        E::ClassConstAccess { class, constant } => {
            constant.eq_ignore_ascii_case(b"class")
                && matches!(&class.kind, E::Identifier(n) if n.eq_ignore_ascii_case(b"self"))
        }
        E::BinaryOp { left, right, .. } => rec(left) || rec(right),
        E::UnaryOp { operand, .. } => rec(operand),
        E::Cast(_, inner) => rec(inner),
        E::Ternary {
            condition,
            if_true,
            if_false,
        } => rec(condition) || if_true.as_deref().is_some_and(rec) || rec(if_false),
        E::NullCoalesce { left, right } => rec(left) || rec(right),
        E::ArrayAccess { array, index } => rec(array) || index.as_deref().is_some_and(rec),
        E::Array(elements) => elements
            .iter()
            .any(|e| e.key.as_ref().is_some_and(rec) || rec(&e.value)),
        E::PropertyAccess { object, .. } => rec(object),
        E::New { args, .. } => args.iter().any(|a| rec(&a.value)),
        _ => false,
    }
}

fn expr_to_source_string(expr: &Expr) -> String {
    match &expr.kind {
        ExprKind::True => "true".to_string(),
        ExprKind::False => "false".to_string(),
        ExprKind::Null => "null".to_string(),
        ExprKind::Int(n) => n.to_string(),
        ExprKind::Float(f) => format!("{}", f),
        ExprKind::String(s) => {
            // Escape the string content
            let escaped = String::from_utf8_lossy(s)
                .replace('\\', "\\\\")
                .replace('\'', "\\'");
            format!("'{}'", escaped)
        }
        ExprKind::Variable(name) => {
            format!("${}", String::from_utf8_lossy(name))
        }
        ExprKind::Identifier(parts) => String::from_utf8_lossy(parts).to_string(),
        ExprKind::ConstantAccess(parts) => parts
            .iter()
            .map(|p| String::from_utf8_lossy(p).to_string())
            .collect::<Vec<_>>()
            .join("\\"),
        ExprKind::BinaryOp { op, left, right } => {
            let op_str = match op {
                BinaryOp::Add => "+",
                BinaryOp::Sub => "-",
                BinaryOp::Mul => "*",
                BinaryOp::Div => "/",
                BinaryOp::Mod => "%",
                BinaryOp::Pow => "**",
                BinaryOp::Concat => ".",
                BinaryOp::BitwiseAnd => "&",
                BinaryOp::BitwiseOr => "|",
                BinaryOp::BitwiseXor => "^",
                BinaryOp::ShiftLeft => "<<",
                BinaryOp::ShiftRight => ">>",
                BinaryOp::BooleanAnd => "&&",
                BinaryOp::BooleanOr => "||",
                BinaryOp::LogicalAnd => "and",
                BinaryOp::LogicalOr => "or",
                BinaryOp::LogicalXor => "xor",
                BinaryOp::Equal => "==",
                BinaryOp::Identical => "===",
                BinaryOp::NotEqual => "!=",
                BinaryOp::NotIdentical => "!==",
                BinaryOp::Less => "<",
                BinaryOp::Greater => ">",
                BinaryOp::LessEqual => "<=",
                BinaryOp::GreaterEqual => ">=",
                BinaryOp::Spaceship => "<=>",
                BinaryOp::Coalesce => "??",
            };
            format!(
                "{} {} {}",
                expr_to_source_string(left),
                op_str,
                expr_to_source_string(right)
            )
        }
        ExprKind::UnaryOp {
            op,
            operand,
            prefix,
        } => {
            let op_str = match op {
                UnaryOp::Negate => "-",
                UnaryOp::Plus => "+",
                UnaryOp::BitwiseNot => "~",
                UnaryOp::BooleanNot => "!",
                UnaryOp::PreIncrement => "++",
                UnaryOp::PreDecrement => "--",
                UnaryOp::PostIncrement => "++",
                UnaryOp::PostDecrement => "--",
            };
            let operand_str = expr_to_source_string(operand);
            if *prefix {
                format!("{}{}", op_str, operand_str)
            } else {
                format!("{}{}", operand_str, op_str)
            }
        }
        ExprKind::FunctionCall { name, args } => {
            let name_str = expr_to_source_string(name);
            let args_str = args_to_source_string(args);
            format!("{}({})", name_str, args_str)
        }
        ExprKind::MethodCall {
            object,
            method,
            args,
            ..
        } => {
            let obj_str = expr_to_source_string(object);
            let method_str = expr_to_source_string(method);
            let args_str = args_to_source_string(args);
            format!("{}->{}({})", obj_str, method_str, args_str)
        }
        ExprKind::StaticMethodCall {
            class,
            method,
            args,
            ..
        } => {
            let class_str = expr_to_source_string(class);
            let method_str = String::from_utf8_lossy(method).to_string();
            let args_str = args_to_source_string(args);
            format!("{}::{}({})", class_str, method_str, args_str)
        }
        ExprKind::ArrayAccess { array, index } => {
            let arr_str = expr_to_source_string(array);
            match index {
                Some(idx) => format!("{}[{}]", arr_str, expr_to_source_string(idx)),
                None => format!("{}[]", arr_str),
            }
        }
        ExprKind::PropertyAccess {
            object, property, ..
        } => {
            format!(
                "{}->{}",
                expr_to_source_string(object),
                expr_to_source_string(property)
            )
        }
        ExprKind::StaticPropertyAccess { class, property } => {
            format!(
                "{}::${}",
                expr_to_source_string(class),
                String::from_utf8_lossy(property)
            )
        }
        ExprKind::DynamicStaticPropertyAccess { class, property } => {
            format!(
                "{}::${}",
                expr_to_source_string(class),
                expr_to_source_string(property)
            )
        }
        ExprKind::ClassConstAccess { class, constant } => {
            format!(
                "{}::{}",
                expr_to_source_string(class),
                String::from_utf8_lossy(constant)
            )
        }
        ExprKind::Instanceof { expr, class } => {
            format!(
                "{} instanceof {}",
                expr_to_source_string(expr),
                expr_to_source_string(class)
            )
        }
        ExprKind::Cast(cast_type, inner) => {
            let cast_str = match cast_type {
                CastType::Int => "(int)",
                CastType::Float => "(float)",
                CastType::String => "(string)",
                CastType::Bool => "(bool)",
                CastType::Array => "(array)",
                CastType::Object => "(object)",
                CastType::Unset => "(unset)",
                CastType::Void => "(void)",
            };
            format!("{}{}", cast_str, expr_to_source_string(inner))
        }
        ExprKind::Assign { target, value } => {
            format!(
                "{} = {}",
                expr_to_source_string(target),
                expr_to_source_string(value)
            )
        }
        ExprKind::CompoundAssign { op, target, value } => {
            let op_str = match op {
                BinaryOp::Add => "+=",
                BinaryOp::Sub => "-=",
                BinaryOp::Mul => "*=",
                BinaryOp::Div => "/=",
                BinaryOp::Mod => "%=",
                BinaryOp::Pow => "**=",
                BinaryOp::Concat => ".=",
                BinaryOp::BitwiseAnd => "&=",
                BinaryOp::BitwiseOr => "|=",
                BinaryOp::BitwiseXor => "^=",
                BinaryOp::ShiftLeft => "<<=",
                BinaryOp::ShiftRight => ">>=",
                BinaryOp::Coalesce => "??=",
                _ => "?=",
            };
            format!(
                "({} {} {})",
                expr_to_source_string(target),
                op_str,
                expr_to_source_string(value)
            )
        }
        ExprKind::AssignRef { target, value } => {
            format!(
                "{} = &{}",
                expr_to_source_string(target),
                expr_to_source_string(value)
            )
        }
        ExprKind::Ternary {
            condition,
            if_true,
            if_false,
        } => match if_true {
            Some(t) => format!(
                "{} ? {} : {}",
                expr_to_source_string(condition),
                expr_to_source_string(t),
                expr_to_source_string(if_false)
            ),
            None => format!(
                "{} ?: {}",
                expr_to_source_string(condition),
                expr_to_source_string(if_false)
            ),
        },
        ExprKind::NullCoalesce { left, right } => {
            format!(
                "{} ?? {}",
                expr_to_source_string(left),
                expr_to_source_string(right)
            )
        }
        ExprKind::New { class, args } => {
            let class_str = expr_to_source_string(class);
            // For anonymous classes, show "class" placeholder
            let class_str = if class_str.starts_with("__anonymous_class_") {
                "class".to_string()
            } else {
                class_str
            };
            let args_str = args_to_source_string(args);
            if args_str.is_empty() {
                format!("new {}()", class_str)
            } else {
                format!("new {}({})", class_str, args_str)
            }
        }
        ExprKind::Clone(inner) => {
            format!("\\clone({})", expr_to_source_string(inner))
        }
        ExprKind::Print(inner) => {
            format!("print {}", expr_to_source_string(inner))
        }
        ExprKind::Isset(exprs) => {
            let args_str = exprs
                .iter()
                .map(expr_to_source_string)
                .collect::<Vec<_>>()
                .join(", ");
            format!("isset({})", args_str)
        }
        ExprKind::Empty(inner) => {
            format!("empty({})", expr_to_source_string(inner))
        }
        ExprKind::ThrowExpr(inner) => {
            format!("throw {}", expr_to_source_string(inner))
        }
        ExprKind::Suppress(inner) => {
            format!("@{}", expr_to_source_string(inner))
        }
        ExprKind::Exit(arg) => match arg {
            Some(e) => format!("\\exit({})", expr_to_source_string(e)),
            None => "\\exit()".to_string(),
        },
        ExprKind::Eval(inner) => {
            format!("eval({})", expr_to_source_string(inner))
        }
        ExprKind::Include { kind, path } => {
            let kind_str = match kind {
                IncludeKind::Include => "include",
                IncludeKind::IncludeOnce => "include_once",
                IncludeKind::Require => "require",
                IncludeKind::RequireOnce => "require_once",
            };
            format!("{} {}", kind_str, expr_to_source_string(path))
        }
        ExprKind::Yield(key, val) => match (key, val) {
            (Some(k), Some(v)) => format!(
                "yield {} => {}",
                expr_to_source_string(k),
                expr_to_source_string(v)
            ),
            (None, Some(v)) => format!("yield {}", expr_to_source_string(v)),
            _ => "yield".to_string(),
        },
        ExprKind::YieldFrom(inner) => {
            format!("yield from {}", expr_to_source_string(inner))
        }
        ExprKind::Spread(inner) => {
            format!("...{}", expr_to_source_string(inner))
        }
        ExprKind::DynamicVariable(inner) => format!("${{{}}}", expr_to_source_string(inner)),
        // For complex expressions we can't easily represent, use a placeholder
        _ => "...".to_string(),
    }
}

/// Convert a list of function call arguments to source string.
fn args_to_source_string(args: &[Argument]) -> String {
    args.iter()
        .map(|arg| {
            let prefix = if arg.unpack { "..." } else { "" };
            let name_prefix = arg
                .name
                .as_ref()
                .map(|n| format!("{}: ", String::from_utf8_lossy(n)))
                .unwrap_or_default();
            format!(
                "{}{}{}",
                name_prefix,
                prefix,
                expr_to_source_string(&arg.value)
            )
        })
        .collect::<Vec<_>>()
        .join(", ")
}

fn next_loop_id() -> u32 {
    static NEXT: std::sync::atomic::AtomicU32 = std::sync::atomic::AtomicU32::new(1);
    NEXT.fetch_add(1, std::sync::atomic::Ordering::Relaxed)
}

/// A constructor parameter declaring a promoted property (any of the
/// property modifiers, or hooks).
fn is_promoted_param(p: &Param) -> bool {
    p.visibility.is_some()
        || p.set_visibility.is_some()
        || p.readonly
        || p.is_final
        || p.get_hook.is_some()
        || p.set_hook.is_some()
}

/// Whether a type declaration includes `callable` (not allowed on properties).
fn type_hint_has_callable(h: &TypeHint) -> bool {
    match h {
        TypeHint::Simple(n) => n.eq_ignore_ascii_case(b"callable"),
        TypeHint::Nullable(inner) => type_hint_has_callable(inner),
        TypeHint::Union(types) => types.iter().any(type_hint_has_callable),
        _ => false,
    }
}

/// zend_check_magic_method_arg_type(): whether a declared parameter type
/// admits `ty` ("string" or "array"), e.g. `mixed`, `?string`, `string|int`.
fn type_hint_admits(th: &TypeHint, ty: &[u8]) -> bool {
    match th {
        TypeHint::Simple(n) => {
            n.eq_ignore_ascii_case(ty)
                || n.eq_ignore_ascii_case(b"mixed")
                || (ty == b"array" && n.eq_ignore_ascii_case(b"iterable"))
        }
        TypeHint::Nullable(inner) => type_hint_admits(inner, ty),
        TypeHint::Union(parts) => parts.iter().any(|p| type_hint_admits(p, ty)),
        _ => false,
    }
}

/// "Redefinition of parameter $x" for duplicate parameter names.
/// Also the other per-parameter checks of zend_compile_params(), in its order:
/// auto-globals, `$this`, a variadic that is not last, a variadic default.
fn check_duplicate_params(params: &[Param], line: u32) -> CompileResult<()> {
    let mut seen = std::collections::HashSet::new();
    let mut saw_variadic = false;
    for p in params {
        // CG(zend_lineno) is the parameter's line.
        let line = if p.line > 0 { p.line } else { line };
        if matches!(
            p.name.as_slice(),
            b"GLOBALS"
                | b"_GET"
                | b"_POST"
                | b"_COOKIE"
                | b"_SERVER"
                | b"_ENV"
                | b"_REQUEST"
                | b"_FILES"
                | b"_SESSION"
        ) {
            return Err(CompileError {
                message: format!(
                    "Cannot re-assign auto-global variable {}",
                    String::from_utf8_lossy(&p.name)
                ),
                line,
            });
        }
        if !seen.insert(p.name.as_slice()) {
            return Err(CompileError {
                message: format!(
                    "Redefinition of parameter ${}",
                    String::from_utf8_lossy(&p.name)
                ),
                line,
            });
        }
        if p.name == b"this" {
            return Err(CompileError {
                message: "Cannot use $this as parameter".into(),
                line,
            });
        }
        if saw_variadic {
            return Err(CompileError {
                message: "Only the last parameter can be variadic".into(),
                line,
            });
        }
        if p.variadic {
            saw_variadic = true;
            if p.default.is_some() {
                return Err(CompileError {
                    message: "Variadic parameter cannot have a default value".into(),
                    line,
                });
            }
        }
        if let Some(message) = p
            .default
            .as_ref()
            .and_then(|d| Compiler::const_expr_error(d, true))
        {
            return Err(CompileError { message, line });
        }
    }
    Ok(())
}

/// A constant non-string class expression such as `(0)::X` (PHP: "Illegal class name").
fn is_illegal_class_literal(e: &Expr) -> bool {
    match &e.kind {
        ExprKind::Int(_)
        | ExprKind::Float(_)
        | ExprKind::True
        | ExprKind::False
        | ExprKind::Null => true,
        ExprKind::UnaryOp {
            op: UnaryOp::Negate | UnaryOp::Plus,
            operand,
            ..
        } => {
            matches!(operand.kind, ExprKind::Int(_) | ExprKind::Float(_))
        }
        // A constant array literal is a compile-time zval too.
        ExprKind::Array(elems) => elems.iter().all(|el| {
            !el.unpack
                && !el.by_ref
                && el.key.as_ref().is_none_or(is_scalar_literal)
                && (is_scalar_literal(&el.value) || matches!(el.value.kind, ExprKind::Array(_)))
                && (!matches!(el.value.kind, ExprKind::Array(_))
                    || is_illegal_class_literal(&el.value))
        }),
        _ => false,
    }
}

fn is_scalar_literal(e: &Expr) -> bool {
    matches!(e.kind, ExprKind::String(_)) || is_illegal_class_literal(e)
}

// ---------------------------------------------------------------------------
// Default-value rendering for Reflection (`zend_ast_export` / evaluated
// literals), computed at compile time while namespace/use info is known.
// ---------------------------------------------------------------------------
impl Compiler {
    /// Resolve a class name in a constant expression the way Zend does for
    /// its AST dump: `\Fully\Qualified`, except self/parent/static.
    fn export_class_name(&self, name: &[u8]) -> String {
        let lower = name.to_ascii_lowercase();
        if matches!(lower.as_slice(), b"self" | b"parent" | b"static") {
            return String::from_utf8_lossy(name).to_string();
        }
        let resolved = if lower.starts_with(b"namespace\\") {
            self.prefix_with_namespace(&name[b"namespace\\".len()..])
        } else {
            self.resolve_class_name(name)
        };
        format!("\\{}", String::from_utf8_lossy(&resolved))
    }

    /// Fold a literal-only constant expression into a value (what PHP
    /// evaluates at compile time). None if it needs runtime evaluation.
    fn fold_literal_default(&self, expr: &Expr) -> Option<Value> {
        match &expr.kind {
            ExprKind::Int(n) => Some(Value::Long(*n)),
            ExprKind::Float(f) => Some(Value::Double(*f)),
            ExprKind::String(s) => Some(Value::String(PhpString::from_vec(s.clone()))),
            ExprKind::True => Some(Value::True),
            ExprKind::False => Some(Value::False),
            ExprKind::Null => Some(Value::Null),
            ExprKind::Identifier(n) => match n.to_ascii_lowercase().as_slice() {
                b"true" | b"\\true" => Some(Value::True),
                b"false" | b"\\false" => Some(Value::False),
                b"null" | b"\\null" => Some(Value::Null),
                _ => None,
            },
            ExprKind::UnaryOp {
                op: UnaryOp::Negate,
                operand,
                ..
            } => match self.fold_literal_default(operand)? {
                Value::Long(n) => Some(Value::Long(n.wrapping_neg())),
                Value::Double(f) => Some(Value::Double(-f)),
                _ => None,
            },
            ExprKind::UnaryOp {
                op: UnaryOp::Plus,
                operand,
                ..
            } => match self.fold_literal_default(operand)? {
                v @ (Value::Long(_) | Value::Double(_)) => Some(v),
                _ => None,
            },
            ExprKind::Array(elems) => {
                let mut arr = crate::array::PhpArray::new();
                for el in elems {
                    if el.unpack || el.by_ref {
                        return None;
                    }
                    let v = self.fold_literal_default(&el.value)?;
                    match &el.key {
                        None => arr.push(v),
                        Some(k) => match self.fold_literal_default(k)? {
                            Value::Long(n) => arr.set(crate::array::ArrayKey::Int(n), v),
                            Value::String(s) => {
                                let key = match std::str::from_utf8(s.as_bytes())
                                    .ok()
                                    .and_then(|t| t.parse::<i64>().ok())
                                {
                                    Some(n) if n.to_string().as_bytes() == s.as_bytes() => {
                                        crate::array::ArrayKey::Int(n)
                                    }
                                    _ => crate::array::ArrayKey::String(s),
                                };
                                arr.set(key, v)
                            }
                            Value::True => arr.set(crate::array::ArrayKey::Int(1), v),
                            Value::False | Value::Null => {
                                arr.set(crate::array::ArrayKey::Int(0), v)
                            }
                            _ => return None,
                        },
                    }
                }
                Some(Value::Array(std::rc::Rc::new(std::cell::RefCell::new(arr))))
            }
            ExprKind::BinaryOp { op, left, right } => {
                let l = self.fold_literal_default(left)?;
                let r = self.fold_literal_default(right)?;
                match (op, &l, &r) {
                    (BinaryOp::Add, Value::Long(a), Value::Long(b)) => {
                        a.checked_add(*b).map(Value::Long)
                    }
                    (BinaryOp::Sub, Value::Long(a), Value::Long(b)) => {
                        a.checked_sub(*b).map(Value::Long)
                    }
                    (BinaryOp::Mul, Value::Long(a), Value::Long(b)) => {
                        a.checked_mul(*b).map(Value::Long)
                    }
                    (BinaryOp::BitwiseOr, Value::Long(a), Value::Long(b)) => {
                        Some(Value::Long(a | b))
                    }
                    (BinaryOp::BitwiseAnd, Value::Long(a), Value::Long(b)) => {
                        Some(Value::Long(a & b))
                    }
                    (BinaryOp::ShiftLeft, Value::Long(a), Value::Long(b))
                        if (0..64).contains(b) =>
                    {
                        Some(Value::Long(a << b))
                    }
                    (BinaryOp::Concat, Value::String(a), Value::String(b)) => {
                        let mut v = a.as_bytes().to_vec();
                        v.extend_from_slice(b.as_bytes());
                        Some(Value::String(PhpString::from_vec(v)))
                    }
                    _ => None,
                }
            }
            _ => None,
        }
    }

    /// Port of `zend_ast_export_ex` for constant expressions.
    fn export_const_expr(&self, expr: &Expr, priority: i32) -> Option<String> {
        fn qstr(s: &[u8]) -> String {
            let mut out = String::from("'");
            for &c in s {
                if c == b'\'' || c == b'\\' {
                    out.push('\\');
                }
                out.push(c as char);
            }
            out.push('\'');
            out
        }
        let bin = |sym: &str, p: i32, pl: i32, pr: i32, l: &Expr, r: &Expr| -> Option<String> {
            let ls = self.export_const_expr(l, pl)?;
            let rs = self.export_const_expr(r, pr)?;
            let s = format!("{}{}{}", ls, sym, rs);
            Some(if priority > p { format!("({})", s) } else { s })
        };
        Some(match &expr.kind {
            ExprKind::Int(n) => n.to_string(),
            ExprKind::Float(f) => {
                let s = crate::value::format_php_float(*f);
                if f.is_finite() && !s.contains('.') {
                    format!("{}.0", s)
                } else {
                    s
                }
            }
            ExprKind::String(s) => qstr(s),
            ExprKind::True => "true".to_string(),
            ExprKind::False => "false".to_string(),
            ExprKind::Null => "null".to_string(),
            ExprKind::Identifier(n) => {
                let lower = n.to_ascii_lowercase();
                match lower.as_slice() {
                    b"true" | b"false" | b"null" => String::from_utf8_lossy(&lower).to_string(),
                    _ => {
                        if let Some(rest) = n.strip_prefix(b"\\") {
                            String::from_utf8_lossy(rest).to_string()
                        } else if lower.starts_with(b"namespace\\") {
                            String::from_utf8_lossy(
                                &self.prefix_with_namespace(&n[b"namespace\\".len()..]),
                            )
                            .to_string()
                        } else if n.contains(&b'\\') {
                            String::from_utf8_lossy(&self.resolve_class_name(n)).to_string()
                        } else {
                            String::from_utf8_lossy(&self.prefix_with_namespace(n)).to_string()
                        }
                    }
                }
            }
            ExprKind::ClassConstAccess { class, constant } => {
                let cls = match &class.kind {
                    ExprKind::Identifier(n) => {
                        // Zend marks the name fully qualified only if resolution
                        // changed it (or it was written that way).
                        let full = self.export_class_name(n);
                        if !n.starts_with(b"\\") && full.as_bytes().get(1..) == Some(&n[..]) {
                            String::from_utf8_lossy(n).to_string()
                        } else {
                            full
                        }
                    }
                    _ => return None,
                };
                format!("{}::{}", cls, String::from_utf8_lossy(constant))
            }
            ExprKind::UnaryOp {
                op: UnaryOp::Negate,
                operand,
                ..
            } => {
                let s = format!("-{}", self.export_const_expr(operand, 241)?);
                if priority > 240 {
                    format!("({})", s)
                } else {
                    s
                }
            }
            ExprKind::UnaryOp {
                op: UnaryOp::Plus,
                operand,
                ..
            } => {
                let s = format!("+{}", self.export_const_expr(operand, 241)?);
                if priority > 240 {
                    format!("({})", s)
                } else {
                    s
                }
            }
            ExprKind::UnaryOp {
                op: UnaryOp::BooleanNot,
                operand,
                ..
            } => {
                let s = format!("!{}", self.export_const_expr(operand, 241)?);
                if priority > 240 {
                    format!("({})", s)
                } else {
                    s
                }
            }
            ExprKind::UnaryOp {
                op: UnaryOp::BitwiseNot,
                operand,
                ..
            } => {
                let s = format!("~{}", self.export_const_expr(operand, 241)?);
                if priority > 240 {
                    format!("({})", s)
                } else {
                    s
                }
            }
            ExprKind::BinaryOp { op, left, right } => {
                let (sym, p, pl, pr) = match op {
                    BinaryOp::Add => (" + ", 200, 200, 201),
                    BinaryOp::Sub => (" - ", 200, 200, 201),
                    BinaryOp::Mul => (" * ", 210, 210, 211),
                    BinaryOp::Div => (" / ", 210, 210, 211),
                    BinaryOp::Mod => (" % ", 210, 210, 211),
                    BinaryOp::ShiftLeft => (" << ", 190, 190, 191),
                    BinaryOp::ShiftRight => (" >> ", 190, 190, 191),
                    BinaryOp::Concat => (" . ", 185, 185, 186),
                    BinaryOp::BitwiseOr => (" | ", 140, 140, 141),
                    BinaryOp::BitwiseAnd => (" & ", 160, 160, 161),
                    BinaryOp::BitwiseXor => (" ^ ", 150, 150, 151),
                    BinaryOp::Identical => (" === ", 170, 171, 171),
                    BinaryOp::NotIdentical => (" !== ", 170, 171, 171),
                    BinaryOp::Equal => (" == ", 170, 171, 171),
                    BinaryOp::NotEqual => (" != ", 170, 171, 171),
                    BinaryOp::Less => (" < ", 180, 181, 181),
                    BinaryOp::LessEqual => (" <= ", 180, 181, 181),
                    BinaryOp::Greater => (" > ", 180, 181, 181),
                    BinaryOp::GreaterEqual => (" >= ", 180, 181, 181),
                    BinaryOp::Pow => (" ** ", 250, 251, 250),
                    BinaryOp::LogicalXor => (" xor ", 40, 40, 41),
                    BinaryOp::Spaceship => (" <=> ", 180, 181, 181),
                    BinaryOp::BooleanAnd => (" && ", 130, 130, 131),
                    BinaryOp::BooleanOr => (" || ", 120, 120, 121),
                    _ => return None,
                };
                return bin(sym, p, pl, pr, left, right);
            }
            ExprKind::NullCoalesce { left, right } => {
                return bin(" ?? ", 110, 111, 110, left, right);
            }
            ExprKind::Ternary {
                condition,
                if_true,
                if_false,
            } => {
                let c = self.export_const_expr(condition, 100)?;
                let f = self.export_const_expr(if_false, 101)?;
                let s = match if_true {
                    Some(t) => format!("{} ? {} : {}", c, self.export_const_expr(t, 101)?, f),
                    None => format!("{} ?: {}", c, f),
                };
                if priority > 100 {
                    format!("({})", s)
                } else {
                    s
                }
            }
            ExprKind::Array(elems) => {
                let mut parts = Vec::new();
                for el in elems {
                    let mut p = String::new();
                    if el.unpack {
                        p.push_str("...");
                    }
                    if let Some(k) = &el.key {
                        p.push_str(&self.export_const_expr(k, 80)?);
                        p.push_str(" => ");
                    }
                    if el.by_ref {
                        p.push('&');
                    }
                    p.push_str(&self.export_const_expr(&el.value, 80)?);
                    parts.push(p);
                }
                format!("[{}]", parts.join(", "))
            }
            ExprKind::New { class, args } => {
                let cls = match &class.kind {
                    ExprKind::Identifier(n) => self.export_class_name(n),
                    _ => return None,
                };
                let mut parts = Vec::new();
                for a in args {
                    let v = self.export_const_expr(&a.value, 0)?;
                    parts.push(match &a.name {
                        Some(n) => format!("{}: {}", String::from_utf8_lossy(n), v),
                        None if a.unpack => format!("...{}", v),
                        None => v,
                    });
                }
                format!("new {}({})", cls, parts.join(", "))
            }
            _ => return None,
        })
    }

    /// The reflection rendering of a parameter/property default value:
    /// literal values are formatted as PHP prints evaluated defaults, other
    /// constant expressions as their AST dump.
    pub(crate) fn default_value_repr(&self, expr: &Expr) -> Option<String> {
        self.default_value_repr_scoped(expr, None)
    }

    /// Like `default_value_repr`; `self::class` folds to the name of
    /// `class_scope` (a non-trait class) as PHP does at compile time.
    pub(crate) fn default_value_repr_scoped(
        &self,
        expr: &Expr,
        class_scope: Option<&[u8]>,
    ) -> Option<String> {
        if let (Some(cls), ExprKind::ClassConstAccess { class, constant }) =
            (class_scope, &expr.kind)
        {
            if constant.eq_ignore_ascii_case(b"class")
                && !cls.starts_with(b"__anonymous")
                && !cls.contains(&0u8)
            {
                if let ExprKind::Identifier(n) = &class.kind {
                    if n.eq_ignore_ascii_case(b"self") {
                        return Some(crate::reflection::format_default_value(&Value::String(
                            PhpString::from_vec(cls.to_vec()),
                        )));
                    }
                }
            }
        }
        if let Some(v) = self.fold_literal_default(expr) {
            return Some(crate::reflection::format_default_value(&v));
        }
        // `X::class` on a known (non-relative) class folds to a string.
        if let ExprKind::ClassConstAccess { class, constant } = &expr.kind {
            if constant.eq_ignore_ascii_case(b"class") {
                if let ExprKind::Identifier(n) = &class.kind {
                    let lower = n.to_ascii_lowercase();
                    if !matches!(lower.as_slice(), b"self" | b"parent" | b"static") {
                        let resolved = self.resolve_class_name(n);
                        return Some(crate::reflection::format_default_value(&Value::String(
                            PhpString::from_vec(resolved),
                        )));
                    }
                }
            }
        }
        self.export_const_expr(expr, 0)
    }
}
